-- quest.lua
local ADDON_NAME = ...
OneWoW.CatalogData:Defer(ADDON_NAME, 'quest', function()
return {
[54781] = {id=54781,name="What's For Lunch?",expansion=11,mapID=2405,rewardItems={248927,248929},questType="world",worldTaskTitle="What's For Lunch?"},
[76308] = {id=76308,name="The Trial of Style",expansion=11,mapID=2393,questType="world",worldTaskTitle="The Trial of Style"},
[84687] = {id=84687,name="Against Overwhelming Odds",level=80,requiredLevel=80,faction="alliance",expansion=11,zoneID=14771,mapID=2339,description="Friends - I sense some troubles out there. There's foes out there that harbor grudges and are looking for a fight. Join others and show those looking for a battle who is mighty.",objectivesText="Slay 25 Level 80 Horde anywhere within the Khaz Algar.",rewardCurrencies={{id=1602,amount=350},{id=2123,amount=450}},starts={{npcID=219260}},ends={{npcID=219260}},coords={x=0.588,y=0.752,source="quest_giver",zoneID=14771},questType="standard"},
[84688] = {id=84688,name="Against Overwhelming Odds",level=80,requiredLevel=80,faction="horde",expansion=11,objectivesText="Slay 25 Level 80 Alliance anywhere within the Khaz Algar.",starts={{npcID=219260}},ends={{npcID=219260}},questType="standard"},
[84912] = {id=84912,name="The Show Must Go On",level=10,requiredLevel=10,faction="both",expansion=11,zoneID=11510,mapID=1565,description="Thank you for coming! We've had a bit of a mishap with the script and various stage props. They've all gone missing! It seems as though a prankster has decided to make a mockery of our productions and scattered several needed items throughout the area. At least the prankster was somewhat considerate and left us some clues as to where we can find the missing items. Do you think you can solve the riddles? And please, do not carry any open flames or shine any bright lights while in our theater.",objectivesText="Help Dapperdew at the Amphitheater in Ardenweald. Progress: Use the play list to find the missing items in the area.",rewardItems={229383,229384,229385,229386,229387},starts={{npcID=171743}},ends={{npcID=171743}},questType="standard",worldTaskTitle="The Show Must Go On"},
[84943] = {id=84943,name="The Long Vigil",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=11400,mapID=1543,description="If you and Arator desire something of me, it will have to wait. There are souls here that require my attention, assuming your bumbling hasn't driven them off. I've managed to track four souls that fell into the Maw without proper judgment. Correct your mistakes and help me to retrieve them, and perhaps I will find time for a chat.",objectivesText="Find and calm four lost souls in the Planes of Torment. Requirements: - Stalwart Soul soothed - Plagued Soul soothed - Betrayed Soul soothed - Smoldering Soul soothed - Familiar Soul",starts={{npcID=231033}},ends={{npcID=231033}},questType="standard"},
[85679] = {id=85679,name="Repair Yourself",level=1,requiredLevel=1,faction="horde",expansion=11,zoneID=10424,mapID=1409,description="Your gear is nearly destroyed from your last fight! Speak with Provisioner Jin'hake to repair it right away.",objectivesText="Speak with Provisioner Jin'hake, then select \"Repair All Items\" to repair your damaged gear. Requirements: - Speak with Provisioner Jin'hake to Repair All Items",starts={{npcID=167212}},ends={{npcID=167212}},questType="standard"},
[85811] = {id=85811,name="Thrayir, Eyes of the Siren",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=10416,mapID=2369,description="Thrayir, Eyes of the Siren . He awaits your acceptance.>",rewardItems={232639},starts={{npcID=233582}},ends={{npcID=233582}},questType="standard"},
[85815] = {id=85815,name="A Small Pouch of Crystals",level=70,requiredLevel=70,faction="both",expansion=11,zoneID=15347,mapID=2346,rewardCurrencies={{id=2815,amount=250}},starts={{npcID=231409}},ends={{npcID=231409}},coords={x=0.436,y=0.508,source="quest_giver",mapID=2346},questType="standard"},
[85818] = {id=85818,name="A Small Pouch of Crystals",level=70,requiredLevel=70,faction="both",expansion=11,zoneID=15347,mapID=2346,rewardCurrencies={{id=2815,amount=250}},starts={{npcID=231409}},ends={{npcID=231409}},coords={x=0.436,y=0.508,source="quest_giver",mapID=2346},questType="standard"},
[85875] = {id=85875,name="Ascent of the Lich King",level=10,requiredLevel=10,faction="both",expansion=11,zoneID=210,mapID=118,description="<Icecrown lies before you. Waiting. Frostmourne bids you... ... ascend.>",objectivesText="Banish your memories. Progress: Arthas... my son.",ends={{npcID=233811}},coords={mapID=118,source="quest_giver",x=0.522,y=0.824},questType="standard"},
[85948] = {id=85948,name="A Burning Journey Through Time",faction="both",expansion=11,zoneID=3703,mapID=111,description="The blazing star shines upon the land, searing the earth and parching the landscape. This star is relentless, malevolent almost. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.",objectivesText="Complete 5 Timewalking dungeons.",rewardItems={232877},starts={{npcID=98685}},ends={{npcID=98685}},questType="standard"},
[86354] = {id=86354,name="A Percussive Antidote",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=13646,mapID=2024,description="These gnolls have been corrupting the land--growing too big and throwing off the ecosystem. We need to stop them, and let this land recover from all that decay.",objectivesText="Slay gnolls and their minions in and around the Brakenhide Hollow. Requirements: - Brackenhide Scrapper x 13 - Brackenhide Rotflinger x 13 - Oozing Decay x 25 - Rotting Treant x 13 - Decaymonger Rotpaw x 5",starts={{npcID=234745}},ends={{npcID=234745}},questType="standard"},
[86509] = {id=86509,name="Friend or Fiend",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="Despite that spirited display, I'm inclined to help you. After all, what's a little violence between friends? And since we're friends, I'll let you in on a secret: shutting down the storm is only possible from inside the Nexus-Points. Of course you can't just walk in--you need the Mantle of Predation. Decimus seems to savor the words.> Do I have your attention? Let's shake the dust off and discuss this somewhere... civilized. Meet me at my estate.",objectivesText="Travel to the Howling Ridge.",rewardGold=34100,rewardXP=1605,rewardCurrencies={{id=3316,amount=5},{id=3389,amount=10}},starts={{npcID=240691}},ends={{npcID=235697}},coords={x=0.41,y=0.726,source="quest_giver",zoneID=15458},questType="standard"},
[86510] = {id=86510,name="Domus Penumbra",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="It seems we all wish to stop the Voidstorm . Common ground--a rare thing here. I'll even tell you how to do it, and all I ask in return is for you to let me enjoy the show. But you must be tired. Show yourself around, and help yourself to the amenities. Then we will continue our discussion. Don't take too long. There is much to see, and the storm rages on.",objectivesText="Establish your base at the Howling Ridge.",rewardGold=170800,rewardXP=6425,rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=235697}},ends={{npcID=235697}},coords={x=0.514,y=0.728,source="quest_giver",zoneID=15458},questType="standard"},
[86511] = {id=86511,name="Edge of the Abyss",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="I don't trust Decimus any more than the rest of the beasts here. I do trust that they only serve themself. Seems having Xal'atath as a master isn't to their taste. We can turn one foe against another. Even Lothraxion would agree if he weren't so stubborn. If this Mantle of Predation will let us stop the storm, then it's our best shot. A troop of ren'dorei have been scouting the Obscurion Citadel. We'll meet with them and see what they've learned.",objectivesText="Meet the ren'dorei scouts near the Obscurion Citadel. Progress: I've avoided this place until now. The howls and the stench are carried on the wind like a warning.",rewardGold=34100,rewardXP=1605,rewardCurrencies={{id=3316,amount=5},{id=3389,amount=10}},starts={{npcID=238296}},ends={{npcID=235471}},coords={x=0.51,y=0.68,source="quest_giver",zoneID=15458},questType="standard"},
[86512] = {id=86512,name="The Harvest",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="Two sigils--you'll need both to open Terminas's vault and claim the Mantle. The first belongs to Torentia, petty ruler of this sad trench. Too ambitious for Terminas to bring her into his inner circle, too cowardly to strike out on her own. So here she cowers behind an unbreakable shield of Void. She's terrified of losing her already meager holdings. What a pity. Slaughter your way through the trench. The potential emergence of a new apex predator is something she won't ignore.",objectivesText="Slay foes to attract Torentia's attention. Progress: Do you feel the hunger of this place? No wonder the Void came here.",rewardGold=341600,rewardXP=12845,rewardItems={264659},rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=235633}},ends={{npcID=236945}},coords={x=0.542,y=0.742,source="quest_giver",zoneID=15458},questType="standard"},
[86513] = {id=86513,name="Face the Tide",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="I expected an army, but this is chaos--beasts pouring from the Void, gorging themselves, taking captives for sport. Our mission is to claim the Mantle, but we can't ignore this. Sooner or later, these forces will be loosed against Silvermoon. Any blows we strike now will save lives down there, $p. Starve their forces, stem the flow of beasts from the Void, and free every captive they've abducted.",objectivesText="Disrupt Obscurion Citadel forces. Progress: Even if we fail--Light forfend--at least we'll have struck a blow.",rewardGold=341600,rewardXP=12845,rewardItems={262351},rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=235469}},ends={{npcID=236944}},coords={x=0.542,y=0.742,source="quest_giver",zoneID=15458},questType="standard"},
[86514] = {id=86514,name="Lady of the Pit",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="For all their power, these domanaar still behave like beasts. That's good for us. Wolves try to avoid each other, but if one threatens another's territory, they'll fight to the death. By now, I think you've more than proven that you're a threat. Torentia can't back down if you challenge her--it would go against her nature. So take the fight to her, slay her, and claim her sigil.",objectivesText="Challenge Torentia and claim her sigil to access the vault. Progress: Have you claimed Torentia's sigil ?",rewardGold=683200,rewardXP=16055,rewardItems={238779,260860,260861,260862,260863},rewardCurrencies={{id=3316,amount=20},{id=3389,amount=100}},starts={{npcID=236945}},ends={{npcID=235502}},coords={x=0.556,y=0.728,source="quest_giver",zoneID=15458},questType="standard"},
[86515] = {id=86515,name="Hollow Hunger",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="Alleria's judgement is clouded. She's spent too much time steeped in Void. I've prosecuted campaigns across the cosmos. Casualties are inevitable. I could not command if the loss of every soldier broke my will. We have the information we need: the location of the sigil bearer. The fiends whisper of a domanaar named Severum. Slay him and take his sigil, then we can be rid of this place.",objectivesText="Slay Severum and claim his sigil. Progress: Would that we could put every voidspawn to the sword.",rewardGold=683200,rewardXP=16055,rewardItems={236752,260864,260865,260866,260867},rewardCurrencies={{id=3316,amount=20},{id=3389,amount=100}},starts={{npcID=235504}},ends={{npcID=235504}},coords={x=0.606,y=0.736,source="quest_giver",zoneID=15458},questType="standard"},
[86516] = {id=86516,name="All Become Prey",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="Lothraxion's acting like we have an army, but a single ultradon will tear through us if we're caught off guard. We need to be smarter. I've watched the beasts of this world: studied them, tracked them, killed them. They prey on weakness, and cull their own kind at the first sign of frailty. Harvest carrion essence from the carcasses around the citadel. Use it to mark ultradons. Other beasts will pounce, thinking they're wounded or dying. Let them tear each other apart, then clean up what's left.",objectivesText="Slay Slavering Ultradons by marking them with Carrion Essence . Progress: These creatures operate on base instinct. We can exploit that.",rewardGold=322100,rewardXP=12845,rewardItems={237807,267082},rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=235502}},ends={{npcID=235502}},coords={x=0.608,y=0.736,source="quest_giver",zoneID=15458},questType="standard"},
[86517] = {id=86517,name="Vanished in the Void",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="\"Acceptable losses.\" I hope I never find it that easy to dismiss the deaths of friends and comrades. What use is the Light if it leaves us as callous as our enemies? Sideras was nearly killed. Luckily, he escaped through a rift. Riftblade Maella led the others in a fighting retreat. Find her. Hopefully they stuck together. I can't leave Sideras--not until he's stable.",objectivesText="Find the missing void elves. Progress: Lothraxion should know better than this.",rewardGold=322100,rewardXP=12845,rewardItems={240831},rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=235503}},ends={{npcID=235503}},coords={x=0.608,y=0.736,source="quest_giver",zoneID=15458},questType="standard"},
[86518] = {id=86518,name="The Mantle of Predation",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="Let's move quickly. We need to steal the Mantle before Terminas returns and before Lothraxion does something rash. I understand this place grates on him, but he should know to trust my instincts. I thought we'd fought together long enough to earn that. Let's end this. Ready when you are.",objectivesText="Steal the Mantle of Predation.",rewardGold=161000,rewardXP=6425,rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=235502}},ends={{npcID=235715}},coords={x=0.608,y=0.736,source="quest_giver",zoneID=15458},questType="standard"},
[86519] = {id=86519,name="Abyssus, Abyssum",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="I don't see Decimus. For all their glee at handing us over, I'd expect they'd want to watch the fight. What could be more important to a domanaar than enjoying a battle? Answers can wait. Right now we need to survive.",objectivesText="Conquer Terminas's arena.",rewardGold=644200,rewardXP=16055,rewardItems={256198,256206,256214,256222},rewardCurrencies={{id=3316,amount=20},{id=3389,amount=100}},starts={{npcID=235715}},ends={{npcID=239574}},coords={x=0.602,y=0.762,source="quest_giver",zoneID=15458},questType="standard"},
[86520] = {id=86520,name="Hunt the Light",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="There's no time. Lothraxion already has the lead. Get to Nexus-Point Xenas, $p. We'll meet you there.",objectivesText="Meet Alleria Windrunner at Nexus-Point Xenas.",rewardGold=32200,rewardXP=1605,rewardCurrencies={{id=3316,amount=5},{id=3389,amount=10}},starts={{npcID=239574}},ends={{npcID=235763}},coords={x=0.6,y=0.76,source="quest_giver",zoneID=15458},questType="standard"},
[86521] = {id=86521,name="Nexus-Point Xenas: Eclipse",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="If he destroys the Nexus-Point, everyone we're fighting for could perish. I'll try to talk him down, but if I can't, if I have to... No hesitation. We end this, one way or another.",objectivesText="Enter Nexus-Point Xenas and stop Lothraxion. Progress: We've come too far to let anything stop us.",rewardGold=1288400,rewardXP=25690,rewardItems={262606},rewardChoices={251093,251206,251217},rewardCurrencies={{id=3316,amount=25},{id=3389,amount=250}},starts={{npcID=235763}},ends={{npcID=235765}},coords={x=0.64,y=0.618,source="quest_giver",zoneID=15458},questType="dungeon"},
[86522] = {id=86522,name="Daylight is Breaking",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15969,mapID=2405,description="Turalyon is busying himself with the troops. We'll need to let him know what they'll face here, tell him about Lothraxion... Thank you, $p. Even when my thoughts feel clouded, you never seem to waver. Go, give Lor'themar my report. Arator and I will brief Turalyon.",objectivesText="Report to Lor'themar Theron in the Sanctum of Light in Silvermoon City.",rewardGold=84500,rewardXP=3210,rewardCurrencies={{id=3316,amount=100},{id=3389,amount=1500}},starts={{npcID=235765}},ends={{npcID=235787}},coords={x=0.458,y=0.646,source="quest_giver",zoneID=15458},questType="standard"},
[86528] = {id=86528,name="A Cracked Holokey",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="<A unique-looking ethereal device rests upon the cold ground. It bears a crack down the middle from damage in a scuffle. Perhaps Alleria will know what it is.>",objectivesText="Bring the Cracked Holokey to Alleria deeper in the Ethereum Refinery.",rewardGold=341600,rewardXP=12845,rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=504349}},ends={{npcID=235717}},coords={x=0.357,y=0.792,source="quest_giver",zoneID=15458},questType="standard"},
[86530] = {id=86530,name="First, The Shells",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="Ages ago, on a dismal world of swamp, I led the Army of the Light to a demon-infested manaforge obscured by vines and fog. My soldiers left that world in a haze of flame and smoke, the scent of burning mana and victory in the air. We will do now as we did then. We'll begin by collecting the empty canisters they use to hold and transport fuel. The ethereals, and especially their automatons, will have them.",objectivesText="Collect 5 Empty Manacells from mechs and ethereals at the Ethereum Refinery. Progress: Just as before.",rewardGold=341600,rewardXP=12845,rewardItems={237380,260848,262375,262376,262672,262674,262675,262678,262733,262737,264657},rewardChoices={260848,262375,262376,262672,262674,262675,262678,262733,262737},rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=235394}},ends={{npcID=235713}},coords={x=0.366,y=0.73,source="quest_giver",zoneID=15458},questType="standard"},
[86531] = {id=86531,name="Work Disruption",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="The Shadowguard may once have defied Xal'atath, but they're part of her army now. Whatever they're doing with the energies gathered here must be stopped. Put down their soldiers, harvesters, and machines. I'll do the same, and meet you deeper within.",objectivesText="Slay Shadowguard and disrupt the Manaforge at the Ethereum Refinery. Progress: What does she have planned...",rewardGold=341600,rewardXP=12845,rewardItems={263240},rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=235389}},ends={{npcID=235717}},coords={x=0.366,y=0.73,source="quest_giver",zoneID=15458},questType="standard"},
[86536] = {id=86536,name="Reliable Enemies",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="The ren'dorei scouts report a familiar enemy upon this world: ethereals. Wretched scavengers and bandits that plague every corner of the Great Dark Beyond. The Shadowguard are the worst of them. We'll handle them. This... thing we've taken prisoner must know what they're doing here, and much else. Press the Void's secrets from it. See that it is convinced to share what it knows, or I will employ my own methods.",objectivesText="Interrogate Decimus. Progress: Lothraxion has a plan. I trust him.",rewardGold=85400,rewardXP=3210,rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=235606}},ends={{npcID=235389}},coords={x=0.354,y=0.59,source="quest_giver",zoneID=15458},questType="standard"},
[86537] = {id=86537,name="Network Insecurity",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="Judging by the design and the strength of this holokey's energy, it must be used to encrypt important communications. Let us try this lead. See if it's compatible with any of the consoles you find around the refinery. Given the damage it's taken, we'll have to piece together whatever scraps of information we can.",objectivesText="Use the Holokey on consoles around the Ethereum Refinery. Progress: What have you found?",rewardGold=322100,rewardXP=12845,rewardItems={237745,262669,262670,262671,262673,262677,262730,262735,262738,262739,268921},rewardChoices={262669,262670,262671,262673,262677,262730,262735,262738,262739,268921},rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=235717}},ends={{npcID=235717}},coords={x=0.362,y=0.804,source="quest_giver",zoneID=15458},questType="standard"},
[86538] = {id=86538,name="Second, The Fuel",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="Ethereals seek corners of the cosmos to drain of potent nether. Arcane, Void, fel--to them, it matters only the yield. And we have a rich vein to work with. Now, slay those who possess that energy: wild arcane elementals from their pipes, or their ethereal harvesters flush with energy. We have need of it.",objectivesText="Collect 50 Arcane Remnants in the Ethereum Refinery. Progress: Go. Collect the catalyst.",rewardGold=341600,rewardXP=12845,rewardItems={237744},rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=235713}},ends={{npcID=235713}},coords={x=0.362,y=0.806,source="quest_giver",zoneID=15458},questType="standard"},
[86539] = {id=86539,name="A Naaru!",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="I refuse to let another naaru fall to darkness. Before our departure, the scouts reported they had found a Nexus-Point connected to this forge. If the Void's forces possess a naaru, it might be where they're keeping it. I will prepare the manacells as we conduct the search. Come.",objectivesText="Find Lothraxion at the overlook to Nexus-Point Mid'Ar.",rewardGold=85400,rewardXP=3210,rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=235713}},ends={{npcID=235648}},coords={x=0.362,y=0.806,source="quest_giver",zoneID=15458},questType="standard"},
[86540] = {id=86540,name="Third, Blow It Up",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="The manacells have been prepared. Set them near the pylon and its supporting machinery. When it's done, I will command Alleria to ignite them from afar. But we cannot proceed until the naaru has been brought to safety. Go now and I will make certain of her freedom.",objectivesText="Place 5 Overcharged Manacells at Nexus-Point Mid'Ar. Progress: What are you doing here? Place the manacells, now!",rewardGold=335000,rewardXP=12845,rewardItems={264340},rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=235648}},ends={{npcID=235649}},coords={x=0.394,y=0.822,source="quest_giver",zoneID=15458},questType="standard"},
[86541] = {id=86541,name="Just In Case...",level=88,requiredLevel=88,faction="none",expansion=11,zoneID=15458,mapID=2405,description="Perhaps Lothraxion will be able to bring that shield down on his own. Or perhaps he is a pompous blowhard. The Devouring Host offers its trusted soldiers fragments of a relic that can override any ethereal device, including that shield. You'll need to carve quite a swath through their forces to recover enough shards. But what do I know? I am merely unworthy voidspawn.",objectivesText="Collect 8 Fragmented Keystones from Devouring Host soldiers at Nexus-Point Mid'Ar. Progress: < Decimus glances sideways at you.>",rewardGold=341600,rewardXP=12845,rewardItems={237895,242254,267209},rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=235650}},ends={{npcID=235652}},coords={x=0.394,y=0.82,source="quest_giver",zoneID=15458},questType="standard"},
[86542] = {id=86542,name="Flicker in the Dark",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="We're dawdling! There's no time to waste! Get that shield down, now! T'era's anguish tears at my soul!",objectivesText="Free and rescue T'era.",rewardGold=644200,rewardXP=16055,rewardItems={260832,260833,260834,260835},rewardCurrencies={{id=3316,amount=20},{id=3389,amount=100}},starts={{npcID=235649}},ends={{npcID=235664}},coords={x=0.38,y=0.832,source="quest_giver",zoneID=15458},questType="standard"},
[86543] = {id=86543,name="Magisters' Terrace: Homecoming",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=16215,mapID=2393,description="We know there's land inside the Voidstorm , through its massive portal. If we can reach it, we can take the fight to Xal'atath. I have found the key. It is a relic known as the Cynosure of Twilight. For ages, it has mystified us by revealing unreachable pathways to infinite unknowns. My research tells me I can use it to open a path to the storm. There's just one problem: it's in Magisters' Terrace. And I'm not exactly... in their good graces, at the moment.",objectivesText="Meet Magister Umbric on the Isle of Quel'Danas, then complete the Magisters' Terrace dungeon.",rewardGold=1366400,rewardXP=25690,rewardChoices={251103,251104,251108,251115,251118,260312},starts={{npcID=235386}},ends={{npcID=235405}},coords={x=0.452,y=0.702,source="quest_giver",zoneID=15969},questType="dungeon"},
[86544] = {id=86544,name="Post-Mortem",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="We all bear a heavy burden in this place. I feel myself slipping towards hopelessness. But we haven't failed until we refuse to stand back up. I know my mother will collect herself. But the others need to know this fight isn't over. Speak with Hieron. He and the other scouts should have information. We can start there.",objectivesText="Check in with the inhabitants of Locus Point. Progress: Mother... Hang in there.",rewardGold=170800,rewardXP=6425,rewardItems={238500},rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=235724}},ends={{npcID=235724}},coords={x=0.416,y=0.746,source="quest_giver",zoneID=15458},questType="standard"},
[86545] = {id=86545,name="The Light's Brand",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="No! , we have to stop them! Lothraxion's boiling temper risks everything! That he chooses now of all times, when my mother is out of commission... There's no time. We have to go!",objectivesText="Intervene in the fight between Lothraxion and Decimus. Progress: I should have realized earlier... Join me, <name>. Let us reveal the truth.",rewardGold=683200,rewardXP=16055,rewardItems={260854,260855,260856,260857},rewardCurrencies={{id=3316,amount=100},{id=3389,amount=1500}},starts={{npcID=235724}},ends={{npcID=235726}},coords={x=0.416,y=0.746,source="quest_giver",zoneID=15458},questType="standard"},
[86549] = {id=86549,name="No Fear of the Dark",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2393,description="Against all odds, we made it. I can open a way into the storm, but it will be a tenuous connection. We can only get a small team through the portal. We have no idea what awaits us on the other side. We must be prepared. I can use the Cynosure to bind us to Magisters' Terrace. If we need a quick escape, I can bring us back there. Come--help me calibrate this spell.",objectivesText="Help Magister Umbric apply the anchor spell and open a portal to Voidstorm .",rewardGold=170800,rewardXP=6425,rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=235405}},ends={{npcID=235411}},coords={x=0.352,y=0.656,source="quest_giver",zoneID=15969},questType="standard"},
[86557] = {id=86557,name="A Matter of Strife and Death",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="Ha! A distant realm, crawling with vicious evil monsters? Just like old times. Alleria, Turalyon, and I faced a thousand years of war with demons in the far-flung realms. It is as simple a solution now as it was then. Kill or be killed.",objectivesText="Kill 12 monsters in The Ingress. Progress: I will not deny, I still thrive in the rush of battle. So long as it is of righteous cause.",rewardGold=335000,rewardXP=12845,rewardItems={264508},rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=235486}},ends={{npcID=235522}},coords={x=0.344,y=0.604,source="quest_giver",zoneID=15458},questType="standard"},
[86558] = {id=86558,name="Save a Piece of Mind",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="The Void here. It is like nothing else. Surely you can feel it, too? The overwhelming power... We must do something to stabilize the area. I'm barely able to keep our escape route from imploding, and the rest of our scouts... I can only hope they can hold it together. The ren'dorei know what to do. They will place Shadestar Loci to protect this area, but will need your help activating them.",objectivesText="Activate 3 Shadestar Loci around The Ingress. Progress: Be careful, <class>. Treachery threatens us from all sides.",rewardGold=341600,rewardXP=12845,rewardItems={260836,260837,260838,260839},rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=235411}},ends={{npcID=235486},{npcID=235522}},coords={x=0.342,y=0.604,source="quest_giver",zoneID=15458},questType="standard"},
[86559] = {id=86559,name="The Far, Far Frontier",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="We have secured this location. Some void elves can make this into a proper camp. There must be some weakness we can exploit to stop the storm. We must bring my army here to mete out justice to Xal'atath's armies! Join me and young Arator. Let us see what we can gather from this place across the horizon.",objectivesText="Survey Voidstorm with Lothraxion and Arator.",rewardGold=34100,rewardXP=1605,rewardCurrencies={{id=3316,amount=5},{id=3389,amount=10}},starts={{npcID=235522}},ends={{npcID=235530}},coords={x=0.368,y=0.586,source="quest_giver",zoneID=15458},questType="standard"},
[86560] = {id=86560,name="A Shrouded Journey Through Time",faction="both",expansion=11,zoneID=6757,mapID=554,description="The shrouded star flickers upon the land with its intermittent light ushering in an eerie mist upon the land. This star and the mists bring deep shadows to the land hiding its secrets and dangers. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.",objectivesText="Complete 5 Timewalking dungeons. Progress: I foresee that you will follow the shrouded star, and walk the paths it reveals.",rewardItems={232877},starts={{npcID=118828}},ends={{npcID=118828}},questType="standard"},
[86561] = {id=86561,name="A Strange, Different World",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="I don't know the purpose of these towers, only that they are called Nexus-Points and they thrum with Void power. We must get more information. The domanaar use some kind of Void-infused metal on the beasts here to add them to armies of the Devouring Host. They call it shadowgrafting. It empowers them, but also influences their minds. What power doesn't? I have a plan for it. With you here, I can finally act on it.",objectivesText="Collect 12 Shadowgraft Fragments in Nexus-Point Antius. Progress: The metal on these creatures... it seems particularly conductive to magical energies. Interesting.",rewardGold=341600,rewardXP=12845,rewardItems={242390,262472},rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=235532}},ends={{npcID=235535}},coords={x=0.312,y=0.544,source="quest_giver",zoneID=15458},questType="standard"},
[86562] = {id=86562,name="Dancing with Death",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="We may be a small strike team, but we are strong. We have you, after all. There is no need to move with complete stealth. We must cut a path to the domanaar here. Take down the strongest enemies you can find. We will join you in the fray.",objectivesText="Slay Voidgrasper , Vathan the Rebel, and Scytheryp the Slicer in Nexus-Point Antius. Progress: Have you found the greatest of the enemies here? I wonder just how powerful a creature can get, consuming Void for eternity...",rewardGold=683200,rewardXP=16055,rewardItems={260840,260841,260842,260843},rewardCurrencies={{id=3316,amount=20},{id=3389,amount=100}},starts={{npcID=235530}},ends={{npcID=235535}},coords={x=0.312,y=0.544,source="quest_giver",zoneID=15458},questType="standard"},
[86565] = {id=86565,name="No Prayer for the Wicked",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="Alleria has a plan to use this shadowgrafting material to capture that domanaar for information. But what good is information given by evil? I've fought countless demons and every one of them was a liar. Lothraxion scowls.> Let us follow her plan, for now. Do what she asks with this metal, then slay the domanaar's pet beast. Once we speak with this vile creature, I will decide how long it lives.",objectivesText="Help modify the Shadowgraft Fragments, slay Sinewshredder in Nexus-Point Antius, and capture the leading domanaar.",rewardGold=644200,rewardXP=16055,rewardItems={260844,260845,260846,260847},rewardCurrencies={{id=3316,amount=100},{id=3389,amount=1500}},starts={{npcID=235535}},ends={{npcID=235606}},coords={x=0.274,y=0.51,source="quest_giver",zoneID=15458},questType="standard"},
[86621] = {id=86621,name="The Wayward Magister",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="Magister Umbric --he's second only to Mother in mastering the Void. If anyone can help us with that storm in the sky, he's the one who can make it happen... if he can forgive the others for not listening to him in the first place. At least Lor'themar saw reason. There's no way we can take the fight to Xal'atath without Umbric. The forces keeping the Voidstorm at bay will only hold out so long. Let's make haste.",objectivesText="Accompany Arator to meet with Magister Umbric in Tranquillien. Progress: What's that you have there?",rewardGold=34100,rewardXP=1470,rewardItems={239496},rewardCurrencies={{id=3316,amount=5},{id=3365,amount=10}},starts={{npcID=236716}},ends={{npcID=236087}},coords={x=0.472,y=0.552,source="quest_giver",zoneID=15968},questType="standard"},
[86622] = {id=86622,name="Chance Meeting",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="I've heard some odd rumors myself. Strange happenings to the south--but also to the east and west, and the north. Tranquillien is surrounded by enemies, it seems. Since you are so dead-set on your investigation, would you look into something for me? There is an important report I need from one of my scouts. Check in with them, while I check over the rest of town.",objectivesText="Meet with Lord Antenorian 's scout near Tranquillien. Progress: Let's get to the bottom of this.",rewardGold=341600,rewardXP=11765,rewardItems={243221,248049,248050},rewardChoices={248049,248050},rewardCurrencies={{id=3316,amount=10}},starts={{npcID=245004}},ends={{npcID=236100}},coords={x=0.472,y=0.682,source="quest_giver",zoneID=15968},questType="standard"},
[86623] = {id=86623,name="Appeal to the Void",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="Kasiea... whatever you've found, you've perished for it. I won't let her work be in vain. There's something to be found here, $p. There are a few locations listed. Let's travel to them and try some of these theorems. The formulae may be incomplete, but perhaps we can discover what she was looking for. It had to have been important.",objectivesText="Assist Umbric with testing Void theorems outside of Tranquillien.",rewardGold=341600,rewardXP=11765,rewardItems={251883},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=236087}},ends={{npcID=236087}},coords={x=0.476,y=0.698,source="quest_giver",zoneID=15968},questType="standard"},
[86624] = {id=86624,name="Rational Explanation",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="Something just doesn't feel right about all of this. Umbric can look into the notebook, but I suspect there's something more going on here. It couldn't hurt to ask around Tranquillien and see if anyone's heard anything odd. I'll take the north side of town, and you take the south. And... use your discretion, my friend. We should avoid alarming anyone for now.",objectivesText="Question the townsfolk of Tranquillien and take note of any clues. Progress: How goes your investigation?",rewardGold=341600,rewardXP=11765,rewardItems={244194,244195,244197},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=236100}},ends={{npcID=236100}},coords={x=0.476,y=0.698,source="quest_giver",zoneID=15968},questType="standard"},
[86625] = {id=86625,name="The Clue in the Inn",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=15968,mapID=2395,description="Call me paranoid, you'd be correct, but I have been chased out of enough towns that I have a system. I establish a safehouse. Somewhere easily defensible, with enough materials that I can finish any delicate tasks and prepare for departure. That is the situation we find ourselves in-- we will retreat to the top floor of the inn and assess our options from there. I had shared the location with Caliea, when she was still studying with me... hopefully it serves us better than it did her.",objectivesText="Retreat to Umbric's safehouse on the top floor of the inn.",rewardGold=309800,rewardXP=11765,questType="standard"},
[86626] = {id=86626,name="The Ransacked Lab",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="My notes, my research... I never should have left it alone. I was just beginning to understand the Voidstorm! Everything I'd learned, torn from my hands by cultists... Were they watching the entire time? Waiting for me to turn my back? I cannot let this stop me. They can't have destroyed everything. Perhaps there's enough here to salvage.",objectivesText="Scour Umbric's ransacked lab for any salvageable research.",rewardGold=341600,rewardXP=11765,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=242143}},ends={{npcID=236687}},coords={x=0.476,y=0.698,source="quest_giver",zoneID=15968},questType="standard"},
[86632] = {id=86632,name="The Battle for Tranquillien",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="The Twilight's Blade? Attacking in broad daylight now that their cover's blown... we'll prove what a mistake that was. Slay the traitors and the creatures they've summoned. Destroy their effigies and their supplies. Make this retreat costly, .",objectivesText="Free Tranquillien from the grip of the Twilight's Blade. Progress: Let's hope there's enough left here to rebuild.",rewardGold=625600,rewardXP=14705,rewardCurrencies={{id=3316,amount=20},{id=3365,amount=100}},starts={{npcID=236687}},ends={{npcID=243984}},coords={x=0.476,y=0.698,source="quest_giver",zoneID=15968},questType="standard"},
[86633] = {id=86633,name="Comprehend the Void",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="Kasiea's notes may be lost forever, but we must try and improvise. I have one final ritual to try. If this doesn't work, then the answers lay in Deatholme, the Twilight's Blade's heart. But first...",objectivesText="Meet Umbric at the ritual site in Windrunner Village. There, collect 4 Void Shards and return them to the Void nexus. Progress: I can't hold this indefinitely--a little speed would be appreciated!",rewardGold=341600,rewardXP=11765,rewardItems={248046,250361},rewardChoices={248046,250361},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=236363}},ends={{npcID=237240}},coords={x=0.37,y=0.74,source="quest_giver",zoneID=15968},questType="standard"},
[86634] = {id=86634,name="The Past Keeps Watch",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="I don't trust the quiet here. Let's shore up the defenses. Did you see those slumped-over arcane golems around the village? They may not look like much now, but a quick tune up will have them on their feet soon enough. They're good for standing guard, and also for ferreting out any hidden snakes in the weeds. Let's get to work. The sooner the golems are running, the better I'll feel about this town's safety.",objectivesText="Activate 6 Decrepit Ranger Constructs on the borders of Windrunner Village. Progress: It's odd being here. This place is... well, I suppose it's technically my namesake.",rewardGold=341600,rewardXP=11765,rewardItems={248030,248031,248032,248033},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=236391}},ends={{npcID=236391}},coords={x=0.37,y=0.74,source="quest_giver",zoneID=15968},questType="standard"},
[86635] = {id=86635,name="To Deatholme",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="That coward Antenorian has doomed us all. I had hoped it wouldn't come to this, but... We need the rest of Kasiea's research--the missing pages that were stolen from her corpse. But the cult has retreated south, to the ruins of Deatholme. Fitting that such traitors would sequester themselves in such a vile place. But we must root them out.",objectivesText="Meet with Magister Umbric in the Ruins of Deatholme. Progress: Watch your back. The ruins of Deatholme are still dangerous.",rewardGold=34100,rewardXP=1470,rewardCurrencies={{id=3316,amount=5},{id=3365,amount=10}},starts={{npcID=237240}},ends={{npcID=236730}},coords={x=0.374,y=0.746,source="quest_giver",zoneID=15968},questType="standard"},
[86636] = {id=86636,name="Void Walk With Me",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16594,mapID=2395,description="I did not expect this place to be so heavily guarded. This is far more complicated than one charismatic leader and a group of wayward pilgrims. Still... if we take out Antenorian, it should weaken them considerably. A cult is nothing without its leader. Valeera tracked the governor to that cavern. He's gone in. We'll make sure he never comes out.",objectivesText="Complete the Deatholme Delve. Progress: Let's be done with this. The Twilight's Blade must fall.",rewardGold=1366400,rewardXP=23530,rewardItems={249630,249634,249638,249642,249646,249650,249654,249658,253153},rewardChoices={249630,249634,249638,249642,249646,249650,249654,249658},rewardCurrencies={{id=3316,amount=100}},starts={{npcID=236730}},ends={{npcID=236730}},coords={x=0.444,y=0.85,source="quest_giver",zoneID=15968},questType="standard"},
[86637] = {id=86637,name="Anything but Reprieve",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="This is dire. The Twilight's Blade is much larger--much more powerful--than any of us could have guessed. I'm relieved Umbric is on the case, but we need to let Silvermoon know what's happened here.",objectivesText="Contact Silvermoon.",rewardGold=34100,rewardXP=1470,rewardCurrencies={{id=3316,amount=5},{id=3365,amount=10}},starts={{npcID=242433}},ends={{npcID=236099}},coords={x=0.446,y=0.852,source="quest_giver",zoneID=15968},questType="standard"},
[86638] = {id=86638,name="Choking Tendrils",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="I haven't the expertise of Orweyna in these matters. But if the Lightbloom moved this quickly, I assume the rutaani are accelerating the spread here just as they were in Fairbreeze. The town is beyond saving, but we can at least try to contain the Lightbloom within its walls.",objectivesText="Cull the Lightbloom in Suncrown Village. Progress: Fairbreeze was nothing compared to this. What... happened here?",rewardGold=341600,rewardXP=11765,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=236132}},ends={{npcID=236568}},coords={x=0.526,y=0.616,source="quest_giver",zoneID=15968},questType="standard"},
[86639] = {id=86639,name="What's Left",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="You see what we have to contend with here. Runestone Shan'dor is helping stop the spread further north, but if this Lightbloom surges again, I don't know if we can halt it. I've heard cries for help from survivors still trapped within. We have to find them, and direct them to safety!",objectivesText="Find and aid survivors in Suncrown Village. Progress: By the Light... this is so much worse than I would have ever imagined.",rewardGold=341600,rewardXP=11765,rewardItems={248057,248058},rewardChoices={248057,248058},rewardCurrencies={{id=3316,amount=10}},starts={{npcID=236099}},ends={{npcID=236099}},coords={x=0.536,y=0.546,source="quest_giver",zoneID=15968},questType="standard"},
[86640] = {id=86640,name="Premonition",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="I came as quickly as I could. This is... devastating. I have called in our Magisters to reinforce this runestone. They will keep an eye on the Lightbloom spread. I suspect Halduron Brightwing and the Farstriders have uncovered more than the villagers know. I can rely on him for anything. We shall rendezvous with him at the encampment to the north, and soon have some answers.",objectivesText="Regroup with Lor'themar Theron at Scintilas Outpost.",rewardGold=34100,rewardXP=1470,rewardCurrencies={{id=3316,amount=5},{id=3365,amount=10}},starts={{npcID=236572}},ends={{npcID=241206}},coords={x=0.534,y=0.546,source="quest_giver",zoneID=15968},questType="standard"},
[86641] = {id=86641,name="Old Scars",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="Of course the Amani would use this moment to encroach, the cowards. We are beset on all sides! This land belongs to the sin'dorei, and I will not see it taken by anyone. Not by raging plants, not by a cult, not by the Void, and never by the Amani! Whatever they are doing over there, it must be stopped. Do whatever you can to disrupt them and send them scurrying back to Zul'Aman where they belong.",objectivesText="Disrupt the Amani lumber operation in Tor'Watha.",rewardGold=341600,rewardXP=11765,rewardItems={248019,248020,248021,248022},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=241206}},ends={{npcID=241272}},coords={x=0.592,y=0.51,source="quest_giver",zoneID=15968},questType="standard"},
[86642] = {id=86642,name="A Foe Unseen",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="I know Lor'themar is angry, but... this is strange, $p. They didn't attack Suncrown--the Lightbloom did. What are the Amani doing over there? There has to be some kind of explanation for this. It doesn't look like an invasion. Let's see what we can find out.",objectivesText="Find information about what the trolls are doing in Tor'Watha.",rewardGold=170800,rewardXP=5885,rewardItems={244469},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=236567}},ends={{npcID=241205}},coords={x=0.59,y=0.51,source="quest_giver",zoneID=15968},questType="standard"},
[86643] = {id=86643,name="Following the Root",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="Lor'themar has a right to defend this land, but I don't think he's seeing clearly. The presence of Amani is too inciting. This doesn't add up. The trolls are going out of their way to craft Lightbloom weapons--to fight what? It isn't us. They didn't attack Suncrown. They could have, and they didn't. We need to find the truth. Let's head south. That hideout I discovered must have some answers.",objectivesText="Meet Arator at Watha'nan Crypts in Eversong. Progress: There must be a reasonable answer for all of this.",rewardGold=34100,rewardXP=1470,rewardCurrencies={{id=3316,amount=5},{id=3365,amount=10}},starts={{npcID=241205}},ends={{npcID=241205}},coords={x=0.644,y=0.486,source="quest_giver",zoneID=15968},questType="standard"},
[86644] = {id=86644,name="Gods Before Us",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2579,description="I suppose I shouldn't have expected a greeting with open arms, but I did not expect to be trapped in here. The Amani are clever. They must have made a way to escape. We have only to find it. Let's look around.",objectivesText="Explore Watha'nan Crypts and pursue Zul'jan. Progress: There's a way out of here--I know it.",rewardGold=312800,rewardXP=11765,rewardItems={244143,244144,252677},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=236610}},ends={{npcID=236610}},questType="standard"},
[86646] = {id=86646,name="An Impasse",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="How deep does this crypt go? We need to find Zul'jan and explain to him that we fight a common enemy. Surely he'll see reason! Come on. They can't have gotten much farther in this maze.",objectivesText="Pursue Vanatha and Zul'jan deeper into Watha'nan Crypts.",rewardGold=683200,rewardXP=14705,rewardItems={248080,250470,250471,250472,250473,250474,250475,250476,250477,250478,250479,250480},rewardChoices={248080,250470,250471,250472,250473,250474,250475,250476,250477,250478,250479,250480},rewardCurrencies={{id=3316,amount=20}},starts={{npcID=240662}},ends={{npcID=236737}},questType="standard"},
[86647] = {id=86647,name="Beat of Blood",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="None of this is necessary. We need to make them see reason! My father will know what to do. I know he'll see reason, once I explain what has happened here. There is no need for bloodshed! It's simple: if the Amani are set against the Twilight's Blade, we fight on the same side.",objectivesText="Meet Arator at the Amani Pass.",rewardGold=31500,rewardXP=1470,rewardCurrencies={{id=3316,amount=5},{id=3365,amount=10}},starts={{npcID=236737}},ends={{npcID=236611}},coords={x=0.548,y=0.682,source="quest_giver",zoneID=15968},questType="standard"},
[86648] = {id=86648,name="Light Guide Us",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="Our findings at Tor'Watha were correct. By the time Turalyon and I arrived here with troops, the Amani had already begun to take the pass. They seek to establish another path to acquire the lightwood from our land. The Amani have chosen war, as they always do. This, at least, is a threat I know how to handle. Arator is but a boy. He cannot grasp the magnitude of history between the sin'dorei and Amani--and I don't expect him to. Will you stand by the blood elves, and all that is right?",objectivesText="Resolve the battle at the Amani Pass by helping the blood elves secure it, or try to dissuade the blood elves from fighting.",rewardGold=1024800,rewardXP=17650,rewardItems={248027,248028,248029,248053},rewardCurrencies={{id=3316,amount=100},{id=3365,amount=1500}},starts={{npcID=236612}},ends={{npcID=236612}},coords={x=0.602,y=0.814,source="quest_giver",zoneID=15968},questType="standard"},
[86649] = {id=86649,name="Past Redemption",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="These monsters deserve nothing more than swift retribution. For Silvermoon. For the sin'dorei. For Alleria. This will be finished!",objectivesText="Finish the battle against the Amani at the Amani Pass.",rewardGold=319000,rewardXP=11765,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=241654}},ends={{npcID=237433}},coords={x=0.602,y=0.814,source="quest_giver",zoneID=15968},questType="standard"},
[86650] = {id=86650,name="Fractured",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2395,description="Lady Liadrin will remain here. The rest of us shall return to Silvermoon and debrief. We still have many battles ahead, it seems.",objectivesText="Return to Silvermoon City. Progress: There is much to do.",rewardGold=966300,rewardXP=17650,rewardItems={244538},rewardCurrencies={{id=3316,amount=5},{id=3365,amount=10}},starts={{npcID=237433}},ends={{npcID=235787}},coords={x=0.606,y=0.814,source="quest_giver",zoneID=15968},questType="standard"},
[86652] = {id=86652,name="Left in the Shadows",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="De loa have not spoken to us in many years... not since I was a young child. And dey have shown no sign of wanting to help us now. No. It is up to us alone. We must find a way to rally de other tribes and fight de Twilight's Blade as one. I will speak to de tribal representatives and help de refugees where I can--dey are our priority. Come, you might learn somethin' about de Amani.",objectivesText="Join Zul'jarra and Liadrin as they check on Atal'Aman refugees. Progress: Ancestors willing, we will find our opportunity to strike back soon.",rewardGold=256200,rewardXP=9130,rewardCurrencies={{id=3316,amount=100},{id=3354,amount=1500}},starts={{npcID=236659}},ends={{npcID=236126}},coords={x=0.426,y=0.668,source="quest_giver",zoneID=15947},questType="standard"},
[86653] = {id=86653,name="The Path of the Amani",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Kinduru is my uncle, and I trust him... But dis \"path of de hash'ey\"... Things are not what dey were decades ago. The loa are gone--they not gonna hear us. Zul'jarra lets out a low growl only you and Liadrin hear.> No. We're running out of options. If dis is de time for old myths and dreams, so be it. We meet at the foot of the mountains, Akil'zon's Reach, where de old hash'ey shrines are.",objectivesText="Meet Zul'jarra outside Akil'zon's Reach.",rewardGold=34100,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3354,amount=10}},starts={{npcID=236126}},ends={{npcID=236140}},coords={x=0.438,y=0.684,source="quest_giver",zoneID=15947},questType="standard"},
[86654] = {id=86654,name="Gnarldin Bashing",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Zul'jarra regards the gnarldin as a fierce, nomadic people that normally keep to themselves. It is clear by their clothing and weapons that they have a primitive but unique culture. If the circumstances were different, I would advocate for diplomacy. But they are between us and our mission. They cannot block our path or continue to damage the shrines or the nests of the eagles that roost here. We will eliminate only those that are in our way. The Amani can choose what to do with them later.",objectivesText="Slay 12 gnarldin in Akil'zon's Reach. Progress: The gnarldin seem ready to fight us. Let's give them what they want, shall we?",rewardGold=341600,rewardXP=12170,rewardItems={264255},rewardCurrencies={{id=3316,amount=20},{id=3354,amount=100}},starts={{npcID=236143}},ends={{npcID=236146}},coords={x=0.516,y=0.708,source="quest_giver",zoneID=15947},questType="standard"},
[86655] = {id=86655,name="De Ancient Path",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="My uncle, de loa speaker, spoke of de hash'ey when I was a child. But when de loa remained silent so many years... I do not think he would admit it, but he lost a little faith too. I remember some of his lessons. A chieftain must light de shrines on de way to de temple. De hash'ura must as well. Why? I do not remember. But if it is de only way to get de loa's favor? Come. Let us get dis out of de way.",objectivesText="Light the 4 Hash'ey Shrines in Akil'zon's Reach. Progress: I hope we are doing dis right.",rewardGold=341600,rewardXP=12170,rewardItems={248567,248568,248569,248570},rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=236140}},ends={{npcID=236147}},coords={x=0.516,y=0.708,source="quest_giver",zoneID=15947},questType="standard"},
[86656] = {id=86656,name="Brutal Feast",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Zul'jarra 's brow furrows and her lip curls as she looks toward the temple.> When we lit de last shrine, some of de eagles returned to de temple. It could be a sign. Zul'jarra scoffs.> Or de eagles are movin' in after de gnarldin started movin' out. When we get to the temple, all we gonna find is silence. Just like always. But we still gonna try. We should go now and present an offerin'.",objectivesText="Reach the Temple of Akil'zon and seek Akil'zon's attention.",rewardGold=170800,rewardXP=6085,rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=236147}},ends={{npcID=244422}},coords={x=0.518,y=0.76,source="quest_giver",zoneID=15947},questType="standard"},
[86657] = {id=86657,name="Shadebasin Watch",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Zul'jarra smiles slightly as Akil'zon's blessing buffets her.> Kinduru's stories were real. We have de blessin' of Akil'zon, and de path of the hash'ey stretches out before us. We must follow Akil'zon's advice and seek out Halazzi next. As Akil'zon is de loa of de rulin' tribe--de Amani--and my family, Halazzi is de loa of the Witherbark and their leaders. If their loa speakers are gone, then maybe Kul'amara will know how to approach him.",objectivesText="Speak with Kul'amara the Fierce at Shadebasin Watch. Progress: I thought de Witherbark were strong enough to handle de Vilebranch on their own. I should have come here before now.",rewardGold=34100,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3354,amount=10}},starts={{npcID=236141}},ends={{npcID=244438}},coords={x=0.522,y=0.81,source="quest_giver",zoneID=15947},questType="standard"},
[86658] = {id=86658,name="The Crypt in the Mist",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Zul'jarra growls through her gritted tusks.> Now it's not as surprisin' dat Malacrass's tribe, de Vilebranch, fell to the lure of hex magic. But dat is their choice and a path dey chose long ago--a path away from us. I won't let dem live long enough to regret it. What de Vilebranch have done to de Witherbark has gone too long without an Amani response. De mist is not in our way. We can use it to our advantage. We will take a life for all de lives dey took. And make sure dey stay dead.",objectivesText="Slay 8 Vilebranch trolls and Ritualist Zongha in Numazon Crypt. Progress: Finding Halazzi can wait. The Vilebranch are preyin' on my people. It's about time some predators hunted dem.",rewardGold=683200,rewardXP=15215,rewardItems={248571,248572,248573,248574},rewardCurrencies={{id=3316,amount=20},{id=3354,amount=100}},starts={{npcID=244438}},ends={{npcID=244588}},coords={x=0.44,y=0.344,source="quest_giver",zoneID=15947},questType="standard"},
[86659] = {id=86659,name="Breaching the Mist",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="The Vilebranch seemed to be just as confused by the mist as the Witherbark. Whatever has caused de mist, dealin' with de Vilebranch changed nothing. And now we must find de hash'ey shrines in de dark. Zul'jarra moves her hand in front of her face, testing her range of visibility, and frowns.> We must light de shrines. Try not to get separated. Dis will try my patience. But I'm sure if we use our heads, we will find de path.",objectivesText="Light the Hash'ey Shrines around the Temple of Halazzi.",rewardGold=341600,rewardXP=12170,rewardItems={248575,248576},rewardChoices={248575,248576},rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=244588}},ends={{npcID=236155}},coords={x=0.368,y=0.35,source="quest_giver",zoneID=15947},questType="standard"},
[86660] = {id=86660,name="Rescue from the Shadows",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Kul'amara has told me dat a shadowy mist has fallen over Numazon. She believes de Vilebranch are behind it, usin' their magic to hide de crimes dey commit against de Witherbark. She believes dey are hidin' in de Numazon crypts. De hash'ey shrines are near there as well. We must find our way to Numazon and rescue de Witherbark captives. If we find de hash'ey shrines along de way, so be it. If Halazzi will not stand with us, den maybe de Witherbark will.",objectivesText="Rescue 8 Witherbark captives in Numazon. Progress: Keep on de lookout for more Witherbark captives!",rewardGold=341600,rewardXP=12170,rewardItems={253469},rewardCurrencies={{id=3316,amount=20},{id=3354,amount=100}},starts={{npcID=244438}},ends={{npcID=244588}},coords={x=0.44,y=0.344,source="quest_giver",zoneID=15947},questType="standard"},
[86661] = {id=86661,name="Coals of a Dead Loa",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="By helpin' de Witherbark, we helped ourselves--and passed Halazzi's trial. There is a lesson in that. Now dat Halazzi has returned, we should go back and let Vun'zarah know. I hope dis will improve de relationship between our tribes. And maybe he knows where we can find out how to resurrect Jan'alai.",objectivesText="Travel to Witherbark Bluffs and speak with Vun'zarah, leader of the Witherbark Tribe. Progress: We have come dis far. We must try to resurrect de dead loa.",rewardGold=32200,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3354,amount=10}},starts={{npcID=236155}},ends={{npcID=244592}},coords={x=0.324,y=0.316,source="quest_giver",zoneID=15947},questType="standard"},
[86663] = {id=86663,name="Embers to a Flame",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="The loa speaker talks of fire in de heart--in all hearts. Jan'alai is de loa of birth, death, and rebirth. Maybe de loa speaker is askin' for sacrifice. Zul'jarra smiles deviously.> Hey, Liadrin. How much fire you think is in an elf's heart, eh? Heh. Whatever de loa speaker wants, it is either part of resurrectin' de loa or part of de trial. Let's see what he has do say.",objectivesText="Slay Amazards to empower the Ember of Jan'alai. Progress: This loa speaker's holding onto his faith a bit like Kinduru. But Kinduru knows how to speak clearly what he means. Usually.",rewardGold=341600,rewardXP=12170,rewardItems={264715},rewardCurrencies={{id=3316,amount=20},{id=3354,amount=100}},starts={{npcID=236162}},ends={{npcID=236162}},coords={x=0.55,y=0.184,source="quest_giver",zoneID=15947},questType="standard"},
[86664] = {id=86664,name="Seer or Sear",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Dis old, crazy loa speaker is too busy dancin' to tell us what to do next. But I think I know. We could not light de shrines on de way to de temple. But now dat Jan'alai's presence is here... Maybe now we can. I will take de ember to de hash'ey shrines. Den maybe de trial will start. I jumped from de top of de temple of Akil'zon. I found my way through de mists of Halazzi. I am ready for Jan'alai's fire. We can only hope dey will receive us after what my grandfather has done.",objectivesText="Assist Zul'jarra in lighting Hash'ey Shrines of Jan'alai. Progress: No stoppin' de trial now. We must do what needs to be done.",rewardGold=650600,rewardXP=15215,rewardItems={248577,248578},rewardChoices={248577,248578},rewardCurrencies={{id=3316,amount=20},{id=3354,amount=100}},starts={{npcID=236162}},ends={{npcID=236162}},coords={x=0.55,y=0.184,source="quest_giver",zoneID=15947},questType="standard"},
[86665] = {id=86665,name="Face in the Fire",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="First my grandfather, then my brother. Jan'alai knew my shame at my grandfather's rage. And de rage I feel when Zul'jan disrespects me. I know I put fuel on his fire by respondin' de way I do. Maybe dat needs to change. I have left my doubt of de loa behind me. I can leave those thoughts behind too, and continue de path of de hash'ey. Stoke de coal, . I am ready for de final trial, whatever it may be.",objectivesText="Slay the last Fire Manifestation in the Temple of Jan'alai. Progress: Let's get dis over with.",rewardGold=683200,rewardXP=15215,rewardCurrencies={{id=3316,amount=20},{id=3354,amount=100}},starts={{npcID=236162}},ends={{npcID=236162}},coords={x=0.55,y=0.184,source="quest_giver",zoneID=15947},questType="standard"},
[86666] = {id=86666,name="In the Shadow of Rebirth",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Jan'alai's trial has made me realize... I need to make things right between me and my brother. He acts out at me, but it's because I put him down. I do not think about how hard it must be to be my brother. We should also check on how our preparations are goin' and if my troops are gettin' de food and rest dey need. Nalorakk's not gonna go anywhere. He can wait a few hours.",objectivesText="Meet Zul'jarra in Amani'Zar Village.",rewardGold=33500,rewardXP=1520,rewardCurrencies={{id=3316,amount=100},{id=3354,amount=1500}},starts={{npcID=236162}},ends={{npcID=240186}},coords={x=0.55,y=0.184,source="quest_giver",zoneID=15947},questType="standard"},
[86681] = {id=86681,name="Den of Nalorakk: A Taste of Vengeance",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Zul'jan has taken de troops without my orders--again! And de number of casualties... for what? For wood? I want to take his tusks and... Zul'jarra growls but seems to center herself.> Kinduru will need help with de soldiers' death rites. Help him prepare de herb mixture and pour it onto de fires. My brother and I need to... talk.",objectivesText="Assist Elder Kinduru with the death rites. Progress: There are so few of us left. What was my brother thinking?",rewardGold=341600,rewardXP=12170,rewardItems={264479,264480,264481},rewardChoices={264479,264480,264481},rewardCurrencies={{id=3316,amount=20},{id=3354,amount=100}},starts={{npcID=240186}},ends={{npcID=240186}},coords={x=0.438,y=0.682,source="quest_giver",zoneID=15947},questType="standard"},
[86682] = {id=86682,name="Den of Nalorakk: Waking de Bear",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="We must set aside what Zul'jan has done and focus on de final hash'ey trial: facin' Nalorakk, de Loa of War. De Revantusk were once beloved of Nalorakk. Legend has it dat his loa speaker was so devoted, she followed him into his temple and his den with de most faithful of de Revantusk's warriors. But now de temple is sealed. We cannot speak to de loa speaker, but maybe Lilaju knows how to get Nalorakk's attention. She keeps watch for de Twilight's Blade at Torntusk Overlook with her guards.",objectivesText="Travel to Torntusk Overlook and speak with Lilaju, the Revantusk leader. Progress: Lilaju is de only person who can help us now.",rewardGold=341600,rewardXP=12170,rewardCurrencies={{id=3316,amount=20},{id=3354,amount=100}},starts={{npcID=240186}},ends={{npcID=240215}},coords={x=0.438,y=0.682,source="quest_giver",zoneID=15947},questType="standard"},
[86683] = {id=86683,name="Hash'ey Away",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="We've done it, . De loa are at our side once again. Am I hash'ey? I do not know. But I do know I would not have gotten dis far without my hash'ura. Come. We will return to Amani'Zar and tell Kinduru and Zul'jan de good news.",objectivesText="Meet Zul'jarra at Amani'Zar Village.",rewardGold=34100,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3354,amount=10}},starts={{npcID=240215}},ends={{npcID=240216}},coords={x=0.336,y=0.788,source="quest_giver",zoneID=15947},questType="standard"},
[86684] = {id=86684,name="The Blade's Edge",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="With de other tribes and de loa's help, we can take de fight to de Twilight's Blade and take dem down. Blood for blood!",objectivesText="Meet Zul'jarra and Liadrin at Broken Throne to fight the Twilight's Blade.",rewardGold=34100,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3354,amount=10}},starts={{npcID=240216}},ends={{npcID=240033}},coords={x=0.436,y=0.688,source="quest_giver",zoneID=15947},questType="standard"},
[86685] = {id=86685,name="Chip and Shatter",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Zul'jarra shakes her head back and forth and jumps in place, shaking out her muscles. She stops and turns to you, grinning broadly.> Heh. Do you feel it, my hash'ura? De electricity in de air? De smell of blood and fire? My soul is leapin' to join de fight. You ready to chop de enemy down, bathe in dey blood, and make dem pay for what dey done? Me too.",objectivesText="Slay the Twilight's Blade at Broken Throne.",rewardGold=341600,rewardXP=12170,rewardCurrencies={{id=3316,amount=20},{id=3354,amount=100}},starts={{npcID=240033}},ends={{npcID=245270}},coords={x=0.284,y=0.774,source="quest_giver",zoneID=15947},questType="standard"},
[86686] = {id=86686,name="Light Indiscriminate",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Though the dead litter this field, I still see plenty of Amani clinging to life. Help me heal the injured. We'll ensure their reputation for survival continues on after this day.",objectivesText="Heal 10 Injured Amani Warriors. Progress: Every warrior healed is another sword at our side!",rewardGold=335000,rewardXP=12170,rewardCurrencies={{id=3316,amount=20},{id=3354,amount=100}},starts={{npcID=240039}},ends={{npcID=245271}},coords={x=0.284,y=0.774,source="quest_giver",zoneID=15947},questType="standard"},
[86687] = {id=86687,name="Conduit Crisis",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="With de loa at our side, we can finally break de Twilight's Blade and return to Amani'Zar with Mor'duun's head. De loa are already attackin' de main source of Mor'duun's power: summoned spheres of pure void energy. Go to de loa and offer your assistance. When de orbs are destroyed, we can move forward and strike at Mor'duun!",objectivesText="Destroy the 12 Void Conduits hindering Nalorakk, Akil'zon, Halazzi, and Jan'alai in Broken Throne. Progress: Don't be afraid. If you assist dem, de loa will grant you their strength.",rewardGold=319000,rewardXP=12170,rewardItems={248579,248580,248581,248582},rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=240033}},ends={{npcID=245270}},coords={x=0.284,y=0.774,source="quest_giver",zoneID=15947},questType="standard"},
[86692] = {id=86692,name="Blade Shattered",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="It ends here. De path of the hash'ey, my path, has led me here. Let dis fight bring a new age for my people. Come. It is time.",objectivesText="Slay Mor'duun, High Inquisitor of the Twilight's Blade.",rewardGold=1024800,rewardXP=18255,rewardItems={248583},rewardCurrencies={{id=3316,amount=100},{id=3354,amount=1500}},starts={{npcID=240034}},ends={{npcID=240037}},coords={x=0.226,y=0.774,source="quest_giver",zoneID=15947},questType="standard"},
[86693] = {id=86693,name="De Legend of de Hash'ey",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Mor'duun is slain. De Twilight's Blade will continue to plague our lands, but of dem only Mor'duun's \"fodder\" is left. Dey will be easy prey for us. And now I will say somethin' my uncle would be proud of. Let us follow de teachin' of Nalorakk, de Loa of War. De battle is over. It is time to rest--I can tell by your eyes both my hash'ura need it too. Let us leave dis place. We can speak again back in Amani'Zar.",objectivesText="Speak with Zul'jarra in Amani'Zar Village.",rewardGold=34100,rewardXP=1520,rewardItems={255648},rewardCurrencies={{id=3316,amount=5},{id=3354,amount=10}},starts={{npcID=240037}},ends={{npcID=249653}},coords={x=0.214,y=0.774,source="quest_giver",zoneID=15947},questType="standard"},
[86708] = {id=86708,name="The Gates of Zul'Aman",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15968,mapID=2395,description="After the Amani surrender, we demanded Zul'jan relinquish our lightwood and return to their lands. Even so, Zul'jan still lingers at the gates of Zul'Aman with his troops. Lady Liadrin and her Blood Knights hold the pass, and Liadrin is trying to remedy the situation with diplomacy, but she reports that aggression may begin anew. She requests your assistance in this precarious matter.",objectivesText="Meet Lady Liadrin at the Amani Pass.",rewardGold=154900,rewardXP=6085,starts={{npcID=240523}},ends={{npcID=236436}},questType="standard"},
[86710] = {id=86710,name="The Line Must Be Drawn Here",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15968,mapID=2395,description="I had hoped that Zul'jan would leave the lightwood and return swiftly to his lands after our confrontation with him. But dealing with the Amani has never been a simple matter. Diplomacy is the only way to avoid more bloodshed, but Zul'jan is finished listening to me. Perhaps he will listen to you?",objectivesText="Speak to Zul'jan and defuse the situation. Progress: An outsider's view may help him see reason.",rewardGold=683200,rewardXP=15215,starts={{npcID=236436}},ends={{npcID=236436}},coords={x=0.602,y=0.814,source="quest_giver",zoneID=15968},questType="standard"},
[86711] = {id=86711,name="Amani Clarion Call",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=16194,mapID=2536,description="If you want to survive here in Atal'Aman, find and beat de city's battle drums. Dat will rally our remainin' soldiers forward to join de fight. It will also bring all de tribes of Zul'Aman --de Witherbark, de Revantusk, and de Shadowpine--to our aid and tell our civilians to retreat to de Altar of Malacrass if we need to evacuate. Use de drums to spread de word. Find me at de Altar of Malacrass when you are done.",objectivesText="Sound the Amani War Drums in Atal'Aman.",rewardGold=341600,rewardXP=12170,rewardItems={264334},rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=236468}},ends={{npcID=236559}},coords={x=0.056,y=0.474,source="quest_giver",zoneID=16194},questType="standard"},
[86712] = {id=86712,name="The Amani Stand Strong",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=16194,mapID=2536,description="Zul'jarra doesn't think de lightwood is worth de risks I am taking. We will prove her wrong. I have seen too many warriors discouraged because their weapons don't work against de Twilight's Blade. Don't just tell them to retreat. Give them de lightwood weapons . Nothing stirs Amani blood like an effective axe in their hands. Let dem fight their way back to de Altar of Malacrass.",objectivesText="Give 8 Lightwood Weapons to Demoralized Defenders .",rewardGold=341600,rewardXP=12170,rewardItems={237501,264257},rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=236540}},ends={{npcID=236588}},coords={x=0.224,y=0.798,source="quest_giver",zoneID=16194},questType="standard"},
[86715] = {id=86715,name="Rituals Cut Short",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2536,description="In our reconnaissance flight around the city, Zul'jarra and I got a look at the Twilight's offensive. They're summoning more Twilight's Blade directly into Atal'Aman. We can counter them by disrupting their dark summoning rituals. That will stop the flow of their cultists into the city and give the Amani time to strategize. Kill the ritualists, and any trollbreakers already portaled into the area.",objectivesText="Destroy 6 Twilight Ritualists and 6 Twilight Trollbreakers in Firewing Terrace. Progress: We cannot allow the Twilight's Blade to bring even more troops into Atal'Aman.",rewardGold=319000,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=236542}},ends={{npcID=236586}},coords={x=0.23,y=0.796,source="quest_giver",zoneID=16194},questType="standard"},
[86716] = {id=86716,name="Armed by Light",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=16194,mapID=2536,description="You might be good at killing, , but so are we Amani. And even more de better our weapons! I took an army into Eversong to reclaim de lightwood forests for de Amani. It was against my sister's orders, yes, but lightwood gives us an advantage. Take back de weapons being stolen by de Twilight's Blade, and I'll show you why it was worth de effort.",objectivesText="Recover 8 stolen Lightwood Weapons . Progress: These weapons are the difference between my people living or dying.",rewardGold=319000,rewardXP=12170,rewardItems={237767,248555,248556,248557,248558,248559,248560,248561,248562},rewardChoices={248555,248556,248557,248558,248559,248560,248561,248562},rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=236522}},ends={{npcID=236540}},coords={x=0.166,y=0.206,source="quest_giver",zoneID=16194},questType="standard"},
[86717] = {id=86717,name="Show Us Your Worth",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=16194,mapID=2536,description="De Twilight's Blade's general, Mor'duun, has got us by de throat. We're not winnin', and we are too few. We've got to evacuate before there's no one left--and hope de other tribes meet us at Amani'Zar. In de meantime, I'm glad to use you while we rally de people of Zul'Aman . De civilians' lives are my priority. Go to Swiftclaw Terrace and evacuate de people there. Tear through de Twilight's Blade as you go. Find your way to Zul'jan when you're done.",objectivesText="Rescue Amani civilians and destroy the Twilight's Blade presence at Swiftclaw Terrace in Atal'Aman. Progress: Separate their limbs from their bodies. Tear down their banners and shelters too!",rewardGold=341600,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=236559}},ends={{npcID=236522}},coords={x=0.46,y=0.486,source="quest_giver",zoneID=16194},questType="standard"},
[86718] = {id=86718,name="Twilight Bled",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=16194,mapID=2536,description="Mor'duun may be de leader of de Twilight's Blade in Zul'Aman , but dat ogre can't be everywhere. De elf found his military commander--a hulkin' pile of armor and flesh named Benvis Bladesplatter. He's paradin' 'round like he's already won just because dey seized Firewing Terrace. Make him pay for his arrogance.",objectivesText="Kill Benvis Bladesplatter at Firewing Terrace. Progress: Have you ended him yet?",rewardGold=341600,rewardXP=12170,rewardItems={260468,260469,260470,260471},rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=236541}},ends={{npcID=236587}},coords={x=0.228,y=0.796,source="quest_giver",zoneID=16194},questType="standard"},
[86719] = {id=86719,name="Important Amani",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=16194,mapID=2536,description="De drums have sounded. But de elders have not come. We cannot lose them. They are our link to our culture--our sages and our best minds. Torundo helped devise de lightwood weapons. And Doru is our provisioner. We will need both if de battle goes on. Go find Doru in de market and Torundo in de tribute hall. De last one is de old loa speaker--our uncle, Kinduru. He may need... special persuasion to leave. I will go to Talonstrike Terrace to speak to him. Meet me there after you find de others.",objectivesText="Find the Amani elders: Torundo the Grizzled , Doru, and Kinduru. Progress: Do whatever is necessary to get Kinduru to leave. He's our uncle. We can't leave him here.",rewardGold=341600,rewardXP=12170,rewardItems={237768},rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=236558}},ends={{npcID=236522}},coords={x=0.46,y=0.486,source="quest_giver",zoneID=16194},questType="standard"},
[86720] = {id=86720,name="Break the Blade",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=16194,mapID=2536,description="Zul'jan's ballista is ready. And it had better work after what he has done. We lost de army we needed to defend de city, but we can fend off Mor'duun long enough to let our people escape. Help my brother man de ballista. Focus on de shadow warders and de pylon. Liadrin and I will distract Mor'duun. I will kill him if I can, but even then we can't stay here. There's too much void energy. And too much destruction. Atal'Aman is truly lost.",objectivesText="Use the Lightwood Ballista to destroy the Empowering Shadows and the Scrying Focus to bring down Mord'uun's barrier.",rewardGold=1024800,rewardXP=18255,rewardItems={248563,248564,248565,248566},rewardCurrencies={{id=3316,amount=20},{id=3354,amount=100}},starts={{npcID=236587}},ends={{npcID=236601}},coords={x=0.474,y=0.468,source="quest_giver",zoneID=16194},questType="standard"},
[86721] = {id=86721,name="Everything We Worked For",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=16194,mapID=2536,description="My blood is boiling! While waiting for Kinduru, de Twilight's Blade was destroying what little stores of lightwood we had left at Ragemaw Terrace! But if we act quickly, we can save enough to arm de lightwood ballista--and take a shot at Mor'duun. And without de ballista, we cannot claim victory!",objectivesText="Extinguish fires on the Lightwood Piles at Ragemaw Terrace. Progress: Don't let de lightwood burn!",rewardGold=341600,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=236522}},ends={{npcID=236540}},coords={x=0.166,y=0.206,source="quest_giver",zoneID=16194},questType="standard"},
[86722] = {id=86722,name="Heart of the Amani",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2536,description="You and your elf friend amuse me. And you've more than proved yourself in battle. Our people are headin' to Amani'Zar. We hope dat de other tribes rallied there instead of Atal'Aman. Their representatives will give us council, and then we will mount an attack on de Twilight's Blade. If you still wish to fight with de Amani, meet me on de northwest side of de village. Zul'jan will have gone ahead to speak of his deeds--and yours--but do not enter de village without me. Amani kill strangers on sight.",objectivesText="Meet Zul'jarra at the entrance to Amani'Zar Village.",rewardGold=170800,rewardXP=6085,rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=236601}},ends={{npcID=236602}},coords={x=0.478,y=0.476,source="quest_giver",zoneID=16194},questType="standard"},
[86723] = {id=86723,name="Isolation",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="We will speak to Torundo, my war advisor. And if de representatives of de tribes are here, we will have a council meetin' in de Zari Lodge. Together, we must agree on a way to defeat de Twilight's Blade. Explore de village if you want. But keep your weapons where dey can be seen. You are here by my invitation and my word is law, but I can only run so fast if one of my people thinks you looked at dem in de wrong way. Zul'jarra smiles a tusky grin as if proud of her people's short fuse.>",objectivesText="Meet Zul'jarra and Liadrin to assess the situation with the other troll tribes. Progress: I need de advise of my advisor, Torundo. And we must see why de other tribes did not heed de drums. Dey may think I am desperate to ask for your help. But dey also would dare not challenge me.",rewardGold=170800,rewardXP=6085,rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=236602}},ends={{npcID=236659}},coords={x=0.426,y=0.668,source="quest_giver",zoneID=15947},questType="standard"},
[86733] = {id=86733,name="Silvermoon Negotiations",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2424,description="It would be an understatement to say things between Silvermoon and the Alliance are often tense and uneasy. I thank you for setting aside any prejudices you might have had and lending your strength to the defense of Silvermoon and the Sunwell. We have Xal'atath's forces held for now, but this is far from over. I would include you in our next steps. Meet me at the Sanctum of Light .",objectivesText="Journey to Silvermoon City.",rewardGold=30900,rewardXP=1470,rewardItems={248059,248061,248062,248063,248067,248068,248070,248071,248075,248076,248078},rewardChoices={248063,248067,248070,248075},starts={{npcID=236779}},ends={{npcID=235787}},coords={x=0.526,y=0.882,source="quest_giver",zoneID=16215},questType="standard"},
[86734] = {id=86734,name="Diplomacy",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="We shall all weigh in on the situation. As you can see, there are many tensions at play. Please give us a moment to discuss.",objectivesText="Listen to the discussion. Progress: We have much to discuss.",rewardGold=309800,rewardXP=11765,rewardCurrencies={{id=3316,amount=10}},starts={{npcID=235787}},ends={{npcID=235787}},coords={x=0.454,y=0.704,source="quest_giver",zoneID=15969},questType="standard"},
[86735] = {id=86735,name="Paved in Ash",level=80,requiredLevel=80,faction="alliance",expansion=11,zoneID=15969,mapID=2393,description="Now that the matter is settled, you should acquaint yourself with Silvermoon. There are a few key civilians I'd like informed about your presence here--you should check in with them. Show them my signet ring--they'll know you've my permission to be here. But please take care where you go, and stay in the outer city to avoid any issues.",objectivesText="Show Lor'themar's Signet around the city. Progress: Have you spoken to everyone yet?",rewardGold=341600,rewardXP=11765,rewardItems={248042,248043,248044,248045,250352,263231},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=235787}},ends={{npcID=235787}},coords={x=0.454,y=0.704,source="quest_giver",zoneID=15969},questType="standard"},
[86736] = {id=86736,name="Paved in Ash",level=80,requiredLevel=80,faction="horde",expansion=11,zoneID=15969,mapID=2393,description="I've more to review with Turalyon, but in the meantime, the rest of the city should be informed that we will have some temporary guests in the outer perimeter. I'd like you to check in with a few key civilians and deliver the news. While you're out there, take the chance to familiarize yourself with Silvermoon. We've made impressive strides rebuilding it since you've last visited.",objectivesText="Check in with civilians around the city. Progress: Have you met with everyone?",rewardGold=341600,rewardXP=11765,rewardItems={248042,248043,248044,248045,250352,263231},rewardCurrencies={{id=3365,amount=50}},starts={{npcID=235787}},ends={{npcID=235787}},coords={x=0.454,y=0.704,source="quest_giver",zoneID=15969},questType="standard"},
[86737] = {id=86737,name="Fair Breeze, Light Bloom",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2393,description="In recent years, small pockets of wild growth we call \"Lightbloom\" have blossomed throughout Eversong. A curiosity for our local botanists, for the most part. However, the Magistrix in Fairbreeze is asking for help with the local Lightbloom. Every capable hand I have is focused on holding back the Voidstorm--but if the Magistrix cannot handle the matter herself, it requires swift attention. I'd like you to see to the issue. Magister Rommath can provide you with an arcane projector to keep in touch.",objectivesText="Journey to Fairbreeze Village.",rewardGold=34100,rewardXP=1470,rewardCurrencies={{id=3316,amount=5},{id=3365,amount=10}},starts={{npcID=235787}},ends={{npcID=236739}},coords={x=0.454,y=0.704,source="quest_giver",zoneID=15969},questType="standard"},
[86738] = {id=86738,name="Sharpmaw",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="These beasts roaming the village are nuisances, but we have a bigger problem. There's a feral lynx prowling nearby that we call Sharpmaw . She used to keep her distance from the village, but the current situation has made her more bold. We've plenty of little ones around here, and more than once the guards have caught that beast eyeing them like they were a snack waiting to be snatched. Stop her before she starts attacking my people in earnest!",objectivesText="Slay Sharpmaw .",rewardGold=309800,rewardXP=11765,rewardItems={248023,248024,248025,248026},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=236739}},ends={{npcID=236739}},coords={x=0.466,y=0.456,source="quest_giver",zoneID=15968},questType="standard"},
[86739] = {id=86739,name="Fairbreeze Favors",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="This is the oddest situation I've ever been in--our village is being overrun! I like to keep things neat and tidy around here, but these animals... they've come in from the wilds like they own the town. They're attacking our sweet pets, overturning our belongings, and causing havoc. No sooner have I solved one problem than another is rearing its head. I'm only one elf--I can't stop all of this on my own! Lend a hand, won't you? This... elf... troll... person hasn't lifted a finger.",objectivesText="Help restore order in Fairbreeze Village. Progress: The sooner the village is returned to peace, the sooner I can breathe.",rewardGold=341600,rewardXP=11765,rewardItems={264248},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=236739}},ends={{npcID=236739}},coords={x=0.466,y=0.456,source="quest_giver",zoneID=15968},questType="standard"},
[86740] = {id=86740,name="Displaced Denizens",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="The wildlife here seems to have been upset by something. Perhaps this is why the world's song bade me here: to discover why and correct it. Study the displaced wildlife. Bring me your findings. If there is anything unusual, I wish to know of it. I will speak with the Magistrix. Perhaps together we can uncover this mystery.",objectivesText="Study 3 disturbances caused by displaced wildlife and 3 unusual plants in Fairbreeze Village. Progress: Perhaps we can solve this problem together.",rewardGold=341600,rewardXP=11765,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=236743}},ends={{npcID=236743}},coords={x=0.466,y=0.456,source="quest_giver",zoneID=15968},questType="standard"},
[86741] = {id=86741,name="Lightbloom Looming",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="The wildlife seems to have been displaced from the south. It is there we will surely find answers. Come--I will use my magic to illuminate the path and we will follow the trail.",objectivesText="Follow the trail of the displaced wildlife.",rewardGold=341600,rewardXP=11765,rewardItems={245992,248018,248054,248055,248056},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=236743}},ends={{npcID=236903}},coords={x=0.466,y=0.456,source="quest_giver",zoneID=15968},questType="standard"},
[86742] = {id=86742,name="Curious Cultivation",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="This place is unlike anything I have seen before. The plant growth is unique. $p, let us examine the Lightbloom more closely. Perhaps we can uncover the secrets of this place together.",objectivesText="Examine 3 Lightbloom Plant Growths in Lightbloom Ath'Ran. Progress: This makes no sense.",rewardGold=341600,rewardXP=11765,rewardItems={248047,248048,253386},rewardChoices={248047,248048},rewardCurrencies={{id=3316,amount=10}},starts={{npcID=236903}},ends={{npcID=236903}},coords={x=0.458,y=0.554,source="quest_giver",zoneID=15968},questType="standard"},
[86743] = {id=86743,name="Trimming the Lightbloom",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="The creatures of this Lightbloom see us as the intruders. They threaten the surrounding wildlife and inhabitants who are naturally here. We should reduce their numbers and end this threat.",objectivesText="Kill Lightbloom creatures in Lightbloom Ath'ran. Progress: These creatures are so odd... as if they are driven.",rewardGold=341600,rewardXP=11765,rewardCurrencies={{id=3316,amount=5},{id=3365,amount=10}},starts={{npcID=236903},{npcID=240663}},ends={{npcID=236903},{npcID=240663}},coords={x=0.458,y=0.554,source="quest_giver",zoneID=15968},questType="standard"},
[86744] = {id=86744,name="Seeking Truth",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="I will channel on this strange seed we have collected, and see if I can discover what has happened here. This may upset the rutaani. Make sure I am not interrupted. This is why I was called here--I know now. But I must discover what needs to be done.",objectivesText="Defend Orweyna . Progress: Ah... perhaps we have some answers.",rewardGold=683200,rewardXP=14705,rewardItems={248038,248039,248040,248041},rewardCurrencies={{id=3316,amount=100},{id=3365,amount=1500}},starts={{npcID=236903}},ends={{npcID=236903}},coords={x=0.458,y=0.554,source="quest_giver",zoneID=15968},questType="standard"},
[86745] = {id=86745,name="Silvermoon Must Know",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="This growth--Lor'themar needs to know about this. I worry what will happen should it get out of control. And the Light's influence... my father should know, too.",objectivesText="Contact Silvermoon. Progress: We must contact Silvermoon to give them an update.",rewardGold=341600,rewardXP=11765,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=236716}},ends={{npcID=236716}},coords={x=0.472,y=0.552,source="quest_giver",zoneID=15968},questType="standard"},
[86769] = {id=86769,name="Last Bastion of the Light",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16182,mapID=2432,description="Your arrival has reignited hope. We have pushed Xal'atath's forces away from the Sunwell, yet they still infest the Isle of Quel'Danas , and appear to be massing for another attack as they prey upon the sin'dorei. We must join up with the Vanguard of Light.",objectivesText="Follow Lady Liadrin to Parhelion Plaza.",rewardGold=30900,rewardXP=1470,starts={{npcID=236692}},ends={{npcID=236693}},coords={x=0.486,y=0.384,source="quest_giver",zoneID=16182},questType="standard"},
[86770] = {id=86770,name="Champions of Quel'Danas",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16211,mapID=2432,description="Lor'themar has formed a rally point at Sunstrider Rise, while the civilians there are evacuated to Silvermoon, but the forces of the Vanguard of Light are scattered throughout the battlefield. We need to fight as one to defeat this host. Together, we can defeat Xal'atath and save the Sunwell.",objectivesText="Rally Faerin Lothar , Lothraxion , and Alonsus Faol at Light's Spire. Progress: You have gathered help?",rewardGold=30900,rewardXP=1470,starts={{npcID=236693}},ends={{npcID=236896}},coords={x=0.46,y=0.444,source="quest_giver",zoneID=16182},questType="standard"},
[86780] = {id=86780,name="Where Heroes Hold",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16215,mapID=2432,description="We have stopped the Devouring Host's initial attack. This battle will not be won if we go on the defensive, not even to safeguard the innocents of Quel'Danas. Focus on culling the Voidfront. Without their invading force, the Devouring Host cannot maintain a foothold! We will rally at Sunstrider Rise when ready.",objectivesText="Hinder the Voidfront forces along the walls of Parhelion Plaza. Progress: Have you thwarted the enemy?",rewardGold=309800,rewardXP=11765,rewardItems={251076,251116},rewardChoices={251076,251116},starts={{npcID=236906}},ends={{npcID=236954}},coords={x=0.46,y=0.444,source="quest_giver",zoneID=16182},questType="standard"},
[86781] = {id=86781,name="Face the Past",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="Tranquillien was marked, as are a number of other locations. Windrunner Village. It's marked. The Twilight's Blade retreated to their base in Deatholme, but my home may be in peril. We must make sure my people in Windrunner Village are safe before pursuing them.",objectivesText="Regroup in Windrunner Village.",rewardGold=34100,rewardXP=1470,rewardCurrencies={{id=3316,amount=5},{id=3365,amount=10}},starts={{npcID=242143}},ends={{npcID=236363}},coords={x=0.476,y=0.698,source="quest_giver",zoneID=15968},questType="standard"},
[86805] = {id=86805,name="The Hour of Need",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16211,mapID=2432,description="Turalyon is thinking like a battlefield captain and not like a leader! My people, the sin'dorei, have suffered much in these past few wars. How many must die in the name of his victory? Please, . Rescue any citizens you can and help guide them safely to the boats at the Silver Landing. Every life saved is a victory for the blood elves.",objectivesText="Rescue $10oa citizens, then head to the Silver Landing. Progress: The ships still have space for more! Rescue as many as you can.",rewardGold=309800,rewardXP=11765,rewardItems={248239,268326,268327},rewardChoices={268326,268327},starts={{npcID=236896}},ends={{npcID=236961}},coords={x=0.354,y=0.44,source="quest_giver",zoneID=16182},questType="standard"},
[86806] = {id=86806,name="Luminous Wings",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16182,mapID=2432,description="No! Xal'atath's Host has opened portals above the strait. Void creatures spill out and descend upon the refugee's ships. We have to safeguard the civilians! Those dragonhawks have been empowered by the Light. They should give you enough power to defeat the Void beasts and rescue the fleeing civilians.",objectivesText="Take flight on the Empowered Dragonhawk , destroy 16 Devouring Host, and rescue 3 civilians in need. Progress: The ships full of sin'dorei refugees are still in danger.",rewardGold=309800,rewardXP=11765,starts={{npcID=236961}},ends={{npcID=236961}},coords={x=0.412,y=0.568,source="quest_giver",zoneID=16182},questType="standard"},
[86807] = {id=86807,name="The Gate",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16211,mapID=2432,description="The High Exarch commanded us to assemble with his Vanguard of Light and attack the Devouring Host. I do not regret my delay of that order, but he will have noticed my absence. We should make haste and assemble with the others.",objectivesText="Assemble with the Vanguard of Light. Progress: We shouldn't delay any longer.",rewardGold=30900,rewardXP=1470,starts={{npcID=243091}},ends={{npcID=236974}},coords={x=0.412,y=0.566,source="quest_giver",zoneID=16182},questType="standard"},
[86808] = {id=86808,name="The Riddled Speaker",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Chief Vun'zarah knew little of Jan'alai, but he did know about their loa speaker. If dey are still at de temple, then there is hope we can resurrect de loa. Zul'jarra 's hand tightens on her axe.> Makin' Akil'zon flee, woundin' Halazzi, sendin' Nalorakk into a rage, and killin' Jan'alai... My grandfather and Malacrass have so much to pay for.",objectivesText="Meet Zul'jarra and Liadrin at the Temple of Jan'alai.",rewardGold=34100,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3354,amount=10}},starts={{npcID=244592}},ends={{npcID=236162}},coords={x=0.384,y=0.224,source="quest_giver",zoneID=15947},questType="standard"},
[86810] = {id=86810,name="Harvesting the Void",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,description="To effectively counteract the void anomalies present here, we must obtain viable samples of the anomalies. Search the area for containment vessels that hold developing anomalies, as well as the Unstable Oozelings created from the contamination. Use the collection device to make this process easier. Only living Oozelings will provide viable samples.",rewardGold=341600,rewardXP=13690,rewardItems={246951},starts={{npcID=248114,x=0.268,y=0.68,zoneID=15458}},ends={{npcID=248114,x=0.268,y=0.68,zoneID=15458}},coords={x=0.268,y=0.68,source="quest_giver",zoneID=15458},questType="world",worldTaskTitle="Harvesting the Void"},
[86811] = {id=86811,name="Ethereal Eradication",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16182,mapID=2432,description="! I have a mission for you. There is a contingent of Shadowguard ethereals to the northeast. They appear to be looting the buildings, but that could change in a moment. The Vanguard cannot afford to be flanked as we advance. Take out their leader and decimate their forces while we engage the Host.",objectivesText="Eliminate Norkonahl the Looter and 12 Shadowguard intruders. Progress: Have you completed the mission?",rewardGold=309800,rewardXP=11765,starts={{npcID=236978}},ends={{npcID=236978}},coords={x=0.454,y=0.27,source="quest_giver",zoneID=16182},questType="standard"},
[86832] = {id=86832,name="A Worthy Forge",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Thank you for all your help, $p. It's strange to hold what remains of my father's shield and know that, prior to that day, he was such a defender of others. I feel I've only seen his aggressive side. I realize he means well, but I don't think... That is not the path for me. Regardless, let's return to Silvermoon and get these fragments we've gathered to a worthy forge.",rewardGold=31900,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3365,amount=10}},starts={{npcID=237508,x=0.366,y=0.51,zoneID=46}},ends={{npcID=237511,x=0.456,y=0.654,zoneID=15969}},coords={x=0.366,y=0.51,source="quest_giver",zoneID=46},questType="world",worldTaskTitle="A Worthy Forge"},
[86833] = {id=86833,name="A Bulwark Remade",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15969,mapID=2393,description="$p, it is time to see what we can do with these fragments of Turalyon's shield. While it did break, it was exceptionally powerful in its day, and it could be a great help to Turalyon against the Void. Perhaps a moment of healing and letting go, as well.",rewardGold=341600,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=237511,x=0.456,y=0.654,zoneID=15969}},ends={{npcID=237510,x=0.406,y=0.66,zoneID=15969}},coords={x=0.456,y=0.654,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="A Bulwark Remade"},
[86834] = {id=86834,name="Voidborn Banishing",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16182,mapID=2565,description="The Devouring Host are composed of horrors from the depths of the Void, but they are still an army, with soldiers and leaders. Amongst that sea of void walkers, I notice there are singular creatures. Whether commander or mascot to the Host, removing them from the battlefield will help to break their lines.",objectivesText="Slay Latrunculon , Blightclaw , and The Wasting . Progress: We need to defeat all of the void commanders.",rewardGold=309800,rewardXP=11765,rewardItems={251241,251242},rewardChoices={251241,251242},starts={{npcID=236964},{npcID=237222}},ends={{npcID=236978}},coords={x=0.494,y=0.216,source="quest_giver",zoneID=16211},questType="standard"},
[86836] = {id=86836,name="The Hunter Awaits",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="I have warned Orweyna of the dangers and madness that lay within the Rift of Aln, but she believes it is her only path forward. I envy her faith. Someone can help show her the way: the Shul'ka. The Hunters of Shadows. They have sacrificed everything to protect the haranir from the effects of the rift. I will let one know that you need help. You will find him in the Vale of Mists.",objectivesText="Find Orweyna and the Shul'ka in the Vale of Mists.",rewardGold=34100,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3370,amount=10}},starts={{npcID=241045}},ends={{npcID=237236}},coords={x=0.542,y=0.556,source="quest_giver",zoneID=15355},questType="standard"},
[86837] = {id=86837,name="Meet at the Sunwell",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=16215,mapID=2424,description="I have been tasked with bolstering the Vanguard of Light that empower the Sunwell. I need your help, though not just for that simple task. Our mutual friend, Arator , is... stuck. Stuck in his grief and anger over that tragic conflict between him and his father. I'm just an old priest that's been raised from the dead, but I've found that a quest is just the thing to set a young paladin back on the right path. Would you help?",rewardGold=34100,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3365,amount=10}},starts={{npcID=237565,x=0.456,y=0.658,zoneID=15969}},ends={{npcID=240240,x=0.528,y=0.552,zoneID=16215}},coords={x=0.456,y=0.658,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Meet at the Sunwell"},
[86838] = {id=86838,name="Renewal for the Weary",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=16215,mapID=2424,description="The Vanguard of Light are maintaining a difficult ritual at the Sunwell. It requires focus, discipline, and is quite exhausting. Take my staff. I've had it since I was Archbishop in Stormwind. It is meaningful to me and my faith. The Light responds to meaning and intention. It should renew the Vanguard's spirits so they can maintain the ritual a while longer. I can't approach any closer to the Sunwell, so you will have to do this for me.",rewardGold=341600,rewardXP=12170,rewardItems={237811,251274,251275,251276,251277},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=240240,x=0.528,y=0.552,zoneID=16215}},ends={{npcID=240240,x=0.528,y=0.552,zoneID=16215}},coords={x=0.528,y=0.552,source="quest_giver",zoneID=16215},questType="world",worldTaskTitle="Renewal for the Weary"},
[86848] = {id=86848,name="Light's Arsenal",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16182,mapID=2432,description="The armory here stores legendary weapons and artifacts, blessed with the power of the Light due to their proximity to the Sunwell. While we are pinned down by the Host, the ethereals are looting these treasures. , secure these holy artifacts. They are our best weapons against the Void. Use them to cut down these invaders if you have the need.",objectivesText="Collect 7 Legendary Weapons. Progress: Have you secured our artifacts?",rewardGold=309800,rewardXP=11765,rewardItems={238807,238842,238843,238844,238845,238846,238890,251250,251251,251252,251253,251254,251255,251256,251257,251258,251259,251260},rewardChoices={251257},starts={{npcID=237253}},ends={{npcID=237253}},coords={x=0.452,y=0.27,source="quest_giver",zoneID=16182},questType="standard"},
[86849] = {id=86849,name="Wrath Unleashed",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16182,mapID=2432,description=", the time has come! We push these fiends to Sun's Reach Harbor! We drive them back into their accursed void portal and drive them from these sacred shores! For the Light! For Azeroth!",objectivesText="Join the charge of the Vanguard of Light. Progress: Don't stop until we drive them from these shores!",rewardGold=309800,rewardXP=11765,starts={{npcID=236978}},ends={{npcID=237277}},coords={x=0.454,y=0.27,source="quest_giver",zoneID=16182},questType="standard"},
[86850] = {id=86850,name="Broken Sun",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16182,mapID=2432,description="We need to fall back! This is not a battle that we can win. Not like this. But there is still hope! The Sunwell. It brought the Vanguard of Light here to defend it. It brought you, . Fall back to the Sunwell chamber and defend it for as long as we can. I have faith the Light did not intend for us to lose this day.",objectivesText="Meet Liadrin at the entrance to the Sunwell.",rewardGold=309800,rewardXP=11765,starts={{npcID=237277}},ends={{npcID=237278}},coords={x=0.458,y=0.114,source="quest_giver",zoneID=16182},questType="standard"},
[86851] = {id=86851,name="The Foundation of Aln",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="The presence of the goddess reverberates through everything in the Rift of Aln. The voice is too powerful for haranir to resist. In mere minutes, one of our flock would be lost forever. There are, however, ways to protect oneself for a short time. Kill the rejects that crawl up from the rift and gather the Alndust from which they are created. I can show Orweyna how to craft a short-term solution for entering the rift.",objectivesText="Collect 6 alndust from Rift creatures in the Vale of Mists. Progress: I will let your young companion know what to do with the Alndust.",rewardGold=341600,rewardXP=12170,rewardItems={238417,266259},rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=237236}},ends={{npcID=241070}},coords={x=0.62,y=0.546,source="quest_giver",zoneID=15355},questType="standard"},
[86852] = {id=86852,name="Light's Last Stand",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16215,mapID=2432,description="Our attempts to fight Xal'atath's Devouring Host have failed. Our only hope is to call upon the Light once more and trust that there was a reason it brought this Vanguard together. , you and Arator need to protect the Sunwell from the Devouring Host. With so few of us left, we cannot spare any more defenders. Our faith in the Light will save us.",objectivesText="Defend the Sunwell from the attacking forces.",rewardGold=929400,rewardXP=17650,rewardCurrencies={{id=3316,amount=100},{id=3365,amount=500}},starts={{npcID=237278}},ends={{npcID=241068}},coords={x=0.526,y=0.504,source="quest_giver",zoneID=16182},questType="standard"},
[86855] = {id=86855,name="Consequences of Our Duty",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="You must see with your own eyes the effects that the Rift of Aln can have on any haranir. Even those who stand guard over the border are oft affected by its call. Take this. I use it as an emergency salve to help those who are stricken of the dangers of Aln. Patrol these lands and give aid to those who need it. Perhaps then you will understand the gravity of what you seek to do.",objectivesText="Heal 5 Wounded Guardians in the Vale of Mists. Progress: I did not know that these castoffs from the rift could affect us so much...",rewardGold=335000,rewardXP=12170,rewardItems={243595,256334,256335},rewardChoices={256334,256335},rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=237236}},ends={{npcID=241070}},coords={x=0.62,y=0.546,source="quest_giver",zoneID=15355},questType="standard"},
[86856] = {id=86856,name="Dampening the Call",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Amarakk told me how to prepare Alndust to create the salve. In small doses, Alndust can strengthen the mind against madness and terror. It offers clarity and peace, but only if expertly employed. I could use your help to set an anchor to this place, $p. The ritual is delicate, and failure could be disastrous.",objectivesText="Help Orweyna create the Alndust Filter at the Vale of Mists. Progress: The process sounded simple enough--well within my abilities. But I appreciate your presence here to ground me.",rewardGold=170800,rewardXP=6085,rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=241070}},ends={{npcID=241070}},coords={x=0.618,y=0.544,source="quest_giver",zoneID=15355},questType="standard"},
[86857] = {id=86857,name="Descent into the Rift",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="With this, I will be able to venture down into the Rift of Aln. I will not have long, so we should not dawdle. Let us find Amarakk and gain his help.",objectivesText="Find the Wards of the Shul'ka in the Rift of Aln to find Amarakk .",rewardGold=341600,rewardXP=12170,rewardItems={246407},rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=241070}},ends={{npcID=237284}},coords={x=0.618,y=0.544,source="quest_giver",zoneID=15355},questType="standard"},
[86858] = {id=86858,name="The Madness Roots Deep",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="I found you while I was in the middle of one of my duties. Someone has spent too long within the rift and has fallen prey to the call of the goddess. I must rescue him and send him back to where he belongs. Help me with this task, and I will help you.",objectivesText="Defeat On'hiea in the Rift of Aln. Progress: We can save him!",rewardGold=335000,rewardXP=12170,rewardItems={256199,256207,256215,256223},rewardChoices={256199,256207,256215,256223},rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=237284}},ends={{npcID=237284}},coords={x=0.61,y=0.572,source="quest_giver",zoneID=15355},questType="standard"},
[86859] = {id=86859,name="Grinding Out a Solution",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="I have been pondering what Hagar could have meant from the moment Orweyna mentioned an answer to your problems. There are no mystical fountains--no weapons. Everything in the rift is created from the same source: Alndust, the distillation of the influence of the goddess. If we hunt a large manifestation, you will have the power of creation in its purest form. We cannot defeat it without help. Search the rift and look for fungi large enough to cultivate. I can use them to give us an edge.",objectivesText="Find 5 Alngrown Fungus in the Rift of Aln. Progress: Any advantage that we can have against the manifestation will give us a better chance to survive.",rewardGold=341600,rewardXP=12170,rewardItems={238651},rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=237284}},ends={{npcID=237284}},coords={x=0.61,y=0.572,source="quest_giver",zoneID=15355},questType="standard"},
[86860] = {id=86860,name="Before They Grow",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Within every creature that roams the Rift of Aln thrums a gathering of the foundation of the goddess's influence. This Alndust yearns to merge with others of its ilk. Part of my duties as the Shul'ka is to make sure to keep the number of large manifestations low so they do not overwhelm the Den. It is easiest to do that while they are small. Take this spear. You may use it to shatter the smaller creatures down to... trivial sizes.",objectivesText="Use Amarakk's Influence to defeat Aln Mites and creatures in the Rift of Aln.",rewardGold=341600,rewardXP=12170,rewardItems={239131},rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=237284}},ends={{npcID=237284}},coords={x=0.61,y=0.572,source="quest_giver",zoneID=15355},questType="standard"},
[86861] = {id=86861,name="Herding Manifestations",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="We are preparing to fight a giant manifestation. Let me emphasize this again. We must fight just one. If we fight two at a time, we would have no chance of survival. Place these wards around the rift to draw the others away. They will not last long... but we will need every advantage we can gain.",objectivesText="Place 3 Wards around the Rift of Aln. Progress: These wars are a creation of my own making. They attack the larger creatures toward them by mimicking their reaction to food.",rewardGold=341600,rewardXP=12170,rewardItems={252045},rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=237284}},ends={{npcID=237284}},coords={x=0.61,y=0.572,source="quest_giver",zoneID=15355},questType="standard"},
[86862] = {id=86862,name="The Greater They Aln",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="We have one chance at this only. I pray we have prepared enough.",objectivesText="Defeat the Aln Manifestation and gather its components in the Rift of Aln. Progress: The power of the Rift of Aln is beyond mortal comprehension. What we are doing is simply borrowing some of it for a brief moment.",rewardGold=683200,rewardXP=15215,rewardItems={238738,252956,252957,259477},rewardChoices={252956,259477},rewardCurrencies={{id=3316,amount=20},{id=3370,amount=100}},starts={{npcID=237284}},ends={{npcID=237284}},coords={x=0.61,y=0.572,source="quest_giver",zoneID=15355},questType="standard"},
[86864] = {id=86864,name="Watch the Den",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Finally, we have a moment to breathe. This is where we feel closest to the goddess--we are below the Cradle where she used to rest. The elders will not allow us to use any of the Alndust they have gathered over the centuries. They see only what the goddess asked of us before, not what her world needs now. Alndust is rare, but there are ways to get it. Ask around. I will check... elsewhere.",objectivesText="Speak to the Innkeeper, Renown Quartermaster, and the Flight Master at the Den. Progress: I hope that you will be able to rest here. You must know how to navigate this place.",rewardGold=34100,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3370,amount=10}},starts={{npcID=237860}},ends={{npcID=237234}},coords={x=0.444,y=0.524,source="quest_giver",zoneID=15921},questType="standard"},
[86865] = {id=86865,name="In Search of the Problem",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="We did what Hagar asked us to do. The next step will be to test this on something--or someone--afflicted with the Lightbloom. It may be difficult to find the Lightbloom in enough quantities in Harandar , but I believe we will find what we need at Har'alnor. I will meet you there!",objectivesText="Meet Orweyna at Har'alnor.",rewardGold=170800,rewardXP=6085,rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=237234}},ends={{npcID=237295}},coords={x=0.542,y=0.556,source="quest_giver",zoneID=15355},questType="standard"},
[86866] = {id=86866,name="Can We Heal This?",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="The rutaani have escaped their nearby villages to Har'alnor. The guards have told me that some of them have been afflicted with the Lightbloom, yet have not succumbed to its effects. This may be our best opportunity to test the Alndust's powers. Time is of the essence!",objectivesText="Use the Greater Alndust on the Afflicted Rutaani at Har'alnor. Progress: This is it, <name>. The moment of truth. Do we have an answer for the problems on Azeroth?",rewardGold=341600,rewardXP=12170,rewardItems={254319},rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=237325}},ends={{npcID=237356}},coords={x=0.314,y=0.648,source="quest_giver",zoneID=15355},questType="standard"},
[86867] = {id=86867,name="Into the Lightbloom",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="We've gathered the haranir we have available and distributed the Alndust. We have everything we need, but they need to be able to safely enter the area. Scouts have told us that the creatures spreading the Lightbloom are protected by a shield. We must stop them. We will also need to thin their numbers. Get on the petalwing, , and let's clear the way.",objectivesText="Ride on the Petalwing, destroy the shields protecting 4 Lightbloom Spreaders, and defeat Lightbloom creatures in the Blinding Bloom. Progress: We ride together!",rewardGold=638000,rewardXP=15215,rewardItems={253467},rewardCurrencies={{id=3316,amount=20},{id=3370,amount=100}},starts={{npcID=237356}},ends={{npcID=237356}},coords={x=0.306,y=0.772,source="quest_giver",zoneID=15355},questType="standard"},
[86868] = {id=86868,name="Goodwill Tour",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=16194,mapID=2536,description="The situation here is far worse than I imagined. The Twilight's Blade and their leader, Mor'duun, have completely overrun this city. We will use this opportunity to show the Amani how efficient we are at eliminating forces of the Void. Perhaps that will help convince them to stall hostilities between our people... at least until the current threat has passed.",objectivesText="Kill 10 Invading Shadows while traveling deeper into the city of Atal'Aman.",rewardGold=341600,rewardXP=12170,rewardItems={248551,248552,248553,248554},rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=236485}},ends={{npcID=236570}},coords={x=0.054,y=0.472,source="quest_giver",zoneID=16194},questType="standard"},
[86874] = {id=86874,name="Culling the Light",level=83,requiredLevel=83,faction="horde",expansion=11,zoneID=15355,mapID=2413,rewardGold=683200,rewardXP=15215,starts={{npcID=237356,x=0.306,y=0.772,zoneID=15355}},ends={{npcID=237356,x=0.306,y=0.772,zoneID=15355}},coords={x=0.306,y=0.772,source="quest_giver",zoneID=15355},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Lightbloom curbed"}},worldTaskTitle="Culling the Light"},
[86877] = {id=86877,name="Righteous Pruning",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="This is a threat that could destroy all of Harandar if left unchecked. That's why we will pull this out at the root. The ruutani who did not have the time to escape this place must be fully corrupted by now. Unfortunate, but it makes our plan of attack simple. Their leaders must be spreading the Lightbloom. We must strike them down.",objectivesText="Kill 4 Lightblinded Sap Weavers in the Blinding Bloom. Progress: If these leaders are allowed to thrive, they will gather more forces to the Lightbloom. We can't allow that to happen.",rewardGold=670000,rewardXP=15215,rewardItems={256198,256206,256214,256222},rewardChoices={256198,256206,256214,256222},rewardCurrencies={{id=3316,amount=20},{id=3370,amount=100}},starts={{npcID=237356}},ends={{npcID=237356}},coords={x=0.306,y=0.772,source="quest_giver",zoneID=15355},questType="standard"},
[86880] = {id=86880,name="Our Beloved, Returned",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="The haranir had a presence by the roots of Shaladrassil, as a sign of goodwill with the cultures that live within our home. When the guards retreated, they left some of our treasured mementos and artifacts. Since the spread of the Lightbloom has been greater than I ever expected, I do not know when we'll be able to come back. Let's find those artifacts in the Blinding Bloom and bring them home.",objectivesText="Recover 6 Haranir Artifacts in the Blinding Bloom. Progress: It would be good to bring some of these items back in our hands.",rewardGold=335000,rewardXP=12170,rewardItems={238792},rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=237356}},ends={{npcID=237356}},coords={x=0.306,y=0.772,source="quest_giver",zoneID=15355},questType="standard"},
[86881] = {id=86881,name="At the Root",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="The growths that help them spread the Lightbloom so quickly should be vulnerable after your attack from the air, but we still need to destroy them. Return to the Blinding Bloom and uproot the spreaders before they can recover from our attack.",objectivesText="Destroy the Lightbloom Spreaders in the Blinding Bloom. Progress: We need to stop the spread of the Lightbloom, lest it take over all of Harandar .",rewardGold=341600,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=237356}},ends={{npcID=237356}},coords={x=0.306,y=0.772,source="quest_giver",zoneID=15355},questType="standard"},
[86882] = {id=86882,name="Alndust in Right Hands",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="We can now go to the roots of Shaladrassil and stop the Lightbloom spreading even further into Harandar . We have enough Alndust to inoculate any haranir who are willing to risk their lives to follow us into battle. Find them, $p, and give them the Alndust.",objectivesText="Give Alndust to 5 haranir around Har'alnor and the Blinding Bloom. Progress: I know that my people are ready to step up to the challenge.",rewardGold=341600,rewardXP=12170,rewardItems={256197,256205,256213,256221},rewardChoices={256197,256205,256213,256221},rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=237356}},ends={{npcID=237356}},coords={x=0.306,y=0.772,source="quest_giver",zoneID=15355},questType="standard"},
[86883] = {id=86883,name="The Frenzied March",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15968,mapID=2413,description="Halduron's news is dire. If the Lightbloom is frenzying on the surface, then the danger has grown far more quickly than we were prepared to reckon with. We must make for Eversong at once. I will stand against any threat to Aln'hara's creation, be it here or in the world above... and I will do it alone, if I must.",objectivesText="Return to Eversong Forest.",rewardGold=33500,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3370,amount=10}},starts={{npcID=241742}},ends={{npcID=237361}},coords={x=0.5,y=0.542,source="quest_giver",zoneID=15355},questType="standard"},
[86884] = {id=86884,name="Cull and Burn",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15968,mapID=2395,description="Simply culling these creatures is not sufficient. If their bodies are left unattended, the Light will seep from their remains and spread through the soil to the surrounding foliage. We must take more drastic measures. Gather the bones of the creatures you slay. If we burn them, perhaps we can prevent their further spread through the roots of this forest.",objectivesText="Collect 10 Corrupted Bones from Lightbloom-Infested wildlife. Progress: Do not delay. The longer we wait to cull this growth, the more of this forest the sin'dorei will lose.",rewardGold=335000,rewardXP=12170,rewardItems={238196,256224,256225},rewardChoices={256224,256225},rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=237361}},ends={{npcID=237361}},coords={x=0.622,y=0.594,source="quest_giver",zoneID=15968},questType="standard"},
[86885] = {id=86885,name="Stem the Tides",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15968,mapID=2395,description="When the Farstriders first discovered the Lightbloom, we thought it to be merely an aesthetic change--a small quirk of the Sunwell's influence. Would that we knew then what we know now. These Light-frenzied rootways must lead all the way back to Harandar . If we don't close them, it won't matter how many of these damned things I bring down. Close the rootways and we might have a fighting chance.",objectivesText="Burn 5 Lightfrenzy Portalways. Progress: What are you waiting for? Every moment that passes, more of those things filter through. Our odds are scant enough as it is.",rewardGold=341600,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=237465}},ends={{npcID=237465}},coords={x=0.622,y=0.594,source="quest_giver",zoneID=15968},questType="standard"},
[86887] = {id=86887,name="Expeditious Retreat",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15968,mapID=2395,description="I have a way to stop the Lightbloom from spreading further through the forest, but it isn't exactly a delicate touch. Normally, I'd never dream of resorting to a controlled burn in such a healthy portion of Eversong... but the frenzy is spreading too quickly, and we are running out of options. I've sounded the retreat to my Farstriders, but some of them haven't responded. I need you to find any rangers in particularly sticky situations, and lend your aid in securing their escape.",objectivesText="Rescue 3 Beleaguered Farstriders. Progress: We're short on time, <name>. I can't execute my plan if we have Farstriders still in the field.",rewardGold=315900,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=237465}},ends={{npcID=241130}},coords={x=0.622,y=0.594,source="quest_giver",zoneID=15968},questType="standard"},
[86890] = {id=86890,name="Tell the People What You Have Seen",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15921,mapID=2413,description="We may have stemmed the malignant growth, but we have so many more questions than answers. How did this happen? How did this grow so much? How did Ruia not understand the extent of the calamity? $p, we must return to the Cradle immediately. The elders must know what happened today.",objectivesText="Return to the Den to speak to the Elders. Progress: I only pray that they are more receptive to the truth this time around.",rewardGold=322100,rewardXP=12170,rewardItems={256228,256229},rewardChoices={256228,256229},rewardCurrencies={{id=3316,amount=25},{id=3370,amount=1500}},starts={{npcID=237356}},ends={{npcID=241742}},coords={x=0.306,y=0.772,source="quest_giver",zoneID=15355},questType="standard"},
[86891] = {id=86891,name="A Last Resort",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15968,mapID=2395,description="With our ground forces pulled back, our position will be overwhelmed in a matter of minutes. It's time to execute our gambit. Rommath and the Magisters have provided us a mana gem that can be used to overload Lash'ra's runestones. Take it, and infuse the stones with the mana contained therein. That will set the stage for the Magisters' ritual: to detonate the runestones and burn the entirety of Lash'ra to the ground. We just have to hope the Lightbloom cannot survive in an inferno.",objectivesText="Overload 3 Phoenixfire Runestones.",rewardGold=341600,rewardXP=12170,rewardItems={254878},rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=237465}},ends={{npcID=241130}},coords={x=0.622,y=0.594,source="quest_giver",zoneID=15968},questType="standard"},
[86892] = {id=86892,name="Survive",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15968,mapID=2395,description="Our retreat to safer ground has not gone unnoticed. The rutaani mark us at every turn, and now they mean to cross the river. We have to buy Rommath and the Magisters as much time as we can. If we fail here, the whole of Eversong could be lost. Stand tall. Do not falter. And do your best not to die.",objectivesText="Survive the Lightbloom onslaught. Progress: We do not know when the frenzy will push past the lakeshore and encroach upon our position. Better to have Rommath start the ritual sooner rather than later.",rewardGold=670000,rewardXP=15215,rewardItems={256192,256200,256208,256216},rewardChoices={256192,256200,256208,256216},rewardCurrencies={{id=3316,amount=20},{id=3370,amount=100}},starts={{npcID=237361}},ends={{npcID=237361}},coords={x=0.622,y=0.594,source="quest_giver",zoneID=15968},questType="standard"},
[86894] = {id=86894,name="The Gift of Aln'hara",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15968,mapID=2395,description="Ruia has always been a zealous advocate, but this behavior is beyond the pale. The Lightbloom must be affecting him, driving him to these dangerous lengths. But we do not have to be like him. This forest need not fall to the bloom like Shaladrassil's roots did. The Hara'ti brought enough Alndust to bolster our allies against corruption, and prevent the frenzy from spreading further. Together, you and I shall spread Aln'hara's gift across the forest. This frenzy shall advance no further.",objectivesText="Use the Alndust to combat the Lightbloom frenzy in Lightbloom Lash'ra. Progress: Alndust is no mere common reagent. We must be precious about its use. For my people, though, I will not hesitate to give all I have.",rewardGold=325300,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=237361}},ends={{npcID=237361}},coords={x=0.622,y=0.594,source="quest_giver",zoneID=15968},questType="standard"},
[86896] = {id=86896,name="Light Finds a Way",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15968,mapID=2395,description="I am an expert in the fauna of Eversong, and I can say with certainty that the vast majority of the wildlife here tend to be of fairly average size. But these Light-frenzied saptors are decidedly, unequivocally not. One bite from those thorny jaws could claim the lives of half a dozen Farstriders, if they are caught unawares. My rangers have their quivers full culling the chaff alongside the haranir. See to it that those towering tyrannosaptors don't catch them unawares.",objectivesText="Slay 3 Lightfrenzy Tyrannosaptors in Lightbloom Lash'ra.",rewardGold=341600,rewardXP=12170,rewardItems={247234},rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=241130}},ends={{npcID=237465}},coords={x=0.586,y=0.572,source="quest_giver",zoneID=15968},questType="standard"},
[86897] = {id=86897,name="Quelling the Frenzy",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15968,mapID=2395,description="The day is nearly won. The sin'dorei cull every new sprout that blooms, and the Hara'ti ward the surrounding wilds against the frenzy's influence. All that yet remains is to remove this lightbound serpent's misguided head. Rootwarden Ruia has opposed our every action and shouted down our every word. But he is still a Rootwarden, and one with the power of a frenzying Lightbloom host at his beck and call. He is strong. But he does not walk with Aln'hara. It is time to end this.",objectivesText="Confront Lightwarden Ruia .",rewardGold=683200,rewardXP=15215,rewardItems={252957,259896},rewardChoices={252957,259896},rewardCurrencies={{id=3316,amount=20},{id=3370,amount=100}},starts={{npcID=237361}},ends={{npcID=241704}},coords={x=0.622,y=0.594,source="quest_giver",zoneID=15968},questType="standard"},
[86898] = {id=86898,name="Rise of the Haranir",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15969,mapID=2395,description="It is done. The frenzy is routed, the Rootwarden has fled, and the sin'dorei have reclaimed control of their forests. I can scarcely believe it, but... we succeeded, . By Aln'hara's grace, we found a path forward. Now Halduron's people invite us to their den. I am not fond of your surface-cities, but... You have aided me so many times, my friend. It is time that the Hara'ti reached out hands of our own.",objectivesText="Meet Orweyna and Halduron in the Gardens of Remembrance in Silvermoon City.",rewardGold=170800,rewardXP=6085,rewardCurrencies={{id=3316,amount=25},{id=3370,amount=1500}},starts={{npcID=241704}},ends={{npcID=255822}},coords={x=0.584,y=0.554,source="quest_giver",zoneID=15968},questType="standard"},
[86899] = {id=86899,name="The Root Cause",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2395,description="The rutaani who attacked Silvermoon come from my homeland, Harandar . This Lightbloom infection is new, however. The time has come for me to return to my people. I will face their judgement, and explain my actions. If the Lightbloom has spread, I must warn my people of the danger. If you're willing to join me, I will take you and your insistent friend through the rootways to Harandar . Let me know when you are ready to go.",objectivesText="Take the portal and meet Orweyna in Harandar .",rewardGold=34100,rewardXP=1520,starts={{npcID=236704}},ends={{npcID=237480}},coords={x=0.454,y=0.454,source="quest_giver",zoneID=15968},questType="standard"},
[86900] = {id=86900,name="To Har'athir",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="All of the world's roots grow toward our homeland. The ones above you are mighty, but new--born of a fledgling World Tree you call Amirdrassil. As far as World Trees go, it is a strange one. But its nature matters less than its reach. Any roots that seek to protect our world from harm are worth protecting. Let us follow the road down to Har'athir and check in with the Rootwarden. We will ask if he's noticed signs of Lightbloom yet.",objectivesText="Follow Orweyna into Harandar .",rewardGold=341600,rewardXP=12170,rewardItems={256226,256227},rewardChoices={256226,256227},starts={{npcID=237480}},ends={{npcID=239525}},coords={x=0.756,y=0.536,source="quest_giver",zoneID=15355},questType="standard"},
[86901] = {id=86901,name="The Rift and the Den",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="As I suspected, the elders are quite upset with my actions. Now that I have seen the children and Ku'paal to safety, I am ready to face the Council. I will do what I can to make them see that the Lightbloom is a threat, and to enable your ability to move freely through Harandar . Petalvane will carry you safely to the Den. Let us make haste.",objectivesText="Ride Petalvane to the Den.",rewardGold=34100,rewardXP=1520,starts={{npcID=237483}},ends={{npcID=237345}},coords={x=0.7,y=0.514,source="quest_giver",zoneID=15355},questType="standard"},
[86902] = {id=86902,name="Relinquishing Relics",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=16215,mapID=2424,description="My staff bought us time in the effort to hold back the Void, but these relics will be a more powerful aid. Let us hope it will be enough. Quickly, deliver these relics to our friends.",rewardGold=335000,rewardXP=12170,rewardItems={257240},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=251355,x=0.526,y=0.558,zoneID=16215}},ends={{npcID=251355,x=0.526,y=0.558,zoneID=16215}},coords={x=0.526,y=0.558,source="quest_giver",zoneID=16215},questType="world",worldTaskTitle="Relinquishing Relics"},
[86903] = {id=86903,name="The Arcantina",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=10473,mapID=2541,description="$p, there's a place that we used during the Second War, when we missed our homes an' needed to remember Azeroth. Somethin' of a retreat an' a sanctuary for those who've seen too much fighting--too much pain. Over time, we've brought friends and allies there. In recent years, members o' the Horde have been invited as well. We call it the Arcantina. I believe Arator , and you, would benefit from some respite there. Use this key to make a portal.",rewardGold=683200,rewardXP=15215,rewardItems={248131,253629,254838},rewardCurrencies={{id=3316,amount=20},{id=3365,amount=100}},starts={{npcID=253125,x=0.406,y=0.66,zoneID=15969}},ends={{npcID=237502,x=0.508,y=0.604,zoneID=10473}},coords={x=0.406,y=0.66,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="The Arcantina"},
[86907] = {id=86907,name="The Den of Echoes",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Greetings, stranger. I am Elder Hagar . You have been granted permission to stay, as long as you pass through the trials of the Den of Echoes. Aln'hara will determine your fate, and you will learn about our people and customs. Let us meet at the caves.",objectivesText="Meet Hagar at the Den of Echoes.",rewardGold=32200,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3370,amount=10}},starts={{npcID=237332}},ends={{npcID=237567}},coords={x=0.44,y=0.542,source="quest_giver",zoneID=15921},questType="standard"},
[86909] = {id=86909,name="Unrestful Spirits",level=83,requiredLevel=83,faction="none",expansion=11,zoneID=15355,mapID=2413,rewardGold=319000,rewardXP=12170,questType="world",worldTaskTitle="Unrestful Spirits"},
[86910] = {id=86910,name="Koozat's Trample",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Koozat is usually very docile. This isn't like him at all. Please, find out what happened.",objectivesText="Follow Orweyna . Progress: Koozat is not usually a violent creature.",rewardGold=34100,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3370,amount=10}},starts={{npcID=237572}},ends={{npcID=240533}},coords={x=0.348,y=0.25,source="quest_giver",zoneID=15355},questType="standard"},
[86911] = {id=86911,name="Echoes and Memories",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="The history of the haranir has been recorded for tens of thousands of years in the caves within. The memories of our people are painted on the stone, that we might never forget where we came from and what our purpose is. You are the first outsiders to ever witness the Den of Echoes. When you touch the paintings, our ancestors will share our stories and struggles. Zur'ashar Kassameh awaits you within. He will guide you and Halduron on your journeys. I wish you luck.",objectivesText="Complete the first vision of the Den of Echoes. Progress: Our people have been here for tens of thousands of years, but it was not always so. Once, we lived on the surface as you do.",rewardGold=341600,rewardXP=12170,rewardItems={239014,246415},rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=237567}},ends={{npcID=239650}},coords={x=0.388,y=0.468,source="quest_giver",zoneID=15355},questType="standard"},
[86912] = {id=86912,name="Down the Rootways",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="You have gained a glimpse into our history. There is one trial yet remaining. If you survive, the goddess's blessing will be upon you, and the Council will not be able to deny your presence here. Descend now into the earth and follow in our ancestors' footsteps.",objectivesText="Complete the Gulf of Memories delve and obtain the Fragment of Revelation from its treasure room. Progress: You have survived the Gulf of Memories. Welcome to Har'mara, friend.",rewardGold=683200,rewardXP=15215,rewardItems={249620,249627,251512},rewardChoices={249620,249627},rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=243884}},ends={{npcID=240839}},coords={x=0.34,y=0.448,source="quest_giver",zoneID=15355},questType="standard"},
[86913] = {id=86913,name="A Hut in Har'mara",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="The others have gathered downstairs. Come. Orweyna is eager to see that you are in one piece.",objectivesText="Meet Orweyna in Har'mara.",rewardGold=34100,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3370,amount=10}},starts={{npcID=240839}},ends={{npcID=237786}},coords={x=0.348,y=0.25,source="quest_giver",zoneID=15355},questType="standard"},
[86914] = {id=86914,name="Tending to Har'mara",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Har'mara has long been a refuge for those who have removed themselves from the conflicts that often arise between the rutaani and the fungarians. Here, they learn how to live with one another. They work, play, and live together--balanced. You have learned much about the past of the haranir, including our deepest shame. Now you will see our current work: harmony.",objectivesText="Complete tasks in Har'mara. Progress: It is the natural state of the fungarians and the rutaani to spread themselves out. At times, this can lead to overgrowth and the crowding out of other species. Maintaining that balance is important, and is the duty the haranir fulfill as stewards of Harandar .",rewardGold=341600,rewardXP=12170,rewardItems={238024,256174,256175,256177,256180,256184,256186,256188,256190,256231,269982},rewardChoices={256174,256175,256177,256180,256184,256186,256188,256190,256231,269982},rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=237572}},ends={{npcID=237572}},coords={x=0.348,y=0.25,source="quest_giver",zoneID=15355},questType="standard"},
[86929] = {id=86929,name="The Council Assembles",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15921,mapID=2413,description="Guards collected Orweyna and took her to get ready to meet the Council. When you are ready, we should attend the gathering.",objectivesText="Attend the Council meeting. Progress: Orweyna will be judged for her actions.",rewardGold=341600,rewardXP=12170,rewardItems={256193,256201,256209,256217},rewardChoices={256193,256201,256209,256217},starts={{npcID=237345}},ends={{npcID=237332}},coords={x=0.548,y=0.512,source="quest_giver",zoneID=15355},questType="standard"},
[86930] = {id=86930,name="To Sow the Seed",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15921,mapID=2413,description="Eonka's seed from Rift of Aln is the clue we were looking for. The inhabitants and plants there seem immune to the Lightbloom! We must investigate the rift for ourselves. Let us return to the Den and plan our next moves.",objectivesText="Return to the Den.",rewardGold=335000,rewardXP=12170,rewardItems={256195,256203,256211,256219},rewardCurrencies={{id=3316,amount=25},{id=3370,amount=1500}},starts={{npcID=237786}},ends={{npcID=237860}},coords={x=0.348,y=0.25,source="quest_giver",zoneID=15355},questType="standard"},
[86942] = {id=86942,name="Culling the Spread",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Powdercap said that the visiting travelers were the first to show signs of the Lightbloom infection--right after you questioned them! Sadly, it seems Koozat has also fallen to the sickness. Take out the merchants and see to Koozat as well. He's far too dangerous a creature to be trampling around here.",objectivesText="Slay the visiting rutaani merchants and Koozat . Progress: I raised Koozat since he was small enough to fit in my hands. The Lightbloom does not discriminate who it infects.",rewardGold=644200,rewardXP=15215,rewardItems={256194,256202,256210,256218},rewardChoices={256194,256202,256210,256218},rewardCurrencies={{id=3316,amount=20},{id=3370,amount=100}},starts={{npcID=240533}},ends={{npcID=240533}},coords={x=0.356,y=0.252,source="quest_giver",zoneID=15355},questType="standard"},
[86944] = {id=86944,name="Seeds of the Rift",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="The situation is stabilizing, but let's make sure we're in the clear. I will see how Hagar is faring. Check on Eonka again and be sure that she's not showing any signs of Lightbloom. She is on an upper level in Hagar's Hut.",objectivesText="Check on Eonka . Progress: Let us hope Eonka is unchanged.",rewardGold=34100,rewardXP=1520,rewardItems={258623},rewardCurrencies={{id=3316,amount=5},{id=3370,amount=10}},starts={{npcID=240533}},ends={{npcID=237786}},coords={x=0.356,y=0.252,source="quest_giver",zoneID=15355},questType="standard"},
[86956] = {id=86956,name="The Traveling Flowers",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Orweyna mentioned that there are rutaani who are visiting from other villages. This is an opportunity for us to get to know what they're like when they're not Light-crazed. I will stay here to speak with Meeka. You should speak with the visiting rutaani to determine whether the Lightbloom has reached their homes.",objectivesText="Talk to the visiting rutaani merchants. Progress: We must stop the spread of the Lightbloom! Determining its spread will help us fight it in the long run.",rewardGold=256200,rewardXP=9130,rewardItems={262614},rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=237787}},ends={{npcID=237787}},coords={x=0.348,y=0.25,source="quest_giver",zoneID=15355},questType="standard"},
[86973] = {id=86973,name="Halting Harm in Har'mara",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Lightbloom-infected rutaani are attacking the village! Rizam and Teetem both succumbed to the infection. It looks like Eonka hasn't been affected, but we must handle the others. I will stay here and keep an eye on her. I need you to do what you can to protect Har'mara. Take out Rizam and Teetem as well.",objectivesText="Slay 8 Lightbloom rutaani.",rewardGold=335000,rewardXP=12170,rewardItems={245535},rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=240533}},ends={{npcID=240533}},coords={x=0.356,y=0.252,source="quest_giver",zoneID=15355},questType="standard"},
[86996] = {id=86996,name="Dark Places",level=88,requiredLevel=88,faction="none",expansion=11,zoneID=15458,mapID=2405,objectivesText="Unraveling Captive Rescued",rewardGold=309800,rewardXP=12845,questType="standard",db2Objectives={{orderIndex=0,type=0,amount=8,objectID=235710,text="Unraveling Captive Rescued"}},worldTaskTitle="Dark Places"},
[86997] = {id=86997,name="Spellbook Scuffle",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="You there! I've heard whispers of your so-called \"heroics,\" but I'm convinced they must be false. For if they were true, it would mean you would have achieved more than I, Tytalor Goldenblade --the finest, smartest, and most handsome mage at this academy. Therefore, I challenge you to prove your worth, if you are not a coward. The arcane tomes will make a fine warm-up for you... if you survive. Tear out their pages and prove you're not a complete fraud.",objectivesText="Collect 9 Torn Spellbook Pages from Arcane Tomes in Sunstrider Isle. Progress: Well? Are the pages in your possession, or will you admit your deception?",rewardGold=341600,rewardXP=11765,rewardItems={235808},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=237873}},ends={{npcID=237904}},coords={x=0.394,y=0.174,source="quest_giver",zoneID=15968},questType="standard"},
[86998] = {id=86998,name="Training Arc",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="Hah! You actually managed to defeat the spell books? I suppose even a blind squirrel finds a nut once in a while. Don't get too proud of yourself though! My followers ahead won't be so easily dismantled by your flailing. When you inevitably fail, I'll be sure to remember this as the moment your arrogance got the better of you.",objectivesText="Best 6 mages in Sunstrider Isle. Progress: Ah! So you've come crawling back after failing to defeat even my least competent followers?",rewardGold=341600,rewardXP=11765,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=237904}},ends={{npcID=237905}},coords={x=0.394,y=0.174,source="quest_giver",zoneID=15968},questType="standard"},
[87002] = {id=87002,name="Academic Aspirations",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="How charming. You've actually made it this far thinking you've proven something. Let me make it clear--nothing you've done compares to my prowess. You've struggled through the simplest of challenges, but now you'll face me. Meet me at the top of this tower and I'll show you exactly how far beneath me you really are.",objectivesText="Defeat Tytalor Goldenblade in Sunstrider Isle.",rewardGold=638000,rewardXP=14705,rewardItems={263324,263325},rewardChoices={263324,263325},rewardCurrencies={{id=3316,amount=25},{id=3365,amount=250}},starts={{npcID=237905}},ends={{npcID=237907}},coords={x=0.384,y=0.186,source="quest_giver",zoneID=15968},questType="standard"},
[87254] = {id=87254,name="Curse Cleanse",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Warlord Akutu could die at any moment, and you brought no pango liver? Bah! Each day I scream at Kulzi to tell me how to cure him. I say, \"you force me to use de forbidden liver ritual!\" But de loa says nothin'. Loa Speaker Sij'ta 's eyes seem angry but also afraid.> If he won't tell us what is wrong, then we will have to use de pango liver ritual. It is rumored to be a potent but forbidden ritual. Get de largest pango liver you can find. There is no time to waste.",rewardGold=341600,rewardXP=11765,rewardItems={245982},rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=237953}},ends={{npcID=237953}},coords={x=0.404,y=0.494,source="quest_giver",zoneID=15947},questType="standard"},
[87256] = {id=87256,name="Alternative Medicine",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15947,mapID=2437,description="I can't leave de warlord's side. I swore an oath to Zul'jin himself to save de Amani warlords at any cost. If I leave, he is sure to die. He is already cold as death! If he weren't movin' and talkin', I'd swear he was already dead. There are things we can do without de loa's diagnosis. Bring me de bloodweed branches dat grow below de shrine. They're very important to de healin' rituals we can still do. Gather me a heap of dem.",objectivesText="Collect Bloodweed Branches from shrubs below the Shrine of Kulzi. Progress: Dey must be pungent if dey gonna work.",rewardGold=341600,rewardXP=11765,rewardItems={235912},rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=237953}},ends={{npcID=237953}},coords={x=0.404,y=0.494,source="quest_giver",zoneID=15947},questType="standard"},
[87267] = {id=87267,name="Demands Unmet",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Good, we have de branches. We will use them! Above us are de altars where we bring de injured to Kulzi for healin'... Wait. I already did this. I brought Akutu up there, an' laid him upon one of de altars. Dat is where he held my hand, made me swear to... What? Why can't I remember? You--you're here for a reason. Go get answers. If de loa appears, tell him he's gotta fix dis--or else!",objectivesText="Confront Kulzi , the Loa of Medicine. Progress: Kulzi cannot keep ignorin' us!",rewardGold=85400,rewardXP=2940,rewardItems={246210},rewardCurrencies={{id=3316,amount=5},{id=3354,amount=10}},starts={{npcID=237953}},ends={{npcID=237953}},coords={x=0.404,y=0.494,source="quest_giver",zoneID=15947},questType="standard"},
[87268] = {id=87268,name="Required Repentance",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15947,mapID=2437,description="I remember dis staff. And I remember dat day. We are... dead, then. Akutu was near death from a battle in de city. He had some serious wounds. Kulzi said he could not heal dem. Akutu would not accept dis. He wanted me to use de staff--a hexlord staff--on Kulzi to force him to heal. And then... I think I broke it. Show de other spirits here dis staff. Maybe we can piece together what happened from their memories.",objectivesText="Use the staff to aid Forgetful Ghosts in remembering what happened at the Shrine of Kulzi. Progress: Show dem de staff. See what dey remember.",rewardGold=341600,rewardXP=11765,rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=237953}},ends={{npcID=237953}},coords={x=0.404,y=0.494,source="quest_giver",zoneID=15947},questType="standard"},
[87317] = {id=87317,name="Denial Denied",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15947,mapID=2437,description="So, I broke de staff. And everybody died. Maybe dis is my mistake. Sometimes it's too hard to say we made a mistake. And den we made even more mistakes. We in this deep, now. While you were talkin' to the others, I tried to get through to Akutu that we're dead. But he's not listenin'. All he does is blame others. Maybe I deserve it. Show Warlord Akutu de staff. Den take him to Kulzi. We need to try to talk to de loa. De pieces of dis puzzle are fallin' into place.",objectivesText="Help Warlord Akutu face the truth and speak to Kulzi. Progress: Why aren't ya helpin me?!",rewardGold=341600,rewardXP=11765,rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=237953}},ends={{npcID=246525}},coords={x=0.404,y=0.494,source="quest_giver",zoneID=15947},questType="standard"},
[87350] = {id=87350,name="Abundance: Loaknit Den",level=80,requiredLevel=80,faction="none",expansion=11,questType="standard",worldTaskTitle="Abundance: Loaknit Den"},
[87388] = {id=87388,name="A Bigger Beast",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="Return to Umbric? But we're on the brink of deeper understandings! Hypothesis: there exists an apex predator amongst these creatures that might hold immense power! And this predator's relationship with the Void could further our own understanding of the infinite darkness. Eradicate some of the smaller creatures and see if such a beast answers the call of violence!",objectivesText="Slay 8 Vicious Karions in the Bladeburrows. Progress: There is a connection between these beasts and the Void... not so unlike the ren'dorei.",rewardGold=341600,rewardXP=12845,rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=236908}},ends={{npcID=236908}},coords={x=0.412,y=0.616,source="quest_giver",zoneID=15458},questType="standard"},
[87391] = {id=87391,name="Sampling the Local Fare",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="This place is a food chain of ferocity and far too many teeth. Our studies grow more dangerous by the minute, but if Matrean insists on staying, we may as well assist him. We're studying a link between the nature of these creatures and the Void's accumulation here. Dispatch some of the beasts below and bring samples of their tissue back to me. We can study them to learn more of their connection with the Void.",objectivesText="Collect 30 Exotic Tissue Samples from creatures in the Bladeburrows. Progress: Can there even BE a ruler of such a chaotic animal kingdom?",rewardGold=341600,rewardXP=12845,rewardItems={235632},rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=236930}},ends={{npcID=236930}},coords={x=0.412,y=0.614,source="quest_giver",zoneID=15458},questType="standard"},
[87392] = {id=87392,name="Cargo Conspiracy",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="The Sunwell's radiance may shine, but its Light has not purged the filth that festers within this city. Smugglers scuttle through the streets like vermin, preying upon the desperate and enriching the spineless. Yet, there are whispers of something fouler still--trade in wares so vile that even the Venture Company would recoil. I require someone to spy on each shipping company and find out which cloaks a smuggling ring. Will you stand with me, or will you turn away as the rot spreads?",objectivesText="Investigate shipping companies in Fairbreeze Village. Progress: So, what did our fine dockworkers have to say?",rewardGold=170800,rewardXP=5885,rewardItems={237722},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=238490}},ends={{npcID=238490}},coords={x=0.468,y=0.452,source="quest_giver",zoneID=15968},questType="standard"},
[87393] = {id=87393,name="Warranted Search",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="Tideborne Freight, is it? A name far too polished, like an ornate blade designed to distract from the blood it has shed. Smuggling through the port... but I suspect this venture involves something far more perilous than we think. We must act with haste before they set sail and vanish into the mists. Keep your weapons honed and your senses sharper. Make them understand that crossing me was a grave miscalculation.",objectivesText="\"Interrogate\" 12 Tideborne Freight sailors in Sunsail Anchorage. Progress: Back already? Let's hear it. What did you uncover about the Tideborne? And don't leave out any details",rewardGold=341600,rewardXP=11765,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=238490}},ends={{npcID=238505}},coords={x=0.468,y=0.452,source="quest_giver",zoneID=15968},questType="standard"},
[87394] = {id=87394,name="Supplier Surveillance",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="This note all but drips with guilt, but mere words alone will not bring down Tideborne Freight. I require undeniable proof--evidence so damning that not even their well-bribed magistrates can turn a blind eye. That is where you come in. Take this arcane recorder and make your way to the docks. Document their shipments, their crew--anything that reeks of smuggling. A single image can speak volumes, and I intend to make every word count.",objectivesText="Record evidence in Sunsail Anchorage. Progress: You're back, and with the recordings, I hope.",rewardGold=341600,rewardXP=11765,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=238490}},ends={{npcID=238505}},coords={x=0.468,y=0.452,source="quest_giver",zoneID=15968},questType="standard"},
[87395] = {id=87395,name="Below the Brine",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="Discarding crates into the ocean? How utterly desperate. Whatever they seek to conceal must be damning--sufficient enough to unravel their entire operation, should we recover it. Take a deep breath and retrieve it before the current sweeps it away. Every thread we pull unravels their scheme further. Soon there will be nothing left but the ruin of their own making.",objectivesText="Recover 12 Submerged Cargo Items in Sunsail Anchorage. Progress: So what did our friends at Tideborne Freight so desperately want to hide? Their scuttling cannot conceal their true intentions forever.",rewardGold=341600,rewardXP=11765,rewardItems={239022,242552},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=238505}},ends={{npcID=239368}},coords={x=0.394,y=0.45,source="quest_giver",zoneID=15968},questType="standard"},
[87396] = {id=87396,name="Dead to Rights",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="Tideborne's decision to discard crates into the ocean was no mere error. It was a calculated delivery. Pursue them, and ensure the naga are reminded of the grave consequences they face when they dare to cross us.",objectivesText="Defeat 10 Tideborne naga in Sunset Strand. Progress: Get after them!",rewardGold=319000,rewardXP=11765,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=239368}},ends={{npcID=239368}},coords={x=0.358,y=0.438,source="quest_giver",zoneID=15968},questType="standard"},
[87397] = {id=87397,name="Cargo Collateral",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="If the naga manage to siphon the remaining arcane energy from those unstable arcana, they will gain the very power they seek. Destroy, incinerate, shatter them--do whatever is necessary. Ensure not a single shard remains for the naga or Tideborne to exploit. I do not wish to see even the faintest trace of arcane energy linger.",objectivesText="Destroy 5 Smuggled Crates in Sunset Strand. Progress: I trust you gave that cargo a proper send-off.",rewardGold=319000,rewardXP=11765,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=239368}},ends={{npcID=239368}},coords={x=0.358,y=0.438,source="quest_giver",zoneID=15968},questType="standard"},
[87398] = {id=87398,name="Smuggler Showdown",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="The naga acted out of desperation. Tideborne's crew, however, is driven by arrogance. They sit smugly aboard their ship, convinced of their invulnerability and counting their ill-gotten wealth. It is time we put an end to that. Captain Bloodwake shall be made to answer for every crate, every transaction, and every transgression. Are you prepared to extract the truth?",objectivesText="Defeat Captain Dorynth Bloodwake in Sunsail Anchorage.",rewardGold=683200,rewardXP=14705,rewardItems={263447,263480,263481,263482,263484,263485,263486,263487},rewardChoices={263447,263480,263481,263482,263484,263485,263486,263487},rewardCurrencies={{id=3316,amount=25},{id=3365,amount=250}},starts={{npcID=239368}},ends={{npcID=244870}},coords={x=0.358,y=0.438,source="quest_giver",zoneID=15968},questType="standard"},
[87399] = {id=87399,name="Facing the Sun",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="This sanctum was studying the Lightbloom well before the incident at Fairbreeze. We had no reason to be concerned over their research up until that point. However, the last message we attempted to send never received a reply. And this doesn't look good now that we're here. We need to clear out some of the wildlife first, though. We cannot risk any contamination.",objectivesText="Kill 8 encroaching wildlife. Progress: How goes the hunt?",rewardGold=341600,rewardXP=11765,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=238083}},ends={{npcID=238083}},coords={x=0.504,y=0.782,source="quest_giver",zoneID=15968},questType="standard"},
[87400] = {id=87400,name="Scattered in Sunbeams",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="We've given the garden tenders some space to continue their work unimpeded. Hopefully they can keep this place pristine until Silvermoon has the chance to fix it up. But now we need to figure out where the missing scholars are. They were studying mana influence on plants in the gardens toward the back. Perhaps we'll find a sign of them there.",objectivesText="Find signs of what happened to the Sanctum's researchers.",rewardGold=341600,rewardXP=11765,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=238083}},ends={{npcID=238083}},coords={x=0.504,y=0.782,source="quest_giver",zoneID=15968},questType="standard"},
[87401] = {id=87401,name="Gardener Mishap",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="The sanctum door seems to be locked. Probably from the inside. I believe an arcane construct is used for heavy lifting and general upkeep alongside the treants. The core of it should override the lock on the door and work as a master key. I doubt it will just let us take it, so be careful.",objectivesText="Find a magical construct and retrieve its core. Progress: Yes?",rewardGold=341600,rewardXP=11765,rewardItems={238677},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=238084}},ends={{npcID=238084}},coords={x=0.504,y=0.78,source="quest_giver",zoneID=15968},questType="standard"},
[87402] = {id=87402,name="The Light Provides",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="We need to get into the Sanctum. Now. Burn away the roots on that door! And be prepared--nothing good can be behind it.",objectivesText="Open the door to the Sanctum of the Sun and deal with what lies beyond. Progress: We cannot wait.",rewardGold=638000,rewardXP=14705,rewardItems={246441,263326,263327,263328,263331},rewardChoices={263326,263327,263328,263331},rewardCurrencies={{id=3316,amount=25},{id=3365,amount=250}},starts={{npcID=238084}},ends={{npcID=238084}},coords={x=0.504,y=0.78,source="quest_giver",zoneID=15968},questType="standard"},
[87455] = {id=87455,name="Trials and Tabulations",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="In hindsight, we should have gone drinking in neutral territory. Gidwin and I were here in Silvermoon on vacation when the Fourth War broke out. We escaped the city but left behind a... rather large bar tab. Gidwin's run off to the place we were staying to find an expensive item we'd left behind, but he's late. Would you go find him while I keep this debt collector busy? He should have been back by now.",objectivesText="Find Gidwin Goldbraids in Silvermoon.",rewardGold=30900,rewardXP=1470,rewardCurrencies={{id=3316,amount=5},{id=3365,amount=10}},starts={{npcID=238730}},ends={{npcID=238834}},coords={x=0.576,y=0.688,source="quest_giver",zoneID=15969},questType="standard"},
[87456] = {id=87456,name="Souvenirs Scattered",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="When Tarenar and I escaped the city before, we left some things behind. An open bar tab, sure. But we'd also bought souvenirs for some of our friends. Could you look around for them? They're somewhere in this mess.",objectivesText="Find the souvenirs in Silvermoon. Progress: Have you found all the souvenirs? We got other things for the rest of our crew back in Suramar, but we didn't have time to mail these when we escaped.",rewardGold=170800,rewardXP=5885,rewardItems={237164,237165,237166},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=238732}},ends={{npcID=238748}},coords={x=0.334,y=0.892,source="quest_giver",zoneID=15969},questType="standard"},
[87457] = {id=87457,name="What We Do Best",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="That spider! It blasted me right as I walked in the door. I've been gooped by one spider too many, what with all the nerubians we've been punching lately! I saw something around its neck out of the corner of my eye. It's an artifact we found while fighting the Legion. It ought to fetch a good price. You just have to tear that spider's head off!",objectivesText="Kill Squatter and collect the Antique Necklace in Silvermoon. Progress: This necklace was in a camp we cleared of demons. Must've been for a ritual, but we stopped them from cursing it.",rewardGold=683200,rewardXP=14705,rewardItems={237167},rewardCurrencies={{id=3316,amount=20},{id=3365,amount=100}},starts={{npcID=238732}},ends={{npcID=238748}},coords={x=0.334,y=0.892,source="quest_giver",zoneID=15969},questType="standard"},
[87458] = {id=87458,name="Debts Paid",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="That's everything, I think. Can't believe it's been so long since the Fourth War. We left in such a rush. Let's get that necklace to Tarenar. He's been waiting long enough.",objectivesText="Return to Tarenar Sunstrike in Silvermoon.",rewardGold=34100,rewardXP=1470,rewardItems={263437,263438},rewardChoices={263437,263438},rewardCurrencies={{id=3316,amount=25},{id=3365,amount=250}},starts={{npcID=238748}},ends={{npcID=238730}},coords={x=0.334,y=0.892,source="quest_giver",zoneID=15969},questType="standard"},
[87540] = {id=87540,name="Begin the Sky Assaults",level=10,requiredLevel=10,faction="none",expansion=11,questType="standard"},
[87550] = {id=87550,name="Week 2: We're Really Taking Off",level=0,requiredLevel=0,faction="both",expansion=11,zoneID=14717,mapID=2248,description="It's Dastardly Duos' second week! Twice the brutality, twice the fun! Win a match this week for even more rewards!",rewardGold=34100,rewardItems={239440},starts={{npcID=234296}},ends={{npcID=234296}},coords={x=0.528,y=0.516,source="quest_giver",zoneID=14717},questType="standard"},
[87672] = {id=87672,name="Void is in the Air",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="We void elves all face the same risk... that should our resilience falter, madness awaits. The caves below are steeped in Void's vile touch. Void Surges erupt from the earth, creating a miasma of filth that fills the nesting grounds. Take this. It will capture the surges of dark energy bursting from the soil. We will study them safely back at the Ingress.",objectivesText="Capture 3 Void Surges in the Bladeburrows caves. Progress: The Voidstorm threatens our very existence. We cannot stay long.",rewardGold=341600,rewardXP=12845,rewardItems={267614},rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=236930}},ends={{npcID=236930}},coords={x=0.412,y=0.614,source="quest_giver",zoneID=15458},questType="standard"},
[87759] = {id=87759,name="Encapsulated Void",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=16648,mapID=2444,rewardXP=13690,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Subdue Void Creatures or Kill Players"},{orderIndex=2,type=0,amount=10,objectID=239434,text="Subdue Void Creatures"}},worldTaskTitle="Encapsulated Void",db2QuestInfoID=113,db2QuestInfoName="PvP World Quest"},
[88653] = {id=88653,name="Yolks on You",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="Our research has proven fruitful. I can feel the promise of power beckoning. Do you hear it, ? The apex predator calls to us. The beast must be nearby. We must gather tribute. Yes... we must offer it a gift of vitality! We must meet it bathed in the essence of the young... Some of the smaller creatures are nesting in the tunnels below. Break a few eggs and bathe in their juices. Then, perhaps, the beast will be drawn to the smell!",objectivesText="Bathe yourself in bestial fluids by destroying 15 Blistercreep Eggs in the Bladeburrows caves. Progress: So much flesh and bone and meat. How can we resist?",rewardGold=341600,rewardXP=12845,rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=236908}},ends={{npcID=236908}},coords={x=0.412,y=0.616,source="quest_giver",zoneID=15458},questType="standard"},
[88679] = {id=88679,name="Encountering the Unexpected",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=16648,mapID=2444,rewardXP=13690,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Subdue Creatures or Kill Players"},{orderIndex=2,type=0,amount=10,objectID=240349,text="Subdue Creatures"},{orderIndex=3,type=0,amount=10,objectID=240349,text="Subdue Creatures"}},worldTaskTitle="Encountering the Unexpected",db2QuestInfoID=113,db2QuestInfoName="PvP World Quest"},
[88696] = {id=88696,name="The Devouring Citadel",level=90,requiredLevel=90,faction="horde",expansion=11,zoneID=15458,mapID=2424,description="I must return to Silvermoon, but Turalyon has commanded all able-bodied champions of the Light to meet him at the muster point outside the Voidspire. The forces of the Devouring Host will fall, . One way, or the other.",objectivesText="Report to Turalyon at the Voidspire muster point: The Approach.",rewardGold=34100,rewardXP=1370,rewardCurrencies={{id=3316,amount=5},{id=3365,amount=10}},starts={{npcID=247414}},ends={{npcID=239810}},coords={x=0.53,y=0.586,source="quest_giver",zoneID=16215},questType="standard"},
[88697] = {id=88697,name="Clarity of Purpose",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,description="The ethereals on the nearby plateau are forcing us to ground our heavier weapons. We'll need to neutralize their turrets before we can begin our assault on the Voidspire. Speak to Umbric and he'll help you gain a tactical understanding of the battlefield.",objectivesText="Use Umbric's Void Scryer to observe the current tactical situation. Progress: Turalyon's focus is on the obstacle in front of him, but there's more to this fight than just armies and ramparts.",rewardGold=256200,rewardXP=10270,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=239810}},ends={{npcID=239828}},coords={x=0.454,y=0.63,source="quest_giver",zoneID=15458},questType="standard"},
[88698] = {id=88698,name="Master of Mayhem",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,description=", ethereals have been striking out from the Ethereum Overcroft, harassing our Vanguard forces where they find them. If you can bring the fight to them, it'll take the pressure off our muster. Can you do that for us?",objectivesText="Wreak havoc across the Ethereum Overcroft.",rewardGold=341600,rewardXP=13690,rewardItems={257164,257165,257166,257167},rewardChoices={257164,257165,257166,257167},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=239828}},ends={{npcID=239828}},coords={x=0.454,y=0.63,source="quest_giver",zoneID=15458},questType="standard"},
[88699] = {id=88699,name="Powerless",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,description="Their very life force is being siphoned to power the ethereals' guns, ! This cannot be allowed to continue. Head into the Ethereum Overcroft and free my fellow void elves from the ethereals' clutches. With their freedom, the turrets will have no power, and Turalyon will be able to launch his warframes.",objectivesText="Free the captured void elves to silence the Overcroft's turrets. Progress: We can't leave our people to be tortured like this.",rewardGold=683200,rewardXP=17110,rewardItems={257178,257179,257181,257182},rewardChoices={257178,257179,257181,257182},rewardCurrencies={{id=3316,amount=20},{id=3365,amount=100}},starts={{npcID=239828}},ends={{npcID=239828}},coords={x=0.454,y=0.63,source="quest_giver",zoneID=15458},questType="standard"},
[88700] = {id=88700,name="Two Tons of Metal and Holy Fire",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,description="Finally, the might of our warframes can be brought to bear. With the Overcroft's air batteries silenced, our powerful warframes will be able to perform strafing runs along the spire ramparts, softening the opposition to our siege. If you'd like, you may have the honor of piloting one of these warframes for the glory of the Light!",objectivesText="Piloting the Warframe, destroy defenders along the Voidspire ramparts. Progress: Soon, the Devouring Host will feel the wrath of the Light.",rewardGold=341600,rewardXP=13690,rewardItems={257187,257188,257189,257190,262610},rewardChoices={257187,257188,257189,257190},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=239810}},ends={{npcID=239810}},coords={x=0.454,y=0.63,source="quest_giver",zoneID=15458},questType="standard"},
[88701] = {id=88701,name="The Memory Remains",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,description="Our Vanguard forces have been harrying the Devouring Host, probing for weaknesses and gathering intelligence. Unfortunately, nearly all of them have succumbed to the Host. We are too late to help those who have fallen, but perhaps we can gather something to remember them by. Will you do this, ? Recover mementos of the fallen so they can be returned to those they fought to protect.",objectivesText="Recover Mementos from fallen Vanguard Scouts. Progress: Have you recovered them yet? I'm sure these keepsakes will be a source of comfort to their loved ones.",rewardGold=341600,rewardXP=13690,rewardItems={237827,257205,257206,257207,257208},rewardChoices={257205,257206,257207,257208},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=239827},{npcID=244093}},ends={{npcID=244093}},coords={x=0.46,y=0.648,source="quest_giver",zoneID=15458},questType="standard"},
[88702] = {id=88702,name="Aegis of the Redeemer",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,description="We're more than just an army, , even if my father doesn't see that. We're a fellowship, joined by a desire to protect those that matter to us, and those that don't have a protector of their own. And now, that protection extends to those wounded on the battlefield.",objectivesText="Rescue the beleaguered Vanguard forces. Progress: The Devouring Host is aptly-named. Those that join it or fight with it are consumed--one way, or the other.",rewardGold=341600,rewardXP=13690,rewardItems={257209,257210,257212,257213},rewardChoices={257209,257210,257212,257213},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=239827},{npcID=244093}},ends={{npcID=244093}},coords={x=0.46,y=0.648,source="quest_giver",zoneID=15458},questType="standard"},
[88703] = {id=88703,name="The Night Before",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,description="Vicious voidbeasts have been snatching our officers, . I've been told that you saw one from afar, through Umbric's void scryer. Those beasts are steeped in void energy, using their instinctual mastery of teleportation to strike at our most vulnerable before melting back into the shadows. Alleria has gone after them, and sent a request for another pair of eyes. You can find her at a campsite at the mouth of the gorge to the east. I'll mark it on your map.",objectivesText="Meet Alleria at her campsite. Progress: I'm glad you could make it. It's easier to track with some support at your side.",rewardGold=34100,rewardXP=1370,rewardCurrencies={{id=3316,amount=5},{id=3365,amount=10}},starts={{npcID=254884}},ends={{npcID=239826}},coords={x=0.462,y=0.632,source="quest_giver",zoneID=15458},questType="standard"},
[88704] = {id=88704,name="The Patient Hunter",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,description="These void beasts are elusive, able to open temporary void portals that they can use to move short distances instantaneously. They may be beneath Turalyon's notice, but they're having devastating effects on the Vanguard's morale. Between the two of us, I'm confident we can outmaneuver them.",objectivesText="Track down the void beasts in the gorge.",rewardGold=341600,rewardXP=13690,rewardItems={257214,257216,257217,257218},rewardChoices={257214,257216,257217,257218},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=239826}},ends={{npcID=243886}},coords={x=0.558,y=0.648,source="quest_giver",zoneID=15458},questType="standard"},
[88705] = {id=88705,name="Killing Blow",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,description="I heard about these beasts, but I thought it was a rumor. Void creatures appearing out of void portals, kidnapping and eating our officers... sounds like a load of bunk. I never thought it'd happen to me. There was a big one that got me, but he ran off. Please, let's get out of here before it comes back!",objectivesText="Escort Nadia safely from the cave.",rewardGold=683200,rewardXP=17110,rewardItems={257201,257202,257203,257204},rewardChoices={257201,257202,257203,257204},rewardCurrencies={{id=3316,amount=20},{id=3365,amount=100}},starts={{npcID=243886}},ends={{npcID=239826}},coords={x=0.562,y=0.65,source="quest_giver",zoneID=15458},questType="standard"},
[88706] = {id=88706,name="Nothing Stands Forever",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,description="With the Patriarch defeated, these cunning creatures should no longer pose a serious threat. Return to Turalyon and report on our success. I will join you all shortly.",objectivesText="Speak to Turalyon at the Voidspire muster point. Progress: My wife's hunting instinct is unmatched. If she chose that target, then it was surely a worthy one.",rewardGold=1024800,rewardXP=20540,rewardItems={257183,257184,257185,257186,264660},rewardCurrencies={{id=3316,amount=100},{id=3365,amount=1000}},starts={{npcID=239826}},ends={{npcID=239810}},coords={x=0.558,y=0.648,source="quest_giver",zoneID=15458},questType="standard"},
[88707] = {id=88707,name="The Stage is Set",level=90,requiredLevel=90,faction="alliance",expansion=11,zoneID=15458,mapID=2405,description="I know better than to question my wife when she's set on a target, but I trust that the target was chosen well. Our forces have acquitted themselves admirably, readying the battlefield for the main assault. Now listen, as the war council begins.",objectivesText="Return to Turalyon.",ends={{npcID=239810}},coords={mapID=2405,source="quest_giver",x=0.454,y=0.63},questType="standard"},
[88708] = {id=88708,name="Violent Conclusions",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="Our research here is complete. Conclusion: the Void is attracted to this realm due to its violent nature! The Voidstorm is a melting pot of torment and savagery. The Void was drawn to this aura of endless suffering. This place is a dire threat to the ren'dorei. However, our mission here is important. Let us take our findings back to the others. Can you help me snap Matrean out of it?",objectivesText="Convince Matrean to return to the Ingress. Progress: Was any of this worth it? Did we sin'dorei make a mistake marrying our fate to the Void?",rewardGold=683200,rewardXP=16055,rewardItems={243146},rewardCurrencies={{id=3316,amount=25},{id=3389,amount=250}},starts={{npcID=236930}},ends={{npcID=236930}},coords={x=0.412,y=0.614,source="quest_giver",zoneID=15458},questType="standard"},
[88709] = {id=88709,name="The Voidspire",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2405,description="At long last, we will ride to glory and dispense justice upon this vile creature who would levy the very Void itself against us. Today is the day Xal'atath's forces will face our judgement. Now is the hour we strike back! Come, let us make an end of this enemy.",objectivesText="Assault the Voidspire.",rewardGold=20496000,rewardXP=27380,rewardItems={257172,257173,257174,257175},rewardChoices={257172,257173,257174,257175},rewardCurrencies={{id=3316,amount=75},{id=3344,amount=10},{id=3365,amount=1500}},starts={{npcID=239810},{npcID=244298}},ends={{npcID=253603},{npcID=244297}},coords={x=0.454,y=0.63,source="quest_giver",zoneID=15458},questType="raid"},
[88710] = {id=88710,name="March on Quel'Danas",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16215,mapID=2424,description="Champion... friend... this is it. We must wrest the Darkwell from L'ura , or fall to the Void. We do not have the forces available for a second chance. Strike hard, and strike true. Watch your allies' flanks, and we will see this day won.",objectivesText="March on Quel'Danas. Progress: How does one rebuild in the wake of so much destruction?",rewardGold=20496000,rewardXP=27380,rewardItems={257736},rewardCurrencies={{id=3316,amount=100},{id=3344,amount=10},{id=3365,amount=1000}},starts={{npcID=243824},{npcID=245061}},ends={{npcID=243824},{npcID=244557}},coords={x=0.504,y=0.07,source="quest_giver",zoneID=16342},questType="raid"},
[88719] = {id=88719,name="A Voice from the Light",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16182,mapID=84,description="$p, you have been chosen. Xal'atath's army of the Void has descended upon the Sunwell. We have put our faith in the Light, and in turn, the Light has called upon the greatest champions of Azeroth. Answer this summons and stand against the Devouring Host! The fate of Quel'Danas and the world rests in your hands.",objectivesText="Accept the summons and travel to Quel'Danas to aid the Vanguard of the Light.",rewardGold=30900,rewardXP=1470,rewardItems={239151},starts={{npcID=241677}},ends={{npcID=236692}},coords={x=0.532,y=0.544,source="quest_giver",zoneID=1519},questType="standard"},
[88755] = {id=88755,name="Scholarly Pursuits",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="... a favor. My research partner Matrean and I are studying the local wildlife and their relationship to the Void. I've concluded my findings, but Matrean--reckless and obsessive as ever--insists there is more to discover. Can you help convince him to return here?",objectivesText="Meet with Kelia and Matrean in the Bladeburrows.",rewardGold=32200,rewardXP=1605,rewardCurrencies={{id=3316,amount=5},{id=3389,amount=10}},starts={{npcID=242700}},ends={{npcID=236908}},coords={x=0.358,y=0.586,source="quest_giver",zoneID=15458},questType="standard"},
[88768] = {id=88768,name="Agents of Darkness",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="When that shield goes down, Xal'atath's forces will be upon us in droves. If I'm going to detonate those manacells from afar, I'll need an opening. Thin the Devouring Host of their strongest, and the rest of Xal'atath's lackeys will be easier to fight off. We will make sure the shield goes down in the meantime. Good luck, .",objectivesText="Slay Nexus-King Salhadaar's lieutenants within Nexus-Point Mid'Ar. Progress: Have you taken them out?",rewardGold=341600,rewardXP=12845,rewardItems={263282},rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=235660}},ends={{npcID=235662}},coords={x=0.394,y=0.822,source="quest_giver",zoneID=15458},questType="standard"},
[88769] = {id=88769,name="The Battle of the Bridge",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16215,mapID=2393,description="Our elven allies have arrived. It is time to take the fight to the Darkwell. Xal'atath's forces hold the bridge and recently pushed into the harbor to reinforce their position. We must retake the harbor, launch our naval forces, and use a combined assault to take the bridge. Are you ready, ?",objectivesText="Complete the Battle of the Bridge scenario.",rewardGold=1024800,rewardXP=20540,rewardItems={258122,260233},rewardCurrencies={{id=3316,amount=100},{id=3365,amount=1000},{id=3391,amount=10}},starts={{npcID=240267}},ends={{npcID=245061}},coords={x=0.458,y=0.702,source="quest_giver",zoneID=15969},questType="standard"},
[88919] = {id=88919,name="Into the Darkway",level=90,requiredLevel=90,faction="horde",expansion=11,zoneID=16642,mapID=2393,description="Ulen's imposter may have escaped, but I suspect I know what the cult has been doing. The Twilight's Blade must be redirecting Suramar's mana flow. Without it being sent to the correct places, our awareness dulls, our golems wilt, and our entire society risks a mana withdrawal. There is only one place they would be able to exert control over our ley lines like this, and that would be the Arcway. Go. Find them and crush them. We will meet in Silvermoon when you are done.",objectivesText="Slay Twilight Imposter Gulkat in the Darkway Delve.",rewardGold=341600,rewardXP=13690,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50},{id=3391,amount=10}},starts={{npcID=256046}},ends={{npcID=254654}},questType="standard"},
[88920] = {id=88920,name="The Kaldorei",level=90,requiredLevel=90,faction="alliance",expansion=11,zoneID=15105,mapID=2393,description="We must retake the Darkwell and defeat L'ura before the world is torn asunder. We will need an army. No. Many armies. We need to reach out to the other elves. We should start with the kaldorei at Bel'ameth. Oculeth can teleport a small envoy there and we can present our request. Still... there has been much blood spilt among the elves. Vendettas that go far and strike deep. Hold on to hope, . It is all we have left.",objectivesText="Listen to Arator 's plan and then use Telemancer Oculeth's Portal to Bel'ameth . Progress: Are you ready to depart, Champion?",rewardGold=34100,rewardXP=1370,rewardCurrencies={{id=3316,amount=5},{id=3365,amount=10}},starts={{npcID=240267}},ends={{npcID=240334}},coords={x=0.458,y=0.702,source="quest_giver",zoneID=15969},questType="standard"},
[88922] = {id=88922,name="The Quel'dorei",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15968,mapID=2239,description=", while the kaldorei are mustering, I could use your help as a witness as I ask another group for aid. We will need the quel'dorei for what is to come, no matter how much some of the sin'dorei will protest. Oculeth has agreed to open a portal for the two of us to reach my aunt, Vereesa Windrunner, where she awaits us in Eversong. The sin'dorei will not come with me. Will you?",objectivesText="Take Oculeth's portal to Eversong Woods.",rewardGold=34100,rewardXP=1370,rewardCurrencies={{id=3316,amount=5},{id=3365,amount=10}},starts={{npcID=251335}},ends={{npcID=240296}},coords={x=0.482,y=0.704,source="quest_giver",zoneID=15105},questType="standard"},
[88923] = {id=88923,name="Children of the Stars",level=90,requiredLevel=90,faction="alliance",expansion=11,zoneID=15105,mapID=2239,description="You have traveled far to ask my people to march to yet another war. Maiev's fervor is blunt but not misplaced. While Silvermoon is under threat, let us not forget how many of my people burned when the sin'dorei failed to aid us at Teldrassil. However, Bel'ameth stands tall thanks to their aid. Let each present their reasoning and I shall then make my decision.",objectivesText="Have each envoy present their case to Shandris Feathermoon . Progress: Have you more to add?",rewardGold=170800,rewardXP=6850,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50},{id=3391,amount=10}},starts={{npcID=240334}},ends={{npcID=240334}},coords={x=0.482,y=0.706,source="quest_giver",zoneID=15105},questType="standard"},
[88925] = {id=88925,name="Awaken the Ancient of War",level=90,requiredLevel=90,faction="alliance",expansion=11,zoneID=15105,mapID=2239,description="If we are to muster for war, then there is an ancient we must bring with us or they will never forgive us. They are a mentor to myself and nearly every sentinel who serves the kaldorei. They are skilled in war, tactics, and rallying our greatest forces. And they fell asleep again. If history is any lesson, they will only awaken with the aid of someone who has known war. Will you seek out their grove keeper to learn how to awaken them?",objectivesText="Awaken the Ancient of War in Bel'ameth.",rewardGold=341600,rewardXP=13690,rewardChoices={251782,252957,264694,264701,264968,265027},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50},{id=3391,amount=10}},starts={{npcID=240334}},ends={{npcID=240334}},coords={x=0.482,y=0.706,source="quest_giver",zoneID=15105},questType="standard"},
[88926] = {id=88926,name="Return to Belanaar",level=90,requiredLevel=90,faction="none",expansion=11,description="This has been most productive. I suspected the kaldorei might be our the most difficult to convince, but Shandris has turned a new leaf of leadership for her people. Let this be the first of many successful partnerships between our people. Now swiftly, . Let us return home and prepare our defense.",objectivesText="Return to the docks in Bel'ameth with Lor'themar and Shandris.",rewardGold=34100,rewardXP=1370,questType="standard"},
[88927] = {id=88927,name="Awaken the Ancient Protector",level=90,requiredLevel=90,faction="alliance",expansion=11,zoneID=15105,mapID=2239,description="The enemy we face is a vast host with many capabilities. We will need to match their strength and versatility on the battlefield. To that end, I ask that you seek out Elder Verdantbark --an ancient protector who has long kept our people safe in times of war. They are stubborn and may require you to entice them in some fashion, but their grove keeper will know best how to do so.",objectivesText="Awaken the Ancient Protector in Bel'ameth.",rewardGold=341600,rewardXP=13690,rewardItems={257234,257237,257238,257249,257250,257251,257252,257256,257269,257271,257289},rewardChoices={257234,257237,257238,257249,257250,257251,257252,257256,257269,257271,257289},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50},{id=3391,amount=10}},starts={{npcID=240334}},ends={{npcID=240334}},coords={x=0.482,y=0.706,source="quest_giver",zoneID=15105},questType="standard"},
[88928] = {id=88928,name="The Shal'dorei",level=90,requiredLevel=90,faction="horde",expansion=11,zoneID=7637,mapID=2393,description="Champion, your timing is fortuitous. I sent the call for the armies of Suramar to muster, but they have not arrived yet. My seneschal should have alerted me if anything went wrong, but I have heard nothing. I plan to go to Suramar to investigate what is amiss. Would you join me? I may have need of your skills.",objectivesText="Use Oculeth's portal to travel to Suramar.",rewardGold=170800,rewardXP=6850,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50},{id=3391,amount=10}},starts={{npcID=240255}},ends={{npcID=250958}},coords={x=0.458,y=0.7,source="quest_giver",zoneID=15969},questType="standard"},
[88929] = {id=88929,name="An Illusion!",level=90,requiredLevel=90,faction="horde",expansion=11,zoneID=10425,mapID=680,description="The mana of Suramar is carefully cultivated, regulated, and controlled. It does not just randomly \"stop.\" Someone or something must be interfering with it. As you investigate the mana drain, I want you to occasionally dispel illusions in the area. Focus on those gathered here. I suspect not everyone is what they appear to be.",objectivesText="Dispel illusions in the Botanist's Garden that may be concealing sabotage or saboteurs. Progress: How many of my people have been taken by this evil?",rewardGold=341600,rewardXP=13690,rewardItems={248920},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50},{id=3391,amount=10}},starts={{npcID=240302}},ends={{npcID=240302}},coords={x=0.706,y=0.742,source="quest_giver",zoneID=7637},questType="standard"},
[88930] = {id=88930,name="Drained Mana",level=90,requiredLevel=90,faction="horde",expansion=11,zoneID=10425,mapID=680,description="I have received no word from High Arcanist Thalyssra for days! We have had many mana problems lately, so there is a chance her message spells were simply not able to be received.",objectivesText="Investigate the Mana Drain at the Botanist's Terrace in Suramar. Progress: Have you found anything?",rewardGold=341600,rewardXP=13690,rewardItems={264287,264288},rewardChoices={264287,264288},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50},{id=3391,amount=10}},starts={{npcID=250958}},ends={{npcID=250958}},coords={x=0.706,y=0.742,source="quest_giver",zoneID=7637},questType="standard"},
[88932] = {id=88932,name="With the Shal'dorei",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=7637,mapID=680,description="Our reinforcements will be arriving shortly. Some will stay behind to defend Suramar. The rest will join us in Silvermoon. Thank you for joining me in this journey, . Hold on to the memory of this place in the battles to come. It will shield you from any doubt the void plants within you. Accompany me back to Silvermoon. We have many allies to find yet if we are to prevail against this force.",objectivesText="Meet First Arcanist Thalyssra in the Sanctum of Light in Silvermoon City.",rewardGold=34100,rewardXP=1370,questType="standard"},
[88937] = {id=88937,name="Awaken the Ancient of Lore",level=90,requiredLevel=90,faction="alliance",expansion=11,zoneID=15105,mapID=2239,description="While our forces gather, I would like you to have the honor of awakening our ancients. There is a particular ancient of lore we will need awakened. They are a master of magic, a teacher of our druids, and a force that has walked alongside us across many battlefields. Find their grove keeper to learn what is needed to wake the ancient.",objectivesText="Awaken an Ancient of Lore in Bel'ameth. Progress: What stories does the ancient of lore have to tell, I wonder?",rewardGold=341600,rewardXP=13690,rewardItems={257242,257248,257254,257270,257284,257537,257686,257687,257688},rewardChoices={257242,257248,257254,257270,257284,257537,257686,257687,257688},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50},{id=3391,amount=10}},starts={{npcID=240334}},ends={{npcID=240334}},coords={x=0.482,y=0.706,source="quest_giver",zoneID=15105},questType="standard"},
[88938] = {id=88938,name="Symbols of the Past",level=90,requiredLevel=90,faction="alliance",expansion=11,zoneID=15968,mapID=2395,description="Arator 's warning is poignant. There will be no small amount of grief or even threats when we return to Silvermoon. I suspect Aethas and his Sunreavers will bar our passage if we enter without preparations. To that end, I have saved some precious remnants of our shared history from before the demise of Dalaran. Would you please gather them for me, ?",objectivesText="Gather the Relics of High King Anasterian Sunstrider. Progress: We were not able to preserve much from Dalaran before its fall. But every object recovered carries with it history, meaning, and lessons--lessons that any citizen of Quel'Thalas should understand on sight.",rewardGold=341600,rewardXP=13690,rewardItems={251899,251904,257171,264286},rewardChoices={257171,264286},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50},{id=3391,amount=10}},starts={{npcID=240295}},ends={{npcID=240295}},coords={x=0.312,y=0.912,source="quest_giver",zoneID=15968},questType="standard"},
[88939] = {id=88939,name="Rest for the Restless",level=90,requiredLevel=90,faction="alliance",expansion=11,zoneID=15968,mapID=2395,description="Before we are able to make amends with the living, we must lay the dead to rest. Years ago, I purged Dalaran of all elves allied with the Horde. I blamed them for the actions of the warchief at the time that resulted in the death of my husband. Now, years later, those ghosts still haunt me. Will you put them to rest and gather their remains? I'll perform some small atonement by bringing these remains to Silvermoon. They deserve to be returned home.",objectivesText="Gather 10 Remains of the Fallen from the Purged of Dalaran. Progress: I have allowed them to torment my people for too long. I bear that guilt as well.",rewardGold=341600,rewardXP=13690,rewardItems={258041},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50},{id=3391,amount=10}},starts={{npcID=240295}},ends={{npcID=240295}},coords={x=0.312,y=0.912,source="quest_giver",zoneID=15968},questType="standard"},
[88941] = {id=88941,name="For Quel'Thalas",level=90,requiredLevel=90,faction="alliance",expansion=11,zoneID=15969,mapID=2395,description="It is time for us to return to Silvermoon. I have no doubt we will be greeted as traitors and murderers. I do not care how we are seen. I care that Quel'Thalas survives. Will you join us, ? From what Arator has said, you have earned more than a measure of respect from Silvermoon. I would be honored if you would assist us in entering the city without incident.",objectivesText="Confront the Sunreavers with Vereesa Windrunner at the gates of Silvermoon.",rewardGold=341600,rewardXP=13690,rewardItems={251914,257169,257220},rewardChoices={257169,257220},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50},{id=3391,amount=10}},starts={{npcID=240295}},ends={{npcID=240262}},coords={x=0.312,y=0.912,source="quest_giver",zoneID=15968},questType="standard"},
[88942] = {id=88942,name="The Elves are Going to War",level=90,requiredLevel=90,faction="horde",expansion=11,zoneID=15969,mapID=2393,description="We have learned much about the forces we will be facing in the battle to come. Suramar remembers the debt we owe the sin'dorei for their aid in our time of need. Now that our forces are assembled and our golems prepared, we are ready to defend this city as if it were our own. Come, . Let us return to Lor'themar. It is time to discuss battle strategy.",objectivesText="Return to the Sanctum of Light in Silvermoon City.",rewardGold=1024800,rewardXP=20540,rewardItems={246458},rewardChoices={248583,251783,251784,251786,251788,251791,259896},rewardCurrencies={{id=3316,amount=100},{id=3365,amount=1000},{id=3391,amount=10}},starts={{npcID=254654}},ends={{npcID=240266}},coords={x=0.402,y=0.328,source="quest_giver",zoneID=15969},questType="standard"},
[88977] = {id=88977,name="Reenact the Crime",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="Ah, you there! You appear to have the wisdom to assist me, unlike a certain bow-wielding simpleton who thinks sniffing dirt will solve our problem. We've accidentally misplaced a very important journal--the sort my mentor would transmogrify me to have lost! Please use my arcane timepiece to summon echoes of the past and investigate these moments. That should allow us to find my journal properly, without indulging Vardis's primitive methods.",objectivesText="Use the Arcane Timepiece to investigate 3 Frozen Moments in the West Sanctum. Progress: Impossible. My magic has never failed me before... It seems we are at an impasse. To be thwarted by something so simple, yet so insidiously effective... is infuriating.",rewardGold=341600,rewardXP=11765,rewardItems={238730,240946,240961,240962,240963,240964,240965},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=240403}},ends={{npcID=240420}},coords={x=0.41,y=0.384,source="quest_giver",zoneID=15968},questType="standard"},
[88978] = {id=88978,name="Tracking the Trail",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="While a certain wyrm-brained mage wastes time with his inept magic, we'll actually solve this case. The local wildlife has likely eaten the journal. Time to gut them and see if we can recover it. If the journal's inside, we'll find it... unlike someone who couldn't track his own insipid ego if it were carved into the ground.",objectivesText="Gather 8 pieces of evidence in the West Sanctum. Progress: What do you mean none of them had the journal? How is this even possible? It defies logic! If the wildlife didn't take it, then where in the Twisting Nether could it have gone?",rewardGold=341600,rewardXP=11765,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=240408}},ends={{npcID=240421}},coords={x=0.41,y=0.384,source="quest_giver",zoneID=15968},questType="standard"},
[88979] = {id=88979,name="Caught Red-Handed",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="A dog, of all creatures? This is the thief we've been chasing? And now we must save it from a lynx? Truly, this day has taken a most... irritating turn. No matter, we shall retrieve the journal... though I do wonder if this canine truly understands the gravity of its actions.",objectivesText="Defeat the Hot-Headed Lynx in the West Sanctum. Progress: Did you manage to retrieve the journal?",rewardGold=341600,rewardXP=11765,rewardItems={241192},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=240422}},ends={{npcID=242663}},coords={x=0.384,y=0.396,source="quest_giver",zoneID=15968},questType="standard"},
[88982] = {id=88982,name="Prey Contract: Renegade Magister",level=90,requiredLevel=90,faction="none",expansion=11,questType="standard"},
[88985] = {id=88985,name="Recuperating Returns",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="One of our lightwood loggin' outposts is late with their weapon shipments. Dey used to be punctual, but now we are lacking crucial supplies. Go check on de camp. Somethin' must be goin' on.",objectivesText="Meet Woodcrafter Azai at Zeb'Alar Lumberyard.",rewardGold=33500,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3354,amount=10}},starts={{npcID=241082}},ends={{npcID=240521}},coords={x=0.456,y=0.654,source="quest_giver",zoneID=15947},questType="standard"},
[88986] = {id=88986,name="Blind the Bandits",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Dis elf showed up here seekin' revenge, thinkin' we were responsible for de death of his sister. But instead of killin' him, I'm gonna set de boy straight. De Amani got no business with some farm! He don't understand de Twilight's Blade is attackin' on both sides of de Zul'Aman border! I don't blame de child. He don't know dat de Twilight's Blade can hide demselves with their void powers. Take some lightwood splinters . Throw 'em on de shrouded Twilight's Blade. Show him who de real enemy is!",objectivesText="Kill 8 Twilight's Blade cultists. Progress: Dat boy came here seekin' revenge on de first trolls he saw. Keep his restraints tight. Dat should help him sober up to de consequences of his childish recklessness.",rewardGold=341600,rewardXP=12170,rewardItems={238962},rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=240521}},ends={{npcID=241219}},coords={x=0.284,y=0.272,source="quest_giver",zoneID=15947},questType="standard"},
[88987] = {id=88987,name="Salvaged Sabotage",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Rakani overreacted when de boy came crashin' into camp, but we all have been on edge. De Twilight's Blade had already snuck into our camp and sabotaged our work. It has already been challengin' to keep up with de demand for weapons. And our people need de weapons to defend themselves! If we can get de broken weapons back, we can maybe make up for what we lost. While you deal with dem, see if you can get any of our weapons back--whatever condition dey are in.",objectivesText="Retrieve 6 Stolen Equipment . Progress: De chaos de elf caused is nothin' next to what we're facin' every day. We have to be extra cautious with de Twilight's Blade tryin' to sabotage our every move.",rewardGold=341600,rewardXP=12170,rewardItems={238964},rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=240521}},ends={{npcID=241219}},coords={x=0.284,y=0.272,source="quest_giver",zoneID=15947},questType="standard"},
[88988] = {id=88988,name="The Artisan's Apprentice",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Looks like de boy has realized there is more in dis world than his family farm an' de big bad trolls of Zul'Aman . But I'm not done with him yet. He gonna learn hard work too. De boy needs to make up for de disruption he caused and de work we lost. It'll be a learnin' opportunity--for de both of you. You are goin' to make somethin' for us. Pay attention. One wrong move can destroy de lightwood. With de Twilight's Blade sabotagin' our equipment, our resources are too limited already.",objectivesText="Follow Woodcrafter Azai 's instructions to craft a Lightwood Javelin. Progress: De lightwood is challengin' to work with, even for experienced woodcrafters. Be patient. Be precise. And do everything I say.",rewardGold=341600,rewardXP=12170,rewardItems={239138},rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=241219}},ends={{npcID=241219}},coords={x=0.284,y=0.274,source="quest_giver",zoneID=15947},questType="standard"},
[88989] = {id=88989,name="Another One Bites the Sawdust",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Dat boy is a fool. But he's a courageous fool. It's time to test dis weapon you crafted. He'll be goin' after their commander. He's killed many of my crafters, but revenge is not worth his life or dat of anyone else. Go after him before he gets himself killed. I did not go through all dis trouble just for him to die now, eh?",objectivesText="Kill Covert Commander Tofir and rescue Kellor Sunshimmer. Progress: Dat commander killed some of our own. His troops most likely killed de boy's sister. But even though killin' him would make craftin' weapons and sendin' dem back to Amani'Zar easier, it's not worth dat boy's life.",rewardGold=683200,rewardXP=15215,rewardItems={241612,264449,264450,264451,264452,264453,264454,264455,264456,264457,264458,264459},rewardChoices={264449,264450,264451,264452,264453,264454,264455,264456,264457,264458,264459},rewardCurrencies={{id=3316,amount=25},{id=3354,amount=250}},starts={{npcID=241219}},ends={{npcID=241219}},coords={x=0.284,y=0.274,source="quest_giver",zoneID=15947},questType="standard"},
[88992] = {id=88992,name="Envisioned Mastery",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=15958,mapID=2444,rewardXP=13690,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Kill Shadowguards or Kill Players"},{orderIndex=2,type=0,amount=10,objectID=240645,text="Kill Shadowguard"},{orderIndex=3,type=0,amount=10,objectID=240647,text="Kill Shadowguard"}},worldTaskTitle="Envisioned Mastery",db2QuestInfoID=113,db2QuestInfoName="PvP World Quest"},
[88993] = {id=88993,name="Wey'nan's Ward",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="To claim this relic, travel to the Vale of Secrets. Seek the Visionstone. Its surface bears sacred paintings, with a hand print aglow at the center. Press your hand upon it and let your spirit be known. Your body will falter into trance, and your soul will walk visions of the past. Be warned: these visions are no mere dreams, and the dangers within may strike true. Return to me with the wisdom you uncover.",objectivesText="Travel to the indicated shrine in Harandar to meditate and experience the history of Wey'nan's Ward. Progress: Has your journey revealed the truth of Wey'nan's Ward? Share what you have uncovered.",rewardGold=683200,rewardXP=15215,rewardItems={263037},rewardCurrencies={{id=3316,amount=100},{id=3370,amount=1000}},starts={{npcID=238170}},ends={{npcID=238170}},coords={x=0.542,y=0.53,source="quest_giver",zoneID=15355},questType="standard"},
[88994] = {id=88994,name="The Cauldron of Echoes",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="For untold eons, the Cauldron of Echoes has rested in shadow, its purpose obscured by time. When I first walked the path of the Zur'ashar, my master spoke of its significance--a relic tied to the very origins of our kind. Yet its secrets eluded even them... a mystery left unanswered. Now, it calls to us once more. Will you uncover what has been forgotten? The truth waits within, and I would be forever grateful for your discovery.",objectivesText="Travel to the Glade of Walking Memories in Harandar to learn the history of the Cauldron of Echoes. Progress: Has your journey revealed the truth of the Cauldron of Echoes? Share what you have uncovered.",rewardGold=683200,rewardXP=15215,rewardItems={263315},rewardCurrencies={{id=3316,amount=100},{id=3370,amount=1000}},starts={{npcID=238170}},ends={{npcID=238170}},coords={x=0.542,y=0.53,source="quest_giver",zoneID=15355},questType="standard"},
[88995] = {id=88995,name="Aln'hara's Bloom",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="When I was young in the path of a Zur'ashar, I heard a tale of a gift from Aln'hara: \"A sign of the goddess, felt in the stillness.\" Unfortunately, all those who were there to experience the event eventually passed on before we learned the secrets of our special paint. Would you walk the memory that surrounds the bloom and find out if this theory is true?",objectivesText="Travel to Veilroot Clearing and uncover the truth behind Aln'hara's Bloom. Progress: Tell me what you witnessed, and we will ensure the memory is not lost again.",rewardGold=683200,rewardXP=15215,rewardItems={263196},rewardCurrencies={{id=3316,amount=100},{id=3370,amount=1000}},starts={{npcID=238170}},ends={{npcID=238170}},coords={x=0.542,y=0.53,source="quest_giver",zoneID=15355},questType="standard"},
[88996] = {id=88996,name="The Echoless Flame",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="The Echoless Flame's fate is lost to time. Down through the ages, it was whispered that the lantern contained the power of Aln'hara herself. But now, it lies dormant--a shell without even a flicker left within. Perhaps you can uncover its secrets where others have failed? Retrace the steps of Obayo, the first of the Shul'ka, and bear witness to the glory of the relic and its true purpose.",objectivesText="Travel to the Verdant Sepulcher in Harandar to learn the history of the Echoless Flame. Progress: Have you uncovered the secrets of the Echoless Flame?",rewardGold=683200,rewardXP=15215,rewardItems={264262},rewardCurrencies={{id=3316,amount=100},{id=3370,amount=1000}},starts={{npcID=238170}},ends={{npcID=238170}},coords={x=0.542,y=0.53,source="quest_giver",zoneID=15355},questType="standard"},
[88997] = {id=88997,name="Russula's Outreach",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="A weather-worn spear haft, laced with pale mushroom threads, rests in silent vigil. The elders name it Russula's Outreach, yet no tale agrees on what that outreach was, or whom it spared. Was this weapon raised in fury, or lowered in mercy? The relic offers no answers here, only a lingering pull toward the old culling grounds. Follow that pull. Trace the footsteps lost to rot and rumor, and let the visions speak of what history forgot.",objectivesText="Travel to the Verdant Sepulcher to learn the history of Russula's Outreach. Progress: Has your journey revealed the secrets of Russula's Outreach?",rewardGold=683200,rewardXP=15215,rewardItems={262906},rewardCurrencies={{id=3316,amount=100},{id=3370,amount=1000}},starts={{npcID=238170}},ends={{npcID=238170}},coords={x=0.542,y=0.53,source="quest_giver",zoneID=15355},questType="standard"},
[88998] = {id=88998,name="Root of the World",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="The Root of the World is the first gift of the land to the haranir, or so it has been said. We have forgotten much about how the staff came to be in the possession of my people. But the root of the story, if you will permit, begins at a time not long after the haranir first came to Harandar . I trust that together, we can uncover its lost past. It is known that Ruilla the Huntress was a pivotal figure in the events that led to the creation of the staff. Go and see history through her eyes.",objectivesText="Travel to the Vale of Secrets to learn the history of the Root of the World. Progress: Have you learned about the Root of the World? What truths have you uncovered?",rewardGold=683200,rewardXP=15215,rewardItems={263041},rewardCurrencies={{id=3370,amount=1000}},starts={{npcID=238170}},ends={{npcID=238170}},coords={x=0.542,y=0.53,source="quest_giver",zoneID=15355},questType="standard"},
[88999] = {id=88999,name="Sky's Hope",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Sky's Hope: the stone that legend says fell from the sky. Little is known about it besides it being considered a symbol of hope. But why? Following in the path of our ancient ancestor, Awe'ohna, might shed some light on the matter.",objectivesText="Travel to the Shrouded Grove in Harandar to learn the history of Sky's Hope. Progress: Back so soon? What mysteries of Sky's Hope have been revealed?",rewardGold=683200,rewardXP=15215,rewardItems={253443},rewardCurrencies={{id=3370,amount=1000}},starts={{npcID=238170}},ends={{npcID=238170}},coords={x=0.542,y=0.53,source="quest_giver",zoneID=15355},questType="standard"},
[89012] = {id=89012,name="A Safe Path",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16211,mapID=2432,description="We must rescue the civilians and get them to the ships, yet the path to the docks is barred by a vile, hungering creature. If we are to save my people, then we need to clear an evacuation path. We cannot leave them to fend for themselves.",objectivesText="Eliminate Gloomstress . Progress: Does the engulfing Void still bar the way?",rewardGold=309800,rewardXP=11765,starts={{npcID=237222}},ends={{npcID=236896},{npcID=236961}},coords={x=0.376,y=0.308,source="quest_giver",zoneID=16182},questType="standard"},
[89032] = {id=89032,name="Renowned with The Singularity",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15458,mapID=2405,description="You continue to show us that you are an integral member of our community. To honor that bond seek me out in Iskaara as I have prepared a pack of supplies to aid you.",objectivesText="Speak with Murik in Iskaara.",rewardItems={259334},starts={{npcID=248328}},ends={{npcID=248328}},questType="standard"},
[89034] = {id=89034,name="Burning Bitterblooms",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Lightbloom-infested rutaani are working to spread the contamination through the village. This plant showed significant signs of the disease. Destroy any of the plants they've come into contact with. We must contain this!",objectivesText="Destroy 6 Lightbloom-Infected plants in Har'mara. Progress: The Lightbloom cannot be allowed to spread. The harmony of Har'mara is delicately balanced. We must keep it intact.",rewardGold=335000,rewardXP=12170,rewardItems={256196,256204,256212,256220},rewardChoices={256196,256204,256212,256220},rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=240630}},ends={{npcID=240630}},coords={x=0.356,y=0.252,source="quest_giver",zoneID=15355},questType="standard"},
[89035] = {id=89035,name="Renowned with the Hara'ti",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15355,mapID=2413,description="The Hara'ti are stronger for what you have done. Go to Naynar . She will see that your deeds are remembered, and present you trophies appropriate for all you have done.",objectivesText="Speak with Naynar in the Den.",rewardItems={256055},starts={{npcID=240407}},ends={{npcID=240407}},questType="standard"},
[89193] = {id=89193,name="Arator",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Archbishop Alonsus Faol has left a message asking to speak with you in regards to a project to help Arator and the Vanguard of Light.",objectivesText="Speak with Alonsus Faol .",rewardGold=30900,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3365,amount=10}},starts={{npcID=240523}},ends={{npcID=237565}},questType="standard"},
[89199] = {id=89199,name="A Small Task",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="You will forgive the lack of pleasantries, as this situation requires prompt remediation. All you need know is that I am Aradis, wardsmith of Silvermoon. We are an order of Magisters who maintain the city's defenses. I am recovering from a... minor battle injury, and require aid charging my wardbreaker staff. You will be compensated, and perhaps provided additional opportunities to aid me. I can furnish the details as you work, so long as you are not terribly slow.",objectivesText="Collect the Depleted Wardbreaker , then charge it using 4 arcane reservoirs. Progress: Do handle the wardbreaker carefully. I will not tolerate seeing it damaged.",rewardGold=341600,rewardXP=11765,rewardItems={239511},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=241393}},ends={{npcID=241405}},coords={x=0.54,y=0.338,source="quest_giver",zoneID=15969},questType="standard"},
[89200] = {id=89200,name="Unraveling Wards",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Dawnblaze is keeping the blackmail documents in her study. It is highly warded, naturally. The wards themselves are pitifully made. However, she is supplying additional power to them using arcane conduits placed throughout the city. I found the first link in the chain and brought it here to study. It is also warded, but weakly. I theorize that if the conduits are broken in sequence, then the shields on Dawnblaze's study will be vulnerable. Sabotage them, then recover the documents. Understood?",objectivesText="Use the charged Wardbreaker to destroy the shields guarding 5 Warded Conduits.",rewardGold=341600,rewardXP=11765,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=241405}},ends={{npcID=241400}},coords={x=0.54,y=0.338,source="quest_giver",zoneID=15969},questType="standard"},
[89201] = {id=89201,name="Outschemed",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="The entrance to Dawnblaze's study is in the terrace just beneath us. Since my magic can project this close to her wards, that means the magic guarding this place has been weakened... as I predicted. Break the larger ward sealing the entrance and find the documents she forged to slander me. I will expect your expedient return to my office thereafter.",objectivesText="Use the Wardbreaker to enter Magister Dawnblaze 's study, then find the Incriminating Documents . Progress: I will be taking those documents back.",rewardGold=341600,rewardXP=11765,rewardItems={239608},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=241400}},ends={{npcID=241398}},coords={x=0.372,y=0.742,source="quest_giver",zoneID=15969},questType="standard"},
[89202] = {id=89202,name="Stir the Nest",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Aradis told you the blackmail was false? Of course. He is vying for my position. These receipts would ruin him. He is a warlock, and we have rules about fel magic. It is not banned, but it must be used discreetly. Aradis is not discreet. Magic misuse, unsanctioned demons, fel smuggling, bribery... His list of crimes is long. But you need not take my word for it. Aradis has earned many enemies in the city. If you can find him in the Row, a man named Jaeth could tell you all about our dear warlock.",objectivesText="Question 8 Row Rats about Jaeth 's whereabouts.",rewardGold=341600,rewardXP=11765,rewardItems={259992},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=241398}},ends={{npcID=241399}},coords={x=0.388,y=0.756,source="quest_giver",zoneID=15969},questType="standard"},
[89203] = {id=89203,name="Mutual Benefit",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Jaeth waves a hand to cut you off as you explain.> All right, Dawnblaze sent you. That means there's a job. Not surprised she doesn't want to dirty her robes coming to the Row herself. The types who hire us never do. Everyone that high up in Silvermoon backstabs each other. When it's literal, they pay us to do it for them. They get whatever power they're chasing, and we get enough coin to live another week. Whose back is getting a knife this time?",objectivesText="Show Jaeth the incriminating documents about Aradis. Progress: Come on. Spit out the details.",rewardGold=341600,rewardXP=11765,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=241399}},ends={{npcID=241399}},coords={x=0.518,y=0.636,source="quest_giver",zoneID=15969},questType="standard"},
[89204] = {id=89204,name="Five Finger Discount",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Aradis gave you his wardbreaker? What an idiot. Those get sold on the black market as skeleton keys. Expensive, but you have to attune them to the magic you're breaking, which isn't easy. Looks like yours is empty. We can fix that. If we pocket a few magic valuables around the city, my buddy upstairs can disenchant them and get that wardbreaker juiced with fel magic. Aradis won't have anywhere to hide then.",rewardGold=683200,rewardXP=14705,rewardItems={241205,241207,241208},rewardCurrencies={{id=3316,amount=20},{id=3365,amount=100}},starts={{npcID=241399}},ends={{npcID=241401}},coords={x=0.518,y=0.636,source="quest_giver",zoneID=15969},questType="standard"},
[89205] = {id=89205,name="Cutting a Key",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="I told Zanien here the whole story. He's been training warlocks for a long time--and if anyone hates sloppy ones, it's him. He's confident he can get the wardbreaker recharged. Follow his instructions and we should be good to head out afterward.",objectivesText="Attune the Wardbreaker to fel magic. Progress: That staff should be able to break this ward now.",rewardGold=34100,rewardXP=1470,rewardItems={242253},rewardCurrencies={{id=3316,amount=5},{id=3365,amount=10}},starts={{npcID=241401}},ends={{npcID=241402}},coords={x=0.508,y=0.61,source="quest_giver",zoneID=15969},questType="standard"},
[89206] = {id=89206,name="Break and Enter",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Can you hear that? It sounds like it's coming from downstairs. Like someone's in pain. The last kidnapping from the Row was pretty recent. This could be where he's been keeping the people he took. My people. My friends. Even if Aradis doesn't show his face, we're not letting him keep them here. Bring this ward down. We're going in.",objectivesText="Destroy the fel magic warding Aradis's private study. Progress: We're getting them out of here.",rewardGold=341600,rewardXP=11765,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=241402}},ends={{npcID=241403}},coords={x=0.542,y=0.336,source="quest_giver",zoneID=15969},questType="standard"},
[89207] = {id=89207,name="Rats Can Bite",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="I know all of these people. They're workers, not fighters. Aradis went after the ones who couldn't fend him off. That's why he ran when he tried to take me and realized he picked the wrong target. After the trouble we've made, there's no way he doesn't know we're here. Be on guard. Once he shows his face, he's dead.",objectivesText="Kill Magister Aradis .",rewardGold=625600,rewardXP=14705,rewardItems={263358,263359,263362,263364},rewardCurrencies={{id=3316,amount=20},{id=3365,amount=100}},starts={{npcID=241403}},ends={{npcID=241404}},coords={x=0.542,y=0.336,source="quest_giver",zoneID=15969},questType="standard"},
[89208] = {id=89208,name="What We're Owed",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Everyone out here should be fine. Sarvi... I'll get her back to the Row. If we leave her here, the guards will just have the body tossed. I hope they do the same to Aradis, but I'm sure they won't. Come on. Let's go talk to Dawnblaze and get our payment. I remember where her office is.",objectivesText="Inform Magister Dawnblaze that the job was completed. Progress: I see you recruited our dear assassin to the cause. Well done.",rewardGold=341600,rewardXP=11765,rewardCurrencies={{id=3316,amount=25},{id=3365,amount=250}},starts={{npcID=241404}},ends={{npcID=241490}},coords={x=0.53,y=0.33,source="quest_giver",zoneID=15969},questType="standard"},
[89230] = {id=89230,name="A Lover Not a Fighter",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="De elders are plannin' a festival to give thanks to de loa. I wanna ask Namaji to accompany me but.... It is tradition that a suitor give a gift that proves their prowess as a warrior. But I am a poor fighter and de others laugh at me because of it. Kagara hangs his head dejectedly.> Perhaps you can help me? I know Namaji has always wanted a threshadon tooth necklace . De gnarldin make dem, but only de strongest have one. Could you find one for me and deliver it to her on my behalf?",objectivesText="Collect a Threshadon Tooth Necklace from the gnarldin at Akil'zon's Reach. Progress: Did you need somethin'?",rewardGold=341600,rewardXP=12170,rewardItems={249271},rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=240976}},ends={{npcID=240975}},coords={x=0.44,y=0.662,source="quest_giver",zoneID=15947},questType="standard"},
[89231] = {id=89231,name="A Fighter Not a Lover",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="You goin' to de loa festival? Young trolls like me are expected to ask someone dey like to go wit' dem. And to give a gift to show their worthiness. I wanna go wit' Namaji . I'm a great fighter, but I'm sure there are many other warriors dat wanna go wit' her! They'll gift her trophies and spoils. But I'll be different. I think she'd like a headdress, but I have no idea how to make one. Could you make a feathered headdress for me and give it to her? You can find feathers at Akil'zon's Reach.",objectivesText="Collect 8 Eagle Feathers from Akil'zon's Reach and make an Amani Headdress . Progress: Another gift?",rewardGold=341600,rewardXP=12170,rewardItems={249231,249236},rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=240977}},ends={{npcID=240975}},coords={x=0.438,y=0.66,source="quest_giver",zoneID=15947},questType="standard"},
[89233] = {id=89233,name="Love Triangle",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="It seems we have a problem: Kagara and Zak'kash both wanna go wit' me to de festival! Which one do I choose? I like both of dem well enough. Please , you need to help me! What do you think?",objectivesText="Help Namaji decide who to go to the festival with. Progress: Dey are both good choices...",rewardGold=170800,rewardXP=6085,rewardItems={264447,264448},rewardChoices={264447,264448},rewardCurrencies={{id=3316,amount=25},{id=3354,amount=250}},starts={{npcID=240975}},ends={{npcID=240975}},coords={x=0.444,y=0.656,source="quest_giver",zoneID=15947},questType="standard"},
[89249] = {id=89249,name="Overwhelmed",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="We were too late. All of the strength between us wasn't enough. Arator looks over his shoulder, wary. Then, he crouches and places his hand on Alleria's shoulder. She responds only with a ragged exhale.> Let's fall back. The ren'dorei have been exploring the wilds while we've been following Lothraxion. We might be able to find their encampment nearby.",objectivesText="Reconvene with Arator at Locus Point.",rewardGold=83700,rewardXP=3210,rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=241109}},ends={{npcID=235724}},coords={x=0.416,y=0.788,source="quest_giver",zoneID=15458},questType="standard"},
[89267] = {id=89267,name="Mysterious Entity",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=15958,mapID=2444,rewardXP=13690,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Kill Ethereal or Kill Players"},{orderIndex=2,type=0,amount=10,objectID=241448,text="Kill Shadowguard"},{orderIndex=3,type=0,amount=10,objectID=241447,text="Kill Ethereal"},{orderIndex=4,type=0,amount=20,objectID=242459,text="Kill Ethereal"}},worldTaskTitle="Mysterious Entity",db2QuestInfoID=113,db2QuestInfoName="PvP World Quest"},
[89268] = {id=89268,name="Lost Legends",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Among these walls lie relics, silent and forgotten, their stories obscured by time. The path to reclaiming our past is clear: take a relic to the sacred shrines and step into the echoes of its history. The visions will guide you, letting you walk the tale firsthand and breathe life into memory once more. If you would lend your spirit to this cause, choose a relic to reawaken its story.",objectivesText="Select a relic to pursue.",rewardGold=34100,rewardXP=1520,starts={{npcID=238170}},ends={{npcID=238170}},coords={x=0.542,y=0.53,source="quest_giver",zoneID=15355},questType="standard"},
[89271] = {id=89271,name="My Son",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16211,mapID=2432,description="One moment, . I have a personal matter. I would like you to find my son, Arator . He is a member of the Silver Hand, an accomplished paladin. I know he must have been called. His faith is strong. The Light would want him here fighting against Xal'atath.",objectivesText="Find Arator and bring him to Turalyon at Light's Spire. Progress: Have you found my son?",rewardGold=309800,rewardXP=11765,starts={{npcID=236906}},ends={{npcID=236954}},coords={x=0.46,y=0.444,source="quest_giver",zoneID=16182},questType="standard"},
[89276] = {id=89276,name="Light Snacks",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="Classics are classic for a reason, darling. One simply cannot host a worthwhile soiree without a fine selection of mana for one's guests to indulge in. The Magisters could bring some, but mana is best when freshly siphoned. The mana wyrms in southern Eversong have a decadent brightness to them that I find particularly lovely. Be a dear and gather some for us.",objectivesText="Siphon magical energy from 6 Scintillant Wyrms in the Tranquil Repose. Progress: Time is of the essence, dear.",rewardGold=341600,rewardXP=11765,rewardItems={242241},rewardCurrencies={{id=3310,amount=35},{id=3310,amount=52},{id=3379,amount=40},{id=3379,amount=50}},starts={{npcID=240834}},ends={{npcID=240834}},coords={x=0.426,y=0.462,source="quest_giver",zoneID=15968},questType="standard"},
[89277] = {id=89277,name="Illuminate the Space",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="I share our dear Saltheril's love for vintage fixtures, but the lighting enchantment he is using is far too common for such an auspicious occasion. My Magisters can create a far more stunning enchantment. Simply gather some fibers from the Lightbloom for me and I can have them broken down into spell reagents. The effect will be marvelous.",objectivesText="Gather 8 Luminous Fibers from creatures near Lightbloom Ath'Ran. Progress: We need only a small quantity. Our spellwork is quite efficient.",rewardGold=341600,rewardXP=11765,rewardItems={239067},rewardCurrencies={{id=3310,amount=35},{id=3310,amount=52},{id=3379,amount=50},{id=3379,amount=60}},starts={{npcID=240834}},ends={{npcID=240834}},coords={x=0.426,y=0.462,source="quest_giver",zoneID=15968},questType="standard"},
[89278] = {id=89278,name="Minding Our Duty",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="While the court does demand our consideration, we cannot forget duties. Our guests will enjoy themselves more freely if they are assured of the solidity of Eversong's defenses. The Magisters are tasked with maintaining the runestone wards throughout Eversong. Please survey them for us and let us know if any wards need our attention.",objectivesText="Inspect the integrity of 4 Runestone wards around Eversong Woods .",rewardGold=341600,rewardXP=11765,rewardItems={242241},rewardCurrencies={{id=3310,amount=35},{id=3310,amount=52},{id=3379,amount=40},{id=3379,amount=50}},starts={{npcID=240834}},ends={{npcID=240834}},coords={x=0.426,y=0.462,source="quest_giver",zoneID=15968},questType="standard"},
[89285] = {id=89285,name="Saltheril's Favor",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=15968,mapID=2395,questType="standard"},
[89289] = {id=89289,name="Favor of the Court",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="Ah, , my favorite ! I am delighted to see you in attendance once more. You have quite the natural talent for these sorts of affairs. The nobles are pleased with your presence and your favor has been swaying their coffers. Let us not stop a good thing, shall we? Help me choose an ally of our representatives to invite to the Haven this week. I'm ever curious to see the drama you will stir up. As my personal guest of honor, your favor will be seen as an extension of my favor.",rewardGold=341600,rewardXP=11765,rewardItems={238987},starts={{npcID=240832,x=0.426,y=0.472,zoneID=15968}},ends={{npcID=240832,x=0.426,y=0.472,zoneID=15968}},coords={x=0.426,y=0.472,source="quest_giver",zoneID=15968},questType="world",worldTaskTitle="Favor of the Court"},
[89307] = {id=89307,name="Saltheril's Favor",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=15968,mapID=2395,questType="standard"},
[89311] = {id=89311,name="Saltheril's Favor",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=15968,mapID=2395,questType="standard"},
[89314] = {id=89314,name="Saltheril's Favor",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=15968,mapID=2395,questType="standard"},
[89334] = {id=89334,name="Ahead of the Issue",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="I do not know de loa Akil'zon, but she cannot be happy with de gnarldin defilin' de hash'ey shrines and makin' meals of her eagle kin. We gotta let dem know dis is a sacred place and dat we will not take kindly to their presence here. I may not know Akil'zon, but I know de giants. All dey understand is strength--de language of Zul'Aman . Our strongest message we can send is to take de heads of their fiercest warriors.",objectivesText="Collect the heads of Brulagh the Crusher, Cragward Gaahl, and Pulverizer Helthra. Progress: Take their heads. How painful de method is between you and whatever force you worship.",rewardGold=683200,rewardXP=15215,rewardItems={239083,243188,243189,260458,260459,260461},rewardChoices={260458,260459,260461},rewardCurrencies={{id=3316,amount=20},{id=3354,amount=100}},starts={{npcID=236140}},ends={{npcID=236147}},coords={x=0.516,y=0.708,source="quest_giver",zoneID=15947},questType="standard"},
[89347] = {id=89347,name="Overcoming the Unknown: Rage-Riddled Drifter",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=15958,mapID=2444,rewardXP=17110,questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=241472,text="Kill the Rage-Riddled Drifter"}},worldTaskTitle="Overcoming the Unknown: Rage-Riddled Drifter",db2QuestInfoID=278,db2QuestInfoName="PvP Elite World Quest"},
[89354] = {id=89354,name="Preparing for Battle",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15958,mapID=2444,description="Void creatures have been multiplying throughout Slayer's Rise. Go help clear some out and return to me for a prize. There are turrets that are normally used in battle that can be used to make this task easier for you.",objectivesText="Kill 20 Void Creatures in Slayer's Rise. Progress: This isn't enough! Go clear more of the void creatures.",rewardItems={245937},rewardCurrencies={{id=1792,amount=500},{id=2123,amount=150},{id=3410,amount=1000}},starts={{npcID=245976}},ends={{npcID=245976}},coords={x=0.388,y=0.814,source="quest_giver",zoneID=15958},questType="pvp"},
[89377] = {id=89377,name="Undercover Hunt",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=15958,mapID=2444,rewardXP=13690,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Kill Behemoths or Kill Players"},{orderIndex=2,type=0,amount=10,objectID=241570,text="Kill Behemoths"},{orderIndex=3,type=0,amount=10,objectID=242481,text="Kill Kaiju"}},worldTaskTitle="Undercover Hunt",db2QuestInfoID=113,db2QuestInfoName="PvP World Quest"},
[89383] = {id=89383,name="One Adventurous Hatchling",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="One of my hatchlings was frightened off when that giant construct marched past the ranch. He bolted right through the fence and into the woods before I could stop him! He's small, fast, and probably hiding somewhere nearby. Please find him before something else does, and return him to me.",objectivesText="Find the missing Hawkstrider Fledgling at Stillwhisper Pond. Progress: Did you find the hatchling?",rewardGold=341600,rewardXP=11765,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=241553}},ends={{npcID=241553}},coords={x=0.568,y=0.356,source="quest_giver",zoneID=15968},questType="standard"},
[89384] = {id=89384,name="A Hungry Flock",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="Some think that raising hawkstriders is an easy task, but it most certainly is not. Hawkstrider appetites tend to be notoriously fussy! More often than not they'll turn their beaks up at anything I offer. But this time of year? Frog legs. They love the slimy little things. They can't get enough of them! There's a pond just down the hill just swarming with the leggy little morsels. Could you gather some for me, please?",objectivesText="Gather frog legs from the Gloombelly Toads at Stillwhisper Pond. Progress: Have you found any frogs? The hawkstriders are hungry!",rewardGold=341600,rewardXP=11765,rewardItems={244214},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=241553}},ends={{npcID=241553}},coords={x=0.568,y=0.356,source="quest_giver",zoneID=15968},questType="standard"},
[89385] = {id=89385,name="First Step Into Parenthood",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,rewardGold=309800,rewardXP=11765,rewardItems={244339,262510},rewardCurrencies={{id=3316,amount=25},{id=3365,amount=250}},starts={{npcID=241553}},ends={{npcID=241553}},coords={x=0.568,y=0.356,source="quest_giver",mapID=2395},questType="standard"},
[89386] = {id=89386,name="A Roost-ed Development",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="A comfortable hawkstrider is a happy hawkstrider. We don't expect them to stand all day. They need someplace cozy to roost! There's a plant called golden sunleaf that sprouts just beyond the ridge. It makes the softest bedding--the hawkstriders love it. Could you gather some for me?",objectivesText="Collect Golden Sunleaf at Stillwhisper Pond. Progress: Did you find the golden sunleaf ?",rewardGold=341600,rewardXP=11765,rewardItems={245531},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=241553}},ends={{npcID=241553}},coords={x=0.568,y=0.356,source="quest_giver",zoneID=15968},questType="standard"},
[89388] = {id=89388,name="Voidstorm",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Magister Umbric has a plan to infiltrate the Voidstorm and take the fight to the Devouring Host directly. This will be no easy task, and he is assembling a small but powerful team to strike at the enemy's heart.",objectivesText="Speak with Magister Umbric in the Sanctum of Light in Silvermoon.",rewardGold=34100,rewardXP=1470,starts={{npcID=240523}},ends={{npcID=235386}},questType="standard"},
[89402] = {id=89402,name="Harandar",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15968,mapID=2395,description="With the Devouring Host occupying much of our attention and time, we leave our backs exposed to other threats that wait in the wings. This Lightbloom that has afflicted Eversong grows worse by the day. If it gets out of control, then we might find ourselves fighting a two-front conflict--or worse, having our home consumed completely while we busy ourselves with the Void. The strange woman who you found poking about the Lightbloom... You seem to be familiar with her. Seek her out. She may have answers.",objectivesText="Speak with Orweyna in Fairbreeze Village.",rewardGold=34100,rewardXP=1520,starts={{npcID=240523}},ends={{npcID=236704}},questType="standard"},
[89440] = {id=89440,name="Protecting the Flank",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=16178,mapID=2432,rewardGold=309800,rewardXP=11765,questType="world",worldTaskTitle="Protecting the Flank"},
[89441] = {id=89441,name="Clear the Decks",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=16182,mapID=2432,rewardGold=309800,rewardXP=11765,questType="world",db2Objectives={{orderIndex=2,type=0,amount=1,objectID=244062,text="Instruct Salandria to fall back"}},worldTaskTitle="Clear the Decks"},
[89483] = {id=89483,name="Beginning of Abundance",level=80,requiredLevel=80,faction="none",expansion=11,description="The land is alive. With our relationship to the loa rekindled, the very ground beneath us responds in joy. Rich materials are providing themselves in quantities never witnessed before. One such place is in a cave in the north of Zul'Aman, just past Halazzi's domain. Meet me there if you wish to obtain great abundance!",objectivesText="Meet Chel the Chip at the cave in Northern Zul'Aman.",questType="standard"},
[89503] = {id=89503,name="Somber Siblings",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Iz'ken left us many years ago, $p. Preparin' may be tense, but at least we won't have to do it alone. First, we need to collect de spores of de weepin' mushrooms. You can get dem from the mushrooms, or de boars. I'll be usin' dem to create incense for de ritual. Be careful, $p--de boars might be unhappy when we take their food.",objectivesText="Collect 30 Weeping Spores from Weeping Caps or boars in the Solemn Valley. Progress: They're called weepin' spores, because when dey burn dey make your eyes water. De spores give our warriors a good excuse if dey are too cowardly to admit their feelings at de pyre.",rewardGold=341600,rewardXP=12170,rewardItems={239447},rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=247424}},ends={{npcID=256867}},coords={x=0.458,y=0.724,source="quest_giver",zoneID=15947},questType="standard"},
[89506] = {id=89506,name="Strong Ties",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Next we need to collect sinew from giants. De sinew makes sure de bonfire is not gonna fall apart, and de act of risking ya life against a powerful foe honors de fallen. I am a tested warrior, so do not worry for me. But please make sure Iz'ken does not come to harm from de giants.",objectivesText="Collect 3 Resilient Sinew from mountain giants in the Solemn Valley. Progress: De sinew of mountain giants is a strong buildin' material. But we only use it for dis one purpose, because it's dangerous to get and there are not enough giants.",rewardGold=341600,rewardXP=12170,rewardItems={239480},rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=256867}},ends={{npcID=256867}},coords={x=0.468,y=0.809,source="quest_giver",zoneID=15947},questType="standard"},
[89507] = {id=89507,name="Abundant Offerings",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2437,description="We have been called on yet again by de Loa of Abundance! Seek, harvest, and provide offerings at any of the abundance sites in Eversong, Zul'Aman, Harandar, or Voidstorm. I will provide you with the appropriate glory when the Harvest Lord has been satisfied.",objectivesText="Earn 20,000 points in Abundance harvests.",rewardXP=14705,rewardItems={263466,268488,269702,279523},rewardCurrencies={{id=3310,amount=35},{id=3310,amount=50},{id=3310,amount=52},{id=3310,amount=75}},starts={{npcID=241928},{npcID=248658},{npcID=257632},{npcID=257633}},ends={{npcID=241928},{npcID=248658},{npcID=257632},{npcID=257633}},coords={x=0.316,y=0.262,source="quest_giver",zoneID=15947},questType="standard"},
[89513] = {id=89513,name="Kindling Aplenty",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Next, we need to collect de logs for our bonfire. Kan'sha, de large tree at de end of de valley, was infected with poison from a stray arrow long ago. She's quite tough. To survive, she sheds her branches regularly. In a way, Kan'sha has become a regular part of our rituals. Her strong wood burns warm and hot--like Amani blood. It is perfect for bonfires.",objectivesText="Collect 4 Fallen Branches around Kan'sha in the Solemn Valley. Progress: Do not worry for Kan'sha. She has outlived generations of trolls, and de druids say she'll survive many more.",rewardGold=341600,rewardXP=12170,rewardItems={239483},rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=256867}},ends={{npcID=256867}},coords={x=0.468,y=0.809,source="quest_giver",zoneID=15947},questType="standard"},
[89559] = {id=89559,name="Reasonless Worship",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Ahead is an old shrine. Nobody knows anymore what we worshipped there or why, but it was a place my mother loved. It would honor her if we put a stone from it on de pyre with her.",objectivesText="Collect a Weathered Shrine Piece . Progress: We both know dat de shrine is a place dat pleased our mother. I can't say she knew dat much about us.",rewardGold=341600,rewardXP=12170,rewardItems={239494},rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=256867}},ends={{npcID=256867}},coords={x=0.468,y=0.809,source="quest_giver",zoneID=15947},questType="standard"},
[89560] = {id=89560,name="A Quiet Farewell",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Now we set up de bonfire to burn de body. Destroying the body means it cannot be used by de Vilebranch for evil and makes sure de spirit finds rest. It still chills me how quiet she is now. The tribe should be gatherin' down at de Funerary Coast.",objectivesText="Setup the bonfire for Chana and Iz'ken. Progress: It's time. We are ready.",rewardGold=341600,rewardXP=12170,rewardItems={264654},rewardCurrencies={{id=3316,amount=25},{id=3354,amount=250}},starts={{npcID=256867}},ends={{npcID=242014}},coords={x=0.468,y=0.809,source="quest_giver",zoneID=15947},questType="standard"},
[89565] = {id=89565,name="The Path of Mourning",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Hash'ura, could I ask for your aid? My mother passed recently, and I'm de one responsible for performin' her death rituals. It's a lotta work for one person to do. Most would get help from their family, but I don't have any left. Can you help me?",objectivesText="Meet Chana in the Solemn Valley.",rewardGold=30900,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3354,amount=10}},starts={{npcID=242014}},ends={{npcID=247424}},coords={x=0.462,y=0.912,source="quest_giver",zoneID=15947},questType="standard"},
[90093] = {id=90093,name="Prey Contract: Murloc Shadowhunter",level=90,requiredLevel=90,faction="none",expansion=11,questType="standard"},
[90094] = {id=90094,name="Echo of the Hunt",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Haranir are fierce and ferocious--cunning and canny. In time, we became the most feared beasts upon the mountain. A great many wise and powerful beasts roamed the hills of our old mountain. But in time, we came to master them all. Today, you shall hunt as we once did.",objectivesText="Complete the second trial at the Den of Echoes.",rewardGold=341600,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=239650}},ends={{npcID=239795}},coords={x=0.36,y=0.442,source="quest_giver",zoneID=15355},questType="standard"},
[90095] = {id=90095,name="Echo of the Call",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="When the haranir began to grow restless, they looked to new sources of purpose. Some cast their gazes upward, toward the stars and the moon. Others, such as the Hara'ti , heard a call from deep within the world. The moment the first of the Hara'ti heard the Song echoing from the roots, we knew that we had found a new purpose. We would seek out the source of the Song, and discover the truth of it for ourselves. But it would be a difficult road. Strange stone monsters sought to block our path.",objectivesText="Complete the third trial at the Den of Echoes.",rewardGold=644200,rewardXP=15215,rewardItems={256176,256178,256179,256181,256182,256183,256185,256187,256189,256191,256230},rewardChoices={256176,256178,256179,256181,256182,256183,256185,256187,256189,256191,256230},rewardCurrencies={{id=3316,amount=20},{id=3370,amount=100}},starts={{npcID=239795}},ends={{npcID=243884}},coords={x=0.348,y=0.428,source="quest_giver",zoneID=15355},questType="standard"},
[90115] = {id=90115,name="Infinite Research: Combat Studies, Groverunner",level=10,requiredLevel=10,faction="both",expansion=11,mapID=619,description="In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma. This will be a study of your attunement to the forest, so focus on fighting opponents using the power of nature. And remember, this is for the greater good.",objectivesText="Kill 100 enemies while Call of the Forest is your active artifact ability.",starts={{npcID=241748}},ends={{npcID=241748}},questType="standard"},
[90467] = {id=90467,name="Tales of the Sky",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Wait a minute... You're no rutaani at all! Are you one of those \"outsiders\" that Saku and Orkon keep talking about? Oh! I just had a great idea. Did you know that the Goddess used to have a pet? Rumor has it that when the Goddess disappeared, Aln'sharan was SO sad that he flew up into the highest roots of Harandar , never to be seen again. But every so often, he goes looking for food... And his scales fall as skyglass! I wanna gather some. It's my dream to see Aln'sharan firsthand! Will you help me?",rewardGold=341600,rewardXP=12170,rewardItems={240484},rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=242358,x=0.662,y=0.254,zoneID=15355}},ends={{npcID=242689,x=0.694,y=0.292,zoneID=15355}},coords={x=0.662,y=0.254,source="quest_giver",zoneID=15355},questType="world",worldTaskTitle="Tales of the Sky"},
[90468] = {id=90468,name="Ugh, Chores!",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Okay, so I may have a DIFFERENT thing that I'm supposed to be doing in the Cascades, too. It's my turn to gather saptor fronds for stew. It's such a pain. Not only are saptor fronds horribly bitter, but the saptors are barely even fun to hunt! They don't even make your blood flow that fast before they die. But hey! You probably don't get to fight saptors as often as I do. Maybe while you're looking for skyglass, you could gather some up for me? You know... while you're in the area.",objectivesText="Collect 8 Intact Saptor Fronds from the saptors of the Harandar Cascades. Progress: Oh, Kuri ...",rewardGold=341600,rewardXP=12170,rewardItems={240485},rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=242358}},ends={{npcID=242689}},coords={x=0.662,y=0.254,source="quest_giver",zoneID=15355},questType="standard"},
[90469] = {id=90469,name="Carry On, Wayward Kuri",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Oh, that Kuri . She holds tightly to our ancient traditions and tales... perhaps too tightly. There is a difference between holding reverence for our ancient ways and chasing them into dangerous caves. I fear she might bite off more than she can chew in her search for Aln'sharan. Won't you go after her? She seems to trust you, now that she sees you as her co-conspirator in this quest. Please bring her home safely.",objectivesText="Find Kuri in Dreth'amar Cavern. Progress: I'm certain Kuri will be fine. She's got her head in the roots, but she's made of tough stuff. But with Harandar as volatile as it has been of late, I would rather be safe than sorry.",rewardGold=256200,rewardXP=9130,rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=242689}},ends={{npcID=242691}},coords={x=0.694,y=0.292,source="quest_giver",zoneID=15355},questType="standard"},
[90470] = {id=90470,name="Skyglass Scavenging",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="The adults find all sorts of stuff in the caves around here that we use back at the village. A lot of the critters that live in the caves like to gather skyglass, in particular. I guess they think it's shiny. That's good for us, though! It means we can go and get a bunch of skyglass. Go in there and make sure the coast is clear, and then I'll come in and gather up as much as I can carry! At this rate, we'll be able to summon Aln'sharan in no time.",objectivesText="Gather as much Skyglass as Kuri can carry from Dreth'amar Cavern in Harandar . Progress: Come onnn! We've gotta hurry before mom gets TOO worried.",rewardGold=341600,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=242691}},ends={{npcID=242691}},coords={x=0.696,y=0.266,source="quest_giver",zoneID=15355},questType="standard"},
[90474] = {id=90474,name="The Legend of Aln'sharan",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="This is it! We have all the skyglass we can carry. The legends say that Aln'sharan cries crystal tears to mourn the missing Goddess. Maybe if we give the crystals back to him, he won't be so sad? Maybe then he'll appear for us! Meet me back at the village. I think I know the perfect place to make our offering.",objectivesText="Return to Kuri in Har'kuai. Progress: Come on! We don't wanna miss our chance! Also all of this skyglass is heavy. Can't you carry some?!",rewardGold=341600,rewardXP=12170,rewardItems={255826},rewardCurrencies={{id=3316,amount=25},{id=3370,amount=250}},starts={{npcID=242691}},ends={{npcID=242358}},coords={x=0.696,y=0.266,source="quest_giver",zoneID=15355},questType="standard"},
[90481] = {id=90481,name="I Have a Permit",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="These Witherbark youths are telling us we can't stay here. But I've been talking to one of their elders for months to be sure we'd have permission to set up camp and explore. I even have copies of all the letters! Can you find Elder Ren'zen in Witherbark Village and show him his letter of approval?",objectivesText="Find Elder Ren'zen in Witherbark Village. Progress: Elder Ren'zen seemed so pleasant in his letters. Why all the hostility now?",rewardGold=34100,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3354,amount=10}},starts={{npcID=242383}},ends={{npcID=242383}},coords={x=0.462,y=0.26,source="quest_giver",zoneID=15947},questType="standard"},
[90482] = {id=90482,name="Cuisine Connection",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Dis \"seeker\" has been askin' a lot of questions about de foods we eat. It sounds like these tortollans like to eat poisonous foods. De Witherbark do as well. There are many foods we eat that could kill us if not treated properly. Go collect zapgut eel stomachs and blisterskin kelp . I'd like to test dis turtle's tongue.",objectivesText="Collect 6 Zapgut Eel Stomachs and 60 Blisterskin Kelp . Progress: We ingest some poisons to make ourselves resistant to potential threats. Some just taste good or provide a good thrill.",rewardGold=341600,rewardXP=12170,rewardItems={241013,241014},rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=242394}},ends={{npcID=242394}},coords={x=0.472,y=0.246,source="quest_giver",zoneID=15947},questType="standard"},
[90483] = {id=90483,name="A Witherbark Story",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="The Witherbark say they have a lot of stories to tell, but I've heard two and BOTH involved a sparring match! Please, can you ask the Witherbark here for stories? My old bones can't take another reenactment!",objectivesText="\"Reenact\" 5 Witherbark stories in Camp Stonewash. Progress: What's wrong with a gentle story about falling asleep at an inopportune time? Tortollan folklore is full of those. Do trolls not sleep?",rewardGold=341600,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=242391}},ends={{npcID=242391}},coords={x=0.472,y=0.244,source="quest_giver",zoneID=15947},questType="standard"},
[90484] = {id=90484,name="Sightseeing Stegadon",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Wow, your armor is sooooo cool! Trishe stares, slack-jawed.> Oh, have you seen my friend Steggy? She was here with me, but then there were all these pretty bugs and things, and she ran off after them, and I was too slow to follow her. Trishe pouts.> I'm s'posed to watch Steggy. I'm response-able! And now you're response-able for finding her, okay?",objectivesText="Find Steggy and defeat Hidegorger the Everburning in Zul'Aman . Progress: Have you seen how big the trolls are? Steggy is going to be bigger than the trolls, but she's still little like me. Steggy needs to eat so she can get bigger. Please find her so I can feed her!",rewardGold=683200,rewardXP=15215,rewardCurrencies={{id=3316,amount=20},{id=3354,amount=100}},starts={{npcID=242393}},ends={{npcID=242393}},coords={x=0.472,y=0.26,source="quest_giver",zoneID=15947},questType="standard"},
[90485] = {id=90485,name="Afterthought Artifacts",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="This location is ideal for finding artifacts. Searching through the rubble at the bottom of that lake could reveal many treasures. If you have a moment, you're welcome to take a look around yourself. Bring me anything you find and we'll see if it's valuable.",objectivesText="Find artifacts in the lake near Camp Stonewash in Zul'Aman . Progress: Found anything exciting yet?",rewardGold=170800,rewardXP=6085,rewardItems={241614,241615,251075,251272},rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=242391}},ends={{npcID=242391}},coords={x=0.472,y=0.244,source="quest_giver",zoneID=15947},questType="standard"},
[90486] = {id=90486,name="Dangerous Delicacies",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="A Witherbark troll could survive eatin' each of these ingredients raw, but dey would need aid. Together, de ingredients would be deadly. We're going to cook dem into one dish. Don't worry. I'll show you how to take out enough poison so it tastes good AND has paralytic effects.",objectivesText="Cook Blistereel Boar in Camp Stonewash. Progress: What do you think this is going to taste like? Amaxi says it's absolutely arresting and could kill a stegodon!",rewardGold=170800,rewardXP=6085,rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=242394}},ends={{npcID=242390}},coords={x=0.472,y=0.246,source="quest_giver",zoneID=15947},questType="standard"},
[90493] = {id=90493,name="The Heart of Tranquillien",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="We can't let the Twilight's Blade get away with this. There are innocent citizens all over town who had nothing to do with this cult. You heard the governor: anyone who doesn't join will be executed. I won't stand for that. Go--aid any civilians you can find. Get them out of harm's way. If they're being attacked, take their attacker down. Tranquillien will not fall under my watch.",objectivesText="Rescue 8 innocent Tranquillien Citizens.",rewardGold=322100,rewardXP=11765,rewardItems={253485,253488},rewardChoices={253485,253488},rewardCurrencies={{id=3316,amount=10}},starts={{npcID=236686}},ends={{npcID=243984}},coords={x=0.476,y=0.696,source="quest_giver",zoneID=15968},questType="standard"},
[90494] = {id=90494,name="The Missing Magister",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="Umbric went to chase down Antenorian when the fighting broke out, but nobody has seen him since. I trust him to hold his own, but between Kasiea's death and Antenorian's betrayal, I worry he may be so set on revenge that he won't see an attack if one happens. Can you find him for me? I'll stay here and make sure these civilians remain safe.",objectivesText="Find Magister Umbric . Progress: I will not allow them to get away with this.",rewardGold=341600,rewardXP=11765,rewardItems={239134,243468,248051,248052},rewardChoices={248051,248052},rewardCurrencies={{id=3316,amount=10}},starts={{npcID=243984}},ends={{npcID=242143}},coords={x=0.49,y=0.684,source="quest_giver",zoneID=15968},questType="standard"},
[90509] = {id=90509,name="The Traitors of Tranquillien",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="Some of the town's most respected citizens, traitors? How long has the Twilight's Blade been here? How many scouts have gone missing? Crimes gone unreported? Innocents recruited by those they thought they could trust? They must be stopped. Cut down the traitors. Show them that Tranquillien is no home for cultists.",objectivesText="Slay Ranger Lethvalin , Matron Narsilla , and Guard Captain Leonic . Progress: We cannot allow these traitors to escape!",rewardGold=341600,rewardXP=11765,rewardItems={248064,248065,248066,248069,248072,248074,248077,248084,250355,250356},rewardChoices={248065,248069,248084,250355,250356},rewardCurrencies={{id=3316,amount=10}},starts={{npcID=236686}},ends={{npcID=243984}},coords={x=0.476,y=0.696,source="quest_giver",zoneID=15968},questType="standard"},
[90533] = {id=90533,name="Go Get Orweyna!",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Hey! Champ! Look, I swear I'm glad to see ya. I'm just in a little bit of a diplomatic situation here. Can you go get Orweyna and bring her back here? See if she'll talk this beast into letting me go? I'm not an elekk plushie, for cryin' out loud.",rewardGold=34100,rewardXP=1520,rewardItems={241125},rewardCurrencies={{id=3316,amount=5},{id=3370,amount=10}},starts={{npcID=242593,x=0.47,y=0.458,zoneID=15355}},ends={{npcID=242592,x=0.54,y=0.552,zoneID=15355}},coords={x=0.47,y=0.458,source="quest_giver",zoneID=15355},questType="world",worldTaskTitle="Go Get Orweyna!"},
[90534] = {id=90534,name="The Home of the Haranir",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15921,mapID=2413,description="I am eager to show Monte my home, but I know it is very different from what he is used to. Come with us as he meets my people.",objectivesText="Accompany Orweyna and Gazlowe around the Cradle and the Den.",rewardGold=341600,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=242592}},ends={{npcID=242881}},coords={x=0.54,y=0.552,source="quest_giver",zoneID=15355},questType="standard"},
[90535] = {id=90535,name="Leave Your Mark",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15921,mapID=2576,description="One thing that is very important to the haranir is our past. Some may remove their ability to hear the Goddess, but we are all connected to who came before us. You and Gazlowe are a part of our history now. You have earned the right to leave your mark here in the Den, for as long as the Den remains. Go, touch the wall with your painted hand, and know that you touch the same stone as generations before you.",objectivesText="Paint your mark on the wall of the Den. Progress: We are continually making ourselves new, even as we hold to what came before. I should remember this more often.",rewardGold=315900,rewardXP=12170,rewardItems={260427},rewardCurrencies={{id=3316,amount=25},{id=3370,amount=250}},starts={{npcID=242882}},ends={{npcID=242882}},coords={x=0.478,y=0.226,source="quest_giver",zoneID=15921},questType="standard"},
[90536] = {id=90536,name="The Tale of Wey'nan's Ward",level=83,requiredLevel=83,faction="none",expansion=11,zoneID=15355,mapID=2413,objectivesText="Zaratti forces slain Follow Wey'nan's trail tall grass Wey'nan calmed Wey'nan's Ward crafted",rewardItems={241349,241611},starts={{npcID=241117}},ends={{npcID=241117}},questType="standard",db2Objectives={{orderIndex=0,type=0,amount=6,objectID=240970,text="Zaratti forces slain"},{orderIndex=1,type=0,amount=1,objectID=241172,text="Follow Wey'nan's trail"},{orderIndex=6,type=0,amount=1,objectID=241831,text="Wey'nan's Ward crafted"},{orderIndex=2,type=19,amount=0,objectID=36978,text="tall grass"},{orderIndex=4,type=0,amount=1,objectID=241560,text="Wey'nan calmed"}},worldTaskTitle="The Tale of Wey'nan's Ward"},
[90537] = {id=90537,name="Late Bloomers",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="It is good to see you again, . Orweyna told me that you might be able to help me with something. A group of rutaani were due to arrive here earlier today, but they're late. They're coming up from Blooming Terrace with my mentor, Ru'gar, and I am worried they've had trouble on the road. Will you scout along the road from here down to the Terrace? I'll come up from there and we can meet on the way if we find nothing.",objectivesText="Look for the missing company of rutaani and haranir. Progress: Quietly now. The enemy is close.",rewardGold=170800,rewardXP=6085,rewardItems={244337},rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=242650}},ends={{npcID=243053}},coords={x=0.368,y=0.26,source="quest_giver",zoneID=15355},questType="standard"},
[90538] = {id=90538,name="Prey Contract: Zealous Crusader",level=90,requiredLevel=90,faction="none",expansion=11,questType="standard"},
[90540] = {id=90540,name="Rutaani Rescue",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Over the hill north of here is a fungarian village, Fungal Cleft. I believe the missing rutaani have been taken there. The fate that awaits them is a brutal one if we do not get them back quickly. Usually, fungarians favor hosts that are already dead for their reproductive purposes. The ones here are strangely vicious, however. I have seen some mushroom-covered animals and rutaani who are still moving around! It is unnatural. Go to Fungal Cleft and see if you can rescue the missing travelers.",objectivesText="Rescue 5 Captured Rutaani .",rewardGold=315900,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=243053}},ends={{npcID=243053}},coords={x=0.49,y=0.298,source="quest_giver",zoneID=15355},questType="standard"},
[90544] = {id=90544,name="Thief at Bark",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="Luma stands in front of you, ears perked, thankful for your help. She lets out a short bark, tail wagging once before trotting a few steps forward, then pausing. Glancing back, Luma waits expectantly. Her body language pleads, \"Come on, follow me!\">",objectivesText="Follow Luma . Progress: < Luma appears to be waiting for your approval.>",rewardGold=341600,rewardXP=11765,rewardItems={262999},rewardCurrencies={{id=3316,amount=25},{id=3365,amount=250}},starts={{npcID=242688}},ends={{npcID=242688}},coords={x=0.398,y=0.392,source="quest_giver",zoneID=15968},questType="standard"},
[90546] = {id=90546,name="Missing Paladins",level=90,requiredLevel=90,faction="alliance",expansion=11,zoneID=15968,mapID=2393,description="Some of our brothers and sisters in the Light were responding to a request for help by the Magisters at the Sanctum of the Moon. Apparently the Twilight's Blade has been seen lurking in the area. We expected to hear back from them awhile ago, but we've heard nothing. Given the strength of the party that went, Salandria and I wanted some additional backup before we looked into the issue. Care to lend a hand?",objectivesText="Meet Taelia at the Sanctum of the Moon.",rewardGold=31200,rewardXP=1370,rewardCurrencies={{id=3316,amount=5},{id=3365,amount=10}},starts={{npcID=242803}},ends={{npcID=242889}},coords={x=0.532,y=0.696,source="quest_giver",zoneID=15969},questType="standard"},
[90547] = {id=90547,name="Missing Paladins",level=90,requiredLevel=90,faction="horde",expansion=11,zoneID=15968,mapID=2393,description="Some of our brothers and sisters in the Light--including my friend Dawnheart--were responding to a request for help by the Magisters at the Sanctum of the Moon. Apparently the Twilight's Blade has been seen lurking in the area. We expected to hear back from them awhile ago, but we've heard nothing. Given the strength of the party that went, Taelia and I wanted some additional backup before we looked into the issue. Care to lend a hand?",objectivesText="Meet Salandria at the Sanctum of the Moon.",rewardGold=34100,rewardXP=1370,rewardCurrencies={{id=3316,amount=5},{id=3365,amount=10}},starts={{npcID=242802}},ends={{npcID=242890}},coords={x=0.532,y=0.696,source="quest_giver",zoneID=15969},questType="standard"},
[90548] = {id=90548,name="Twilight Missive",level=90,requiredLevel=90,faction="horde",expansion=11,zoneID=16182,mapID=2395,description="We need to figure out what the Twilight's Blade is trying to do here. We also need to get rid of these cultists so the Magisters can get back to their work building runestones. Take out as many cultists as you can. See if any of them are carrying information we can use.",objectivesText="Collect 6 missives. Progress: What'd you find?",rewardGold=341600,rewardXP=13690,rewardItems={244844},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=242890}},ends={{npcID=242890}},coords={x=0.44,y=0.67,source="quest_giver",zoneID=15968},questType="standard"},
[90549] = {id=90549,name="Signs of the Struggle",level=90,requiredLevel=90,faction="alliance",expansion=11,zoneID=15968,mapID=2395,description="The Twilight's Blade are acting boldly in their takeover here. None of these Magisters have any information for us. We'll hold this end of the bridge and protect any Magisters who escape. You get in there and look for signs of the missing paladins. Were they taken? Did they put up a fight, or were they ambushed? Are they still armed? I have a bad feeling we are running out of time.",objectivesText="Look for signs of the lost paladins. Progress: Have you found sign of the missing paladins?",rewardGold=341600,rewardXP=13690,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=242889}},ends={{npcID=242889}},coords={x=0.44,y=0.67,source="quest_giver",zoneID=15968},questType="standard"},
[90550] = {id=90550,name="A Somber Sun",level=90,requiredLevel=90,faction="horde",expansion=11,zoneID=15968,mapID=2395,description="Salandria will want to know of this.>",objectivesText="Report the corpse to Salandria .",rewardGold=170800,rewardXP=6850,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=242811}},ends={{npcID=242890}},coords={x=0.432,y=0.698,source="quest_giver",zoneID=15968},questType="standard"},
[90551] = {id=90551,name="Captured Information",level=90,requiredLevel=90,faction="horde",expansion=11,zoneID=15968,mapID=2395,description="We need to find out where the paladins were taken. Easiest way to do that is ask... under a bit of duress. Find an isolated target, beat them down, and then drag them to the hollow on the other side of the Sanctum. Taelia and I will get the civilians to safety and meet you there.",objectivesText="Capture and bring an isolated cultist to the Hollow Grove. Progress: Did you capture a cultist?",rewardGold=341600,rewardXP=13690,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=242890}},ends={{npcID=242893}},coords={x=0.44,y=0.67,source="quest_giver",zoneID=15968},questType="standard"},
[90552] = {id=90552,name="Interrogation",level=90,requiredLevel=90,faction="horde",expansion=11,zoneID=15968,mapID=2395,description="We need to know where Dawnheart and the others were taken. This one doesn't seem to want to talk... but we can fix that.",objectivesText="Interrogate the captive cultist. Progress: Are you sure we don't need to use a little more force?",rewardGold=341600,rewardXP=13690,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=242893}},ends={{npcID=242893}},coords={x=0.416,y=0.722,source="quest_giver",zoneID=15968},questType="standard"},
[90553] = {id=90553,name="Executing the Blades",level=90,requiredLevel=90,faction="horde",expansion=11,zoneID=15968,mapID=2395,description="Those monsters will pay for what they have done! Take out any Twilight's Blade cultists you see. We'll scour them from Eversong for good!",objectivesText="Kill 15 cultists. Progress: Show them no mercy!",rewardGold=341600,rewardXP=13690,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=242897}},ends={{npcID=245944}},coords={x=0.444,y=0.812,source="quest_giver",zoneID=15968},questType="standard"},
[90554] = {id=90554,name="Leave Ashes in Your Wake",level=90,requiredLevel=90,faction="horde",expansion=11,zoneID=15968,mapID=2395,description="We need to make it clear to these cultists that they aren't welcome. Tear down their banners, and destroy their books and supplies. Do whatever you can to wreck their camp!",objectivesText="Wreck the Twilight's Blade camp in Deatholme. Progress: Have you destroyed the camp?",rewardGold=341600,rewardXP=13690,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=242897}},ends={{npcID=245944}},coords={x=0.444,y=0.812,source="quest_giver",zoneID=15968},questType="standard"},
[90555] = {id=90555,name="Blessing of Freedom",level=90,requiredLevel=90,faction="alliance",expansion=11,zoneID=15968,mapID=2395,description="Our friends are being held in this area. I have no idea what state we'll find them in, but I pray they are at least alive. Help me find and free our missing paladins in the Ruins of Deatholme.",objectivesText="Free paladins in the Ruins of Deatholme. Progress: Have <name> found everyone yet?",rewardGold=341600,rewardXP=13690,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=242898}},ends={{npcID=245943}},coords={x=0.444,y=0.812,source="quest_giver",zoneID=15968},questType="standard"},
[90556] = {id=90556,name="Cutting off the Head",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15968,mapID=2395,description="We'll crush their leader! For justice and the Light!",objectivesText="Slay Overseer Mognak . Progress: May their ilk never come around here again!",rewardGold=683200,rewardXP=17110,rewardItems={263374,263375,263376,263378},rewardCurrencies={{id=3316,amount=25},{id=3365,amount=250}},starts={{npcID=245944}},ends={{npcID=245944}},coords={x=0.437,y=0.857,source="quest_giver",zoneID=15968},questType="standard"},
[90568] = {id=90568,name="Unlikely Friends",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="This old Witherbark pot you found is quite interesting. I've made a series of notes on its construction and use, but now it's time we speak to Elder Ren'zen . The pot should be returned to him. And he can fill in the gaps in the pot's story! Let's speak with him in the village.",objectivesText="Speak with Elder Ren'zen in Witherbark Village.",rewardGold=34100,rewardXP=1520,rewardItems={264182,264183},rewardCurrencies={{id=3316,amount=25},{id=3354,amount=250}},starts={{npcID=242391}},ends={{npcID=242464}},coords={x=0.472,y=0.244,source="quest_giver",zoneID=15947},questType="standard"},
[90569] = {id=90569,name="Back in the Bag",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="What a mess this is. The sack you found was supposed to be filled with seeds. They're part of an important cultivation project that Ru'gar was working on. It appears the fungarians made off with the seeds when they captured the rutaani. While you're looking for the rutaani, see if you can recover the seeds that were stolen.",objectivesText="Collect 6 Stolen Seeds . Progress: I can't bear to think of what the fungarians will do to the seeds that Ru'gar has been carefully cultivating. He had been working with the rutaani on plants that were more hardy and produced greater yield. His work should not be lost.",rewardGold=341600,rewardXP=12170,rewardItems={242226},rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=243053}},ends={{npcID=243053}},coords={x=0.49,y=0.298,source="quest_giver",zoneID=15355},questType="standard"},
[90570] = {id=90570,name="To the Ruins of Deatholme",level=90,requiredLevel=90,faction="alliance",expansion=11,zoneID=15968,mapID=2395,description="Thanks to our \"friend\" here, we know the missing paladins were taken to Deatholme. We have to find them before it's too late! Salandria and I will meet you there.",objectivesText="Meet Taelia and Salandria at Deatholme.",rewardGold=34100,rewardXP=1370,rewardCurrencies={{id=3316,amount=5},{id=3365,amount=10}},starts={{npcID=242894}},ends={{npcID=242898}},coords={x=0.416,y=0.722,source="quest_giver",zoneID=15968},questType="standard"},
[90571] = {id=90571,name="The Lay of the Beast",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="Your friend's scheme to blow up the Nexus-Point was adorable. You all looked so determined, I didn't have the heart to tell you how simple the solution really is. The Mantle of Predation will allow you to enter the Nexus-Points and weaken the storm. Alas, it's claiming the Mantle that will truly test you. Borrow my pet--see through his eyes. I'll show you who you'll steal the Mantle from.",objectivesText="Use Decimus 's pet to scout the Voidspire. Progress: Go on. Ciphus won't mind.",rewardGold=322100,rewardXP=12845,rewardItems={260858,260859},rewardChoices={260858,260859},rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=235697}},ends={{npcID=235697}},coords={x=0.514,y=0.728,source="quest_giver",zoneID=15458},questType="standard"},
[90573] = {id=90573,name="Fortify the Runestones: Magisters",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="We placed a number of runestones throughout Eversong Woods , each one charged with protective arcane magic intended to ward off the Lightbloom. While highly effective, the runestones require an immense amount of power to function. They must be regularly fed with latent arcana lest they weaken. As Magisters, it is our duty to maintain the runestones--especially when the eyes of this Haven are upon us. Recharge their arcane power and defend them from those who would threaten us.",objectivesText="Collect Latent Arcana from Saltheril's Soiree weekly quests and Misplaced Tomes, then use it to charge and defend a Runestone in Eversong Woods . Progress: We must ensure the runestones are charged and defended.",rewardGold=341600,rewardXP=14705,rewardItems={263465},rewardCurrencies={{id=3316,amount=200},{id=3365,amount=2000},{id=3379,amount=125},{id=3379,amount=150}},starts={{npcID=240834}},ends={{npcID=240834}},coords={x=0.426,y=0.462,source="quest_giver",zoneID=15968},questType="group"},
[90574] = {id=90574,name="Fortify the Runestones: Blood Knights",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="The Magisters placed a number of runestones throughout Eversong Woods , each one charged with protective arcane magic intended to ward off the Lightbloom. Naturally, the runestones require an immense amount of power to function. They can be fed with latent arcana, but that power draws enemies seeking to claim it. As Blood Knights, it is our duty to defend the runestones--especially when the eyes of this Haven are upon us. Recharge their arcane power and defend them from those who would threaten us.",objectivesText="Collect Latent Arcana from Saltheril's Soiree weekly quests and Coalesced Light, then use it to charge and defend a Runestone in Eversong Woods . Progress: Maintaining the safety of Eversong is of utmost importance.",rewardGold=341600,rewardXP=14705,rewardItems={263465},rewardCurrencies={{id=3316,amount=200},{id=3365,amount=2000},{id=3379,amount=125},{id=3379,amount=150}},starts={{npcID=240835}},ends={{npcID=240835}},coords={x=0.424,y=0.466,source="quest_giver",zoneID=15968},questType="group"},
[90575] = {id=90575,name="Fortify the Runestones: Farstriders",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="The Magisters placed a handful of runestones across Eversong, each one charged with arcane magic that wards off the Lightbloom. As you might guess, the runestones require a huge amount of power to function. The Magisters feed them with latent arcana, but that kind of power draws a lot of attention. Bad attention. As Farstriders, it's our duty to defend Eversong from those kinds of threats--especially when the Haven is looking at us. Go recharge the runestones and fight off whatever tries to stop you.",objectivesText="Collect Latent Arcana from Saltheril's Soiree weekly quests and Ranger's Caches, then use it to charge and defend a Runestone in Eversong Woods . Progress: We need to keep those runestones safe.",rewardGold=341600,rewardXP=14705,rewardItems={263465},rewardCurrencies={{id=3316,amount=200},{id=3365,amount=2000},{id=3379,amount=125},{id=3379,amount=150}},starts={{npcID=240836}},ends={{npcID=240836}},coords={x=0.428,y=0.464,source="quest_giver",zoneID=15968},questType="group"},
[90576] = {id=90576,name="Fortify the Runestones: Shades of the Row",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2395,description="Have you seen the runestones out in Eversong? Huge rocks full of arcane magic that ward off the Lightbloom. I'm not the magic type, but I know an opportunity when I see one. Those runestones need a lot of power to work. If we help keep them charged, there are a lot of people who would owe us favors--and favors are even better than gold. Here's the plan: I help you get some latent arcana, you drop it into the runestones, beat up whatever tries to stop you, then we bask in the accolades. Deal?",objectivesText="Collect Latent Arcana from Saltheril's Soiree weekly quests and Dead Drops , then use it to charge and defend a Runestone in Eversong Woods . Progress: Those runestones aren't going to charge themselves.",rewardGold=341600,rewardXP=14705,rewardItems={263465},rewardCurrencies={{id=3316,amount=200},{id=3365,amount=2000},{id=3379,amount=125},{id=3379,amount=150}},starts={{npcID=240837}},ends={{npcID=240837}},coords={x=0.428,y=0.456,source="quest_giver",zoneID=15968},questType="group"},
[90601] = {id=90601,name="Gathering Glowshrooms",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Ru'gar used to tell me about how he'd sneak into the nearby cave to harvest glowshrooms . They seemed to be integral to the development of the tla'tak seeds he was cultivating. Will you collect some of the mushrooms within? Oh, and Ru'gar mentioned that the mushrooms have strange properties when harvested. I'm not sure what he meant by that, but maybe stay on your toes.",objectivesText="Collect 6 Glowshrooms . Progress: Ru'gar mentioned that the glowshrooms helped create a more robust harvest when they were mixed into the dirt he'd planted crops in. How he even figured that out, I'll never know. I would like to carry on Ru'gar's work. Since we're already here, we might as well gather what we can.",rewardGold=341600,rewardXP=12170,rewardItems={244429},rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=245166}},ends={{npcID=245166}},coords={x=0.496,y=0.232,source="quest_giver",zoneID=15355},questType="standard"},
[90602] = {id=90602,name="Gomphusta",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="I would ask one last thing of you. I've heard quite a few of the fungarians mention their leader, Gomphusta . It seems he's behind the uptick in their violence and the reason they're stealing the seeds. While you're in the cave, find him and take him out. Without Gomphusta pulling the strings, the other fungarians will be thrown into chaos and won't be able to organize ambushes as well.",objectivesText="Kill Gomphusta . Progress: The fungarians aren't always this violent and aggressive. Gomphusta must be the force driving them. He seems to be the one infecting living creatures with spores. With him gone, the fungarians may return to a more balanced state.",rewardGold=683200,rewardXP=15215,rewardItems={246117,246120,263473},rewardCurrencies={{id=3316,amount=25},{id=3370,amount=250}},starts={{npcID=245166}},ends={{npcID=245166}},coords={x=0.496,y=0.232,source="quest_giver",zoneID=15355},questType="standard"},
[90615] = {id=90615,name="Be Grudge You",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="You look... different! Ever be to Grudge Pit? Grudge Pit is great place! Full of fighting and cheering and fungarians. Also decaying! Boletus is always look for strong creatures to be kill in Grudge Pit. Or for making others be kill. Are strong creature? Should go to Pit!",objectivesText="Speak with Boletus at the Grudge Pit.",rewardGold=33500,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3370,amount=10}},starts={{npcID=254903}},ends={{npcID=243226}},coords={x=0.702,y=0.528,source="quest_giver",zoneID=15355},questType="standard"},
[90616] = {id=90616,name="You Strong?",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="You look strong. Should test yourself in our arena. See how you compare to strong fungarians.",objectivesText="Kill enemies in the Grudge Pit. Progress: Many fungarians watch the fighting. Always so exciting!",rewardGold=341600,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=243226}},ends={{npcID=243226}},coords={x=0.718,y=0.64,source="quest_giver",zoneID=15355},questType="standard"},
[90617] = {id=90617,name="A Few Fun Guys",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="You are very strong, $p. Will teach fungarians to fight? Much we could learn from you. Many fungarians watch battle. Ask if they want to be strong in Pit.",objectivesText="Recruit 3 Fungarians.",rewardGold=170800,rewardXP=6085,rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=243226}},ends={{npcID=243226}},coords={x=0.718,y=0.64,source="quest_giver",zoneID=15355},questType="standard"},
[90619] = {id=90619,name="What Doesn't Kill Them",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Have team, now are ready to fight. Take your team to empty area. Practice fight, and see what can do.",objectivesText="Spar with your teammates. Progress: We fighting you? You are strong. Fight together is good practice for be strong.",rewardGold=341600,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=243226}},ends={{npcID=246208}},coords={x=0.718,y=0.64,source="quest_giver",zoneID=15355},questType="standard"},
[90620] = {id=90620,name="To the Ring",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="TeamName? Not bad. I like! You and the TeamName head on down, and we say words. You fight Spore Storm. If beat, fight Cap Clash. If beat, fight Fungus Force. Always-winners are Glow Guard. You won't beat. No run out! Run out is big, big lose.",objectivesText="Go fight with your team.",rewardGold=683200,rewardXP=15215,rewardCurrencies={{id=3316,amount=20},{id=3370,amount=100}},starts={{npcID=243226}},ends={{npcID=247245}},coords={x=0.718,y=0.64,source="quest_giver",zoneID=15355},questType="standard"},
[90621] = {id=90621,name="Tiny Heroes' Journeys",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="You taught them. Why did they run out? All fungarians were excited to see if a could teach fungarians for be strong. You try one more time, okay? First do what need to get them ready.",objectivesText="Help each member of the team overcome their challenges.",rewardGold=170800,rewardXP=6085,rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=243226}},ends={{npcID=243226}},coords={x=0.718,y=0.64,source="quest_giver",zoneID=15355},questType="standard"},
[90622] = {id=90622,name="Not-Yet Defeated Champions",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="$p, the PHTeamname look stronger now! More ready. Hope they won't run again. Next fight is against Glow Guard. Glow Guard always never lose. Hope your training makes fight better, before TEAMNAME lose. Will be fun for watch!",objectivesText="Enter the Grudge Pit and defeat the Glow Guard. Progress: The Grudge Pit is always looking for new champions, <name>. Until now, we've just been finding the old ones again.",rewardGold=683200,rewardXP=15215,rewardCurrencies={{id=3316,amount=25},{id=3370,amount=250}},starts={{npcID=243226}},ends={{npcID=243226}},coords={x=0.718,y=0.64,source="quest_giver",zoneID=15355},questType="standard"},
[90669] = {id=90669,name="Gold is Gold",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Hey! You there. Sarvi beckons you closer and lowers her voice.> You looking for work? A Magister gave me five gold to find an adventuring type to do some sort of job for him. He said if the person gets it done, I get five more. That'll feed me for months. You fit the bill. If you want to try to get paid too, he has a study over by the harbor. Real fancy place--you can't miss it. The guy's name is Aradis.",objectivesText="Speak to Magister Aradis in his study near the Silvermoon Harbor.",rewardGold=30900,rewardXP=1470,rewardCurrencies={{id=3316,amount=5},{id=3365,amount=10}},starts={{npcID=243290}},ends={{npcID=241393}},coords={x=0.544,y=0.616,source="quest_giver",zoneID=15969},questType="standard"},
[90671] = {id=90671,name="Friend of the Grummles",faction="none",expansion=11,zoneID=5841,description="Be a friend to the grummles!",objectivesText="Help them grummles!",questType="standard"},
[90690] = {id=90690,name="Charge of the Vanguard",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16340,mapID=2393,description="Turalyon reports the Vanguard of the Light is prepared to march on Xal'atath's stronghold. Would that I could join you for the charge. I will keep my retainer of forces here to maintain the defense of the Sunwell and Silvermoon while you take the fight to our enemy. Muster in the Voidstorm, take the fight to the Voidspire, and bring an end to this great enemy. Good hunting.",objectivesText="Meet with Turalyon in the Voidstorm.",rewardGold=34100,rewardXP=1370,starts={{npcID=235787}},ends={{npcID=239810},{npcID=244298}},coords={x=0.454,y=0.704,source="quest_giver",zoneID=15969},questType="raid"},
[90718] = {id=90718,name="Request of the Arcantina",level=90,requiredLevel=90,faction="horde",expansion=11,zoneID=10473,mapID=2393,description="Ah, ! I hear you have a standing invitation to Archmage Khadgar 's... Arcantina? Can you go there for me and bring this missive to the Archmage? I need to source reagents for the sheer volume of telemancy spells I have been asked to conjure. Magister's Terrace has been an excellent source up until recent events but really I need the Kirin Tor to loan me some of their harder to find ingredients.",objectivesText="Deliver Telemancer's Request to Archmage Khadgar at the Arcantina. Progress: Champion? Do you have something for me?",rewardGold=34100,rewardXP=1370,rewardItems={260165},starts={{npcID=240265}},ends={{npcID=242585}},coords={x=0.474,y=0.696,source="quest_giver",zoneID=15969},questType="standard"},
[90724] = {id=90724,name="The Broken Sky",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2405,description="All those people. Our army. Our heroes. Our leaders. Gone. We are exposed here. Umbric's tether saved us, but we need to ensure we survive this. Report to Lor'themar and tell him what transpired in the Voidspire. I will get Umbric to safety and learn what I can here.",objectivesText="Report to Lor'themar in Silvermoon City.",rewardGold=170800,rewardXP=6850,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50},{id=3391,amount=10}},starts={{npcID=244297},{npcID=253603}},ends={{npcID=235787}},coords={x=0.209,y=0.672,source="quest_giver",zoneID=16340},questType="standard"},
[90733] = {id=90733,name="The Listener",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Now that you've learned about our legends, you've earned the notice of one of our elders. He wants to meet you. His name is Aksem , and he knows things that the rest of us have never learned. History that remains hidden, even in the paintings. Go and introduce yourself. He's expecting you.",rewardGold=335000,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=238170,x=0.542,y=0.53,zoneID=15355}},ends={{npcID=243759,x=0.534,y=0.494,zoneID=15355}},coords={x=0.542,y=0.53,source="quest_giver",zoneID=15355},questType="world",worldTaskTitle="The Listener"},
[90734] = {id=90734,name="In the Name of the Goddess",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="The high priest Aksem has asked for you again. He said you are not the only one on a quest for knowledge about the deep history of Harandar . Go to him. I believe he already has another guest who is also interested in learning this hidden history.",rewardGold=341600,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=238170,x=0.542,y=0.53,zoneID=15355}},ends={{npcID=243759,x=0.534,y=0.494,zoneID=15355}},coords={x=0.542,y=0.53,source="quest_giver",zoneID=15355},questType="world",worldTaskTitle="In the Name of the Goddess"},
[90735] = {id=90735,name="The Stolen Staff",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="This time, I do not have a story for you. Instead, Aksem has asked that you meet with him to help recover the next of the relics. Go to speak with him, and he will tell you more of what you must do.",objectivesText="Speak to Aksem in the Den.",rewardGold=34100,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3370,amount=10}},starts={{npcID=238170}},ends={{npcID=243759}},coords={x=0.542,y=0.53,source="quest_giver",zoneID=15355},questType="standard"},
[90736] = {id=90736,name="That's Not Yours",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="The rutaani in the Blossoming Terrace are crafty. They've trained their petalwings to search and grab anything shiny that rolls down from the Den. And, I suspect, sometimes they grab things that haven't naturally fallen. So we want to get those things back. That's where you come in. Go into the terrace, and don't hesitate to use force to send a message. That's a language we all understand.",objectivesText="Retrieve 8 Stolen Belongings from the Blossoming Terrace. Progress: Have you found those missing things?",rewardGold=341600,rewardXP=12170,rewardItems={246221},rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=243762}},ends={{npcID=243762}},coords={x=0.588,y=0.478,source="quest_giver",zoneID=15355},questType="standard"},
[90737] = {id=90737,name="Nested Clues",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="You're looking for a staff called the Root of the World. It's a powerful twist of woven roots, back from before the haranir traveled deep into the mountain. It's irreplaceable, as Aksem knows. So if a rutaani petalwing stole it, that's embarrassing. The only way for everyone to save face is to get it back. Search the nests of the bigger birds. They've been trained to look for more valuable items.",objectivesText="Uncover clues about where the stolen rootstaff could be. Progress: Have you found where the staff might be?",rewardGold=341600,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=243762}},ends={{npcID=243762}},coords={x=0.588,y=0.478,source="quest_giver",zoneID=15355},questType="standard"},
[90738] = {id=90738,name="To the Blossoming Terrace",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="When the haranir first arrived in Harandar , they brought with them a staff formed of the roots of a great tree. That tree has since gone away, but the roots remain. It has been our duty to protect that staff and pass it on through the generations, but now it has been stolen. Your task is to find it and return it to Zur'Ashar Kassameh. Go into the mists below the Den and seek out the Shul'ka. They will guide you on your search.",objectivesText="Meet Shul'ka Seila outside the Blossoming Terrace.",rewardGold=33800,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3370,amount=10}},starts={{npcID=243759}},ends={{npcID=243762}},coords={x=0.534,y=0.494,source="quest_giver",zoneID=15355},questType="standard"},
[90739] = {id=90739,name="The Root of Things",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Looks like you didn't find any sign of the rootstaff among all the thiever's nests. That's a good thing, honestly. But there's more to this test than just recovering stolen goods. Yes, it's a test. You're seeking secret knowledge. That means something here doesn't add up, and the real answer is waiting to be found. So, come find me when you're ready to get that answer.",objectivesText="Follow Shul'ka Seila and recover the missing staff.",rewardGold=341600,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=243762}},ends={{npcID=243759}},coords={x=0.588,y=0.478,source="quest_giver",zoneID=15355},questType="standard"},
[90740] = {id=90740,name="A Legend to Know",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="I am entrusted with many secrets, and the benefit of that is not having to explain myself often. You have recovered the Root of the World, as I asked. Now, take it to Zur'ashar Kassemeh, and learn more about it. There will be more for you, later.",objectivesText="Return to Zur'ashar Kassameh .",rewardGold=32800,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3370,amount=10}},starts={{npcID=243759}},ends={{npcID=238170}},coords={x=0.534,y=0.494,source="quest_giver",zoneID=15355},questType="standard"},
[90741] = {id=90741,name="Once More Into the Rift",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Aksem has asked for you again. He says he's ready for you to undergo the final ritual for the knowledge he wants to teach you. I admit, I'm envious, but I do not envy the trials you'll need to undergo in order to prepare for this knowledge. Go speak to Aksem , and do as he says. Orweyna will be joining you.",rewardGold=33500,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3370,amount=10}},starts={{npcID=238170,x=0.542,y=0.53,zoneID=15355}},ends={{npcID=243795,x=0.618,y=0.622,zoneID=15355}},coords={x=0.542,y=0.53,source="quest_giver",zoneID=15355},questType="world",worldTaskTitle="Once More Into the Rift"},
[90742] = {id=90742,name="Shrouded by Aln'hara",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="As you know well by now, the creatures in the rift are infused with the essence of Aln'hara. What we need is that essence mixed with water. Aksem wants us to collect water here and then infuse the essence of Aln'hara into it. I can only imagine what it might be used for.",objectivesText="Collect water and defeat creatures in the Rift of Aln. Progress: The voice is as strong as ever here.",rewardGold=341600,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=243795}},ends={{npcID=243795}},coords={x=0.618,y=0.622,source="quest_giver",zoneID=15355},questType="standard"},
[90743] = {id=90743,name="Ritual Reinforcement",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="You know the dangers of the Rift of Aln, but this is the best place to prepare for the kind of ritual Aksem wants to perform. Go about the rift and place offerings to prepare yourself.",objectivesText="Place Ritual Offerings in the Rift of Aln.",rewardGold=328500,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=243794}},ends={{npcID=243794}},coords={x=0.618,y=0.622,source="quest_giver",zoneID=15355},questType="standard"},
[90744] = {id=90744,name="The Dreamrift: Malformed Mystery",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15355,mapID=2413,description="We have prepared ourselves as best we can for the next stage. Now, we must venture into the deepest part of the Rift of Aln. Into the Dreamrift. It's a place so dangerous that even the Shul'ka hesitate to go, but we must. Aksem needs us to collect the most powerful infusion of Aln there is. Are you ready?",objectivesText="Defeat Chimaerus in the Dreamrift.",rewardGold=1024800,rewardXP=17650,rewardCurrencies={{id=3316,amount=500},{id=3344,amount=30},{id=3370,amount=1500}},starts={{npcID=243795}},ends={{npcID=243759}},coords={x=0.618,y=0.622,source="quest_giver",zoneID=15355},questType="raid"},
[90745] = {id=90745,name="The Empty Cradle",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="You have ventured far, fought deep, and learned many things about our history to be here. Now it's time to know the truth. Prepare yourself.",objectivesText="Speak to Aksem in the Den.",rewardGold=34100,rewardXP=1520,rewardItems={260306},rewardCurrencies={{id=3370,amount=250}},starts={{npcID=243759}},ends={{npcID=243759}},coords={x=0.534,y=0.494,source="quest_giver",zoneID=15355},questType="standard"},
[90746] = {id=90746,name="The Elves Assemble",level=90,requiredLevel=90,faction="none",expansion=11,description="The time for preparations have passed. Xal'atath's forces are upon us. Join us, champion, as we must rebuff this assault and then press our attack on the Darkwell.",objectivesText="Speak to Arator at the war table.",rewardGold=34100,rewardXP=1370,questType="standard"},
[90748] = {id=90748,name="Quel'Danas",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16215,mapID=2393,description="Champion, the time has come to see an end to the Darkwell. I do not know what awaits us beyond the gates of Quel'Danas, but we cannot tarry any longer. The Void continues to pour into the Darkwell, transforming it. Arator is at the head of our combined armies. He has asked you and your strongest allies join him at his side. It is time to end this and take back our well.",objectivesText="Meet with Arator before the gates of Quel'Danas.",rewardGold=34100,rewardXP=1370,starts={{npcID=235787}},ends={{npcID=245061}},coords={x=0.454,y=0.704,source="quest_giver",zoneID=15969},questType="raid"},
[90749] = {id=90749,name="Our Mutual Enemy",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=16194,mapID=2395,description="We have two choices. We can either continue to talk to the Amani or fight our way inside. I would still prefer to negotiate passage with Zul'jarra, but if our diplomacy goes awry, be ready. For now, follow my lead.",objectivesText="Follow Lady Liadrin into Zul'Aman .",rewardGold=167500,rewardXP=6085,rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=236436}},ends={{npcID=236485}},coords={x=0.602,y=0.814,source="quest_giver",zoneID=15968},questType="standard"},
[90759] = {id=90759,name="The Cult Within",level=10,requiredLevel=10,faction="alliance",expansion=11,zoneID=1519,mapID=84,description="$p, Rumors suggest that Xal'atath's cult, the Twilight's Blade, has been recruiting in Alliance cities. Meet me in Stormwind to investigate these rumors. If the cult is there, then we must stamp it out at once. Magister Umbric",objectivesText="Meet Magister Umbric in Stormwind.",rewardGold=28090,rewardXP=175,starts={{npcID=246156}},ends={{npcID=246156}},coords={x=0.718,y=0.602,source="quest_giver",zoneID=1519},questType="standard"},
[90760] = {id=90760,name="Avoiding Blame",level=10,requiredLevel=10,faction="alliance",expansion=11,zoneID=1519,mapID=84,description="Apocalyptic threats have taken many forms in Azeroth's history, but today we face Xal'atath and her Twilight's Blade. I fear that people are falling into hopelessness as the Radiant Song cries a warning. The Twilight's Blade could use that despair to draw them into their ranks. My mages have identified this district as housing a peculiar amount of void energy. Investigate and stop any cultists you may find.",objectivesText="Disperse 6 Suspicious Citizens in Stormwind. Progress: I understand the comfort the void can provide. But surrendering to it completely is not the peace many are led to believe.",rewardGold=309800,rewardXP=1415,starts={{npcID=246156}},ends={{npcID=246156}},coords={x=0.718,y=0.602,source="quest_giver",zoneID=1519},questType="standard"},
[90761] = {id=90761,name="Avoiding Blame",level=10,requiredLevel=10,faction="horde",expansion=11,zoneID=1637,mapID=85,description="The cult of twilight has long been dedicated to ending Azeroth. That they ally with Xal'atath is no surprise. If the Twilight's Blade are indoctrinating citizens, we must stop them. We cannot permit the weak to fall to the Void's dark designs. The Cleft of Shadow is home to many practitioners of unsavory magic. Identify and end any cultists you may find there.",objectivesText="Disperse 6 Suspicious Citizens in Orgrimmar . Progress: <Rommath sneers at you.> The calm and comfort the Void offers is a lie. You would do well to abandon it.",rewardGold=309800,rewardXP=1415,starts={{npcID=246158}},ends={{npcID=246158}},coords={x=0.42,y=0.606,source="quest_giver",zoneID=1637},questType="standard"},
[90762] = {id=90762,name="The Twilight Highlands",level=10,requiredLevel=10,faction="none",expansion=11,zoneID=4922,mapID=84,description="I've spoken with Grand Magister Rommath . Despite our differences, it seems we are aligned in purpose. We have both found evidence that Twilight's Blade cultists are convening in the Twilight Highlands . It's a place long scarred by the cult's misdeeds. And it's a suitable staging ground for an attack. Meet us there so we may continue our investigation.",objectivesText="Meet Grand Magister Rommath in the Twilight Highlands .",rewardGold=30900,rewardXP=175,starts={{npcID=246156}},ends={{npcID=237504}},coords={x=0.718,y=0.602,source="quest_giver",zoneID=1519},questType="standard"},
[90763] = {id=90763,name="The Twilight Highlands",level=10,requiredLevel=10,faction="horde",expansion=11,zoneID=4922,mapID=85,description="I've received word from Magister Umbric. He has found similar evidence that the Twilight's Blade are recruiting in Stormwind. The Void poses an existential threat to all of Azeroth. We must stop the cult at its source. We've agreed to meet in the cult's homeland, the Twilight Highlands . Find me there so we may continue our investigation.",objectivesText="Meet Grand Magister Rommath in the Twilight Highlands .",rewardGold=30900,rewardXP=175,starts={{npcID=246158}},ends={{npcID=237504}},coords={x=0.42,y=0.606,source="quest_giver",zoneID=1637},questType="standard"},
[90764] = {id=90764,name="The Cult Within",level=10,requiredLevel=10,faction="horde",expansion=11,zoneID=1637,mapID=85,description="$p, I have heard unsettling rumors that Xal'atath's cult, the Twilight's Blade, is recruiting within Horde cities. Meet me in Orgrimmar so we may root out this evil. We cannot suffer a single cultist within our walls. Grand Magister Rommath",objectivesText="Meet Grand Magister Rommath in Orgrimmar.",rewardGold=30900,rewardXP=175,starts={{npcID=246158}},ends={{npcID=246158}},coords={x=0.42,y=0.606,source="quest_giver",zoneID=1637},questType="standard"},
[90765] = {id=90765,name="Midnight Dress",level=10,requiredLevel=10,faction="horde",expansion=11,zoneID=4922,mapID=241,description="Cult activity in the area has risen significantly. While we are gathering troops, you secure a cultist disguise and infiltrate their nearby training grounds. Find out anything you can about the Twilight's Blade and their goals. I will keep this area secure.",objectivesText="Find a Twilight's Blade disguise and infiltrate the Twilight's Blade. Progress: You look lost, fledgling. Isn't there somewhere you should be?",rewardGold=309800,rewardXP=1415,rewardItems={246397,246398,246399,246400},starts={{npcID=237504}},ends={{npcID=246021}},coords={x=0.498,y=0.808,source="quest_giver",zoneID=4922},questType="standard"},
[90766] = {id=90766,name="Xal'atath's Proven Faithful",level=10,requiredLevel=10,faction="both",expansion=11,zoneID=4922,mapID=241,description="It takes more than blistering desperation for the apocalypse to be part of the Cult of Twilight. We are Xal'atath's Twilight's Blade. Our purpose is greater than it has ever been before. And thus, we must become her strongest allies. Go and train with my associates in the field. Educate yourself on our rituals and rhetoric. Only then will I allow you to go through the initiation ceremony.",objectivesText="Train to become a Twilight's Blade cultist.",rewardGold=309800,rewardXP=1415,starts={{npcID=246021}},ends={{npcID=246022}},coords={x=0.464,y=0.72,source="quest_giver",zoneID=4922},questType="standard"},
[90767] = {id=90767,name="More Doom",level=10,requiredLevel=10,faction="alliance",expansion=11,zoneID=4922,mapID=241,description="Having completed your training, you have earned full membership with the Twilight's Blade. As a member of the cult, you will now join your fellow acolytes in an initiation ceremony. They are in the basement of this building receiving instructions from our great leader, Mor'duun. Allow his words to fill you with zeal for the cause. The end is near!",objectivesText="Sabotage the ritual. Progress: Have you discovered more about the cult's plans?",rewardGold=154900,rewardXP=710,rewardItems={250465},starts={{npcID=246022}},ends={{npcID=246025}},coords={x=0.52,y=0.708,source="quest_giver",zoneID=4922},questType="standard"},
[90768] = {id=90768,name="Cult It Out",level=10,requiredLevel=10,faction="none",expansion=11,zoneID=4922,mapID=241,description="Mor'duun and his Twilight's Blade cultists are directly supporting the Harbinger's dark designs for our world. And that is all we need to know. Kill as many as you can, then meet us back at our base of operations. The cult and its leaders must be eliminated.",objectivesText="Kill Gehl Harrowtongue and 12 Twilight's Blade cultists.",rewardGold=619600,rewardXP=1770,rewardItems={246627},rewardCurrencies={{id=2815,amount=30}},starts={{npcID=246025}},ends={{npcID=237504}},coords={x=0.524,y=0.704,source="quest_giver",zoneID=4922},questType="standard"},
[90772] = {id=90772,name="The Flames Rise Higher",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="De coal... it's white-hot now. And I feel like there is somethin' inside it? Brek said dis was de last trial. But Jan'alai is not here. What do we do now? Zul'jarra looks at Brek and scowls.> Talk to Brek and see if he's got anything to say we can understand.",objectivesText="Complete the ritual of Jan'alai. Progress: If I cannot commune with Jan'alai, de path of de hash'ey stops at dis temple.",rewardGold=33500,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3354,amount=10}},starts={{npcID=236162}},ends={{npcID=236162}},coords={x=0.55,y=0.184,source="quest_giver",zoneID=15947},questType="standard"},
[90777] = {id=90777,name="Feeding the Flame",level=90,requiredLevel=90,faction="horde",expansion=11,zoneID=16215,mapID=2393,description="Champion, the Sunwell holds for now, but the Vanguard has begun to deploy the bulk of its forces to Voidstorm. Lady Liadrin has requested your assistance at the Sunwell.",objectivesText="Speak to Liadrin at the Sunwell. Progress: It's heartening to see our commanders so eager to bring the fight to the enemy.",rewardGold=34100,rewardXP=1370,rewardCurrencies={{id=3316,amount=5},{id=3365,amount=10}},starts={{npcID=235787}},ends={{npcID=247414}},coords={x=0.454,y=0.704,source="quest_giver",zoneID=15969},questType="standard"},
[90782] = {id=90782,name="The Nethersent",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15958,mapID=2405,description="Men of Void take us to here. Come from sky. Fighting, killing. Want to go back. Help brothers and sisters. Show you.",objectivesText="Free the draenei and meet with him at the base of Masters' Perch.",rewardGold=85400,rewardXP=3210,rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=242233}},ends={{npcID=241620}},coords={x=0.562,y=0.718,source="quest_giver",zoneID=15458},questType="standard"},
[90818] = {id=90818,name="Murder Row: Loose Lips",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="It is not unexpected to sense some fel magic here. There are still warlocks in the city and old fel siphoning chambers. But the evidence I've found so far is more than could be explained by just that. It feels... different. Chaotic. This practice has to be widespread, which means someone must be talking about it. I've been rooting around too long to go unnoticed, but perhaps you could covertly listen in on some idle banter around the city. If you learn anything useful, report back to me.",objectivesText="Listen in on 3 conversations near the Royal Exchange. Progress: People let many things slip when they assume they're unheard. Never assume you're unheard.",rewardGold=341600,rewardXP=11765,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=245418}},ends={{npcID=244443}},coords={x=0.516,y=0.642,source="quest_giver",zoneID=15969},questType="standard"},
[90819] = {id=90819,name="Murder Row: Acting the Part",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Based on what we discovered, I believe the fel is coming from Murder Row. Someone there is breaking down Legion relics and infusing the magic into mana wyrms for covert siphoning--and people are buying it up in droves. We need to figure out who that someone is. Take this wyrm core with you into the Row and look for more of them. The promise of coin should get you in front of the right person.",objectivesText="Take the Cracked Wyrm Core , then investigate Murder Row to discover the source of the smuggled fel wyrms. Progress: The denizens of Murder Row are tight-lipped, but any information we manage to uncover will be invaluable.",rewardGold=341600,rewardXP=11765,rewardItems={244407,244528,245566,253211,253212},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=244443}},ends={{npcID=244454}},coords={x=0.56,y=0.566,source="quest_giver",zoneID=15969},questType="standard"},
[90821] = {id=90821,name="Murder Row: Harbored Secrets",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="That manifest is stamped by the Silvermoon Harbor. It looks like Zaen has his smugglers working there to push his fel relic shipments through inspections. If we cut off their supply line at the harbor, we can halt the fel operation until we track down Zaen and end it for good. No sense going after the middlemen until then. Subterfuge got us this far, so let's keep at it. Head to the harbor and tell them you're picking up Zaen's shipment. We'll work from there.",objectivesText="Talk to the dockmaster at the Silvermoon Harbor to collect Zaen's fel relic shipment. Progress: Zaen is the mastermind here, or at least he seems to be. We'll need to deal with him to truly end this scheme. Taking out their fel supply line at the harbor will stop the situation from getting any worse while we find him.",rewardGold=341600,rewardXP=11765,rewardItems={244547},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=244454}},ends={{npcID=245297}},coords={x=0.546,y=0.546,source="quest_giver",zoneID=15969},questType="standard"},
[90822] = {id=90822,name="Murder Row: One Fel Swoop",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16091,mapID=2393,description="We have all the puzzle pieces. Zaen smuggles fel relics from the Broken Isles by stacking the Silvermoon Harbor with his own smugglers. The relics are processed in Murder Row, then fel magic is infused into mana wyrms for sale and siphoning. Such a convoluted operation might be impressive, if the goals weren't so reckless. Zaen is preying on people's fear. He doesn't care who he helps or hurts as long as he rakes in the gold. Let us end it. We'll find the Illicit Rain in Murder Row and clear it out.",objectivesText="Dismantle the fel smuggling operation inside Murder Row. Progress: Something seems to have happened in Murder Row since we left. A crowd is forming. Proceed with caution. I'm with you.",rewardGold=1366400,rewardXP=23530,rewardChoices={251132,251136,251142},rewardCurrencies={{id=3316,amount=50},{id=3365,amount=500}},starts={{npcID=245297}},ends={{npcID=244446}},coords={x=0.322,y=0.258,source="quest_giver",zoneID=15969},questType="dungeon"},
[90824] = {id=90824,name="My Brother's Alive!",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="En'liahn saved me from the Rift of Aln. He's my older brother. I know it was stupid to go there, but it wasn't my fault! We all thought En'liahn was dead, but I saw him earlier at the wetland. When he saw me, he ran away. Chua looks sad.> No one here believes me and now I can't go. Will you help me find him again?",objectivesText="Find En'liahn at the Ahl'ua Wetland.",rewardGold=33500,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3370,amount=10}},starts={{npcID=244163}},ends={{npcID=244242}},coords={x=0.522,y=0.55,source="quest_giver",zoneID=15355},questType="standard"},
[90826] = {id=90826,name="The Healing Waters of Ahl'ua",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="I'd hoped Chua hadn't seen me. Better he thinks I died. Instead, I'm self-exiling. I was trapped in the Rift of Aln while saving him. Being in there for so long corrupted my connection to the goddess--if I don't sever it soon, it'll drive me mad, or worse. The Shul'ka who saved me has agreed to mentor me through the process. He told me to come here and gather some things for a ritual to sever the connection. I must collect the nearby healing waters. Will you help me fill this jug?",objectivesText="Collect 6 Healing Waters of Ahl'ua . Progress: I appreciate your help, <name>.",rewardGold=341600,rewardXP=12170,rewardItems={243196,246118},rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=244242}},ends={{npcID=244242}},coords={x=0.43,y=0.614,source="quest_giver",zoneID=15355},questType="standard"},
[90827] = {id=90827,name="Only the Poisonous Parts",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="My Shul'ka mentor instructed me to collect the toxic glands from the creatures here. He said they were crucial to the Ritual of Severing in order to break my connection with the goddess. En'liahn shakes his head in pain.> I'm not looking forward to whatever this ritual is, but her disjointed song in my head is getting stronger and making it hard to focus.",objectivesText="Collect 8 Phytogenic Poison Parts . Progress: Be careful handling that poison. These creatures are some of the deadliest in all of Harandar .",rewardGold=341600,rewardXP=12170,rewardItems={243598},rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=244242}},ends={{npcID=244242}},coords={x=0.43,y=0.614,source="quest_giver",zoneID=15355},questType="standard"},
[90829] = {id=90829,name="Meeting My Mentor",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="I'm in your debt, . I didn't think I'd get any help. My mentor only provides guidance. He says that is the way of the Shul'ka. Thanks to you, I have everything I need for the ritual. Will you continue on with me? I'm heading for the cliffside overlooking the Rift of Aln to the northeast.",rewardGold=34100,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3370,amount=10}},starts={{npcID=244242}},ends={{npcID=244394}},coords={x=0.43,y=0.614,source="quest_giver",zoneID=15355},questType="standard"},
[90830] = {id=90830,name="The Path Will Reveal Itself",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="The next step is to locate the ritual site. It's different for each potential Shul'ka. Amarakk says that I must open myself to the power of the rift--that some part of myself tied to this place will guide the way. All I can tell you is it hurts. Are you still with me?",objectivesText="Travel with En'liahn to discover the ritual site within the Rift of Aln. Progress: I see you made it.",rewardGold=341600,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=244394}},ends={{npcID=244455}},coords={x=0.638,y=0.546,source="quest_giver",zoneID=15355},questType="standard"},
[90831] = {id=90831,name="Doing Is Becoming",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="If En'liahn is to succeed as a Shul'ka, he must learn to disrupt the manifestations in the rift. Sometimes that means closing small tears as they open. Most of the time, we simply slay the manifestations where we find them so they do not become so numerous as to threaten the rest of Harandar . It is a never-ending responsibility each of us bears. It is why we are Shul'ka. This, of course, assumes that he survives the ritual, or even survives to find the ritual site.",objectivesText="Disrupt the manifestations within the Rift of Aln. Progress: I see you, <name>.",rewardGold=341600,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=244419}},ends={{npcID=244455}},coords={x=0.638,y=0.546,source="quest_giver",zoneID=15355},questType="standard"},
[90832] = {id=90832,name="As Her Voice Goes Silent",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="En'liahn is about to drink the mixture of the poison and healing waters to begin the ritual. He will be unconscious and fighting for his life. The manifestations of the rift can sense this, and they are gathering. , you must place the wards and use their power to defend him while he severs his final connection to the goddess before her song drives him to madness.",objectivesText="Protect En'liahn while he endures the Ritual of Severing. Progress: Whatever happens next, you've proven you can be trusted.",rewardGold=170800,rewardXP=6085,rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=244455}},ends={{npcID=244455}},coords={x=0.628,y=0.622,source="quest_giver",zoneID=15355},questType="standard"},
[90833] = {id=90833,name="The Final Rite",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Foolish. En'liahn is still weak from the ritual and not prepared. He has run off to confront Morta'ka the Sundered Echo . This is the final rite of all who would become Shul'ka, but it is usually only attempted after years of preparation. En'liahn will not survive, and in dying will only make Morta'ka more powerful. Will you save him, ?",objectivesText="Help En'liahn to slay the manifestation known as Morta'ka the Sundered Echo inside the Shadow Cleft.",rewardGold=670000,rewardXP=15215,rewardCurrencies={{id=3316,amount=20},{id=3370,amount=100}},starts={{npcID=244455}},ends={{npcID=244473}},coords={x=0.628,y=0.622,source="quest_giver",zoneID=15355},questType="standard"},
[90834] = {id=90834,name="From This Point Forward",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="I don't know how to feel about losing my connection with Aln'hara. There's no more pain... I'm not going mad, but there's a hole inside. Does that make sense? Will you rejoin us back up on the cliff?",objectivesText="Return to En'liahn and Amarakk on the cliff overlooking the Rift of Aln.",rewardGold=335000,rewardXP=12170,rewardItems={263020},rewardCurrencies={{id=3316,amount=25},{id=3370,amount=250}},starts={{npcID=244473}},ends={{npcID=244394}},coords={x=0.616,y=0.602,source="quest_giver",zoneID=15355},questType="standard"},
[90835] = {id=90835,name="Murder Row: Rumors Abound",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="I would advise exploring the city with caution. Not all is what it seems in Silvermoon. The Illidari are performing an investigation which need not be spoken of openly. But you appear formidable... Perhaps you can aid us. My commander, Belath Dawnblade , is heading the investigation. The last I heard, he was surveying the upper terraces of the Bazaar. Seek him out, if you would make use of yourself.",objectivesText="Find Belath Dawnblade in the terraces above the Bazaar.",rewardGold=30900,rewardXP=1470,rewardCurrencies={{id=3316,amount=5},{id=3365,amount=10}},starts={{npcID=244493}},ends={{npcID=244440}},coords={x=0.56,y=0.636,source="quest_giver",zoneID=15969},questType="standard"},
[90837] = {id=90837,name="Murder Row: Traces of Fel",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="I have been sensing powerful fel magic throughout Silvermoon, but this is the first origin point I could locate. The rest were too faint, or perhaps deliberately hidden. Fortunately, this means we now have a specific area to comb through more closely. We need to gather more evidence. Go around this area and see if you can find more hidden sources of fel. I will grant you a temporary portion of my sight so that even the slightest hint of fel magic will be obvious to you.",objectivesText="Discover 5 sources of fel magic near the Royal Exchange. Progress: Were you able to locate anything?",rewardGold=341600,rewardXP=11765,rewardItems={243236,243237,243238,243239,243240},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=245418}},ends={{npcID=244443}},coords={x=0.516,y=0.642,source="quest_giver",zoneID=15969},questType="standard"},
[90838] = {id=90838,name="Oaths and Heirlooms",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="You, stranger... do you know of the Shadowguard that left K'aresh in ruins? My sister was lost in the conflict, her heart forcibly turned to the Void, but I swore oaths to my family... to cherish them no matter their transgressions. My sister, Veraan, is surely lost, but if I were to recover her necklace, at least then my oaths would be upheld in spirit. I am a simple tinkerer. I've tuned this device to track the Shadowguard, but I cannot face them alone. Would you help me?",objectivesText="Meet Kifaan outside of the Ethereum Overcroft.",rewardGold=32800,rewardXP=1605,rewardCurrencies={{id=3316,amount=5},{id=3389,amount=10}},starts={{npcID=244490}},ends={{npcID=244499}},coords={x=0.506,y=0.732,source="quest_giver",zoneID=15458},questType="standard"},
[90840] = {id=90840,name="What's Your Specialty?",level=7,requiredLevel=7,faction="horde",expansion=11,zoneID=13644,mapID=2022,description="The Dragon Isles is a dangerous and uncharted place. We'll need to get you prepared. You're strong enough now that you should choose a combat specialization. This will unlock a new array of abilities for you to face the dangers within the Dragon Isles. Go ahead and choose your combat specialization.",rewardXP=505,rewardItems={246462},starts={{npcID=244496}},ends={{npcID=244496}},coords={x=0.812,y=0.28,source="quest_giver",zoneID=13644},questType="standard"},
[90842] = {id=90842,name="Home Is Where the Hearth Is",level=7,requiredLevel=7,faction="horde",expansion=11,zoneID=13644,mapID=2022,description="Before you head off, you'll want to get yourself a Hearthstone . This little stone will return you to the inn where you last bound it to. It's not much of an \"inn\", but the explorers have a tent set up. Test out that new mount of yours and ride over to Sil'nori Crestshade. He'll get you sorted out with a Hearthstone .",rewardXP=505,starts={{npcID=244496}},ends={{npcID=244496}},coords={x=0.812,y=0.28,source="quest_giver",zoneID=13644},questType="standard"},
[90843] = {id=90843,name="Aiding the Dragon Isles",level=7,requiredLevel=7,faction="horde",expansion=11,zoneID=13644,mapID=2022,description="It's time for us to part ways. I have pressing business further within the Dragon Isles in a place called the Azure Span. Naleidea Rivergleam of the Dragonscale Expedition could use your help. Safe travels, . I look forward to our next meeting!",rewardXP=505,starts={{npcID=244496}},ends={{npcID=184841}},coords={x=0.812,y=0.28,source="quest_giver",zoneID=13644},questType="standard"},
[90844] = {id=90844,name="Fits of Lucidity",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="While I've been lurking, I've been listening. These Shadowguard appear to have a minor rebellion on their hands. Some of the ethereals are acting erratically. They're being rounded up and questioned. What's going on here? Dispatch some of these Shadowguard and intercept their intel. I'll decode anything you bring back to me.",objectivesText="Slay ethereals in the Ethereum Overcroft and collect 8 Interrogated Data . Progress: I thought the Void coursing through these ethereals was all-consuming. And yet, there seem to be some able to resist its infinite darkness.",rewardGold=341600,rewardXP=12845,rewardItems={244146},rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=244499}},ends={{npcID=244499}},coords={x=0.446,y=0.686,source="quest_giver",zoneID=15458},questType="standard"},
[90845] = {id=90845,name="Distant Memories",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="I swore an oath to honor my family... difficult when my sister was converted to the Shadowguard. She may not be here, but tracking the Shadowguard has led me to this place. I'm looking for a necklace that belonged to my sister Veraan. It's odd... I've noticed many K'areshi heirlooms discarded around here. It seems the Shadowguard wish to destroy any reminders of our home world. If you bring some of these trinkets and baubles to me, we can see if there are any I recognize.",objectivesText="Collect 8 K'areshi Keepsakes found at the Ethereum Overcroft. Progress: These keepsakes are some of the last remnants of our home world. The memories they contain are powerful. The Shadowguard is right to fear them.",rewardGold=341600,rewardXP=12845,rewardItems={244775},rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=244499}},ends={{npcID=244499}},coords={x=0.446,y=0.686,source="quest_giver",zoneID=15458},questType="standard"},
[90847] = {id=90847,name="Truth From Power",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="Thanks to your intel, we have learned that the rebels are being interrogated by Questioner Xen'daan . It is said that after being questioned, the rebel ethereals are being taken somewhere to be \"dealt with.\" The head questioner is sure to know more. If we can find where they've taken the rebels, there may still be hope for them.",objectivesText="Slay Questioner Xen'daan at the Ethereum Overcroft to discover the rebels' whereabouts. Progress: At the risk of getting my hopes up... do you think Veraan could be among them? Could I face her now? After the atrocities she's committed in the name of the Void?",rewardGold=683200,rewardXP=16055,rewardItems={245628},rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=244499}},ends={{npcID=244499}},coords={x=0.446,y=0.686,source="quest_giver",zoneID=15458},questType="standard"},
[90848] = {id=90848,name="She Started the Fire",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="Veraan is sure to be amongst the rebels taken to Shadowguard Point. Her fiery spirit fills me with great pride! I came here expecting to say a farewell of sorts. I did not come here expecting to find my sister. Perhaps it's not too late, !",objectivesText="Meet Kifaan at Shadowguard Point.",rewardGold=34100,rewardXP=1605,rewardCurrencies={{id=3316,amount=5},{id=3389,amount=10}},starts={{npcID=244499}},ends={{npcID=244516}},coords={x=0.446,y=0.686,source="quest_giver",zoneID=15458},questType="standard"},
[90849] = {id=90849,name="Light Show",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=16182,mapID=2432,rewardGold=309800,rewardXP=11765,questType="world",db2Objectives={{orderIndex=1,type=0,amount=6,objectID=244520,text="Luminescent Wards activated"}},worldTaskTitle="Light Show"},
[90851] = {id=90851,name="Eating Their Own",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="The Shadowguard seem to have no qualms caging and torturing their own kind. The last thing I want is more violence amongst the people of K'aresh, but better them than us. Disrupt their operation by subduing some of the Shadowguard.",objectivesText="Slay 12 Shadowguard Engineers and Infusers at Shadowguard Point.",rewardGold=341600,rewardXP=12845,rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=244516}},ends={{npcID=244516}},coords={x=0.376,y=0.484,source="quest_giver",zoneID=15458},questType="standard"},
[90852] = {id=90852,name="Techno-Magnetic Pulse",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="The betrayers are being held in stasis chambers. I've seen these cages before. Their design is efficient but fragile. They will fail with the slightest energy variation. Find crackling energy vessels strewn about and heave them at the stasis chambers. With true aim, you will disable them and free the betrayers.",objectivesText="Throw Crackling Energy Vessels at arcane prisons to free the Caged Betrayers .",rewardGold=341600,rewardXP=12845,rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=244516}},ends={{npcID=244516}},coords={x=0.376,y=0.484,source="quest_giver",zoneID=15458},questType="standard"},
[90858] = {id=90858,name="Repress the Oppressors",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="We were brought here to face the wrath of Soulbinder D'zaar. She commands the Shadowguard here. She leverages the power of the Voidstorm to convert souls to energy that she consumes. She and her loyalists are traitors to our kind! Veraan grimaces in pain as the Void courses through her.> They must be stopped... their devices dismantled... their will ended... ... destroy them all!",objectivesText="Disrupt the operation by slaying ethereals, destroying Fragile Energy Piping , and detonating Volatile Energy Reservoirs . Progress: < Veraan trembles with rage.> These kinslayers were willing to sacrifice their own. And in service of what? Xal'atath's will?",rewardGold=341600,rewardXP=12845,rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=244522}},ends={{npcID=244522}},coords={x=0.374,y=0.394,source="quest_giver",zoneID=15458},questType="standard"},
[90860] = {id=90860,name="Shedding the Yoke",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="Rebels like us are brought to Soulbinder D'zaar . She suffers no betrayers. Our fate was to be sacrificed--our souls converted to energy. D'zaar works the conduit with arcane mastery to absorb these souls! We don't have much time. I can feel the Void pressing from within. If we are to leave this life violently, D'zaar and her conduit are coming with us!",objectivesText="Slay Soulbinder D'zaar at Shadowguard Point. Progress: The pressure is building... it's almost time... And besides, do I even deserve to live? What will they say of me, a member of the Shadowguard, when all is said and done? Do you think Kifaan could ever forgive me?",rewardGold=683200,rewardXP=16055,rewardItems={264407,264408,264409,264410},rewardCurrencies={{id=3316,amount=25},{id=3389,amount=250}},starts={{npcID=244522}},ends={{npcID=244522}},coords={x=0.374,y=0.394,source="quest_giver",zoneID=15458},questType="standard"},
[90861] = {id=90861,name="Those Left Behind",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16215,mapID=2393,description="In the wake of Xal'atath's destruction, what remains of our forces are gathering at the Darkwell to determine what we can do about the remnants of the Void. We cannot abide the presence of so much dark energy. Some of our greatest casters and most knowledgeable scholars believe they might have a solution, but we could use your aid. Please, join Arator at the Darkwell at your earliest convenience.",objectivesText="Seek out Arator at the Darkwell.",rewardGold=34100,rewardXP=1370,rewardCurrencies={{id=3316,amount=5},{id=3365,amount=10}},starts={{npcID=235787}},ends={{npcID=244557}},coords={x=0.454,y=0.704,source="quest_giver",zoneID=15969},questType="standard"},
[90862] = {id=90862,name="In Times of Need",level=90,requiredLevel=90,faction="horde",expansion=11,zoneID=16215,mapID=2424,description="The last of the other elven leaders have returned with powers from their homeland that will help us in cleansing the Darkwell. While the Voidstorm no longer barrages the Darkwell, it still needs healing. Please meet with the other leaders and let them know we are ready for them.",objectivesText="Speak with each of the elven leaders.",rewardGold=341600,rewardXP=13690,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50},{id=3391,amount=10}},starts={{npcID=244557}},ends={{npcID=244576}},coords={x=0.526,y=0.584,source="quest_giver",zoneID=16215},questType="standard"},
[90866] = {id=90866,name="Universal Language",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15958,mapID=2405,description="To go home, water of life. Need. This. Of here. Is of fight. Of fight is Void. Void is power. With power, go home. Water of life. Of beast. Much. Yes?",objectivesText="Collect blood from the beasts north of the Night Trench. Progress: You. Not die? Good.",rewardGold=341600,rewardXP=12845,rewardItems={243350},rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=241620}},ends={{npcID=241620}},coords={x=0.398,y=0.49,source="quest_giver",zoneID=15458},questType="standard"},
[90867] = {id=90867,name="From Darkness, Light",level=90,requiredLevel=90,faction="horde",expansion=11,zoneID=16215,mapID=2424,description="We will not let the Sunwell be corrupted again. This Darkwell must change, but it must change to something that we are no longer bound to with such dependency. We do not need this well to be the bait for so many other world-corrupting forces. No, today we heal the Darkwell, and make it something new. Let me know when you are ready.",objectivesText="Conduct the ritual to cleanse the Darkwell.",rewardGold=1024800,rewardXP=20540,rewardItems={257143,265106,265631},rewardCurrencies={{id=3316,amount=100},{id=3365,amount=1000},{id=3391,amount=10}},starts={{npcID=244576}},ends={{npcID=245469}},coords={x=0.526,y=0.462,source="quest_giver",zoneID=16215},questType="standard"},
[90869] = {id=90869,name="It's All in the Image",level=1,requiredLevel=1,faction="horde",expansion=11,zoneID=4737,mapID=194,description="So, the higher-ups in the marketing department say you need a good partner to soften your aesthetic of... you know, \"murder everyone around me for gold.\" We've got two focus group approved goblins over there ready to go, so go take your pick. Sassy will handle the paperwork. Oh, don't give me that look. You only gotta forever-love each other in front of the public. Once the cameras are off, no one cares. It'll be great for your reputation!",objectivesText="Speak to Sassy Hardwrench to select a \"marketing partner.\" Progress: C'mon, this ain't rocket surgery. Pick whoever you wanna pose on some magazine covers with.",starts={{npcID=34874}},ends={{npcID=34874}},questType="standard"},
[90871] = {id=90871,name="The Silversun Compact",level=90,requiredLevel=90,faction="alliance",expansion=11,zoneID=15969,mapID=2393,description="Champion. After much discussion, negotiation, and even some screaming and three duels, the Sunreavers and the Silver Covenant have decided on a course of action to define both of our futures. Given your aid in getting us to this day, we would like you here to act as a witness as we formalize and sign our peace accords. Will you do us the honor of igniting the Flames of Remembrance?",objectivesText="Assist in the formalization of The Silversun Compact . Progress: Strange times. Strange times indeed.",rewardGold=341600,rewardXP=13690,rewardItems={267466,267467,267468},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50},{id=3391,amount=10}},starts={{npcID=244699}},ends={{npcID=247452}},coords={x=0.402,y=0.894,source="quest_giver",zoneID=15969},questType="standard"},
[90872] = {id=90872,name="Drenched In It",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15958,mapID=2405,description="Good. Blood is vio... violent? Violent is power. Need more. Now, brothers and sisters. You can. I say. Then, go out. See of me.",objectivesText="Mark 8 Offworld Refugees with Predator Blood to empower the portal in Exiles' Hovel. Progress: Done?",rewardGold=170800,rewardXP=6425,rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=241620}},ends={{npcID=241620}},coords={x=0.398,y=0.49,source="quest_giver",zoneID=15458},questType="standard"},
[90873] = {id=90873,name="These Violent Delights",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15958,mapID=2405,description="Brothers and sisters. Here. Help. How? Show. Use.",objectivesText="Use the Relic of Liberation to free 10 Master's Prospects and 3 Unwilling Summons. Progress: <Tul'amar holds still, even as you approach.>",rewardGold=341600,rewardXP=12845,rewardItems={244173},rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=241620}},ends={{npcID=241620}},coords={x=0.398,y=0.49,source="quest_giver",zoneID=15458},questType="standard"},
[90874] = {id=90874,name="Their Violent Ends",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15958,mapID=2405,description="Go home. How? Of me? No. Of they. Kill. And. As this. Need.",objectivesText="Collect 8 Abductor's Marks from the voidwalkers of Masters' Perch. Progress: <Tul'amar holds still, even as you approach.>",rewardGold=341600,rewardXP=12845,rewardItems={244171},rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=241620}},ends={{npcID=241620}},coords={x=0.398,y=0.49,source="quest_giver",zoneID=15458},questType="standard"},
[90875] = {id=90875,name="Across Worlds",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15958,mapID=2405,description="Man of Void. Have key. Need. Key to home. Go back, we. Wait. Hope. For you.",objectivesText="Kill Snaerius and recover his Lodestar of the Great Dark . Progress: <Tul'amar smiles sadly at her people.>",rewardGold=683200,rewardXP=16055,rewardItems={244435,264293,264294},rewardChoices={264293,264294},rewardCurrencies={{id=3316,amount=25},{id=3389,amount=250}},starts={{npcID=241620}},ends={{npcID=241620}},coords={x=0.398,y=0.49,source="quest_giver",zoneID=15458},questType="standard"},
[90876] = {id=90876,name="Reluctant Hand",level=90,requiredLevel=90,faction="horde",expansion=11,zoneID=15969,mapID=2393,description="Champion, I felt it was important to have you here for this moment so that neither I nor my wayward former peer get off topic with his many failings. I also want a witness in case he turns to evil. Would you be so kind as to unpack a few items so that I do not have to touch them?",objectivesText="Assist in preparing the Umbral Atrium. Progress: I am not so filled with pride that I cannot admit to some... mild nostalgia for the banter I once enjoyed with my former peer. Magister Umbric was once quite the source of counterpoints and suggestions that went beyond expectations, and helped push our knowledge of magic further and further.",rewardGold=341600,rewardXP=13690,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50},{id=3391,amount=10}},starts={{npcID=244701}},ends={{npcID=247262}},coords={x=0.534,y=0.602,source="quest_giver",zoneID=15969},questType="standard"},
[90889] = {id=90889,name="Tale of the Echoes of Sai'alyo",level=83,requiredLevel=83,faction="none",expansion=11,zoneID=15355,mapID=2413,objectivesText="Collect pigment ingredients Paintings created Animated Paint squished Paint splotches collected",rewardItems={243583,243584,243589},starts={{npcID=245531}},ends={{npcID=245531}},questType="standard",db2Objectives={{orderIndex=4,type=0,amount=1,objectID=244764,text="Paintings created"},{orderIndex=5,type=0,amount=10,objectID=245755,text="Animated Paint squished"},{orderIndex=6,type=0,amount=1,objectID=245842,text="Paint splotches collected"},{orderIndex=0,type=15,amount=1,objectID=0,text="Collect pigment ingredients"}},worldTaskTitle="Tale of the Echoes of Sai'alyo"},
[90907] = {id=90907,name="The First to Know",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="Notes speaking of fear, of uncertainty--of some mysterious truth? This is not good, $p. By all accounts, it sounds as if a cult has managed to infiltrate Tranquillien. If that journal entry was true, Kasiea was attempting to leave it. We must tell Antenorian. He'll want to secure the town and make sure his people are safe.",objectivesText="Inform Lord Antenorian , governor of Tranquillien, of your investigation results. Progress: I hope our fair town is treating you well. If you have any concerns at all, bring them to me.",rewardGold=341600,rewardXP=11765,rewardItems={244783},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=236087}},ends={{npcID=245004}},coords={x=0.476,y=0.698,source="quest_giver",zoneID=15968},questType="standard"},
[90910] = {id=90910,name="Overwhelming Darkness",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="A dreadful presence calls from the den just to the southeast of here. Many of the dazed ren'dorei you see in camp were overwhelmed by its raw power on a scouting mission. Let us go together and see if whatever dwells within can be put to use. We cannot afford to spurn power in the fight against Xal'atath. Before that: we have little need of Kalgorg . The Voidstorm has made my voidwalker unruly and disobedient. Assist me in sacrificing it. We will need all of the Void energy we can muster.",objectivesText="Sacrifice Kalgorg and then meet Lucia Nightbreaker in the Den of Predaxes. Progress: Disobedient little...",rewardGold=85400,rewardXP=3210,rewardItems={247713},rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=239720}},ends={{npcID=239720}},coords={x=0.424,y=0.754,source="quest_giver",zoneID=15458},questType="standard"},
[90914] = {id=90914,name="A Born Killer",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="Ah, . I have so enjoyed our time together. I hunger for more. I wish you knew more of me than my predilection for the taste of mortal suffering. One of my greatest joys is in crafting Void power into various objects and structures. It is my passion--my art. Here, I would like to show you. First, we will need power. You already know how to get it, of course: kill, kill, kill.",objectivesText="Collect 15 Void Essence from monsters around Voidstorm . Progress: What an odd feeling. I feel almost... drawn to you. It must be your mesmerizing presence.",rewardGold=341600,rewardXP=12845,rewardItems={248086},rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=235697},{npcID=243907}},ends={{npcID=243907}},coords={x=0.514,y=0.728,source="quest_giver",zoneID=15458},questType="standard"},
[90915] = {id=90915,name="Artifice of Aggression",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="While we domanaar are best known for leading armies and savoring battles, there is more to us. Many, like myself, enjoy using our mastery over the Void to shape it into the buildings and objects you see around you. How do you think Xal'atath learned to create that great tower of hers? She's a quick study. Come now, and I will show you my work.",objectivesText="Craft a blade with Decimus . Progress: How excellent to spend some time together. You mortals are so very interesting... you most of all.",rewardGold=341600,rewardXP=12845,rewardItems={248281},rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=243907}},ends={{npcID=243907}},coords={x=0.512,y=0.684,source="quest_giver",zoneID=15458},questType="standard"},
[90916] = {id=90916,name="Seek to Destroy",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="It's no easy thing, intertwining Light and Void together. The result is unstable, so we must continue to temper it. We shall quench this blade in the blood of our enemies. Some domanaar attempt to reclaim and re-power Nexus-Point Xenas. That won't be good for your people. I'll assume you want to stop it. What is it you mortals say? Two birds, one stone?",objectivesText="Meet Decimus at Nexus-Point Xenas.",rewardGold=34100,rewardXP=1605,rewardCurrencies={{id=3316,amount=5},{id=3389,amount=10}},starts={{npcID=243907}},ends={{npcID=244929}},coords={x=0.512,y=0.684,source="quest_giver",zoneID=15458},questType="standard"},
[90917] = {id=90917,name="Harvester of Savagery",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="The blade hungers! The blood of our enemies will help stabilize and hone our nascent weapon. You'll need to drench the blade inside some corpses. So, you'll need to make corpses. Decimus 's smile grows broader.> You're good at that, right?",objectivesText="Use the Nascent Blade on corpses in Nexus-Point Xenas. Progress: The monsters native to this land are fierce and violent. Their bloodlust drew the Void here, so naturally... we feel quite at home here.",rewardGold=341600,rewardXP=12845,rewardItems={248593},rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=244929}},ends={{npcID=244929}},coords={x=0.612,y=0.618,source="quest_giver",zoneID=15458},questType="standard"},
[90918] = {id=90918,name="The Unforgiven",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="Since even before our little misadventure, Nexus-Point Xenas has always been the weakest link. The beasts here are stubborn and powerful, always pushing deeper and deeper in. Some domanaar seek to reclaim the Nexus-Point. They are known to me: weaklings, fighting for scraps. Let's ensure they fail.",objectivesText="Slay Noxian , Averus , and Tenebre around Nexus-Point Xenas. Progress: Noxian , Averus , and Tenebre ... all lackeys of Xal'atath, just like the majority of my kin. I wonder how long each would wait before attempting their betrayal of her. Shame we'll never get to see their attempts.",rewardGold=683200,rewardXP=16055,rewardCurrencies={{id=3316,amount=20},{id=3389,amount=100}},starts={{npcID=244929}},ends={{npcID=244929}},coords={x=0.612,y=0.618,source="quest_giver",zoneID=15458},questType="standard"},
[90919] = {id=90919,name="The Fiend That Failed",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="The blade squirms. It is ready for its next transformation. There is only the leader, Vortensiun , left. He is known to me. Once, we formed a pact together to defeat a rival. When the time came for him to betray me, he did so clumsily. I let him live, so I could savor the taste of his regret. I wonder how well that pain has marinated by now? Let's find out. When the blade is tempered in his essence, it shall grow new power.",objectivesText="Slay Vortensiun in Nexus-Point Xenas.",rewardGold=683200,rewardXP=16055,rewardCurrencies={{id=3316,amount=20},{id=3389,amount=100}},starts={{npcID=244929}},ends={{npcID=244948}},coords={x=0.612,y=0.618,source="quest_giver",zoneID=15458},questType="standard"},
[90920] = {id=90920,name="Warmth for the Soul",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="Enjoying the view? The blade is stronger now, but it is not yet complete. A weapon worthy of you deserves nothing less than perfection. But let us relax for a moment. I understand you mortals enjoy a... casual exchange of conversation to get to know each other better. I am familiar with the concept, but am curious to see it in action. Indulge me?",objectivesText="Enjoy a pleasant conversation with Decimus .",rewardGold=170800,rewardXP=6425,rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=244948}},ends={{npcID=244948}},coords={x=0.59,y=0.566,source="quest_giver",zoneID=15458},questType="standard"},
[90922] = {id=90922,name="The Fallen Wake",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="You... left me... to die...",objectivesText="Dispel spirits in the Gnawing Reach. Progress: Such a strange and terrible place. Fear not--if you wish to converse more to settle your nerves... I am here for you.",rewardGold=341600,rewardXP=12845,rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=251891}},ends={{npcID=252853}},questType="standard"},
[90923] = {id=90923,name="Shepherd of Fear",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="Our journey continues... one final battlefield. There are vicious beasts aplenty here. Their Void shall fuel the blade even more. And the blade's newfound power shall draw their Void into itself by mere proximity! Though, this place is different. You may find things you don't expect. Keep an eye out.",objectivesText="Slay monsters and gather Void Essence in the Gnawing Reach. Progress: Don't get distracted, now. This will all be worth it when you have a mighty weapon to hold.",rewardGold=341600,rewardXP=12845,rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=244948}},ends={{npcID=252853}},coords={x=0.59,y=0.566,source="quest_giver",zoneID=15458},questType="standard"},
[90924] = {id=90924,name="The Wicked End",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="The time has come. The final step. Decimus pauses, savoring something.> Let us create the greatest weapon your kind has ever seen.",objectivesText="Complete the forging of the blade. Progress: Your patience has been... appreciated.",rewardGold=683200,rewardXP=16055,rewardItems={264425,264426,264427,264428,264429,264430,264431,264432,264433},rewardChoices={264425,264426,264427,264428,264429,264430,264431,264432,264433},rewardCurrencies={{id=3316,amount=25},{id=3389,amount=250}},starts={{npcID=252853}},ends={{npcID=243907}},coords={x=0.472,y=0.49,source="quest_giver",zoneID=15458},questType="standard"},
[90943] = {id=90943,name="Stormarion Assault",level=90,requiredLevel=90,faction="none",expansion=11,questType="standard"},
[90957] = {id=90957,name="Initiation Day",level=10,requiredLevel=10,faction="both",expansion=11,zoneID=15355,mapID=2413,description=", today is when you find your proper place among the haranir. Root Tender Dalnir will guide you. His path is one of tradition and humility, so don't expect excitement. By the end of the day, you will make your mark in the Den of Remembrance. The story you begin now will build on those that came before, like the roots themselves, growing the foundations of Harandar. Dalnir was clearing invasive drifters from the roots. Before you go to him, aid Dalnir by removing some of the pests yourself.",rewardGold=2000,rewardXP=1415,rewardItems={257527,257528,257529,257530},starts={{npcID=245090,x=0.348,y=0.25,zoneID=15355}},ends={{npcID=245102,x=0.352,y=0.234,zoneID=15355}},coords={x=0.348,y=0.25,source="quest_giver",zoneID=15355},questType="world",worldTaskTitle="Initiation Day"},
[90958] = {id=90958,name="Roots Above All",level=10,requiredLevel=10,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Some say the great trees grow, and Harandar will remain even if we do not tend them. Our traditions say, it does not matter. We remain here to protect, tend and serve. We do this with dedication and humility. Keeping the environment around the roots clean and free of pests reflects upon this duty. Return to me once you are done. You will represent our ways well, .",rewardGold=341600,rewardXP=1415,rewardItems={246112,246126,246129},starts={{npcID=245102,x=0.352,y=0.234,zoneID=15355}},ends={{npcID=245102,x=0.352,y=0.234,zoneID=15355}},coords={x=0.352,y=0.234,source="quest_giver",zoneID=15355},questType="world",worldTaskTitle="Roots Above All"},
[90959] = {id=90959,name="Traditional Duties",level=10,requiredLevel=10,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Dalnir has a point about the ceremony, but we should not focus too narrowly. I still hold the values of our people, but sometimes we must look beyond. Do not worry. You should be focusing on the ceremony. I will search for the outsiders later. I am sure you could join me once the initiation ceremony is done.",rewardGold=338300,rewardXP=1415,rewardItems={257558,257559,257560,257561},starts={{npcID=245879,x=0.352,y=0.234,zoneID=15355}},ends={{npcID=245881,x=0.34,y=0.268,zoneID=15355}},coords={x=0.352,y=0.234,source="quest_giver",zoneID=15355},questType="world",worldTaskTitle="Traditional Duties"},
[90960] = {id=90960,name="My Story, My Legacy",level=10,requiredLevel=10,faction="both",expansion=11,zoneID=15355,mapID=2413,description=", the final part of the ceremony is ahead of you, though you've put it at risk with your digressions. The first mural will show you a vision of your true self, the one that resonates from within you. The second mural will show you a vision of where you are needed. The third mural, tradition tells us, breaks the barrier between us and the Goddess herself. The ceremony will conclude with you painting your story in the Den.",rewardGold=341600,rewardXP=1415,starts={{npcID=245096,x=0.34,y=0.268,zoneID=15355}},ends={{npcID=245097,x=0.318,y=0.274,zoneID=15355}},coords={x=0.34,y=0.268,source="quest_giver",zoneID=15355},questType="world",worldTaskTitle="My Story, My Legacy"},
[90962] = {id=90962,name="Stormarion Assault",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=16648,mapID=2405,rewardXP=17110,rewardItems={260940,268485,269704,279526},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Complete the entire Stormarion Assault Event"},{orderIndex=1,type=0,amount=1,objectID=248313,text="Wave 1 Complete"},{orderIndex=5,type=0,amount=1,objectID=248335,text="Defense Position activated"},{orderIndex=2,type=0,amount=1,objectID=248315,text="Wave 2 Complete"},{orderIndex=3,type=0,amount=1,objectID=248331,text="Wave 3 Complete"}},worldTaskTitle="Stormarion Assault",db2QuestInfoID=136,db2QuestInfoName="Rare Elite World Quest"},
[90963] = {id=90963,name="Caves of the Cleft",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Good work freeing the captured rutaani. With the seeds you recovered, I can try to carry on Ru'gar's work. I did some scouting and gathering while you were keeping the fungarians distracted, and could use your help with another task. Meet me at the cave northeast of here.",objectivesText="Meet Ney'leia near the northeastern cave in Fungal Cleft.",rewardGold=31500,rewardXP=1520,rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=243053}},ends={{npcID=245166}},coords={x=0.49,y=0.298,source="quest_giver",zoneID=15355},questType="standard"},
[90965] = {id=90965,name="How to Train Your Protegee",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=15968,description="Champion! Perhaps you can help me? I've spent months learning bits of each path--the bow of the Farstriders, the Light of the Blood Knights, the arcane teachings of the magisters... but no matter how hard I train, I still can't feel which one is truly right for me. If I could watch you face them--see their true strength in a real fight--I think perhaps then I'd finally understand where I belong. Could you help me?",objectivesText="Spar with Trainers in Sunstrider Isle.",questType="standard"},
[90993] = {id=90993,name="Take the Darkwell!",level=90,requiredLevel=90,faction="none",expansion=11,description="We have our army but what lies behind these walls are the most powerful, most vile, and most empowered foes Xal'atath has in her arsenal. Gather your strongest allies, , and meet us within. It is time to end this and take back our well.",objectivesText="March on Quel'Danas.",rewardGold=34100,rewardXP=1370,questType="raid"},
[91001] = {id=91001,name="Clear de Way",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="With dey magic and dey line broken, de Twilight's Blade is losin' ground. We must take advantage of dey turned backs. I will lead de charge through de ravine to de Conquerer's Sanctum beyond. Mor'duun is there, keepin' his coward-body safe from our spears and axes. He won't be safe much longer.",objectivesText="Regroup with Zul'jarra , Zul'jan, and Lady Liadrin at the foot of Conquerer's Sanctum in Broken Throne. Progress: We must act--now!",rewardGold=33500,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3354,amount=10}},starts={{npcID=245270}},ends={{npcID=240034}},coords={x=0.256,y=0.776,source="quest_giver",zoneID=15947},questType="standard"},
[91040] = {id=91040,name="Vexatious Vilebranch",level=83,requiredLevel=83,faction="none",expansion=11,zoneID=15947,mapID=2437,rewardGold=1366400,rewardXP=24340,questType="world",db2Objectives={{orderIndex=0,type=21,amount=12,objectID=5157,text="Vilebranch forces slain"}},worldTaskTitle="Vexatious Vilebranch"},
[91062] = {id=91062,name="Broken Bridges",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="I make one last request of you before you return with Liadrin to Silvermoon, hash'ura. Find Zul'jan. None have seen him since returnin' to Amani'Zar. On de way back here, I confronted him about takin' our soldiers to Broken Throne against my orders. People died dat shouldn't have. I asked him what he don't understand about dat. He didn't argue. He was blank. His body was there, but his mind? Sometimes he seeks peace in de sound of ocean waves. You might find him on de Skybridge.",objectivesText="Seek out Zul'jan upon the Skybridge.",rewardGold=34100,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3354,amount=10}},starts={{npcID=249653}},ends={{npcID=241308}},coords={x=0.456,y=0.654,source="quest_giver",zoneID=15947},questType="standard"},
[91063] = {id=91063,name="The Blooming Lattice",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="You're that stranger I've been hearing about, aren't you? I'm Su'meera , apprentice painter to Ja'kul. You heard of him? No? Maybe his work hasn't made it to your lands. That makes sense, I guess. Anyhow, I heard you like helping people out. Well, a few important things went missing when Ja'kul was attacked and killed. I want them back. Will you meet me near Blooming Lattice?",objectivesText="Meet Su'meera near Blooming Lattice.",rewardGold=33500,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3370,amount=10}},starts={{npcID=245637}},ends={{npcID=245639}},coords={x=0.654,y=0.226,source="quest_giver",zoneID=15355},questType="standard"},
[91065] = {id=91065,name="Purloining Petals",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="A couple of days ago, a group of rutaani attacked and killed my mentor, Ja'kul. When they did, their stupid birds stole a few things from him. Those petals-for-brains will make off with anything shiny that isn't thorned down. Will you recover Ja'kul's things for me? I'm a painter, not a fighter. I wouldn't last very long in there on my own.",objectivesText="Recover stolen objects from Blooming Terrace. Progress: Those birds would steal your head if it wasn't attached to your shoulders. Especially if you were wearing a shiny hat or helm. Right off your shoulders! <She pauses for a moment as if picturing this, then turns slightly green and shudders.>",rewardGold=341600,rewardXP=12170,rewardItems={245569,245570,245883,245886},rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=245639}},ends={{npcID=245639}},coords={x=0.608,y=0.298,source="quest_giver",zoneID=15355},questType="standard"},
[91069] = {id=91069,name="Vengeance for Tolbani",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Me and Tolbani had loaded de skiff with medicine, steel, and food to bring upriver to de forward camp. It was meant to be a quiet run: no trouble, and no eyes on us. But in de shallows, de murlocs came swarmin' out of de reeds all foam and teeth. Dey hit us hard--too fast to fight back proper. We tipped and lost de cargo. I barely made it to shore. Tolbani didn't. I dragged his dart-riddled body here. De murlocs must pay for what dey have done.",objectivesText="Kill 12 murlocs in Atal'Abasi. Progress: Bleed de mindless beasts. Make dem suffer for killin' Tolbani.",rewardGold=341600,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=245669}},ends={{npcID=245669}},coords={x=0.53,y=0.628,source="quest_giver",zoneID=15947},questType="standard"},
[91070] = {id=91070,name="Reclaim the Goods",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="While I was limping back from de river, I spotted a few of de murlocs dragging our food bags through de mud. They weren't working together either--kept snapping at each other, trying to snatch de best pieces for themselves. I saw one of them stash a whole satchel behind a fallen tree. Another buried something under a pile of rocks. Greedy little monsters think they can steal from us and get away with it.",objectivesText="Find 6 stolen Food Provisions in Atal'Abasi. Progress: Yes, <class>?",rewardGold=341600,rewardXP=12170,rewardItems={245588},rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=245669}},ends={{npcID=245669}},coords={x=0.53,y=0.628,source="quest_giver",zoneID=15947},questType="standard"},
[91071] = {id=91071,name="The Menace of Atal'Abasi",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Our boat didn't ground on its own. We were fightin' de murlocs, and then suddenly we were in de air. Dats when I saw him--one dat wasn't like de rest. Bigger. Stronger. When he attacked, de other murlocs scattered. He picked up our boat like it weighed nothin' and hurled it on de rocks. I've never seen a murloc do somethin' like that. We're gonna keep losin' people and supplies if dat muscle-bound murloc is watchin' de river.",objectivesText="Find and slay Mrruk the Musclefin in Atal'Abasi. Progress: De river's dangerous. We must reclaim it.",rewardGold=683200,rewardXP=15215,rewardCurrencies={{id=3316,amount=20},{id=3354,amount=100}},starts={{npcID=245669}},ends={{npcID=245669}},coords={x=0.53,y=0.628,source="quest_giver",zoneID=15947},questType="standard"},
[91084] = {id=91084,name="Looming Shadows",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Though we've triumphed over Ruia and the Lightbloom for now, more remains to be done. The elders will want to convene regarding the Hara'ti 's new place in the world, now that we have stepped out from the shadows of our past. Our reticence and fear will not vanish overnight. But this is an important first step. We will be fine, . Let Orweyna and I deal with the elders. When the time comes, the Hara'ti shall be at your side. For now, though, I'd imagine you have more pressing matters to attend to.",objectivesText="Return to Regent Lord Lor'themar Theron in the Sanctum of Light in Silvermoon City.",rewardGold=34100,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3370,amount=10}},starts={{npcID=255819}},ends={{npcID=235787}},coords={x=0.366,y=0.686,source="quest_giver",zoneID=15969},questType="standard"},
[91085] = {id=91085,name="Petal Bristles",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Ja'kul was out hunting petalwings when the rutaani came upon him and killed him. We use their feathers for some of our paintbrushes. They are especially useful in helping the young sprouts learn how to be more precise and delicate. While you're up there, will you bring me back some of their plumes?",objectivesText="Collect 8 Petalwing Plumes . Progress: Have you gathered the petalwing plumes I asked for? They're essential for the lessons of the younger haranir.",rewardGold=341600,rewardXP=12170,rewardItems={245571},rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=245639}},ends={{npcID=245639}},coords={x=0.608,y=0.298,source="quest_giver",zoneID=15355},questType="standard"},
[91086] = {id=91086,name="Nipping the Buds",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="The rutaani of Blooming Lattice were behind the attack on Ja'kul. They're led by a Prime Bloomwarden who's even more vicious. I hate them and they're all terrible! How about you go prune the overgrowth and make the rest of us safer?",objectivesText="Kill rutaani and the Prime Bloomwarden in Blooming Lattice.",rewardGold=683200,rewardXP=15215,rewardCurrencies={{id=3316,amount=20},{id=3370,amount=100}},starts={{npcID=245639}},ends={{npcID=245639}},coords={x=0.608,y=0.298,source="quest_giver",zoneID=15355},questType="standard"},
[91087] = {id=91087,name="Reports Returned",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15969,mapID=2437,description="I will go to Silvermoon but... I will return here to advise Zul'jarra. I feel I let my past and my prejudices get in the way of my judgement regarding the Amani. You could say that being a hash'ura is a befitting atonement but... I feel drawn to stay, perhaps to help Zul'jarra in guiding her people back to the loa. I will go to Silvermoon with you to bear the report--and Lor'themar's reaction. If we go now, we may return to... party.",objectivesText="Report to Lor'themar Theron in Silvermoon City.",rewardGold=33500,rewardXP=1520,rewardItems={256928},rewardCurrencies={{id=3316,amount=5},{id=3354,amount=10}},starts={{npcID=241308}},ends={{npcID=235787}},coords={x=0.508,y=0.544,source="quest_giver",zoneID=15947},questType="standard"},
[91088] = {id=91088,name="Behind the Falls",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="The scroll you brought back was left behind for me by my mentor, Ja'kul. I didn't even have a chance to read it before it was stolen away! Ja'kul left directions in the scroll to a cave that's behind a waterfall in Blooming Lattice. I'm not sure what we'll find there, but I would really appreciate if you came along while I check it out. Will you meet me there?",objectivesText="Meet Su'meera in the cave behind the waterfall in Blooming Lattice.",rewardGold=31500,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3370,amount=10}},starts={{npcID=245639}},ends={{npcID=245986}},coords={x=0.608,y=0.298,source="quest_giver",zoneID=15355},questType="standard"},
[91090] = {id=91090,name="Pesky Pests",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="Nearby creatures are suffering an infection of Light, and are being drawn to the Sunbath. Our guests find it disturbing. That is a problem, when one is trying to enjoy a tranquil escape from the world. I confess, having one run into your leg while you are swimming can be unnerving. Please, dissuade the invading sungrubs from joining us, and take to the sky to chase off those persistent butterflies.",objectivesText="Kill 10 Sungrubs and fly to chase away 10 Persistent Butterflies . Progress: Are the insects giving you trouble?",rewardGold=341600,rewardXP=11765,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=245748}},ends={{npcID=245748}},coords={x=0.488,y=0.766,source="quest_giver",zoneID=15968},questType="standard"},
[91095] = {id=91095,name="Prey: Magister Sunbreaker (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,mapID=2437,description="Once a noble Magister of Silvermoon, sworn to protect Quel'Thalas at any cost, he has broken away from the order and now seeks vengeance on his own terms. I see something of myself in him. Kill it for me.",objectivesText="Hunt down Magister Sunbreaker and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=17650,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91096] = {id=91096,name="Prey: Magistrix Emberlash (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,mapID=2437,description="Alas, you can only catch so many innocent bystanders in your fireballs before you find yourself ostracized from polite society. Emberlash was always more interested in flame than friends... She has burned one too many mutual acquaintances. If she will not control her power, we will gladly take it for our own.",objectivesText="Hunt down Magistrix Emberlash and slay her. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=17650,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91097] = {id=91097,name="Prey: Senior Tinker Ozwold (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,mapID=2437,description="Rumor has it that Ozwold single-handedly raised insurance premiums in Gnomeregan before their little exodus. Be that as it may, he's consistently taken to perfecting his gadgetry regardless of the cost to others. His ambition is admirable, but his methods are irredeemable. Go and see that his inventing days come to an end.",objectivesText="Hunt down Senior Tinker Ozwold and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=17650,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91098] = {id=91098,name="Prey: L-N-0R the Recycler (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,mapID=2437,description="Do you know why they call her the Recycler, $p? I don't. And given her history of \"disappearing\" shop assistants, I'm not really inclined to ask her. That being said, watch your step. I understand that she likes to incorporate her victims into her gadgetry. We wouldn't want you becoming a pocket watch or some such thing.",objectivesText="Hunt down L-N-0R the Recycler and slay her. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=17650,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91099] = {id=91099,name="Prey: Mordril Shadowfell (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,mapID=2437,description="The Void is a perfidious thing, like water. The wise keep it at a respectful distance, never dancing too close to the edge. The foolish dive in, and in so doing, drown. Mordril is a danger to himself and everyone around him, so lost is he in his own obsession. See to it that he no longer poses a threat to this realm.",objectivesText="Hunt down Mordril Shadowfell and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=17650,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91100] = {id=91100,name="Prey: Deliah Gloomsong (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,mapID=2437,description="In a previous life, Deliah Gloomsong was a prodigious student--truly a marvel of ambition, talent, and unrelenting curiosity. It was the latter that got the best of her. Put an end to her murderous spree.",objectivesText="Hunt down Deliah Gloomsong and slay her. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=17650,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91101] = {id=91101,name="Prey: Phaseblade Talasha (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,mapID=2437,description="Ethereals... they make my skin crawl. Esoteric. Unknowable. I don't trust anything I can't look in the eyes while it grovels before me. My scouts report that a particularly dangerous ethereal is active in a nearby region. We would do well to nip this in the bud while we still can.",objectivesText="Hunt down Phaseblade Talasha and slay her. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=17650,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91102] = {id=91102,name="Prey: Nexus-Edge Hadim (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,mapID=2437,description="Our activities are drawing unwanted attention. I have heard whispers that a powerful ethereal assassin is on my... on our trail. It would be very difficult indeed to defend our city as twin piles of bloody ribbons. Go out there and show this \"assassin\" the true art of the kill.",objectivesText="Hunt down Nexus-Edge Hadim and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=17650,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91103] = {id=91103,name="Prey: Jo'zolo the Breaker (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,mapID=2437,description="Jo'zolo the Breaker is a troll who abides by his name. Long has he been the bane of our scouts, but no more! Kill him. Feed his anguish to the defenses of our beloved city.",objectivesText="Hunt down Jo'zolo the Breaker and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=17650,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91104] = {id=91104,name="Prey: Zadu, Fist of Nalorakk (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,mapID=2437,description="Our neighbors produce some of the most skilled hunters in all of Azeroth. It is a shame they are so difficult to reason with. There is one named Zadu. Her anguish would make for a most excellent trophy...",objectivesText="Hunt down Zadu, Fist of Nalorakk, and slay her. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=17650,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91105] = {id=91105,name="Prey: The Talon of Jan'alai (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,mapID=2437,description="There is a powerful troll shaman who calls himself the Talon of Jan'alai. Long has he confounded our city's Farstriders, sowing confusion and death in his wake. See to it that he joins the spirits he so ardently venerates.",objectivesText="Hunt down The Talon of Jan'alai and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=17650,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91106] = {id=91106,name="Prey: The Wing of Akil'zon (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,mapID=2437,description="Do you smell that? There is death on the air. This can only mean one thing. The Wing of Akil'zon is near. Go out and slay her. Oh, and be careful. She's responsible for more than one lost Farstrider patrol.",objectivesText="Hunt down The Wing of Akil'zon and slay her. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=17650,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91107] = {id=91107,name="Prey: Ranger Swiftglade (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,mapID=2437,description="It is a difficult thing, to hunt one of our own. Ranger Swiftglade is beyond redemption. His bloodlust could not be sated against our foes, and he has since turned his martial prowess upon his own people. End his sadistic killing spree and put his anguish to better use.",objectivesText="Hunt down Ranger Swiftglade and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=17650,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91108] = {id=91108,name="Prey: Lieutenant Blazewing (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,mapID=2437,description="I do not know what to make of Lieutenant Blazewing. Her entire patrol disappeared during a reconnaissance mission into Zul'Aman. She was the sole survivor, but she returned with a fiery bloodlust and a complete disregard for the lives of others. Whether this is possession or sedition I am unsure, but she must be dealt with.",objectivesText="Hunt down Lieutenant Blazewing and slay her. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=17650,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91109] = {id=91109,name="Prey: Petyoll the Razorleaf (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,mapID=2437,description="Reports are coming in of shredded Farstriders adorned with petals and berries--entire patrols found strung up by razor-vines. There are more gruesome details, but they chafe even my... refined sensibilities. Hunt whatever manner of creature is embarking on this horrific killing spree, and see to it that its anguish is added to our crystals.",objectivesText="Hunt down Petyoll the Razorleaf and slay them. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=17650,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91110] = {id=91110,name="Prey: Lamyne of the Undercroft (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,mapID=2437,description="Do you garden, $p? I've been known to dabble. It seems the plants in our realm are becoming somewhat overbearing these days, sprouting legs and arms and running around murdering our brave soldiers. Let's give them a bit of a pruning, shall we?",objectivesText="Hunt down Lamyne of the Undercroft and slay them. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=17650,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91111] = {id=91111,name="Prey: High Vindicator Vureem (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,mapID=2437,description="High Vindicator Vureem is a victim of his own unyielding faith in the Light and the superiority it gives him. His crusade continues unabated and unresolved. He exists in a constant state of fury at the imperfectness of the world and those within it. In the absence of total purity, Vureem sees only violence and the shadows of his own dogma. What say we put his worldview to the test?",objectivesText="Hunt down High Vindicator Vureem and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=17650,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91112] = {id=91112,name="Prey: Crusader Luxia Maxwell (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,mapID=2437,description="We are not sure if Luxia Maxwell is a deserter or has simply decided to embark on her own personal crusade. Regardless, reports are coming in of her attacking both friend and foe alike, yelling aphorisms of purity and duty. She has become a liability to the defense of Silvermoon. Go and harvest her anguish.",objectivesText="Hunt down Crusader Luxia Maxwell and slay her. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=17650,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91113] = {id=91113,name="Prey: Praetor Singularis (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,mapID=2437,description="The domanaar... I do not profess to know much about them, other than their proclivity for subterfuge, guile, and the absolute destruction of anything that stands before them. Praetor Singularis is no exception. They have been confounding our forces at every turn. Go and put an end to their games.",objectivesText="Hunt down Praetor Singularis and slay them. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=17650,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91114] = {id=91114,name="Prey: Consul Nebulor (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,mapID=2437,description="I have heard that there is one under Xal'atath's command who takes particular delight in dominating their foes. Whispers of a domanaar that taunts its victims with whispers and riddles before annihilating their mortal coil with void magic. Consul Nebulor is their name. Go and show them the limits of their power.",objectivesText="Hunt down Consul Nebulor and slay them. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=17650,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91115] = {id=91115,name="Prey: Executor Kaenius (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,mapID=2437,description="The domanaar have a reputation for guile and cunning, but there are brutes among them: those who seek to dominate their victims through sheer power and force of will. Executor Kaenius is one such domanaar. They stalk the battlefield, singling out our strongest soldiers and viciously cutting them down. Put an end to their rampage.",objectivesText="Hunt down Executor Kaenius and slay them. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=17650,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91116] = {id=91116,name="Prey: Imperator Enigmalia (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,mapID=2437,description="Imperator Enigmalia is personally responsible for the deaths of at least a dozen Farstriders. I say \"at least\" because this particular domanaar makes it somewhat difficult to identify the bodies, so utterly destroyed are they. Go and avenge our fallen soldiers.",objectivesText="Hunt down Imperator Enigmalia and slay them. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=17650,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91117] = {id=91117,name="Prey: Knight-Errant Bloodshatter (Normal)",level=80,requiredLevel=80,faction="horde",expansion=11,zoneID=15969,mapID=2393,description="Death knights are unstable killing machines at the best of times. Knight-Errant Bloodshatter has forsaken any oath or promise that would ostensibly bind one of his kind to the bottom rungs of civilized society, and has gone completely rogue. He is starting to become a liability. Recoup his anguish so that we can make the best of such an unfortunate situation.",objectivesText="Hunt down Knight-Errant Bloodshatter and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=17650,starts={{npcID=245824}},ends={{npcID=246231}},questType="standard"},
[91118] = {id=91118,name="Prey: Vylenna the Defector (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,mapID=2437,description="Vylenna the Defector lives up to her name. After a recent engagement on the field of battle, she became so preoccupied with profaning the dead that she completely abandoned the duties ascribed to her. Then her dereliction turned violent. A veritable font of anguish if you ask me...",objectivesText="Hunt down Vylenna the Defector and slay her. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=17650,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91119] = {id=91119,name="Prey: Lost Theldrin (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,mapID=2437,description="Those of us who succumbed to our base desire for mana were slowly weeded out of civil society, if they survived at all. Theldrin is one such example, only it is a testament to his cunning and will to live that he has made it as long as he has. He accepts no aid, choosing instead to stalk careless students and idle Magisters. His sole obsession is the mana that others possess... See to it that he never harms another elf again.",objectivesText="Hunt down Lost Theldrin and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=17650,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91120] = {id=91120,name="Prey: Neydra the Starving (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,mapID=2437,description="Poor Neydra... I knew her, in a previous life. She was full of vitality. Full of ambition. Unfortunately, she let that ambition get the best of her. She grew too enamored with the raw power of the arcane. She became resentful of all other things. Of all other people... And now she is a murderous creature who beheads rats and attacks innocents in a desperate attempt to garner enough arcane energy to slake her unquenchable thirst. It's funny, the paths life takes us...",objectivesText="Hunt down Neydra the Starving and slay her. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=17650,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91121] = {id=91121,name="Prey: Thornspeaker Edgath (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,mapID=2437,description="This one presents a prickly problem indeed. Thornspeaker Edgath has made a name for himself by using his druidic powers not to preserve Azeroth, but to twist its strength both against his enemies and innocent bystanders alike. He has no regard for anything that is not a beast or growing in the ground. It is time we clip this thorn.",objectivesText="Hunt down Thornspeaker Edgath and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=17650,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91122] = {id=91122,name="Prey: Thorn-Witch Liset (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,mapID=2437,description="Thorn-Witch Liset is a curse upon civilization and a blight upon the land itself. She twists the very trees and beasts, communing with the dark, evil things that live on the very edges of the natural realm. I despise the natural realm.",objectivesText="Hunt down Thorn-Witch Liset and slay her. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=17650,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91123] = {id=91123,name="Prey: Grothoz, the Burning Shadow (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,mapID=2437,description="The Twilight's Blade are an embarrassing band of mediocre cultists and uninspired conspirators. Grothoz is the brains of a particularly stupid cabal that has been active in a nearby region. As his stupidity prevents him from using his whole brain, let us unlock his potential for him...",objectivesText="Hunt down Grothoz, the Burning Shadow and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=17650,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91124] = {id=91124,name="Prey: Dengzag, the Darkened Blaze (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,mapID=2437,description="Do you know why the Twilight's Blade call Dengzag the \"Darkened Blaze?\" It is because they are stupid, small-minded, and utterly bereft of imagination. What a silly name indeed. I, however, am not small-minded. I have quite the prodigious mind, and it is currently intent on putting an end to Dengzag and whatever his tiny brain is up to. Get to it.",objectivesText="Hunt down Dengzag, the Darkened Blaze and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=17650,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91136] = {id=91136,name="Memories in Stone",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Ja'kul was killed before he could finish my training, but I would recognize his work anywhere! He must have painted this vision stone for me! The rutaani will catch on pretty soon that we're up here, and I won't be able to defend myself. Will you keep watch while I journey into the memory he left me?",objectivesText="Defend Su'meera while she vision walks.",rewardGold=631800,rewardXP=15215,rewardItems={260434,260435,260436,260437},rewardChoices={260434,260435,260436,260437},rewardCurrencies={{id=3316,amount=25},{id=3370,amount=250}},starts={{npcID=245986}},ends={{npcID=245728}},coords={x=0.56,y=0.248,source="quest_giver",zoneID=15355},questType="standard"},
[91137] = {id=91137,name="Lost in Light",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="It seems some of our more adventurous guests have not returned from their hike. Val said he saw a rutaani skulking about earlier, but I was certain he was just trying to add some drama to our day. The Lightbloom infiltrated the Sanctum to the north and has been spilling residual issues our way. Our guests are here to escape the troubles of the world... This all could become a bit too real for them. If you'll take care of that situation, I'll make sure Val keeps the guests distracted.",objectivesText="Kill Liya Waterbloom and send the hikers home. Progress: Did they make it back?",rewardGold=638000,rewardXP=14705,rewardItems={263198},rewardCurrencies={{id=3316,amount=25},{id=3365,amount=250}},starts={{npcID=245748}},ends={{npcID=245748}},coords={x=0.488,y=0.766,source="quest_giver",zoneID=15968},questType="standard"},
[91145] = {id=91145,name="The Conquered Heroes",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15958,mapID=2405,description="A domanaar was harrying our back lines. It was... different than the other void beasts--like it was playing rather than fighting. My partner, Callum, led a squad to hunt it down. They never came back. Callum's an Arathi through and through. He wouldn't fall here--I know it. Commander Lightblood refused to send a search party. He said there's a difference between personal and important. Well, the Vanguard can have their war, but I'm going after Cal. I know the route he took, but I can't search alone.",objectivesText="Find Callum Ashvow 's squad.",rewardGold=170800,rewardXP=6425,rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=245878}},ends={{npcID=246035}},coords={x=0.518,y=0.718,source="quest_giver",zoneID=15458},questType="standard"},
[91146] = {id=91146,name="Flickering Light",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15958,mapID=2444,description="I feel traces of Light here--dim, scattered across the plain, but unmistakable. It's Callum. I know his Light like I know my own. That domanaar is a monster: using others like toys, smashing them together until they break. We'll find them, $p, and then I will turn that void beast to ash. One thing at a time. Find the Light, and we find Callum.",objectivesText="Find traces of Callum's Light.",rewardGold=341600,rewardXP=12845,rewardItems={255158,255159,255160},rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=246035},{npcID=252807}},ends={{npcID=252807}},coords={x=0.538,y=0.84,source="quest_giver",zoneID=15958},questType="standard"},
[91147] = {id=91147,name="Cut Her Strings",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15958,mapID=2444,description="Revik, Riandron, Danna... that domanaar made them kill each other. The creatures here are bound with the same shadowgrafts: the same twisted magic. If this is how Imperia controls her victims, we have to find a way to remove it. Restrain the beasts and I'll attempt to break their bonds. If it's forged by the Void, the Light must be able to overcome it.",objectivesText="Subdue creatures while Anais removes their Shadowgrafts.",rewardGold=341600,rewardXP=12845,rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=246035},{npcID=252807}},ends={{npcID=252807}},coords={x=0.538,y=0.84,source="quest_giver",zoneID=15958},questType="standard"},
[91148] = {id=91148,name="Strung Along",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15958,mapID=2444,description="When the Light called, it called both of us. Why? So Callum could die on some void-scarred rock? I can't think here. All I can picture is Callum bleeding out. Come, we'll return to camp. With his belongings, I should be able to find him. Then... I don't know. If we can't break the shadowgrafts, we'll subdue him and drag him back to Silvermoon if we must. I'm not losing him.",objectivesText="Help Knight Anais find and subdue Callum Ashvow .",rewardGold=34100,rewardXP=1605,rewardCurrencies={{id=3316,amount=5},{id=3389,amount=10}},starts={{npcID=252807}},ends={{npcID=253523}},coords={x=0.533,y=0.838,source="quest_giver",zoneID=15958},questType="standard"},
[91149] = {id=91149,name="Bury Me Not",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15958,mapID=2444,description="I knew we'd never grow old together, but I thought we'd have more time. Don't worry. I'm not afraid. I promised myself I wouldn't go home without him... wouldn't spend a night in an empty bed. I'm just keeping that promise. Don't let her have him. Take his tinder box. You'll know what to do.",objectivesText="Take Callum's Tinder Box and defeat Imperia. Progress: My parents always said falling in love with a human would end in heartbreak. <She doesn't lift her head.> There's never enough time, is there?",rewardGold=683200,rewardXP=16055,rewardItems={256135,264289,264290,264291,264292},rewardCurrencies={{id=3316,amount=25},{id=3389,amount=250}},starts={{npcID=253523}},ends={{npcID=253577}},coords={x=0.44,y=0.87,source="quest_giver",zoneID=15958},questType="standard"},
[91197] = {id=91197,name="Collecting Remains",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15958,mapID=2444,objectivesText="Collect 50 Void-Tainted Remains . Progress: The domanaar need void-tainted remains to fuel their war effort. Scavenge the area or slay fellow adventurers across Slayer's Rise to obtain this resource.",rewardItems={245937},rewardCurrencies={{id=1792,amount=50},{id=2123,amount=50},{id=3410,amount=100}},starts={{npcID=245976}},ends={{npcID=245976}},coords={x=0.388,y=0.814,source="quest_giver",zoneID=15958},questType="standard"},
[91206] = {id=91206,name="Loa Disturbance",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Now dat we are tryin' to contact all de loa, my mind turns to Kulzi, de loa of medicine--and the madness that surrounds his shrine. His loa speaker, Sij'ta, was a good friend. He healed many war parties of their injuries. But somethin' happened at Kulzi's shrine, and it is full of angry spirits. Dey attack anybody dat tries to get through to dem, and de loa is silent. Perhaps you can finally reach out to de loa and find his speaker!",objectivesText="Find Loa Speaker Sij'ta at the Shrine of Kulzi.",rewardGold=30900,rewardXP=1470,rewardCurrencies={{id=3316,amount=5},{id=3354,amount=10}},starts={{npcID=254665}},ends={{npcID=237953}},coords={x=0.432,y=0.68,source="quest_giver",zoneID=15947},questType="standard"},
[91207] = {id=91207,name="Prey: Apex Predator",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=16534,mapID=2405,rewardGold=341600,rewardXP=11765,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Defeat enemies to lure out your Prey target"},{orderIndex=1,type=21,amount=13,objectID=5377,text="Creatures slain"},{orderIndex=2,type=0,amount=10,objectID=246605,text="Ambush defeated"}},worldTaskTitle="Prey: Apex Predator",db2QuestInfoID=295,db2QuestInfoName="Prey World Quest"},
[91210] = {id=91210,name="Prey: Magister Sunbreaker (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2437,description="Once a noble Magister of Silvermoon, sworn to protect Quel'Thalas at any cost, he has broken away from the order and now seeks vengeance on his own terms. I see something of myself in him. Kill it for me.",objectivesText="Hunt down Magister Sunbreaker and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91211] = {id=91211,name="Prey: Magister Sunbreaker (Nightmare)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2444,description="Once a noble Magister of Silvermoon, sworn to protect Quel'Thalas at any cost, he has broken away from the order and now seeks vengeance on his own terms. I see something of myself in him. Kill it for me.",objectivesText="Hunt down Magister Sunbreaker and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91212] = {id=91212,name="Prey: Magistrix Emberlash (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2437,description="Alas, you can only catch so many innocent bystanders in your fireballs before you find yourself ostracized from polite society. Emberlash was always more interested in flame than friends... She has burned one too many mutual acquaintances. If she will not control her power, we will gladly take it for our own.",objectivesText="Hunt down Magistrix Emberlash and slay her. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91213] = {id=91213,name="Prey: Magistrix Emberlash (Nightmare)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2444,description="Alas, you can only catch so many innocent bystanders in your fireballs before you find yourself ostracized from polite society. Emberlash was always more interested in flame than friends... She has burned one too many mutual acquaintances. If she will not control her power, we will gladly take it for our own.",objectivesText="Hunt down Magistrix Emberlash and slay her. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91214] = {id=91214,name="Prey: Senior Tinker Ozwold (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2437,description="Rumor has it that Ozwold single-handedly raised insurance premiums in Gnomeregan before their little exodus. Be that as it may, he's consistently taken to perfecting his gadgetry regardless of the cost to others. His ambition is admirable, but his methods are irredeemable. Go and see that his inventing days come to an end.",objectivesText="Hunt down Senior Tinker Ozwold and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91215] = {id=91215,name="Prey: Senior Tinker Ozwold (Nightmare)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2444,description="Rumor has it that Ozwold single-handedly raised insurance premiums in Gnomeregan before their little exodus. Be that as it may, he's consistently taken to perfecting his gadgetry regardless of the cost to others. His ambition is admirable, but his methods are irredeemable. Go and see that his inventing days come to an end.",objectivesText="Hunt down Senior Tinker Ozwold and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91216] = {id=91216,name="Prey: L-N-0R the Recycler (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2437,description="Do you know why they call her the Recycler, $p? I don't. And given her history of \"disappearing\" shop assistants, I'm not really inclined to ask her. That being said, watch your step. I understand that she likes to incorporate her victims into her gadgetry. We wouldn't want you becoming a pocket watch or some such thing.",objectivesText="Hunt down L-N-0R the Recycler and slay her. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91217] = {id=91217,name="Prey: L-N-0R the Recycler (Nightmare)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2444,description="Do you know why they call her the Recycler, $p? I don't. And given her history of \"disappearing\" shop assistants, I'm not really inclined to ask her. That being said, watch your step. I understand that she likes to incorporate her victims into her gadgetry. We wouldn't want you becoming a pocket watch or some such thing.",objectivesText="Hunt down L-N-0R the Recycler and slay her. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91218] = {id=91218,name="Prey: Mordril Shadowfell (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2437,description="The Void is a perfidious thing, like water. The wise keep it at a respectful distance, never dancing too close to the edge. The foolish dive in, and in so doing, drown. Mordril is a danger to himself and everyone around him, so lost is he in his own obsession. See to it that he no longer poses a threat to this realm.",objectivesText="Hunt down Mordril Shadowfell and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91219] = {id=91219,name="Prey: Mordril Shadowfell (Nightmare)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2444,description="The Void is a perfidious thing, like water. The wise keep it at a respectful distance, never dancing too close to the edge. The foolish dive in, and in so doing, drown. Mordril is a danger to himself and everyone around him, so lost is he in his own obsession. See to it that he no longer poses a threat to this realm.",objectivesText="Hunt down Mordril Shadowfell and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91220] = {id=91220,name="Prey: Deliah Gloomsong (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2437,description="In a previous life, Deliah Gloomsong was a prodigious student--truly a marvel of ambition, talent, and unrelenting curiosity. It was the latter that got the best of her. Put an end to her murderous spree.",objectivesText="Hunt down Deliah Gloomsong and slay her. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91221] = {id=91221,name="Prey: Deliah Gloomsong (Nightmare)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2444,description="In a previous life, Deliah Gloomsong was a prodigious student--truly a marvel of ambition, talent, and unrelenting curiosity. It was the latter that got the best of her. Put an end to her murderous spree.",objectivesText="Hunt down Deliah Gloomsong and slay her. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91222] = {id=91222,name="Prey: Phaseblade Talasha (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2437,description="Ethereals... they make my skin crawl. Esoteric. Unknowable. I don't trust anything I can't look in the eyes while it grovels before me. My scouts report that a particularly dangerous ethereal is active in a nearby region. We would do well to nip this in the bud while we still can.",objectivesText="Hunt down Phaseblade Talasha and slay her. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91223] = {id=91223,name="Prey: Phaseblade Talasha (Nightmare)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2444,description="Ethereals... they make my skin crawl. Esoteric. Unknowable. I don't trust anything I can't look in the eyes while it grovels before me. My scouts report that a particularly dangerous ethereal is active in a nearby region. We would do well to nip this in the bud while we still can.",objectivesText="Hunt down Phaseblade Talasha and slay her. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91224] = {id=91224,name="Prey: Nexus-Edge Hadim (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2437,description="Our activities are drawing unwanted attention. I have heard whispers that a powerful ethereal assassin is on my... on our trail. It would be very difficult indeed to defend our city as twin piles of bloody ribbons. Go out there and show this \"assassin\" the true art of the kill.",objectivesText="Hunt down Nexus-Edge Hadim and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91225] = {id=91225,name="Prey: Nexus-Edge Hadim (Nightmare)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2444,description="Our activities are drawing unwanted attention. I have heard whispers that a powerful ethereal assassin is on my... on our trail. It would be very difficult indeed to defend our city as twin piles of bloody ribbons. Go out there and show this \"assassin\" the true art of the kill.",objectivesText="Hunt down Nexus-Edge Hadim and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91226] = {id=91226,name="Prey: Jo'zolo the Breaker (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2437,description="Jo'zolo the Breaker is a troll who abides by his name. Long has he been the bane of our scouts, but no more! Kill him. Feed his anguish to the defenses of our beloved city.",objectivesText="Hunt down Jo'zolo the Breaker and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91227] = {id=91227,name="Prey: Jo'zolo the Breaker (Nightmare)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2444,description="Jo'zolo the Breaker is a troll who abides by his name. Long has he been the bane of our scouts, but no more! Kill him. Feed his anguish to the defenses of our beloved city.",objectivesText="Hunt down Jo'zolo the Breaker and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91228] = {id=91228,name="Prey: Zadu, Fist of Nalorakk (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2437,description="Our neighbors produce some of the most skilled hunters in all of Azeroth. It is a shame they are so difficult to reason with. There is one named Zadu. Her anguish would make for a most excellent trophy...",objectivesText="Hunt down Zadu, Fist of Nalorakk, and slay her. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91229] = {id=91229,name="Prey: Zadu, Fist of Nalorakk (Nightmare)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2444,description="Our neighbors produce some of the most skilled hunters in all of Azeroth. It is a shame they are so difficult to reason with. There is one named Zadu. Her anguish would make for a most excellent trophy...",objectivesText="Hunt down Zadu, Fist of Nalorakk, and slay her. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91230] = {id=91230,name="Prey: The Talon of Jan'alai (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2437,description="There is a powerful troll shaman who calls himself the Talon of Jan'alai. Long has he confounded our city's Farstriders, sowing confusion and death in his wake. See to it that he joins the spirits he so ardently venerates.",objectivesText="Hunt down The Talon of Jan'alai and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91231] = {id=91231,name="Prey: The Talon of Jan'alai (Nightmare)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2444,description="There is a powerful troll shaman who calls himself the Talon of Jan'alai. Long has he confounded our city's Farstriders, sowing confusion and death in his wake. See to it that he joins the spirits he so ardently venerates.",objectivesText="Hunt down The Talon of Jan'alai and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91232] = {id=91232,name="Prey: The Wing of Akil'zon (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2437,description="Do you smell that? There is death on the air. This can only mean one thing. The Wing of Akil'zon is near. Go out and slay her. Oh, and be careful. She's responsible for more than one lost Farstrider patrol.",objectivesText="Hunt down The Wing of Akil'zon and slay her. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91233] = {id=91233,name="Prey: The Wing of Akil'zon (Nightmare)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2444,description="Do you smell that? There is death on the air. This can only mean one thing. The Wing of Akil'zon is near. Go out and slay her. Oh, and be careful. She's responsible for more than one lost Farstrider patrol.",objectivesText="Hunt down The Wing of Akil'zon and slay her. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91234] = {id=91234,name="Prey: Ranger Swiftglade (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2437,description="It is a difficult thing, to hunt one of our own. Ranger Swiftglade is beyond redemption. His bloodlust could not be sated against our foes, and he has since turned his martial prowess upon his own people. End his sadistic killing spree and put his anguish to better use.",objectivesText="Hunt down Ranger Swiftglade and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91235] = {id=91235,name="Prey: Ranger Swiftglade (Nightmare)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2444,description="It is a difficult thing, to hunt one of our own. Ranger Swiftglade is beyond redemption. His bloodlust could not be sated against our foes, and he has since turned his martial prowess upon his own people. End his sadistic killing spree and put his anguish to better use.",objectivesText="Hunt down Ranger Swiftglade and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91236] = {id=91236,name="Prey: Lieutenant Blazewing (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2437,description="I do not know what to make of Lieutenant Blazewing. Her entire patrol disappeared during a reconnaissance mission into Zul'Aman. She was the sole survivor, but she returned with a fiery bloodlust and a complete disregard for the lives of others. Whether this is possession or sedition I am unsure, but she must be dealt with.",objectivesText="Hunt down Lieutenant Blazewing and slay her. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91237] = {id=91237,name="Prey: Lieutenant Blazewing (Nightmare)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2444,description="I do not know what to make of Lieutenant Blazewing. Her entire patrol disappeared during a reconnaissance mission into Zul'Aman. She was the sole survivor, but she returned with a fiery bloodlust and a complete disregard for the lives of others. Whether this is possession or sedition I am unsure, but she must be dealt with.",objectivesText="Hunt down Lieutenant Blazewing and slay her. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91238] = {id=91238,name="Prey: Petyoll the Razorleaf (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2437,description="Reports are coming in of shredded Farstriders adorned with petals and berries--entire patrols found strung up by razor-vines. There are more gruesome details, but they chafe even my... refined sensibilities. Hunt whatever manner of creature is embarking on this horrific killing spree, and see to it that its anguish is added to our crystals.",objectivesText="Hunt down Petyoll the Razorleaf and slay them. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91239] = {id=91239,name="Prey: Petyoll the Razorleaf (Nightmare)",level=90,requiredLevel=90,faction="horde",expansion=11,zoneID=15969,mapID=2393,description="Reports are coming in of shredded Farstriders adorned with petals and berries--entire patrols found strung up by razor-vines. There are more gruesome details, but they chafe even my... refined sensibilities. Hunt whatever manner of creature is embarking on this horrific killing spree, and see to it that its anguish is added to our crystals.",objectivesText="Hunt down Petyoll the Razorleaf and slay them. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=246231}},questType="standard"},
[91240] = {id=91240,name="Prey: Lamyne of the Undercroft (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2437,description="Do you garden, $p? I've been known to dabble. It seems the plants in our realm are becoming somewhat overbearing these days, sprouting legs and arms and running around murdering our brave soldiers. Let's give them a bit of a pruning, shall we?",objectivesText="Hunt down Lamyne of the Undercroft and slay them. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91241] = {id=91241,name="Prey: Lamyne of the Undercroft (Nightmare)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2444,description="Do you garden, $p? I've been known to dabble. It seems the plants in our realm are becoming somewhat overbearing these days, sprouting legs and arms and running around murdering our brave soldiers. Let's give them a bit of a pruning, shall we?",objectivesText="Hunt down Lamyne of the Undercroft and slay them. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91242] = {id=91242,name="Prey: High Vindicator Vureem (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2437,description="High Vindicator Vureem is a victim of his own unyielding faith in the Light and the superiority it gives him. His crusade continues unabated and unresolved. He exists in a constant state of fury at the imperfectness of the world and those within it. In the absence of total purity, Vureem sees only violence and the shadows of his own dogma. What say we put his worldview to the test?",objectivesText="Hunt down High Vindicator Vureem and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91243] = {id=91243,name="Prey: Crusader Luxia Maxwell (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2437,description="We are not sure if Luxia Maxwell is a deserter or has simply decided to embark on her own personal crusade. Regardless, reports are coming in of her attacking both friend and foe alike, yelling aphorisms of purity and duty. She has become a liability to the defense of Silvermoon. Go and harvest her anguish.",objectivesText="Hunt down Crusader Luxia Maxwell and slay her. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91244] = {id=91244,name="Prey: Praetor Singularis (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2437,description="The domanaar... I do not profess to know much about them, other than their proclivity for subterfuge, guile, and the absolute destruction of anything that stands before them. Praetor Singularis is no exception. They have been confounding our forces at every turn. Go and put an end to their games.",objectivesText="Hunt down Praetor Singularis and slay them. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91245] = {id=91245,name="Prey: Consul Nebulor (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2437,description="I have heard that there is one under Xal'atath's command who takes particular delight in dominating their foes. Whispers of a domanaar that taunts its victims with whispers and riddles before annihilating their mortal coil with void magic. Consul Nebulor is their name. Go and show them the limits of their power.",objectivesText="Hunt down Consul Nebulor and slay them. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91246] = {id=91246,name="Prey: Executor Kaenius (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2437,description="The domanaar have a reputation for guile and cunning, but there are brutes among them: those who seek to dominate their victims through sheer power and force of will. Executor Kaenius is one such domanaar. They stalk the battlefield, singling out our strongest soldiers and viciously cutting them down. Put an end to their rampage.",objectivesText="Hunt down Executor Kaenius and slay them. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91247] = {id=91247,name="Prey: Imperator Enigmalia (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2437,description="Imperator Enigmalia is personally responsible for the deaths of at least a dozen Farstriders. I say \"at least\" because this particular domanaar makes it somewhat difficult to identify the bodies, so utterly destroyed are they. Go and avenge our fallen soldiers.",objectivesText="Hunt down Imperator Enigmalia and slay them. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91248] = {id=91248,name="Prey: Knight-Errant Bloodshatter (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2437,description="Death knights are unstable killing machines at the best of times. Knight-Errant Bloodshatter has forsaken any oath or promise that would ostensibly bind one of his kind to the bottom rungs of civilized society, and has gone completely rogue. He is starting to become a liability. Recoup his anguish so that we can make the best of such an unfortunate situation.",objectivesText="Hunt down Knight-Errant Bloodshatter and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91249] = {id=91249,name="Prey: Vylenna the Defector (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2437,description="Vylenna the Defector lives up to her name. After a recent engagement on the field of battle, she became so preoccupied with profaning the dead that she completely abandoned the duties ascribed to her. Then her dereliction turned violent. A veritable font of anguish if you ask me...",objectivesText="Hunt down Vylenna the Defector and slay her. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91250] = {id=91250,name="Prey: Lost Theldrin (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2437,description="Those of us who succumbed to our base desire for mana were slowly weeded out of civil society, if they survived at all. Theldrin is one such example, only it is a testament to his cunning and will to live that he has made it as long as he has. He accepts no aid, choosing instead to stalk careless students and idle Magisters. His sole obsession is the mana that others possess... See to it that he never harms another elf again.",objectivesText="Hunt down Lost Theldrin and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91251] = {id=91251,name="Prey: Neydra the Starving (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2437,description="Poor Neydra... I knew her, in a previous life. She was full of vitality. Full of ambition. Unfortunately, she let that ambition get the best of her. She grew too enamored with the raw power of the arcane. She became resentful of all other things. Of all other people... And now she is a murderous creature who beheads rats and attacks innocents in a desperate attempt to garner enough arcane energy to slake her unquenchable thirst. It's funny, the paths life takes us...",objectivesText="Hunt down Neydra the Starving and slay her. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91252] = {id=91252,name="Prey: Thornspeaker Edgath (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2437,description="This one presents a prickly problem indeed. Thornspeaker Edgath has made a name for himself by using his druidic powers not to preserve Azeroth, but to twist its strength both against his enemies and innocent bystanders alike. He has no regard for anything that is not a beast or growing in the ground. It is time we clip this thorn.",objectivesText="Hunt down Thornspeaker Edgath and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91253] = {id=91253,name="Prey: Thorn-Witch Liset (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2437,description="Thorn-Witch Liset is a curse upon civilization and a blight upon the land itself. She twists the very trees and beasts, communing with the dark, evil things that live on the very edges of the natural realm. I despise the natural realm.",objectivesText="Hunt down Thorn-Witch Liset and slay her. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91254] = {id=91254,name="Prey: Grothoz, the Burning Shadow (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2437,description="The Twilight's Blade are an embarrassing band of mediocre cultists and uninspired conspirators. Grothoz is the brains of a particularly stupid cabal that has been active in a nearby region. As his stupidity prevents him from using his whole brain, let us unlock his potential for him...",objectivesText="Hunt down Grothoz, the Burning Shadow and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91255] = {id=91255,name="Prey: Dengzag, the Darkened Blaze (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2437,description="Do you know why the Twilight's Blade call Dengzag the \"Darkened Blaze?\" It is because they are stupid, small-minded, and utterly bereft of imagination. What a silly name indeed. I, however, am not small-minded. I have quite the prodigious mind, and it is currently intent on putting an end to Dengzag and whatever his tiny brain is up to. Get to it.",objectivesText="Hunt down Dengzag, the Darkened Blaze and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
[91256] = {id=91256,name="Prey: High Vindicator Vureem (Nightmare)",level=90,requiredLevel=90,faction="none",expansion=11,mapID=2444,description="High Vindicator Vureem is a victim of his own unyielding faith in the Light and the superiority it gives him. His crusade continues unabated and unresolved. He exists in a constant state of fury at the imperfectness of the world and those within it. In the absence of total purity, Vureem sees only violence and the shadows of his own dogma. What say we put his worldview to the test?",objectivesText="Hunt down High Vindicator Vureem and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.",rewardXP=20540,starts={{npcID=245824}},ends={{npcID=245824}},questType="standard"},
