[91796] = {id=91796,name="Special Assignment: Ours Once More!",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=15968,mapID=2536,rewardXP=13690,questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=254911,text="Inhabit a Loa Avatar"},{orderIndex=1,type=0,amount=50,objectID=254909,text="Slay Echoes"},{orderIndex=2,type=0,amount=1,objectID=255884,text="Use Time Flies ability to travel"},{orderIndex=3,type=0,amount=1,objectID=254910,text="Raid Leader slain"}},worldTaskTitle="Special Assignment: Ours Once More!",db2QuestInfoID=286,db2QuestInfoName="Capstone World Quest"},
