[91810] = {id=91810,name="Blistereel Boar Buffet",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=15947,mapID=2437,rewardXP=13690,rewardItems={260890},questType="world",db2Objectives={{orderIndex=0,type=0,amount=5,objectID=255859,text="Prepared Zapgut Eel squeezed"},{orderIndex=1,type=0,amount=6,objectID=255860,text="Prepared Saltleaf Boar carved"},{orderIndex=2,type=0,amount=8,objectID=256001,text="Jump on the Blisterskin Kelp"},{orderIndex=4,type=0,amount=1,objectID=256053,text="Blistereel Boar cooked"},{orderIndex=5,type=0,amount=1,objectID=256054,text="Blistereel Boar tasted"}},worldTaskTitle="Blistereel Boar Buffet",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[91811] = {id=91811,name="A Scorched Mirror",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=15947,mapID=2437,rewardXP=13690,questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=256110,text="Coalesced Fire touched"}},worldTaskTitle="A Scorched Mirror",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[91813] = {id=91813,name="The Spiritpaw",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15947,mapID=2437,description="I just chased away some furbolg dat were actin' real strange. Dey were arguin' and then one walked toward Lilaju with his hands in de air. I charged at dem an' scared dem off. Dey are usually hostile and who knows what dey were gonna do? But Lilaju wants to see what dey wanted. Our scouts saw dem follow de river east to de north side of de lake. Track dem down. See what dey want. If it's a trick, then kill dem.",objectivesText="Find the Spiritpaw furbolg that wanted to speak to Lilaju.",rewardGold=32200,rewardXP=1470,rewardCurrencies={{id=3316,amount=5},{id=3354,amount=10}},starts={{npcID=248657}},ends={{npcID=248121}},coords={x=0.336,y=0.788,source="quest_giver",zoneID=15947},questType="standard"},
[91822] = {id=91822,name="The Regent's Request",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2393,description="Lor'themar has requested our presence. He wasn't exactly forthcoming with the details, but the location he chose speaks volumes. Silvermoon Harbor. Quiet and out of sight. Not exactly the kind of place one picks for diplomacy or ceremony. No, this feels like something else entirely. Whatever he's planning, it won't be written down in any official record. Come. Let's find out what the Regent Lord has to say.",objectivesText="Find out what Lor'themar is planning. Progress: Let's not keep the Regent Lord waiting.",rewardGold=341600,rewardXP=11765,starts={{npcID=242381}},ends={{npcID=248750}},coords={x=0.524,y=0.78,source="quest_giver",zoneID=15969},questType="standard"},
[91823] = {id=91823,name="Lines Cut, Tongues Silenced",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="The Twilight's Blade slipped into Tranquillien so easily because they'd stolen knowledge and secrets. About our defenses, our magic, our people. Once inside, they uncovered even more information. Now they pass that intelligence between themselves using enchanted orbs. Quiet whispers drifting through the dark. Every message tightens the noose around Quel'Thalas. Find the orbs. Break them. Every shattered crystal is a whisper silenced.",objectivesText="Destroy the Communications Orbs in Zeb'tela Ruins.",rewardGold=341600,rewardXP=11765,starts={{npcID=248750}},ends={{npcID=248750}},coords={x=0.618,y=0.682,source="quest_giver",zoneID=15968},questType="standard"},
[91824] = {id=91824,name="The Thieves' Trail",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="From what I can see, it looks like the Twilight's Blade stole several arcane artifacts used by our Magisters to enhance long-distance communication. If they learn to wield them, they'll cast their reach far beyond what we can contain. They might even be able to hear our communications... and we can't have that. Recover the artifacts. If anyone gets in your way... you know what to do.",objectivesText="Recover Quel'dorei Artifacts from the Twilight's Blade in Zeb'tela Ruins. Progress: Those artifacts should never have fallen into the wrong hands.",rewardGold=341600,rewardXP=11765,rewardItems={248614},starts={{npcID=248750}},ends={{npcID=248750}},coords={x=0.618,y=0.682,source="quest_giver",zoneID=15968},questType="standard"},
[91825] = {id=91825,name="Dead Men Keep No Secrets",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="From what I've seen, this group isn't acting without direction. There's someone leading them, a man hiding in one of their structures. If I had to guess, he's the one holding whatever they considered too important to trust to crystal or courier. Documents, plans, names. Find him, silence him, and bring back whatever he was protecting.",objectivesText="Retrieve the stolen documents from Gareth the Listener in Zeb'tela Ruins. Progress: You made that look easy.",rewardGold=683200,rewardXP=14705,rewardItems={248615},starts={{npcID=248750}},ends={{npcID=248750}},coords={x=0.618,y=0.682,source="quest_giver",zoneID=15968},questType="standard"},
[91826] = {id=91826,name="Tripwire Tango",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="This cache isn't locked with magic. It's craftsmanship. I can hear the mechanism ticking inside. Tiny cogwheels, tension springs, and probably a poison vial ready to shatter the moment someone tries to pick the lock. We'll have to do this together. I'll take the pins, you keep the mechanism from snapping. One wrong move and it'll be enough to drop an ogre in mid-charge. Steady now.",objectivesText="Disarm the mechanism and retrieve the documents from inside the chest. Progress: Easy does it.",rewardGold=341600,rewardXP=11765,rewardItems={248720},starts={{npcID=248750},{npcID=248874}},ends={{npcID=248874}},coords={x=0.618,y=0.682,source="quest_giver",zoneID=15968},questType="standard"},
[91827] = {id=91827,name="No Loose Ends",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2395,description="You handled yourself well. These documents are too important to pass through couriers or ravens. I'd like you to deliver them personally to Lor'themar. He'll want to see the truth for himself and know who brought it back. Keep them close, and don't let anyone else near them.",objectivesText="Return to Lor'themar Theron in Silvermoon City.",rewardGold=246300,rewardXP=8825,starts={{npcID=248874}},ends={{npcID=235787}},coords={x=0.618,y=0.682,source="quest_giver",zoneID=15968},questType="standard"},
[91828] = {id=91828,name="A Favor for the Lion",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15947,mapID=2393,description="A letter arrived for me. No seal, no name. Just folded parchment and handwriting I'd recognize anywhere. It didn't say much. He never wastes words. I've known his family a long time. When they reach out, I answer.",objectivesText="Read the letter and assist Valeera Sanguinar in Zul'Aman . Progress: Yes?",rewardGold=341600,rewardXP=13690,starts={{npcID=242381}},ends={{npcID=248982}},coords={x=0.524,y=0.78,source="quest_giver",zoneID=15969},questType="standard"},
[91829] = {id=91829,name="One by One",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Every last cultist is a threat to the people we're trying to save. To Silvermoon itself. Blasted fanatics with blood on their hands and no intention of letting anyone walk out alive. We're already in the camp. Let's make it count. I want them to feel this.",objectivesText="Kill cultists of the Twilight's Blade at Speaker's Rest. Progress: Keep the kills quiet if you can.",rewardGold=341600,rewardXP=13690,starts={{npcID=248982},{npcID=250295}},ends={{npcID=250295}},coords={x=0.404,y=0.716,source="quest_giver",zoneID=15947},questType="standard"},
[91830] = {id=91830,name="Intercepted",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15947,mapID=2437,description="The Twilight's Blade hit Tranquillien hard. Slipped in and took all the supplies and information they could ever need, right beneath everyone's nose. Time to return the favor. I've marked a few tents. Command posts, messengers' satchels, a supply ledger tucked under a wine crate. That's where they keep their orders, maps, and routes. Grab everything you can.",objectivesText="Collect 6 Cult Orders from the Twilight's Blade camp at Speaker's Rest. Progress: The right scrap of parchment can win a war. Or start one.",rewardGold=341600,rewardXP=13690,rewardItems={248928},starts={{npcID=248982},{npcID=250295}},ends={{npcID=250295}},coords={x=0.404,y=0.716,source="quest_giver",zoneID=15947},questType="standard"},
[91831] = {id=91831,name="Keys Are Optional",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15947,mapID=2437,description="These people joined the Twilight's Blade looking for purpose, power, or place to belong. For a reprieve from the fear and a promise of certainty. Now they see it for what it is--a prison dressed up as faith. And they want out. We go in together. Get them out before the cult realizes what's happening.",objectivesText="Find and release 4 groups of Cult Deserters in Speaker's Rest. Progress: Ready yourself. This might get messy.",rewardGold=341600,rewardXP=13690,starts={{npcID=248982},{npcID=250295}},ends={{npcID=250295}},coords={x=0.404,y=0.716,source="quest_giver",zoneID=15947},questType="standard"},
[91833] = {id=91833,name="Dirty Deeps",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15947,mapID=2437,description="De Vilebranch are sinkin' deeper into their cursed minds. Dey spit in de face of de loa, and believe dey have mastered death. I could see a certain... someone not likin' dat way of thinkin'. Dey have taken our kin and now dey take our shaman. Meet my scout there and help dem break their plans. Cut de head off de beast and de body will fall.",objectivesText="Meet the Witherbark Scout at Maisara Deeps. Provided item:",rewardGold=34100,rewardXP=1370,rewardItems={248814},rewardCurrencies={{id=3316,amount=5},{id=3354,amount=10}},starts={{npcID=244591}},ends={{npcID=248838}},coords={x=0.384,y=0.224,source="quest_giver",zoneID=15947},questType="standard"},
[91834] = {id=91834,name="Guardians Must Go",level=83,requiredLevel=83,faction="none",expansion=11,objectivesText="Kill the Dark Hex Guardian and meet me below. Provided item:",questType="standard"},
[91835] = {id=91835,name="Send Dem Home",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15947,mapID=2437,description="My friend, dis is a mighty gift. Shadra is givin' us a blessin' for de tasks ahead. These Vilebranch really are livin' up to their name. Dey drain de spirit from de Witherbark and create undead to serve dem. We must free de Witherbark from these necrotic bonds. My friend's still in there... I hope. Me and Bin'zin cut our tusks together growin' up. He grew into a strong shaman. Our village needs him, and he is like a brother to me.",objectivesText="Free 8 Witherbark Prisoners . Progress: Are the prisoners safe?",rewardGold=341600,rewardXP=13690,rewardItems={248745},rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=248838}},ends={{npcID=249106}},coords={x=0.448,y=0.364,source="quest_giver",zoneID=15947},questType="standard"},
[91836] = {id=91836,name="Respect de Totem",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15947,mapID=2437,description="When dey took Bin'zin, de priestess destroyed his totems and gave de shattered remains to her minions--like some grisly memento. Take de pieces back, one by one if ya have to. Dat disrespect will not stand.",objectivesText="Collect 40 Totem Remnants . Progress: How goes de lootin'?",rewardGold=341600,rewardXP=13690,rewardItems={254430},rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=248838}},ends={{npcID=249106}},coords={x=0.448,y=0.364,source="quest_giver",zoneID=15947},questType="standard"},
[91837] = {id=91837,name="Bring Back De Bones",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=15947,mapID=2437,description="Big thanks for breakin' us free. Some were not so lucky. Bring dey bones back to de Chief, he will know what to do.",objectivesText="Collect 8 Bones of de Fallen .",rewardGold=341600,rewardXP=13690,questType="standard"},
[91838] = {id=91838,name="De Vile Diminished",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15947,mapID=2437,description="These vile orbs are harvestin' de souls of our people and sendin' dark energy to de Knife Priestess. She's gettin' mighty powerful. Destroy de orbs so her ritual of death is ruined. With de gift of Shadra, ya will not fail.",objectivesText="Destroy 5 Vile Orbs . Progress: Did ya find all de orbs?",rewardGold=341600,rewardXP=13690,rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=248787}},ends={{npcID=248787}},coords={x=0.448,y=0.364,source="quest_giver",zoneID=15947},questType="standard"},
[91839] = {id=91839,name="Sacrifice Denied",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Our shaman is home and Jin'zin's full of joy to see him again. She was always his little wildcat apprentice. Dey will have sad moments--Tan'zin is a mighty loss. Today, ya brought him home. Go enjoy dat for a bit, $p, before ya be on ya way.",objectivesText="Check on Bin'zin . Progress: Did ya talk to him?",rewardGold=341600,rewardXP=13690,rewardItems={264662,264663,264664,264665},rewardCurrencies={{id=3316,amount=25},{id=3354,amount=250}},starts={{npcID=248838}},ends={{npcID=253326}},coords={x=0.448,y=0.364,source="quest_giver",zoneID=15947},questType="standard"},
[91840] = {id=91840,name="One Will Not Rise",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Now's our best shot! We end de sacrifices here! Stoppin' de dark energy has weakened her hold. Then, you can be de one to bring back her head. Uh, and --no tellin' de chief about me callin' him Big VunVun. He'll be turnin' me into a frog if he hears dat again.",objectivesText="Deliver the head of Knife Priestess Hezzia to Vun'zarah in Witherbark Bluffs. Progress: I am pleased you're takin' my words so literally.",rewardGold=683200,rewardXP=17110,rewardItems={250190,254778},rewardCurrencies={{id=3316,amount=20},{id=3354,amount=100}},starts={{npcID=249106}},ends={{npcID=244591}},coords={x=0.452,y=0.417,source="quest_giver",zoneID=15947},questType="standard"},
[91842] = {id=91842,name="Disarm the Dark Horde",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=51,mapID=36,description="The Dark Horde have no love fer their equipment. Look at their weapons! Cracked, rusted, blunt, and bent. Ach! The only way they function is by making more shoddy tools to constantly replace the ones they've broken. If ye see any of their weapon racks, destroy 'em. Let's see how well they fight without their rusty blades. A bare-fisted orc is nothing to sneeze at, but it'll further delay any daft plans they've got.",objectivesText="Destroy 8 Dark Horde Weapon Racks .",rewardGold=335000,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=237268}},ends={{npcID=237268}},coords={x=0.212,y=0.398,source="quest_giver",zoneID=46},questType="standard"},
[91854] = {id=91854,name="Deepening Shadows",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Champion, I could use your assistance. The natives here in Silvermoon are proving to be less hospitable than we had hoped. In their defense, their city is facing down a darkness unlike anything Azeroth has ever faced, so tensions are high. Can you use your unique perspective and help de-escalate some of the hot spots that are emerging around Silvermoon?",objectivesText="De-escalate rising tensions in Silvermoon City . Progress: Tensions are high.",rewardGold=341600,rewardXP=11765,starts={{npcID=248631}},ends={{npcID=248631}},coords={x=0.454,y=0.702,source="quest_giver",zoneID=15969},questType="standard"},
[91872] = {id=91872,name="The Former Rootwarden",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="$p, I was the Rootwarden of Teldrassil. For years, I watched the roots here below the surface, but I was not aware of what was threatening the tree outside of Harandar . For just as long, I have regretted that failure, but we cannot change the past. I wonder, however, if roots so great may still have life within them. Might there be something which can still be done? I do not know, but I do hope. Will you join me at the Shrine of Ages, to tend the roots?",objectivesText="Meet Hagar at the Shrine of Ages.",rewardGold=34100,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3370,amount=10}},starts={{npcID=237572}},ends={{npcID=252495}},coords={x=0.348,y=0.25,source="quest_giver",zoneID=15355},questType="standard"},
[91873] = {id=91873,name="Buffer Zone",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="At this shrine, I have worked to gather roots that seem to still have the possibility of life within them. They are each greatly damaged, some more than others. My hope is some might recover, with enough time and enough care. In that way, I honor the great tree's memory. For that to be possible, though, we have to keep them safe from the hazards of Harandar . Please be sure that nothing nearby threatens them.",objectivesText="Protect the shrine from local wildlife.",rewardGold=341600,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=252495}},ends={{npcID=252497}},coords={x=0.424,y=0.34,source="quest_giver",zoneID=15355},questType="standard"},
[91874] = {id=91874,name="Flare Up",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="$p, I see smoke rising above Har'mara. The roots are on fire--not here, but beneath the remnants of the tree! I have seen this happen many times, but we must always respond with haste. Take to the skies and douse them, immediately!",objectivesText="Fly near the flames on the roots of Teldrassil to douse them.",rewardGold=341600,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=252496}},ends={{npcID=248886}},coords={x=0.424,y=0.344,source="quest_giver",zoneID=15355},questType="standard"},
[91875] = {id=91875,name="Natural Remedy",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="If we ever hope to see new growth, Teldrassil's roots needs a great deal of special attention. The source of this stream is one of the great roots. The water carries ash, which I believe still contains the tree's essence. The stalkers in the stream carry a mixture of that ash and slime from their tendrils--a very potent mixture. Bring me as much of it as you can carry, and I will combine it with reagents I've gathered. Then we'll be ready to apply it to the roots.",objectivesText="Gather 8 clumps of Verdant Stalker Sludge . Progress: Do you have the rejuvenating mud I asked for?",rewardGold=683200,rewardXP=15215,rewardItems={252649},rewardCurrencies={{id=3316,amount=20},{id=3370,amount=100}},starts={{npcID=252497}},ends={{npcID=252496}},coords={x=0.422,y=0.34,source="quest_giver",zoneID=15355},questType="standard"},
[91876] = {id=91876,name="Tending Hope",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Thank you for tending to those fires, $p. While you were gone, I've used that sludge to make a salve. Help me spread it over Teldrassil's roots. It may take years to see a difference, if we ever do. But though I failed, I made oaths to her, and I can still choose to keep them. I will never stop doing what I can to... help her perhaps grow again. If I do not succeed, the next Rootwarden, or the one who comes after that, may be the one to finish this work. Even so, I shall not stop trying.",objectivesText="Apply Hagar 's salve to 12 Withered Roots. Progress: Have you treated the roots?",rewardGold=335000,rewardXP=12170,rewardItems={260450,260451},rewardChoices={260450,260451},rewardCurrencies={{id=3316,amount=25},{id=3370,amount=250}},starts={{npcID=248886}},ends={{npcID=252494}},coords={x=0.426,y=0.336,source="quest_giver",zoneID=15355},questType="standard"},
[91884] = {id=91884,name="The Illusion of Motion",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="You! Have YOU seen them? I've been tasked to investigate some of our scouts that have gone missing. My reconnaissance had come up empty until recently. Now I've been catching glimpses of the missing scouts, but... they appear formed of pure Void energy. Each time I chase the figures, they lead me further and further before disappearing! The others think I'm crazy. You haven't seen anything like that, have you?",objectivesText="Investigate the mysterious figures Nefina has seen around Locus Point.",rewardGold=33500,rewardXP=1605,rewardCurrencies={{id=3316,amount=5},{id=3389,amount=10}},starts={{npcID=248881}},ends={{npcID=248880}},coords={x=0.414,y=0.74,source="quest_giver",zoneID=15458},questType="standard"},
[91885] = {id=91885,name="Drain You",level=88,requiredLevel=88,faction="none",expansion=11,zoneID=15458,mapID=2405,description="Do you... see...? They follow... They plead... for help... Too weak... too starving... This... will feed me... then together... we find the missing elves...",objectivesText="Slay Voidstorm wildlife and use the Void Splinter to feed the Starving Voidwalker .",rewardGold=341600,rewardXP=12845,rewardItems={249433},rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=248880}},ends={{npcID=256206}},coords={x=0.488,y=0.822,source="quest_giver",zoneID=15458},questType="standard"},
[91886] = {id=91886,name="Voices of Omens",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="The voices of your elven allies rattle inside my head. I know of a way we can find them. There is a way to locate missing things... using old domanaar scanning devices. But they require immense energy to function. Together, we can use these devices to focus the images of your lost friends. Their cries for help will become clearer, and then you can find them. Come. Lend me your strength.",objectivesText="Help the Sentient Voidwalker power Domanaar Scrystones to help locate the missing scouts.",rewardGold=341600,rewardXP=12845,rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=256206}},ends={{npcID=248894}},coords={x=0.488,y=0.822,source="quest_giver",zoneID=15458},questType="standard"},
[91887] = {id=91887,name="Dominion of Deceit",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="We were right to be cautious. The threats we've found here in the Voidstorm are corrupting and irredeemable. This voidwalker's meticulous deceptions are unusual... I can't help but wonder why it would go through all the trouble. But I'm too weak to go on. It really did a number on me. You have the upper hand now! It thinks you're walking into its trap. Walk in with weapons drawn and spells ready!",objectivesText="Slay the Deceitful Voidwalker .",rewardGold=683200,rewardXP=16055,rewardItems={264415,264417,264418,264419,264420,264421,264422,264423,264424},rewardCurrencies={{id=3316,amount=25},{id=3389,amount=250}},starts={{npcID=248894}},ends={{npcID=248881}},coords={x=0.446,y=0.822,source="quest_giver",zoneID=15458},questType="standard"},
[91918] = {id=91918,name="Delves: Measure Once, Cut Twice",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="We've done well to see those deserters to safety, but don't fool yourself into thinking we've freed them all. I've heard whispers of a place they use to break those whose loyalty is in question. The location isn't common knowledge, but I know where to start looking. If we're quick, we might find others before the cult decides they're too great a risk to keep alive. Meet me near the site. Keep your blades sharp and your steps light.",objectivesText="Rescue the remaining Twilight's Blade Deserters from the Twilight Crypts delve on any difficulty.",rewardGold=1024800,rewardXP=20540,starts={{npcID=250295}},ends={{npcID=242381}},coords={x=0.372,y=0.722,source="quest_giver",zoneID=15947},questType="standard"},
[91927] = {id=91927,name="Ooze Booting",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=15355,mapID=2413,rewardXP=13690,questType="world",db2Objectives={{orderIndex=0,type=0,amount=6,objectID=249055,text="Escaping Oozes booted"}},worldTaskTitle="Ooze Booting",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[91928] = {id=91928,name="What's For Lunch?",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,description="My Shadowtrade Mercenaries will fight for Stormarion Cores , no questions asked, but they do get hungry also! Food is quite scarce here, so we need supplies! Take a mercenary out with you and find some food for them to eat. I'll make it worth your while!",rewardGold=341600,rewardXP=20540,rewardItems={248826},starts={{npcID=244749,x=0.264,y=0.676,zoneID=15458}},ends={{npcID=244749,x=0.264,y=0.676,zoneID=15458}},coords={x=0.264,y=0.676,source="quest_giver",zoneID=15458},questType="world",worldTaskTitle="What's For Lunch?"},
[91929] = {id=91929,name="What's For Lunch?",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,description="My Shadowtrade Mercenaries will fight for Stormarion Cores , no questions asked, but they do get hungry also! Food is quite scarce here, so we need supplies! Take a mercenary out with you and find some food for them to eat. I'll make it worth your while!",rewardGold=341600,rewardXP=20540,rewardItems={248905},starts={{npcID=244749,x=0.264,y=0.676,zoneID=15458}},ends={{npcID=244749,x=0.264,y=0.676,zoneID=15458}},coords={x=0.264,y=0.676,source="quest_giver",zoneID=15458},questType="world",worldTaskTitle="What's For Lunch?"},
[91930] = {id=91930,name="The Abundant Lands",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15947,mapID=2437,description="De loa have reunited with us forest trolls, and de land reacts with glorious bounty! Do ya wish to take part? Then go north, and meet me at de entrance to Loaknit Den. There I will introduce ya to prosperity and plentitude like ya never seen...",rewardGold=77400,rewardXP=2940,starts={{npcID=241924,x=0.45,y=0.676,zoneID=15947}},ends={{npcID=241928,x=0.316,y=0.262,zoneID=15947}},coords={x=0.45,y=0.676,source="quest_giver",zoneID=15947},questType="world",worldTaskTitle="The Abundant Lands"},
[91932] = {id=91932,name="The Abundant Awakening",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15947,mapID=2437,description="De Loa of Abundance accepts everyone, and everyone de Loa of Abundance accepts is granted de privilege of learnin' how best to serve abundance. Speak with his glorious visage and become a fellow acolyte.",rewardGold=341600,rewardXP=11765,starts={{npcID=241928,x=0.316,y=0.262,zoneID=15947}},ends={{npcID=251601,x=0.316,y=0.26,zoneID=15947}},coords={x=0.316,y=0.262,source="quest_giver",zoneID=15947},questType="world",worldTaskTitle="The Abundant Awakening"},
[91933] = {id=91933,name="The Abundant Honor",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15947,mapID=2437,description="On to the next phase of your education: mercantilism! Imagine yourself, offering the bounty of endless harvest to my glorious self, and reaping the abundant rewards I bestow upon you in kind. Now let us put that beauteous vision into practice! I will grant you a minute portion of unalloyed abundance . You, in turn, shall trade it to your fellow acolyte for one of many premium goods.",rewardGold=341600,rewardXP=11765,rewardItems={252607,252608},rewardCurrencies={{id=3376,amount=4}},starts={{npcID=251601,x=0.316,y=0.26,zoneID=15947}},ends={{npcID=251601,x=0.316,y=0.26,zoneID=15947}},coords={x=0.316,y=0.26,source="quest_giver",zoneID=15947},questType="world",worldTaskTitle="The Abundant Honor"},
[91937] = {id=91937,name="Portraits in the Vale",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=15355,mapID=2413,rewardXP=13690,questType="world",db2Objectives={{orderIndex=0,type=3,amount=1,objectID=249095,text="Ride Bo'ke"},{orderIndex=1,type=15,amount=1,objectID=0,text="Local Wildlife chronicled"},{orderIndex=2,type=0,amount=50,objectID=249089,text="Common"},{orderIndex=3,type=0,amount=25,objectID=249090,text="Rare"},{orderIndex=4,type=0,amount=14,objectID=249091,text="Epic"},{orderIndex=5,type=0,amount=9,objectID=249092,text="Legendary"}},worldTaskTitle="Portraits in the Vale",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[91955] = {id=91955,name="Just Between Us",level=10,requiredLevel=10,faction="both",expansion=11,mapID=619,description="The artifact we snatched from the timeline earlier was replaced with a simulacrum so none would notice the true artifact's absence. Such a wealth of infinite energy should not be abandoned so readily. You should seek it out and reclaim it. Once you have recovered the simulacrum you can scrap it for an embarassing sum of bronze and infinite power.",objectivesText="Retrieve the Curious Simulacrum left in place of your \"borrowed\" artifact weapon by completing your artifact weapon's acquisition storyline as part of your Order Hall campaign.",rewardItems={242617,247808,248140,248141},starts={{npcID=241142}},ends={{npcID=241142}},questType="standard"},
[91958] = {id=91958,name="Den of Nalorakk: Unforgiven",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Nalorakk is de Loa of War. His trial must be a battle! There would be no greater death for an Amani than to die in combat against de Loa of War. No greater thrill than fightin' him. Does it not make your blood pump faster and harder in your veins, hash'ura? Zul'jarra lets out a feral howl and laughs.> Come. Meet me at Nalorakk's Prowl and we will sit at his fire and face our last trial--together.",objectivesText="Complete the Den of Nalorakk dungeon. Progress: De final trial is at hand.",rewardGold=1366400,rewardXP=24340,rewardChoices={251144,251146,251148,251155,251160,251173},rewardCurrencies={{id=3316,amount=100},{id=3354,amount=1500}},starts={{npcID=240215}},ends={{npcID=240215}},coords={x=0.336,y=0.788,source="quest_giver",zoneID=15947},questType="standard"},
[91963] = {id=91963,name="Running Amok",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="I've heard from the other scouts about that metal--the shadowgraft. The domanaar use it to enforce their control over others. I have to imagine that there's someone holding the reins still. Maybe it's Xal'atath, or maybe someone else. Gather pieces of their shadowgraft and maybe we can make sense of who.",objectivesText="Gather Shadowgraft from foes at Obscurion Citadel. Progress: Have you gathered enough for us to study?",rewardGold=341600,rewardXP=12845,rewardItems={249387},rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=249045},{npcID=249130}},ends={{npcID=249130}},coords={x=0.624,y=0.824,source="quest_giver",zoneID=15458},questType="standard"},
[91966] = {id=91966,name="Saltheril's Soiree",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=15968,mapID=2395,objectivesText="Tend to the Soiree's cleaning and entertainment Song chosen",coords={mapID=2395,x=0.427,y=0.473},questType="standard",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Tend to the Soiree's cleaning and entertainment"},{orderIndex=2,type=0,amount=1,objectID=249510,text="Song chosen"}},worldTaskTitle="Saltheril's Soiree"},
[91967] = {id=91967,name="You Know This Evil?",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Champion, we have a bit of a delicate situation. The Vanguard of the Light has just informed me they have taken Magister Umbric into custody. Apparently he was trying to get close to the Sunwell. I do not have to tell you that tensions are high between my city and the Vanguard. We need Umbric to continue his research if we are to have a chance at contending with the Voidstorm. I want you to represent me in negotiating Umbric's release. Whether we like him or not, we need him.",objectivesText="Negotiate with the Vanguard of the Light for Magister Umbric 's release. Progress: Umbric is necessary. So is the Vanguard. I have a lot of necessary and unsavory elements to deal with these days, but I will do so if it means my people are safe.",rewardGold=341600,rewardXP=11765,starts={{npcID=235787}},ends={{npcID=235787}},coords={x=0.454,y=0.704,source="quest_giver",zoneID=15969},questType="standard"},
[91970] = {id=91970,name="WANTED: Gelatonius",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Are you ready to test yourself against a true foe? In the center of the Gloom Mire is Gelatonius , a fungal giant of enormous proportions. Kill him, if you think you can. I'm willing to be impressed, and to pay handsomely for this task.",rewardGold=683200,rewardXP=16055,rewardCurrencies={{id=3310,amount=25},{id=3310,amount=37},{id=3316,amount=50},{id=3370,amount=250}},starts={{npcID=249361,x=0.518,y=0.742,zoneID=15355}},ends={{npcID=249361,x=0.518,y=0.742,zoneID=15355}},coords={x=0.518,y=0.742,source="quest_giver",zoneID=15355},questType="world",worldTaskTitle="WANTED: Gelatonius",db2QuestInfoID=1,db2QuestInfoName="Group"},
[91971] = {id=91971,name="Hitting the Hammer",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="The Twilight Hammer is dirtying up the ruins of Zeb'tala. Clean up the area and bring back some of their personal tokens. One never knows what curiosities may appeal to those vying for relevancy. Those mindless cultists may stomp around and act tough, but you will make quick work of them.",objectivesText="Bring back 6 Twilight Tokens . Progress: Have you found anything useful?",rewardGold=341600,rewardXP=11765,rewardItems={249411,249412,249413,249415,249416},rewardCurrencies={{id=3310,amount=35},{id=3310,amount=52},{id=3379,amount=40},{id=3379,amount=50}},starts={{npcID=240835}},ends={{npcID=240835}},coords={x=0.424,y=0.466,source="quest_giver",zoneID=15968},questType="standard"},
[91972] = {id=91972,name="Hold the Watch",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="There is still a lot of friction on the border with Zul'Aman, but we must hold the watch on all fronts. Check in with Bloodguard Nelric at the Thalassian Pass. It is rumored to be one of the most uneventful posts. I am certain he would appreciate a reprieve, if only for a few moments. Stay alert, $p!",objectivesText="Check in with Bloodguard Nelric at the Thalassian Pass and hold the watch.",rewardGold=341600,rewardXP=11765,rewardItems={242241},rewardCurrencies={{id=3310,amount=35},{id=3310,amount=52},{id=3379,amount=40},{id=3379,amount=50}},starts={{npcID=240835}},ends={{npcID=240835}},coords={x=0.424,y=0.466,source="quest_giver",zoneID=15968},questType="standard"},
[91973] = {id=91973,name="Naga Blades",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="It seems the locals currently find great appeal in naga blades--the brinier the better. On our southwestern shore, you will find the Daggerspine naga. They have these grungy, barnacle-encrusted scimitars that would perfectly fit the bill. Go grab a few of those. They could have value in some of our upcoming discussions.",objectivesText="Collect 7 Naga Scimitars . Progress: Were you able to procure some blades?",rewardGold=341600,rewardXP=11765,rewardItems={249499},rewardCurrencies={{id=3310,amount=35},{id=3310,amount=52},{id=3379,amount=50},{id=3379,amount=60}},starts={{npcID=240835}},ends={{npcID=240835}},coords={x=0.424,y=0.466,source="quest_giver",zoneID=15968},questType="standard"},
[91974] = {id=91974,name="Sunfire to the Blade",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="I guess there is one benefit to being part of the courtly intrigue: one does hear things. We have this concoction of sunfire infused with the holy energy of the Blood Knights, courtesy of the court alchemists. Take this down to the Sanctum of the Moon and test it on the Twilight intruders. I look forward to hearing the results in detail.",objectivesText="Kill 10 Twilight intruders at the Sanctum of the Moon with Holy Sunfire . Progress: How did it go?",rewardGold=341600,rewardXP=11765,rewardItems={249691},rewardCurrencies={{id=3310,amount=35},{id=3310,amount=52},{id=3379,amount=40},{id=3379,amount=50}},starts={{npcID=240835}},ends={{npcID=240835}},coords={x=0.424,y=0.466,source="quest_giver",zoneID=15968},questType="standard"},
[91975] = {id=91975,name="That's Our Wood",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="It seems the lure of the lightwood continues to be a problem. We may as well take advantage of the trolls' hard work! Collect what they have harvested. We can make use of it. What we do not use for weapons, we can hand over to the carvers. The nobles will clamor over lightwood decor.",objectivesText="Collect 5 Harvested Lightwood . Progress: Did you gather the lightwood?",rewardGold=315900,rewardXP=11765,rewardItems={249407},rewardCurrencies={{id=3310,amount=35},{id=3310,amount=52},{id=3379,amount=50},{id=3379,amount=60}},starts={{npcID=240835}},ends={{npcID=240835}},coords={x=0.424,y=0.466,source="quest_giver",zoneID=15968},questType="standard"},
[91976] = {id=91976,name="Lightbloom Dimmed",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="All of this small talk makes my ears twitch. I would be so much more useful doing field work. For now, you get to do the fun part. The creatures within the Lightbloom are getting a bit dense. I need you to get out there and lower the volume. I am sure you'll run into many options while you are out there. Take a whack at a few for me.",objectivesText="Kill Lightbloom creatures.",rewardGold=341600,rewardXP=11765,rewardItems={242241},rewardCurrencies={{id=3310,amount=35},{id=3310,amount=52},{id=3379,amount=50},{id=3379,amount=60}},starts={{npcID=240835}},ends={{npcID=240835}},coords={x=0.424,y=0.466,source="quest_giver",zoneID=15968},questType="standard"},
[91977] = {id=91977,name="Less Lawless",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="The Tideborne are always running just over the legal line. They are an annoyance at best, but will push boundaries when given too much rope. The ones in Sunsail Anchorage made the mistake of ripping off some nobles not too long ago. Maybe go smack them around a bit--remind them to respect their betters.",objectivesText="Chastise 8 Tideborne. Progress: Have you taught the Tideborne a lesson?",rewardGold=341600,rewardXP=11765,rewardItems={242241},rewardCurrencies={{id=3310,amount=35},{id=3310,amount=52},{id=3379,amount=40},{id=3379,amount=50}},starts={{npcID=240835}},ends={{npcID=240835}},coords={x=0.424,y=0.466,source="quest_giver",zoneID=15968},questType="standard"},
[91978] = {id=91978,name="Taxing the Tideborne",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="Have you ever noticed, that sometimes there is benefit in letting someone think they are getting away with something? The Tideborne will continue to smuggle in plain sight, feeling clever at the taxes they're avoiding paying to Silvermoon. This does add up, though, over time. When you have a moment, please head down to the harbor and relieve them of some of their back taxes.",objectivesText="Collect 50 Tideborne Dubloons . Progress: Is it still stealing when stolen from thieves?",rewardGold=341600,rewardXP=11765,rewardItems={249686},rewardCurrencies={{id=3310,amount=35},{id=3310,amount=52},{id=3379,amount=40},{id=3379,amount=50}},starts={{npcID=240835}},ends={{npcID=240835}},coords={x=0.424,y=0.466,source="quest_giver",zoneID=15968},questType="standard"},
[91979] = {id=91979,name="Chop It Down",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="We received word there's a creature from Lightbloom Ath'Ran making trouble on the western coast. It has caused a bit of drama. Head over and resolve the issue.",objectivesText="Kill the Rampaging Ent near Lightbloom Ath'Ran. Progress: Is the issue resolved?",rewardGold=341600,rewardXP=11765,rewardItems={242241},rewardCurrencies={{id=3310,amount=35},{id=3310,amount=52},{id=3379,amount=40},{id=3379,amount=50}},starts={{npcID=240835}},ends={{npcID=240835}},coords={x=0.424,y=0.466,source="quest_giver",zoneID=15968},questType="standard"},
[91980] = {id=91980,name="WANTED: Hellebora's Thorn",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15355,mapID=2413,description="See that huge creature over that way? That's Hellebora. She's set herself up too close to the road and we're concerned she's going to wander out of the mire and become even more of a threat. Deal with her, if you can, and bring me back one of her thorns as proof of your hunt.",rewardGold=683200,rewardXP=16055,rewardItems={249402},rewardCurrencies={{id=3310,amount=25},{id=3310,amount=37},{id=3316,amount=50},{id=3370,amount=250}},starts={{npcID=249361,x=0.518,y=0.742,zoneID=15355}},ends={{npcID=249361,x=0.518,y=0.742,zoneID=15355}},coords={x=0.518,y=0.742,source="quest_giver",zoneID=15355},questType="world",worldTaskTitle="WANTED: Hellebora's Thorn",db2QuestInfoID=1,db2QuestInfoName="Group"},
[91981] = {id=91981,name="To Poison and to Heal",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=15355,mapID=2413,rewardXP=13690,rewardItems={269022,269023},questType="world",worldTaskTitle="To Poison and to Heal",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[91982] = {id=91982,name="WANTED: Toadshade's Petals",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15355,mapID=2413,description="The three-headed hydra, Hellabora, has been causing havoc in the lower end of Gloom Mire. Give her a good pruning and bring me back her petals as proof.",rewardGold=683200,rewardXP=16055,rewardItems={249403},rewardCurrencies={{id=3310,amount=25},{id=3310,amount=37},{id=3316,amount=50},{id=3370,amount=250}},starts={{npcID=249361,x=0.518,y=0.742,zoneID=15355}},ends={{npcID=249361,x=0.518,y=0.742,zoneID=15355}},coords={x=0.518,y=0.742,source="quest_giver",zoneID=15355},questType="world",worldTaskTitle="WANTED: Toadshade's Petals",db2QuestInfoID=1,db2QuestInfoName="Group"},
[91983] = {id=91983,name="Lovely Plumage",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="The beautiful members of the Silvermoon Court do so love their colorful embellishments. For this, we can stock up while doing a good deed! Head over to Thuron's Livery and pick up some of the brightly colored feathers shed from the hawkstriders in training. Vaelith gets clean up service and we get the lovely plumage.",objectivesText="Collect 8 Bright Feathers . Progress: Did you find loads of feathers?",rewardGold=341600,rewardXP=11765,rewardItems={249439,249440},rewardCurrencies={{id=3310,amount=35},{id=3310,amount=52},{id=3379,amount=40},{id=3379,amount=50}},starts={{npcID=240836}},ends={{npcID=240836}},coords={x=0.428,y=0.464,source="quest_giver",zoneID=15968},questType="standard"},
[91984] = {id=91984,name="Sungrub Silk",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="Oh, $p, have you ever visited the Solaarian Sunbath? If not, it's highly recommended. The sungrubs that wander nearby have a precious silk from which amazing fabric can be made. Solwin Brightstitch is reputed to be masterful in this, with his sartorial magic. The raw materials are often sought out to have him create unique and personalized goods from scratch. Bring us some of that lovely silk. It will provide a soft cushion when faced with harder discussions.",objectivesText="Gather 1 Sunsilk . Progress: Oh, did you get all of the silk?",rewardGold=341600,rewardXP=11765,rewardItems={249422},rewardCurrencies={{id=3310,amount=35},{id=3310,amount=52},{id=3379,amount=50},{id=3379,amount=60}},starts={{npcID=240836}},ends={{npcID=240836}},coords={x=0.428,y=0.464,source="quest_giver",zoneID=15968},questType="standard"},
[91985] = {id=91985,name="Windrunner Memorabilia",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="The nobles do so love the unusual. Take a look around Windrunner Village. There are sure to be some interesting mementos still tucked away there. I will find an advantageous home for the pieces you bring back.",objectivesText="Collect 5 Windrunner Memorabilia. Progress: Did you find anything interesting?",rewardGold=341600,rewardXP=11765,rewardItems={249527,249531,249540,249542,249543,249552,249553,249554},rewardCurrencies={{id=3310,amount=35},{id=3310,amount=52},{id=3379,amount=50},{id=3379,amount=60}},starts={{npcID=240836}},ends={{npcID=240836}},coords={x=0.428,y=0.464,source="quest_giver",zoneID=15968},questType="standard"},
[91986] = {id=91986,name="Put a Little Snap in Their Step",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="Those naga are, as ever, being a beachfront nuisance. Do they not understand that is a prime location? We may not be able to reliably drive them off, but a little mischief would not be untoward. I found this tune that drives the snapdragons mad. They will just attack whoever is nearby. Take this and give it a shot!",objectivesText="Drive 8 Daggerspine Snapdragons mad with a tune. Progress: Are the naga adequately harassed?",rewardGold=341600,rewardXP=11765,rewardItems={249779},rewardCurrencies={{id=3310,amount=35},{id=3310,amount=52},{id=3379,amount=40},{id=3379,amount=50}},starts={{npcID=240836}},ends={{npcID=240836}},coords={x=0.428,y=0.464,source="quest_giver",zoneID=15968},questType="standard"},
[91987] = {id=91987,name="Potted Lashers",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="It seems some of the nobles are botany-curious where the Lightbloom is concerned. They seek the exotic to adorn their windowsills and lurk in the dangerous section of their greenhouses. That's where you come in, $p! Go harvest those small and pernicious plants. Their bulbs will be the best for planting.",objectivesText="Collect 8 Lightblooming Bulbs . Progress: Any problems with the harvest?",rewardGold=341600,rewardXP=11765,rewardItems={249418},rewardCurrencies={{id=3310,amount=35},{id=3310,amount=52},{id=3379,amount=40},{id=3379,amount=50}},starts={{npcID=240836}},ends={{npcID=240836}},coords={x=0.428,y=0.464,source="quest_giver",zoneID=15968},questType="standard"},
[91988] = {id=91988,name="Brightwing Conservation",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="The conservators at Brightwing Estate have a mischievous young dragonhawk named Cerul that likes to run away whenever their backs are turned. He doesn't go far, but it has become a game for him to get them to chase him. Take this delicious treat with you and use it to lure him back home.",objectivesText="Lure Cerul back to his home in Brightwing Estate.",rewardGold=341600,rewardXP=11765,rewardItems={249775},rewardCurrencies={{id=3310,amount=35},{id=3310,amount=52},{id=3379,amount=40},{id=3379,amount=50}},starts={{npcID=240836}},ends={{npcID=240836}},coords={x=0.428,y=0.464,source="quest_giver",zoneID=15968},questType="standard"},
[91989] = {id=91989,name="Ghostland Peppers",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="The delicate blue ghostland peppers may not look like much, but they have a mean burn. Many nobles won't admit it, but they are quite popular in the noble games of \"Truth or Challenge.\" Please procure a few for me. I like to watch them sweat.",objectivesText="Collect 12 Ghostland Peppers . Progress: How goes the harvest?",rewardGold=341600,rewardXP=11765,rewardItems={249497},rewardCurrencies={{id=3310,amount=35},{id=3310,amount=52},{id=3379,amount=40},{id=3379,amount=50}},starts={{npcID=240836}},ends={{npcID=240836}},coords={x=0.428,y=0.464,source="quest_giver",zoneID=15968},questType="standard"},
[91990] = {id=91990,name="Sunset to Sea",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="Naga have set up camp on the Sunset Strand. The sunset slugs that called it home are distraught and seem unsure what to do. This little tune will remind them of their home. Go inspire them to seek the freedom of the open sea.",objectivesText="Send 7 Sunset Slugs back to the sea.",rewardGold=341600,rewardXP=11765,rewardItems={267040},rewardCurrencies={{id=3310,amount=35},{id=3310,amount=52},{id=3379,amount=50},{id=3379,amount=60}},starts={{npcID=240836}},ends={{npcID=240836}},coords={x=0.428,y=0.464,source="quest_giver",zoneID=15968},questType="standard"},
[91991] = {id=91991,name="A Little Errand",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="When conversations get tense, it can be challenging to keep words flowing in a productive way. At times like these, I find a little social lubrication is in order. Swing over to Goldenmist Village and pick up a cask of Vintner's Golden . It's proven to have a euphoric side effect that can be quite helpful.",objectivesText="Collect a Cask of Vintner's Golden . Progress: Did you find the cask?",rewardGold=341600,rewardXP=11765,rewardItems={249732},rewardCurrencies={{id=3310,amount=35},{id=3310,amount=52},{id=3379,amount=40},{id=3379,amount=50}},starts={{npcID=240836}},ends={{npcID=240836}},coords={x=0.428,y=0.464,source="quest_giver",zoneID=15968},questType="standard"},
[91992] = {id=91992,name="Where Has the Wine Gone?",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="I entrusted one of my apprentices with the delivery of several cases of particularly expensive wine. He was to bring them here from my private storage, but he has not yet arrived. I should hate to ask you to retrieve him, but I cannot stress enough how expensive those bottles are. Please see if you can locate him and my delivery. He should have been traveling from the north to arrive here.",objectivesText="Locate the Magister's lost apprentice in Eversong Woods and figure out what happened to the wine shipment. Progress: I dearly hope my apprentice has a colorful excuse for his tardiness.",rewardGold=341600,rewardXP=11765,rewardItems={249421},rewardCurrencies={{id=3310,amount=35},{id=3310,amount=52},{id=3379,amount=40},{id=3379,amount=50}},starts={{npcID=240834}},ends={{npcID=240834}},coords={x=0.426,y=0.462,source="quest_giver",zoneID=15968},questType="standard"},
[91993] = {id=91993,name="Diminutive Demand",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="Keeping preciously small animals as pets is a popular pastime among the nobility. The more unconventional the animal, often obtained through magic, the more of a conversation piece it is. I have enchanted this wand with the appropriate shrinking spell. Use it on some of the colorful toads out near the ponds and bring them back here. The nobles will find them delightful. Naturally, the toads may not take kindly to the enchantment. But I trust you can handle that, should it occur.",objectivesText="Using the Wand of Diminutive Proportions , shrink and capture 4 Gloombelly Toads near Stillwhisper Pond. Progress: Fear not. The enchantment is quite permanent.",rewardGold=341600,rewardXP=11765,rewardItems={249437},rewardCurrencies={{id=3310,amount=35},{id=3310,amount=52},{id=3379,amount=40},{id=3379,amount=50}},starts={{npcID=240834}},ends={{npcID=240834}},coords={x=0.426,y=0.462,source="quest_giver",zoneID=15968},questType="standard"},
[91994] = {id=91994,name="Pyrepetal Purposes",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="Lord Saltheril, that old lynx, has put me in a bit of a bind. He has requested a grand fireworks display to accompany tonight's dinner service, but we are dreadfully low on pyrepetal dust. It is an herb native to Eversong, highly flammable and quite dazzling when set aflame by pyromancy. Could you help us replenish our stores? We mostly harvest it from the woods near Scintilas Falls.",objectivesText="Gather 5 Eversong Pyrepetals near Scintilas Falls. Progress: Do be careful to keep the pyrepetals away from open flame.",rewardGold=341600,rewardXP=11765,rewardItems={249444},rewardCurrencies={{id=3310,amount=35},{id=3310,amount=52},{id=3379,amount=50},{id=3379,amount=60}},starts={{npcID=240834}},ends={{npcID=240834}},coords={x=0.426,y=0.462,source="quest_giver",zoneID=15968},questType="standard"},
[91995] = {id=91995,name="What Horrible Magic",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="Have you seen the encampments the naga have been constructing along our coast? Dreadful business. Not only do they menace our ships and disrupt our trade routes, but they might pose a real threat to Eversong's inland settlements if allowed to continue operations unchecked. Their arcanists are particularly dangerous. Dispose of them and our guests will be in your debt.",objectivesText="Slay 4 Daggerspine Infusers near Daggerspine Point. Progress: I trust this task is within your skill set.",rewardGold=341600,rewardXP=11765,rewardItems={242241},rewardCurrencies={{id=3310,amount=35},{id=3310,amount=52},{id=3379,amount=40},{id=3379,amount=50}},starts={{npcID=240834}},ends={{npcID=240834}},coords={x=0.426,y=0.462,source="quest_giver",zoneID=15968},questType="standard"},
[91996] = {id=91996,name="Fit for a Magister",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="Battle prowess and magical skill are important, of course, but one cannot deny the power of appearances. A well-dressed army instills far more faith than one bedecked in rags. Fortunately, a fine set of robes can be both flattering and functional. The mana silk produced at the North Sanctum can be woven into robes that deepen and intensify our magical reserves. Be a dear and gather some for us, would you? My wardrobe could use a seasonal refreshment.",objectivesText="Gather 5 Iridescent Mana Silk and weave it into a Bolt of Mana Silk Cloth at the North Sanctum. Progress: Do be careful around the mana wyrms. I understand they can be aggressive after harvesting.",rewardGold=341600,rewardXP=11765,rewardItems={249445},rewardCurrencies={{id=3310,amount=35},{id=3310,amount=52},{id=3379,amount=40},{id=3379,amount=50}},starts={{npcID=240834}},ends={{npcID=240834}},coords={x=0.426,y=0.462,source="quest_giver",zoneID=15968},questType="standard"},
[91997] = {id=91997,name="Power Clean",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="The festivities have been wonderfully entertaining, which means the nobles have been leaving a bit of a mess around the estate. Lord Saltheril's servants have been keeping up with the cleaning, but the Magisters could lend a hand. Enchanting a few brooms to sweep the pavilion should be an easy but impressive feat. I was informed that an arcanist was employing the same tactic over at Farstrider Hold. Go retrieve some of his brooms and I will have them re-enchanted here.",objectivesText="Forcefully deactivate and collect 5 Inanimate Brooms at Farstrider Hold. Progress: Technically any broom would do, but the magic is easier to weave if the object has already been primed to receive the enchantment.",rewardGold=331700,rewardXP=11765,rewardItems={249452},rewardCurrencies={{id=3310,amount=35},{id=3310,amount=52},{id=3379,amount=40},{id=3379,amount=50}},starts={{npcID=240834}},ends={{npcID=240834}},coords={x=0.426,y=0.462,source="quest_giver",zoneID=15968},questType="standard"},
[91998] = {id=91998,name="WANTED: Muckmire's Choking Vines",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Deep within the swamp is a creature of mud, leaves, and rage. His vines choke the life out of any who come near, and this dangerous creature cannot be allowed to live. Defeat Muckmire and bring me back his vines as proof of the deed.",rewardGold=683200,rewardXP=16055,rewardItems={249404},rewardCurrencies={{id=3310,amount=25},{id=3310,amount=37},{id=3316,amount=50},{id=3370,amount=250}},starts={{npcID=249361,x=0.518,y=0.742,zoneID=15355}},ends={{npcID=249361,x=0.518,y=0.742,zoneID=15355}},coords={x=0.518,y=0.742,source="quest_giver",zoneID=15355},questType="world",worldTaskTitle="WANTED: Muckmire's Choking Vines",db2QuestInfoID=1,db2QuestInfoName="Group"},
[91999] = {id=91999,name="A Bit of Bloodthistle",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="You know, I bring Saltheril a lot of \"imported\" wine, but one of the first things I started supplying him with was bloodthistle. It's an herb that only grows around Eversong. It's got a smooth bite to it, sort of like mana. Nice and classy. His parties really go through the stuff. I took a look and I don't think he has enough to last this whole thing. We should get some more. The best stuff grows over by the West Sanctum. Grab as much as you can carry. Trust me--it'll go fast.",objectivesText="Gather 5 Fragrant Bloodthistle near the West Sanctum. Progress: Trust me. I know how to keep nobles happy.",rewardGold=341600,rewardXP=11765,rewardItems={249472},rewardCurrencies={{id=3310,amount=35},{id=3310,amount=52},{id=3379,amount=40},{id=3379,amount=50}},starts={{npcID=240837}},ends={{npcID=240837}},coords={x=0.428,y=0.456,source="quest_giver",zoneID=15968},questType="standard"},
[92000] = {id=92000,name="Bring the Ruckus",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="This place is pretty fun so far, despite all the dry political talk. I know Saltheril is trying to get the nobles to buy up war bonds, but we could really use some more energy in here. If the nobles are all asleep, no one's buying anything. Tell you what. Go invite some of my friends. They hang out under the bridge right outside of Silvermoon's gates. If anyone can bring some energy to the soiree, it's us.",objectivesText="Pass along Vyrin's invitation to 6 of his \"trader\" friends near the Path of Dawn.",rewardGold=309800,rewardXP=11765,rewardItems={242241},rewardCurrencies={{id=3310,amount=35},{id=3310,amount=52},{id=3379,amount=40},{id=3379,amount=50}},starts={{npcID=240837}},ends={{npcID=240837}},coords={x=0.428,y=0.456,source="quest_giver",zoneID=15968},questType="standard"},
[92001] = {id=92001,name="One Smuggler to Another",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="The whole point of this deal is showing the nobles what we bring to the table, both for Silvermoon and for them personally. These other groups bring strength, power, and really nice armor. What we bring is resources: getting the sin'dorei what they need, when they need it, with no questions asked. I heard some folks over at Sunsail Anchorage have been trying out the same business, but they're putting gold in the wrong pockets. Swipe their stock and bring it here.",objectivesText="Collect 5 Smuggled Goods around Sunsail Anchorage. Progress: I don't mind competitors, but I don't like the deals those smugglers are making.",rewardGold=341600,rewardXP=11765,rewardItems={249517},rewardCurrencies={{id=3310,amount=35},{id=3310,amount=52},{id=3379,amount=50},{id=3379,amount=60}},starts={{npcID=240837}},ends={{npcID=240837}},coords={x=0.428,y=0.456,source="quest_giver",zoneID=15968},questType="standard"},
[92002] = {id=92002,name="Dangerous Showpieces",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="You'd be surprised at the money you can make off of weapons. No, not the kind you're meant to use--the kind you stick up on the wall and have conversations about. Usually those weapons are expensive, or dangerous, or otherwise hard to get your hands on. The more rare and exclusive, the better. The weapons those Twilight cultists are carrying around should sell pretty well, especially to buyers with edgier tastes. If you happen to come across any, I'll gladly take them off your hands.",objectivesText="Collect 6 pieces of Twilight Weaponry from cultists at the Sanctum of the Moon. Progress: If it has some blood on it, that's actually better.",rewardGold=341600,rewardXP=11765,rewardItems={249528},rewardCurrencies={{id=3310,amount=35},{id=3310,amount=52},{id=3379,amount=40},{id=3379,amount=50}},starts={{npcID=240837}},ends={{npcID=240837}},coords={x=0.428,y=0.456,source="quest_giver",zoneID=15968},questType="standard"},
[92003] = {id=92003,name="Artisanal Replicas",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="Don't let the austere demeanor fool you. Nobles are just as susceptible to flashy party favors as the rest of us. I had my people bring over a batch of Felo'melorn replicas . They look great on display, and even better--they're enchanted. Swing them around and they leave a trail of fire. I haven't sold an enchanted batch before, so I'd like to do some testing before I hand them out. Saltheril wouldn't be too happy if I burned a guest to a crisp. Wanna take one of the replicas for a test run?",objectivesText="Test the fiery capabilities of the Felo'melorn Replica on 5 creatures near Lightbloom Ath'Ran.",rewardGold=309800,rewardXP=11765,rewardItems={249688},rewardCurrencies={{id=3310,amount=35},{id=3310,amount=52},{id=3379,amount=50},{id=3379,amount=60}},starts={{npcID=240837}},ends={{npcID=240837}},coords={x=0.428,y=0.456,source="quest_giver",zoneID=15968},questType="standard"},
[92004] = {id=92004,name="Shady Dealings",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="I feel like I just got here and I'm already fresh out of half the poisons I brought. What? Don't look at me like that. Nobles are some of my top customers for poisons. Quieter than magic and cleaner than blades. I need to restock. The frogs way down in the south produce a poisonous slime that I can bottle without much fuss. Bring some of it to me and I'll get you a cut of the earnings.",objectivesText="Collect 6 Poisonous Frog Secretions from frogs near the Amani Pass. Progress: Were you able to find any of those frogs?",rewardGold=341600,rewardXP=11765,rewardItems={249687},rewardCurrencies={{id=3310,amount=35},{id=3310,amount=52},{id=3379,amount=50},{id=3379,amount=60}},starts={{npcID=240837}},ends={{npcID=240837}},coords={x=0.428,y=0.456,source="quest_giver",zoneID=15968},questType="standard"},
[92005] = {id=92005,name="Throw the Dice",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="We've been making friends with some of the guests by teaching them how to play dice. It's a nice way to draw people out of the crowd and get them in a quieter space where you can talk privately. I wasn't expecting so much interest, to be honest. We're running out of dice sets. I can carve some more, but I'll need materials. Usually teeth or bone are good picks. Actually, the fangs from those naga along the coast would be perfect. Now that's a conversation starter!",objectivesText="Collect 12 Naga Fangs from naga near the Sunset Strand. Progress: Any luck finding some of those fangs?",rewardGold=341600,rewardXP=11765,rewardItems={249541},rewardCurrencies={{id=3310,amount=35},{id=3310,amount=52},{id=3379,amount=40},{id=3379,amount=50}},starts={{npcID=240837}},ends={{npcID=240837}},coords={x=0.428,y=0.456,source="quest_giver",zoneID=15968},questType="standard"},
[92006] = {id=92006,name="We Need a Refill",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="I talked to some of the servants earlier and it sounds like the casks are running low. That's a recipe for disaster at an event like this. Fortunately, I've got a lot of contacts across Eversong who can help us restock. I need to stay here and play politics, but could you head over to Tranquillien and grab a few bottles? I'll give you a list.",objectivesText="Purchase a case of Bloodthistle Brandy , Mana Burner , and Sun-Kissed Tranquilla from vendors in Tranquillien. Progress: Trust me. Everything on that list is fantastic.",rewardGold=341600,rewardXP=11765,rewardItems={249555,249556,249557},rewardCurrencies={{id=3379,amount=40},{id=3379,amount=50},{id=3396,amount=100}},starts={{npcID=240837}},ends={{npcID=240837}},coords={x=0.428,y=0.456,source="quest_giver",zoneID=15968},questType="standard"},
[92007] = {id=92007,name="Begged, Borrowed, or Stolen",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="The oldest trick in the book is to create a problem on purpose, solve it yourself, and look like the hero. One of the nobles just got word that some prized valuable was stolen from their estate while they were occupied here. It just so happens I might have put one of their servants up to it. Go talk to a man named Seridis over at the livery. He'll hand over the valuable to you, then you'll come back here and pretend you valiantly subdued the thief and retrieved the item. Everyone's happy.",objectivesText="Speak to Seridis at Thuron's Livery, then retrieve the stolen item. Progress: Making friends with the servants in noble households opens up a lot of doors. Sometimes literally.",rewardGold=309800,rewardXP=11765,rewardItems={249544},rewardCurrencies={{id=3310,amount=35},{id=3379,amount=40},{id=3379,amount=50},{id=3379,amount=60}},starts={{npcID=240837}},ends={{npcID=240837}},coords={x=0.428,y=0.456,source="quest_giver",zoneID=15968},questType="standard"},
[92010] = {id=92010,name="WANTED: Slewstalk's Stalks",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Not far from here, Slewstalk lurks in the shallows. This creature has developed a taste for flesh and bones, and it won't be long until she wanders out of the Mire in search for warmer blooded prey. Take her out and bring me her luminescent stalks . They'll serve as proof and also make a fine centerpiece for an evening table.",objectivesText="Collect luminecent stalks from Slewstalk. Progress: Try to take Slewstalk down before she can get those long grippers of hers around you.",rewardGold=683200,rewardXP=16055,rewardItems={249405},rewardCurrencies={{id=3310,amount=25},{id=3310,amount=37},{id=3316,amount=50},{id=3370,amount=250}},starts={{npcID=249361}},ends={{npcID=249361}},coords={x=0.518,y=0.742,source="quest_giver",zoneID=15355},questType="group"},
[92012] = {id=92012,name="WANTED: Gorebarb's Pincers",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Gorebarb is a creature quite unlike most others who make Harandar their home. He's incredibly violent and his kind is not seen here very often. Let's see less of him. Kill him and bring me his pincers as proof of the deed.",rewardGold=683200,rewardXP=16055,rewardItems={249406},rewardCurrencies={{id=3310,amount=25},{id=3310,amount=37},{id=3316,amount=50},{id=3370,amount=250}},starts={{npcID=249361,x=0.518,y=0.742,zoneID=15355}},ends={{npcID=249361,x=0.518,y=0.742,zoneID=15355}},coords={x=0.518,y=0.742,source="quest_giver",zoneID=15355},questType="world",worldTaskTitle="WANTED: Gorebarb's Pincers",db2QuestInfoID=1,db2QuestInfoName="Group"},
[92013] = {id=92013,name="WANTED: Dionaea's Thorntusks",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Many thornmaws make the mire their home, but none as are vicious as Dionaea. Unlike the others, she kills merely for the joy of it, and her gluttony threatens the delicate balance of the wildlife in this area. Take her out and restore the equilibrium. Bring me back her thorntusks as proof of the deed.",rewardGold=683200,rewardXP=16055,rewardItems={249408},rewardCurrencies={{id=3310,amount=25},{id=3310,amount=37},{id=3316,amount=50},{id=3370,amount=250}},starts={{npcID=249361,x=0.518,y=0.742,zoneID=15355}},ends={{npcID=249361,x=0.518,y=0.742,zoneID=15355}},coords={x=0.518,y=0.742,source="quest_giver",zoneID=15355},questType="world",worldTaskTitle="WANTED: Dionaea's Thorntusks",db2QuestInfoID=1,db2QuestInfoName="Group"},
[92021] = {id=92021,name="Graveblossom Gardening",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="My colleague Amalthea has taken ill. She requires a specialized poultice of sorts in order to ease the symptoms. I would forage for the plants myself, but the local fauna have grown so testy as of late! While you are out and about, could you gather some graveblossoms for me? I'd happily make it worth your while.",objectivesText="Gather 8 Pristine Graveblossoms for Talandra Dawnsprite at Windrunner Village. Progress: Oh, come now. While we stand here and chat about the weather, my associate continues to suffer under the travails of her malady! Get on with it. It's gloomy, by the way. The weather. As usual.",rewardGold=341600,rewardXP=11765,rewardItems={249471},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=249337}},ends={{npcID=249337}},coords={x=0.374,y=0.724,source="quest_giver",zoneID=15968},questType="standard"},
[92022] = {id=92022,name="A Venomous Vocation",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="My poultice requires venom samples from the local giant bat populations. Please retrieve some of those, as well. Six common vials' worth should do. Don't give me that look. They're bats. There are mad Light-plant-things to the east and a storm of voidwalkers swirling over our heads. Don't you dare give me guff about the dangers of big, fluffy bats. Now shoo. My colleague is depending on your prompt and efficient aid.",objectivesText="Collect six vials of Potent Mournbat Venom from mournbats outside of Windrunner Village. Progress: Strictly speaking, a stronger venom would have a more ample effect. But we're living in strenuous times. This Void hooplah has my usual supply lines at Sunsail completely occupied. We'll have to make do with mournbat venom. Now go.",rewardGold=341600,rewardXP=11765,rewardItems={253869},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=249337}},ends={{npcID=249337}},coords={x=0.374,y=0.724,source="quest_giver",zoneID=15968},questType="standard"},
[92023] = {id=92023,name="Suspicious Sundries",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="Forgive me for my failure to provide specifics, traveler. The mournbat venom and the graveblossoms were only the first of the reagents I require for my associate's medication. Luckily, the final few things I require can all be easily obtained in Goldenmist Village to the north. Be a dear and fetch these last few things for me, won't you? With these, my toil will be nearly complete.",objectivesText="Fetch a Vial of Quicksilver , a Flask of Dragon's Blood , and a Bottle of Magister's Reserve from the vendors at Goldenmist Village. Progress: Eugh. Why do I smell grave soil on you?",rewardGold=341600,rewardXP=11765,rewardItems={254280,254281,254282},rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=249337}},ends={{npcID=249426}},coords={x=0.374,y=0.724,source="quest_giver",zoneID=15968},questType="standard"},
[92024] = {id=92024,name="House Call",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="That woman, that \"apothecary,\" has snared you in one of her schemes. I'd be careful around her, . Rumors travel like wildfire in Eversong. And while I would never disparage a fellow artisan of Eversong without cause, I have heard enough rumors to know that your apothecary deals in more than simple herbs. Take your wine and your reagents, I suppose. But before you pass them off to your patroness, I'd recommend doing some digging--lest you find yourself wrapped up in something you come to regret.",objectivesText="Investigate Talandra's home in Windrunner Village.",rewardGold=341600,rewardXP=11765,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=249426}},ends={{npcID=249426}},coords={x=0.406,y=0.6,source="quest_giver",zoneID=15968},questType="standard"},
[92025] = {id=92025,name="Flowers for Amalthea",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="Talandra Dawnsprite intends to do, she means to do it amidst the ghosts of Windrunner Spire. The time for Talandra's ritual grows nigh.>",objectivesText="Confront Talandra Dawnsprite at Windrunner Spire. Progress: <Time is of the essence. Talandra's ritual approaches.>",rewardGold=341600,rewardXP=11765,rewardItems={257418},rewardCurrencies={{id=3316,amount=25},{id=3365,amount=250}},starts={{npcID=253058}},ends={{npcID=249337}},questType="standard"},
[92034] = {id=92034,name="Thorm'belan",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=15355,mapID=2413,rewardXP=13690,questType="world",worldTaskTitle="Thorm'belan",db2QuestInfoID=289,db2QuestInfoName="World Boss"},
[92061] = {id=92061,name="Rising Storm",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16340,mapID=2393,description="That was an entropic wave. We felt them just before Xal'atath launched her assault on the Sunwell. Champion, you move faster than my best messengers. I need you to check in with the Vanguard commanders and see if their defenses will hold against this latest assault by Xal'atath's Devouring Host.",objectivesText="De-escalate rising tensions in Silvermoon City . Progress: Tensions are high.",rewardGold=341600,rewardXP=11765,starts={{npcID=235787}},ends={{npcID=235787}},coords={x=0.454,y=0.704,source="quest_giver",zoneID=15969},questType="standard"},
[92062] = {id=92062,name="Tending the Roots",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=15355,mapID=2413,rewardXP=13690,questType="world",db2Objectives={{orderIndex=0,type=0,amount=6,objectID=251084,text="Withered Plant removed"},{orderIndex=1,type=2,amount=8,objectID=573141,text="Invasive Fungi removed"}},worldTaskTitle="Tending the Roots",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
