[92084] = {id=92084,name="Halazzi's Guile",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Who are these people? Where did they come from? Did dey find their way here from Numazon? How? De mist keeps you from knowin' if you are comin' or goin'. And where is Halazzi? I need answers... now!",objectivesText="Speak to Loa Speaker Tobui to discover how the Witherbark were rescued. Progress: My vision is clearing, and so is my mind.",rewardGold=319000,rewardXP=12170,rewardCurrencies={{id=3316,amount=20},{id=3354,amount=100}},starts={{npcID=236155}},ends={{npcID=236155}},coords={x=0.324,y=0.316,source="quest_giver",zoneID=15947},questType="standard"},
