[92104] = {id=92104,name="Broomstick Express",level=1,requiredLevel=1,faction="none",expansion=11,description="Hmm. You look like you can ride a broom without crashin' into a chimney. Hallow's End is a busy time for all kinds of deliveries. Got sweets, potions, pumpkins, haunted socks - don't ask - all goin' to the usual oddballs. Take that broom over there, fly fast to make those deliveries, and don't drop nothin'.",objectivesText="Deliver the package to the designated location.",questType="standard",worldTaskTitle="Broomstick Express"},
[92105] = {id=92105,name="Papers, Please!",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=15969,mapID=2393,rewardXP=13690,questType="world",db2Objectives={{orderIndex=0,type=3,amount=1,objectID=249681,text="Ride the Cataloger's Carpet"},{orderIndex=1,type=15,amount=1,objectID=0,text="Take Pictures of Visitors"},{orderIndex=2,type=0,amount=50,objectID=249677,text="Common"},{orderIndex=3,type=0,amount=25,objectID=249678,text="Rare"},{orderIndex=4,type=0,amount=12,objectID=249679,text="Epic"},{orderIndex=5,type=0,amount=6,objectID=249680,text="Legendary"}},worldTaskTitle="Papers, Please!",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[92106] = {id=92106,name="Ignite the Skies: Northern Kalimdor",level=0,requiredLevel=0,faction="both",expansion=11,zoneID=440,mapID=71,description="Midsummer is the time to reflect and a time to tell stories by the bonfire. One such story is the tale of the sun blossom ritual and how this offering to An'she first came to be. Our journey will take us through Northern Kalimdor, into territories beyond the lands of the shu'halo. If you wish, take to the skies of Kalimdor and ignite the blossoms as I tell the tale. Our story begins in the Western Barrens...",rewardGold=303800,rewardItems={23247},starts={{npcID=250811},{npcID=265658}},ends={{npcID=251986}},coords={x=0.478,y=0.374,source="quest_giver",zoneID=1637},questType="standard"},
