[92136] = {id=92136,name="Infusion of Hope",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=16215,mapID=2424,description="I hope my staff's light has been enough to uphold those at the Sunwell while we have sought these relics. Together with those from Light's Hope, they should be a much more significant aid. Let us return there quickly.",rewardGold=170800,rewardXP=6085,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},ends={{npcID=251355,x=0.526,y=0.558,zoneID=16215}},questType="world",worldTaskTitle="Infusion of Hope"},
