[92576] = {id=92576,name="Dominating The Domanaar",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=15958,mapID=2444,rewardXP=11765,questType="world",db2Objectives={{orderIndex=0,type=2,amount=6,objectID=576478,text="Banners Placed"},{orderIndex=1,type=15,amount=1,objectID=0,text="Domanaar Forces Disrupted"},{orderIndex=4,type=0,amount=10,objectID=256087,text="Void Ward Destroyed"}},worldTaskTitle="Dominating The Domanaar",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
