[92583] = {id=92583,name="Fungicide",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=15355,mapID=2413,rewardXP=13690,questType="world",db2Objectives={{orderIndex=1,type=15,amount=1,objectID=0,text="Fight in the Grudge Pit"},{orderIndex=0,type=19,amount=0,objectID=39544,text="Run through the Entryway"}},worldTaskTitle="Fungicide",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[92600] = {id=92600,name="Cracked Keystone",level=80,requiredLevel=80,faction="none",expansion=11,description="Fragmentary images of heroic deeds flash though your mind as you touch the stone, but they fade as fast as they arrive. Perhaps performing a suitably impressive task will stabilize the stone's magic once more?",objectivesText="Complete any dungeon on Mythic 2 or higher difficulty.",rewardGold=1366400,rewardXP=23530,questType="standard"},
[92603] = {id=92603,name="O Lonely Star",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15958,mapID=2444,description="<The void elf writhes in a fitful sleep, tormented by the nearby shade. Perhaps you should try to wake him.>",objectivesText="Learn more about the shade tormenting Orin.",rewardGold=34100,rewardXP=1605,rewardCurrencies={{id=3316,amount=5},{id=3389,amount=10}},starts={{npcID=252510}},ends={{npcID=254012}},coords={x=0.398,y=0.842,source="quest_giver",zoneID=15958},questType="standard"},
[92604] = {id=92604,name="Speak in Blood",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15958,mapID=2444,description="After my failed creation, I sought wisdom from the Void, and it told me of this place. There was a voice--strange, yet familiar. It promised a tool for shaping Void and shadow--something that would free me from my failure, but the Void gives nothing freely. We must command it, and violence is this land's mother tongue. Slay the beasts here and bring me their ichor. We'll use it to write our demands.",objectivesText="Gather 50 Viscous Ichor from creatures in the Fangfall. Progress: Do you have it? The shade won't be silent. It wasn't meant to exist like this.",rewardGold=341600,rewardXP=12845,rewardItems={256692},rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=254012}},ends={{npcID=252510}},coords={x=0.394,y=0.38,source="quest_giver",zoneID=15958},questType="standard"},
[92605] = {id=92605,name="Honest as Bone",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15958,mapID=2444,description="If ichor is to be the carrier for our message, bone shall be its pigment. This is a place of scavengers, with bones stolen from across this land: old, new, all carrying the echoes of violence that brought their ends. Bring me bone splinters and I will powder them for our ink. Please hurry. This shade is a wrong thing, and I must put it right.",objectivesText="Gather 8 Bone Splinters from the Fangfall. Progress: These scavengers must have brought bones from all over Voidstorm .",rewardGold=341600,rewardXP=12845,rewardItems={256694},rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=254012}},ends={{npcID=252510}},coords={x=0.394,y=0.38,source="quest_giver",zoneID=15958},questType="standard"},
[92606] = {id=92606,name="Take Up Your Gift",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15958,mapID=2444,description="This place--this wound--is what the voice from the Void told me I'd find. There's something waiting inside... something to put an end to this broken creation. You can't hear it? It howls. Sometimes in rage. Other times it sounds so lonely that it breaks my heart. Ignore it. With the proper runes written in ichor and bone, I believe we can open this rift wider. Then you can seize what lies within.",objectivesText="Help Orin open the rift and uncover what lies within. Progress: The voice spoke true. There was something waiting here.",rewardGold=170800,rewardXP=6425,rewardItems={256549},rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=252510}},ends={{npcID=254014}},coords={x=0.398,y=0.842,source="quest_giver",zoneID=15958},questType="standard"},
[92607] = {id=92607,name="And Carve New Shapes",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15958,mapID=2444,description="This is what the voice from the Void promised me: the means to divest myself of this shade. You'll have to wield it. Don't worry--it won't harm me. It will separate me from the shade. Then it should simply fade away, no more than an unmoored shadow. Go on. I'm ready.",objectivesText="Separate Orin from his shade.",rewardGold=683200,rewardXP=16055,rewardItems={264308,264309,264310,264311},rewardCurrencies={{id=3316,amount=25},{id=3389,amount=250}},starts={{npcID=254014}},ends={{npcID=254105}},coords={x=0.33,y=0.364,source="quest_giver",zoneID=15958},questType="standard"},
[92608] = {id=92608,name="Landscape Photography",level=25,requiredLevel=25,faction="both",expansion=11,zoneID=16105,mapID=2351,description="I'm having just the best time in your lovely village, it's so quaint! I'm feeling inspired. I would like to paint a landscape picture to commemorate the occasion. But you know the area better than I. Could you provide me with some pictures of the landscape I can use for inspiration? You can use my camera. It's top of the line, of course. I'm sure the perfect spots will just beam at you.",objectivesText="Take enough photos of your neighborhood to inspire Corlen Hordralin . Progress: This place is such a delight, so laid back and rustic.",rewardGold=341600,rewardXP=3440,rewardItems={253316},rewardCurrencies={{id=3363,amount=3}},starts={{npcID=252717}},ends={{npcID=252717}},coords={x=0.538,y=0.556,source="quest_giver",zoneID=15524},questType="standard"},
[92616] = {id=92616,name="Mushrooming Courage",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Brakko sorry that Brakko let $p and TeamName down. Brakko is much scared of sporegliders. Could sneak up at Brakko above cap, where cannot see. Could really hurt cap! Very sorry, $p. Brakko doesn't think Brakko can be tank for team. Unless... $p practice sporegliders with Brakko ?",objectivesText="Help Brakko face his fear of sporegliders.",rewardGold=341600,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=247245}},ends={{npcID=251524}},coords={x=0.718,y=0.64,source="quest_giver",zoneID=15355},questType="standard"},
[92617] = {id=92617,name="Mushrooming Resilience",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="First Tuktuk runs, then Brakko runs. Cannot be the only one still fighting. Ziny will fail by Ziny 's self. Fight is too hard alone, will not be strong enough. Do not want to fail. Cannot let PH_Teamname down! Had choice, fail or run. But run was also fail. Ziny very sorry to $p! Can practice, fight big and scary enemies together?",objectivesText="Face 4 scary enemies with Ziny . Progress: Ziny will try to heal <name>.",rewardGold=341600,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=251723}},ends={{npcID=251723}},coords={x=0.718,y=0.64,source="quest_giver",zoneID=15355},questType="standard"},
[92618] = {id=92618,name="Mushrooming Confidence",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Tuktuk 's poison is not good enough. Tuktuk had to run, before we lose. Sorry if you lose! Tuktuk did not lose. Tuktuk quit. Quit is safe from lose. Grudge Pit very, rrr... is so intense. Tuktuk cannot handle. Tuktuk will stay out where is safe. Tuktuk will find place to relax. Away from Grudge Pit. Tuktuk cannot lose if stay far away.",objectivesText="Help Tuktuk face 3 difficult feelings.",rewardGold=341600,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=251715}},ends={{npcID=247252}},coords={x=0.718,y=0.64,source="quest_giver",zoneID=15355},questType="standard"},
[92630] = {id=92630,name="The Pursuit Continues",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=14771,mapID=2371,description="I bring word from Magister Umbric ! His apprentice, Leona, has been preoccupied with a desire to learn how the ways of the Illidari. She apparently found another demon hunter willing to train her, should she prove herself worthy. But after what happened the last time she sought such a mentor, Umbric is concerned for her safety. Umbric requests you join Leona for this trial. Make sure she is not getting involved in something she is not prepared to handle.",objectivesText="Find Leona and Allari in K'aresh .",rewardGold=154900,rewardXP=5885,starts={{npcID=248153},{npcID=257544},{npcID=259951}},ends={{npcID=254266}},coords={x=0.608,y=0.278,source="quest_giver",zoneID=15336},questType="standard"},
[92631] = {id=92631,name="Abhorrent Gauntlet",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15336,mapID=2371,description="Leona must demonstrate mastery of her weapons--and of her own enmity--by retrieving undamaged pieces of her kills. I will observe from here. You, , will go with her.",objectivesText="Harvest 24 undamaged parts from aberrations in the Tempest Fields. Progress: A demon hunter wields their ire, but is never ruled by it.",rewardGold=309800,rewardXP=11765,rewardItems={253387,257714,257715,258295,266128},starts={{npcID=252617}},ends={{npcID=252617}},coords={x=0.65,y=0.406,source="quest_giver",zoneID=15336},questType="standard"},
[92632] = {id=92632,name="Trial of Wrath",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15336,mapID=2371,description="Cutting through scores of lesser foes is a simple task for any demon hunter. It's when we face a large, singular threat that our skills are truly tested. That will be Leona's trial. You will act as her second. Let us see how she vanquishes a particularly dangerous opponent.",objectivesText="Kill Vraxik , the Dimensional Wanderer.",rewardGold=619600,rewardXP=14705,starts={{npcID=252617}},ends={{npcID=254748}},coords={x=0.65,y=0.406,source="quest_giver",zoneID=15336},questType="standard"},
[92635] = {id=92635,name="Midsummer's Journey to the Barrens",level=0,requiredLevel=0,faction="alliance",expansion=11,zoneID=17,mapID=10,description="Although we have our own traditions during this time, we are not the only ones who pay respects to the spirits of fire during the summer months. If you wish to hear the origins of the tauren traditions, travel to Kalimdor to continue your journey.",rewardGold=170800,rewardItems={23247},starts={{npcID=252784}},ends={{npcID=265658}},coords={x=0.538,y=0.692,source="quest_giver",mapID=10},questType="standard"},
[92636] = {id=92636,name="Predaxas",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=15458,mapID=2405,rewardXP=13690,questType="world",worldTaskTitle="Predaxas",db2QuestInfoID=289,db2QuestInfoName="World Boss"},
[92641] = {id=92641,name="Bloodying the Plain",level=88,requiredLevel=88,faction="none",expansion=11,zoneID=16648,mapID=2405,rewardGold=341600,rewardXP=12845,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Slay creatures in the Bloodplains"}},worldTaskTitle="Bloodying the Plain"},
[92650] = {id=92650,name="The Flickering Anima",level=1,requiredLevel=1,faction="both",expansion=11,zoneID=10565,mapID=1670,description="The strange anima shimmers with a gentle hum, barely larger than a candle. As your hand draws near it erupts, flooding your mind with a torrent of visions. Triumphs earned through blood, regrets etched in grief, serene stillness all too fleeting, the bitter taste of betrayal. The unbearable cascade threatens to shatter your mind like glass. Then, silence. The visions end leaving an image Oribos seared into your mind.",objectivesText="Bring the Flickering Anima to Ta'steld in Oribos. Requirements: - The Flickering Anima",rewardCurrencies={{currencyID=1166,quantity=1}},ends={{npcID=239840}},questType="standard"},
[92657] = {id=92657,name="The Brewing Storm",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,description="Our foothold in Stormarion is tenuous at best. We're barely holding the enemy off on one front. We certainly don't have the forces to assault the rest of the citadel. That's where you and I come in. Meet me in Stormarion Citadel when you're ready to get to work.",objectivesText="Meet Lysikas in the Stormarion Citadel.",rewardGold=30900,rewardXP=1370,rewardItems={246951},rewardCurrencies={{id=3316,amount=5},{id=3389,amount=10}},starts={{npcID=254510}},ends={{npcID=254509}},coords={x=0.36,y=0.598,source="quest_giver",zoneID=15458},questType="standard"},
[92658] = {id=92658,name="Tactical Acquisition",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,description="All our forces are focused on this courtyard, but I think we've got another problem. I've scouted between assaults: there's activity in the lower keep. Not to worry you, but there are signs of another singularity. Up for a little reconnaissance? We'll go through the trench. They've got an impressive operation for gathering Void energy. Might as well hit that on the way. After all, our defenses here can't power themselves. If I'm wrong, we can tell Maella we were proactively shoring up supply lines.",objectivesText="Steal Void Energy Reserves from the trench near Stormarion Citadel.",rewardGold=341600,rewardXP=13690,rewardItems={257727,257728,257870},rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=254509}},ends={{npcID=252947}},coords={x=0.264,y=0.684,source="quest_giver",zoneID=15458},questType="standard"},
[92659] = {id=92659,name="Resource Denial",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,description="I've got a hunch I need to follow in the lower keep, and that means going through the trench. I hate to miss targets of opportunity, and the Host's energy collecting operation is right there. How do you feel about wrecking their production capacity? The longer it takes them to recover, the easier it'll be to maintain the offensive up here. It's not complicated. If it looks useful to the enemy, smash it. After that, we'll move onto the main objective in the keep itself.",objectivesText="Destroy 6 Void Condensers in the trench north of Stormarion Citadel.",rewardGold=341600,rewardXP=13690,rewardItems={246951},rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=254509}},ends={{npcID=252947}},coords={x=0.264,y=0.684,source="quest_giver",zoneID=15458},questType="standard"},
[92660] = {id=92660,name="Null Implements",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,description="Yes, there may be another unstable singularity. No, I didn't tell anyone. We don't have enough forces to divert our attention--that's why I asked you to accompany me. Besides, we've only got the one Singularity Anchor. Don't worry though, I've got a plan. These domanaar are experts on shaping the Void, so they must have some means of controlling singularities. Get in there and grab any tools that look important. We'll find a way to stabilize this singularity ourselves.",objectivesText="Collect domanaar tools in the Stormarion Keep. Progress: I'm sure a domanaar's tools will be able to stabilize a singularity.",rewardGold=341600,rewardXP=13690,rewardItems={257729,257730,257731},rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=252947}},ends={{npcID=252947},{npcID=254515}},coords={x=0.356,y=0.668,source="quest_giver",zoneID=15458},questType="standard"},
[92661] = {id=92661,name="Hammer Meet Anvil",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,description="I don't approve of Lysikas's disregard for duty, but I do trust his instincts. If he says there's something here we need to see, then he's probably right. Even if he's wrong, we shouldn't waste this opportunity. A domanaar weaponsmith and researcher does his work from here. With most of the Stormarion forces attacking our Singularity Anchor, he should be an easy target. Take him out.",objectivesText="Slay Telumnus and 8 Stormarion Keep forces.",rewardGold=683200,rewardXP=17110,rewardItems={246951},rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=252949}},ends={{npcID=254513}},coords={x=0.356,y=0.668,source="quest_giver",zoneID=15458},questType="standard"},
[92662] = {id=92662,name="Core Collapse",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,description="This singularity could reach critical mass at any moment. We've no time to evacuate. It will devour our forces in the upper citadel, maybe even the Ingress. Will you handle the tools? I've no idea how they work, but you've used more artifacts and seen more strange magic than most. Remember, the Void responds to will. Use the tools and command the singularity to stabilize. I trust you'll figure out the rest. The Host will try to stop us. Lay down some defenses, then I'll cover you while you work.",objectivesText="Avert the singularity collapse.",rewardGold=341600,rewardXP=13690,rewardItems={260590,264325,264326,264327,264328},rewardCurrencies={{id=3316,amount=25},{id=3389,amount=250}},starts={{npcID=254513}},ends={{npcID=254513}},coords={x=0.312,y=0.682,source="quest_giver",zoneID=15458},questType="standard"},
[92688] = {id=92688,name="Bronze Simulacrum",level=10,requiredLevel=10,faction="both",expansion=11,mapID=619,description="< Erus will be delighted to scrap this for you for a heaping sum of bronze .>",objectivesText="Give the Bronze Simulacrum to Erus at the Infinite Bazaar near Dalaran. Progress: You have something for Erus ?",ends={{npcID=241141}},coords={mapID=619,source="quest_giver",x=0.458,y=0.68},questType="standard"},
[92689] = {id=92689,name="A Path Forward",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description=", today will be a day of ceremonies and great magic. Before we begin to cleanse the Darkwell, agreements must be made. We have two events that have requested your presence, both as a mediator and as a witness. What we lay down today will have lasting ramifications, and it is important to all of us that we have you at the center of it all. Meet with Aethas and Rommath for their respective events. Once you are done, return here and we shall continue to the Darkwell together.",objectivesText="Assist Aethas Sunstrider and Grand Magister Rommath.",rewardGold=34100,rewardXP=1370,rewardCurrencies={{id=3316,amount=5},{id=3365,amount=10}},starts={{npcID=235787}},ends={{npcID=235787}},coords={x=0.454,y=0.704,source="quest_giver",zoneID=15969},questType="standard"},
[92694] = {id=92694,name="Dusk Among Pigments",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="As Zur'ashar, our oath is to safeguard the harmony within the visions and the histories we preserve. Yet Orn'shan 's crude strokes are reckless. Their creative impulses lack refinement, disturbing the balance we are sworn to protect. In a misguided attempt at creativity, they've created uncontrollable chaos and are distorting the very truths they sought to record. Perhaps they will heed the words of an outsider before their reputation collapses entirely.",objectivesText="Speak with Orn'shan in Amirdrassil Roots.",rewardGold=33500,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3370,amount=10}},starts={{npcID=252871}},ends={{npcID=252872}},coords={x=0.704,y=0.512,source="quest_giver",zoneID=15355},questType="standard"},
[92695] = {id=92695,name="The Stroke of Storms",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="I... I don't think I can mend this. The Zur'ashar were right. I am no true paintmaker. I cannot even capture history properly within my own memories... how could I ever hope to honor it in moments that matter? I thought I could create something beautiful... something worthy. I was foolish to try. Can you... can you help me clean this mess? I... I have no hope left to do it myself.",objectivesText="Use the visionstone to enter the painting and restore harmony. Progress: I fear I ruined everything. Have you been able to undo the destruction I brought upon this vision?",rewardGold=341600,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=252872}},ends={{npcID=252872}},coords={x=0.724,y=0.556,source="quest_giver",zoneID=15355},questType="standard"},
[92696] = {id=92696,name="Colors Born Anew",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Outsider... thank you. I'm still shaken... but I can feel a small spark returning. I'd nearly abandoned my work entirely, yet your kindness... it has steadied me. I think I finally see what I'm meant to create: something meaningful that honors the Zur'ashar tradition through my voice, but to begin, I need the raw essence of color itself. Will you help me collect the ingredients I need? I'd be looking for anything I can use to turn into paint.",objectivesText="Collect ingredients for Orn'shan from the Shrouded Grove. Progress: Have you collected the ingredients I need?",rewardGold=341600,rewardXP=12170,rewardItems={258571},rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=252872}},ends={{npcID=252872}},coords={x=0.724,y=0.556,source="quest_giver",zoneID=15355},questType="standard"},
[92697] = {id=92697,name="Hues of Tomorrow",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="I... never expected to feel this again. Your help has given me hope. These ingredients feel right, and maybe even enough. I want you to be the first to paint. Do not fret over perfection. Paint what you feel, and I'll capture its essence into the memory I preserve. I look forward to see what you create.",objectivesText="Paint Pictures for Orn'Shan in Amirdrassil Roots. Progress: Have you put paint to stone and watched your creativity flow?",rewardGold=167500,rewardXP=6085,rewardItems={260523,260524,260525,260526,260527,260528,260529,260530,269981},rewardChoices={260523,260524,260525,260526,260527,260528,260529,260530,269981},rewardCurrencies={{id=3316,amount=25},{id=3370,amount=250}},starts={{npcID=252872}},ends={{npcID=252872}},coords={x=0.724,y=0.556,source="quest_giver",zoneID=15355},questType="standard"},
[92711] = {id=92711,name="Ignite the Skies: Stormwind",level=0,requiredLevel=0,faction="alliance",expansion=11,zoneID=1519,mapID=84,description="Welcome to the Midsummer Festival of Fire, friend! Have you come to toss a few torches? Or maybe dance around the maypole? Ah, you must be here to ignite the blossom lights over the skies of Stormwind, aren't you? It is an old tradition, long forgotten but newly rekindled! Well, come on then. Take to the skies and fly!",rewardGold=315900,rewardItems={23247},starts={{npcID=252528}},ends={{npcID=252528}},coords={x=0.48,y=0.718,source="quest_giver",zoneID=1519},questType="standard"},
[92713] = {id=92713,name="Echoes Rekindled",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="The relics you restored still hum with the visions you once walked. Their stories yearn to be lived again, and each retelling leaves the world just a little richer than before. Return them to the shrines, let the memories flow, and I shall place in your hands a reward for one who walks the paths of legend.",objectivesText="Select a relic to experience once again.",starts={{npcID=238170}},ends={{npcID=238170}},coords={x=0.542,y=0.53,source="quest_giver",zoneID=15355},questType="standard"},
[92716] = {id=92716,name="The Story of Wey'nan's Ward",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="You have walked this path before, , yet the Vale of Secrets stirs anew. The Visionstone awaits, its sacred paintings familiar to your eyes, the handprint at its heart calling for you again. Press your hand upon it once more and let your spirit be known. The trance will take you as before, carrying your soul through visions whose truths still shift with every telling. Return to me with what new wisdom the echoes grant you.",objectivesText="Travel to the indicated shrine in Harandar to meditate and experience the history of Wey'nan's Ward. Progress: Tell me, <name>, what new truths did the past reveal this time?",rewardGold=683200,rewardXP=15215,rewardItems={263467,279525},rewardCurrencies={{id=3316,amount=100},{id=3370,amount=1000}},starts={{npcID=238170}},ends={{npcID=238170}},coords={x=0.542,y=0.53,source="quest_giver",zoneID=15355},questType="standard"},
[92719] = {id=92719,name="The Story of the Cauldron of Echoes",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Once more, the Cauldron of Echoes stirs. When I first walked the path of the Zur'Ashar, my master spoke of its place at our beginning. Even they could not grasp its full meaning. Now, it beckons again. Step into its quiet and draw forth what the ages have hidden. Bring me the truth as it speaks to you this time.",objectivesText="Travel to the Glade of Walking Memories in Harandar to learn the history of the Cauldron of Echoes.",rewardGold=683200,rewardXP=15215,rewardItems={263467,279525},rewardCurrencies={{id=3316,amount=100},{id=3370,amount=1000}},starts={{npcID=238170}},ends={{npcID=238170}},coords={x=0.542,y=0.53,source="quest_giver",zoneID=15355},questType="standard"},
[92720] = {id=92720,name="The Story of Aln'hara's Bloom",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="The bloom still waits, its stillness carrying the same quiet call you once followed. Yet the bloom's story deepens with each telling. Walk its path again, let the stillness speak anew, and see what more the goddess chooses to share.",objectivesText="Travel to Veilroot Clearing and uncover the truth behind Aln'hara's Bloom.",rewardGold=683200,rewardXP=15215,rewardItems={263467,269703,279525},rewardCurrencies={{id=3316,amount=100},{id=3370,amount=1000}},starts={{npcID=238170}},ends={{npcID=238170}},coords={x=0.542,y=0.53,source="quest_giver",zoneID=15355},questType="standard"},
[92721] = {id=92721,name="The Story of the Echoless Flame",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="The Echoless Flame rests as you left it, yet the air around it stirs once more. You have walked Obayo's path before, felt the echo of that first Shul'ka's purpose. But the past is a shifting thing, and the Flame's silence may yet hide verses you have not heard. Return to its vigil. Follow Obayo's steps again, and let the vision show you what remains untold.",objectivesText="Travel to the Verdant Sepulcher in Harandar to learn the history of the Echoless Flame. Progress: Tell me, <name>, what new light did the flame cast for you this time?",rewardGold=683200,rewardXP=15215,rewardItems={263467,279525},rewardCurrencies={{id=3316,amount=100},{id=3370,amount=1000}},starts={{npcID=238170}},ends={{npcID=238170}},coords={x=0.542,y=0.53,source="quest_giver",zoneID=15355},questType="standard"},
[92722] = {id=92722,name="The Story of Russula's Outreach",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="The spear still waits where you last left it, pale threads of mushroom slowly weaving new patterns into its grain. The culling grounds draw you again. Walk their softened paths, follow what spores still rise, and let the visions show what time has chosen to reveal this season.",objectivesText="Travel to the Verdant Sepulcher to learn the history of Russula's Outreach.",rewardGold=683200,rewardXP=15215,rewardItems={263467,279525},rewardCurrencies={{id=3316,amount=100},{id=3370,amount=1000}},starts={{npcID=238170}},ends={{npcID=238170}},coords={x=0.542,y=0.53,source="quest_giver",zoneID=15355},questType="standard"},
[92724] = {id=92724,name="The Story of the Root of the World",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="The Root of the World stands as it did before--ancient, unbowed--yet the soil breathes differently today. Beneath your feet, the pulse of Harandar quickens, as though eager to share another verse of its oldest story. You have seen through Ruilla the Huntress's eyes once before. But the Rootways are never walked the same way twice. Go again, and let the land decide which truths it will show you now.",objectivesText="Travel to the Vale of Secrets to learn the history of the Root of the World. Progress: And so the Root yielded another fragment? Tell me, what shade of truth did it whisper this time?",rewardGold=683200,rewardXP=15215,rewardItems={263467,269703,279525},rewardCurrencies={{id=3316,amount=100},{id=3370,amount=1000}},starts={{npcID=238170}},ends={{npcID=238170}},coords={x=0.542,y=0.53,source="quest_giver",zoneID=15355},questType="standard"},
[92725] = {id=92725,name="The Story of Sky's Hope",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Sky's Hope rests in its cradle as before, yet the heavens above seem sharper tonight. You have traced Awe'ohna's path once, but the tale shifts with every telling. Walk the path again, and perhaps the sky will tilt just so, revealing a truth you missed before.",objectivesText="Travel to the Shrouded Grove in Harandar to learn the history of Sky's Hope.",rewardGold=683200,rewardXP=15215,rewardItems={263467,279525},rewardCurrencies={{id=3316,amount=100},{id=3370,amount=1000}},starts={{npcID=238170}},ends={{npcID=238170}},coords={x=0.542,y=0.53,source="quest_giver",zoneID=15355},questType="standard"},
[92728] = {id=92728,name="Dogged Disturbances",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="That dog! It ran through here and disrupted every lesson on the schedule. Now there are fire elementals everywhere and my students are ill-prepared to handle this mess. How am I supposed to teach in all of this chaos? You look capable--would you clear out some of these rowdy little elementals? The sooner we get this situation under control, the better!",objectivesText="Kill 8 Rowdy Elementals in Thalassian University. Progress: Have you gotten those rowdy little sparks under control?",rewardGold=341600,rewardXP=11765,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=253015}},ends={{npcID=253015}},coords={x=0.354,y=0.578,source="quest_giver",zoneID=15969},questType="standard"},
[92729] = {id=92729,name="Hounded and Hassled",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Gilneas and Kul Tiras are both known for their hunting hounds. With the resurgence of elfhounds in Silvermoon, I thought perhaps they could be similarly utilized. They're dogs, after all. How hard could training possibly be? Long story short, that dog made a mess and dashed off. I have to clean this up. Would you please find that creature and bring him back to me before the local canine cafe has my head? I only borrowed him for the day!",objectivesText="Speak to Magistrix Zaedana in Thalassian University.",rewardGold=30900,rewardXP=1470,rewardCurrencies={{id=3316,amount=5},{id=3365,amount=10}},starts={{npcID=252500}},ends={{npcID=253015}},coords={x=0.358,y=0.69,source="quest_giver",zoneID=15969},questType="standard"},
[92731] = {id=92731,name="Artificing Aggression",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=16648,mapID=2405,rewardXP=11765,questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=248584,text="Speak with Decimus to begin"},{orderIndex=1,type=0,amount=1,objectID=208283,text="Blade forged"}},worldTaskTitle="Artificing Aggression",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[92732] = {id=92732,name="Light Disturbance",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="We have had victories against the Lightbloom, but Alndust is rare. Until we can gather more, the Lightbloom continues its spread. Our forces are stretched too thin to watch their every movement. A scout spotted a strange corpse by the road to the east, along with a report of a general disturbance of the light-cursed creatures. I can't look into both at once. Could you find that corpse while I investigate deeper into the Encroaching Bloom?",objectivesText="Go to the disturbance Hannan 's scout found.",rewardGold=33500,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3370,amount=10}},starts={{npcID=241629}},ends={{npcID=253087}},coords={x=0.314,y=0.648,source="quest_giver",zoneID=15355},questType="standard"},
[92735] = {id=92735,name="Breadcrumb",level=88,requiredLevel=88,faction="none",expansion=11,description="I need to test some hypothesis but I can't do this alone.",objectivesText="Go to the Stormfields.",questType="standard"},
[92736] = {id=92736,name="Light Stroll",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="<These potatoad creatures are seldom seen near the Lightbloom. It is covered in spores and looks like it was trying to escape. You should search for more clues.>",objectivesText="Search for clues.",rewardGold=170800,rewardXP=6085,rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=253087}},ends={{npcID=253105}},coords={x=0.406,y=0.63,source="quest_giver",zoneID=15355},questType="standard"},
[92737] = {id=92737,name="Light Carnage",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="The Lightbloom has infected many of these potatoads and spurred them into a frenzy. They spread the spores and reproduce at a dangerous rate. If we don't act, we will be overrun. Will you cull this heard while I search for the source of the corruption?",objectivesText="Kill 12 Lightfrenzied Potatoads . Progress: We must protect Harandar 's natural species from this invasive growth.",rewardGold=335000,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=253105}},ends={{npcID=253105}},coords={x=0.416,y=0.678,source="quest_giver",zoneID=15355},questType="standard"},
[92738] = {id=92738,name="Potatoad Tots",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="It is too late for the adults, but the young may still be saved. If you can capture them, we can remove the spores before they take root. Gather up the spore covered potadpoles and bring them to me. I will take them to Har'alnor myself to purge this Lightbloom. Do not let their first breaths be their last. Please, : save the babies.",objectivesText="Collect 8 Lightspored Potadpoles and bring them to Hannan .",rewardGold=341600,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=253105}},ends={{npcID=253105}},coords={x=0.416,y=0.678,source="quest_giver",zoneID=15355},questType="standard"},
[92739] = {id=92739,name="O.K. Bloomer",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="I have discovered the lair of a cunning creature I call Adzikel . With luck, this name will soon be forgotten. Adzikel sneaks into the potatoad nests to steal their young, and plants the Lightbloom spores to accelerate their growth into the frenzied toads, which spread more spores. For the little ones to have a chance, I must return to Har'alnor, but you have earned the right to slay this beast. Go with honor, and finish the hunt!",objectivesText="Kill the creature spreading these spores.",rewardGold=619600,rewardXP=15215,rewardItems={260585},rewardCurrencies={{id=3316,amount=25},{id=3370,amount=250}},starts={{npcID=253105}},ends={{npcID=241629}},coords={x=0.416,y=0.678,source="quest_giver",zoneID=15355},questType="standard"},
[92746] = {id=92746,name="The Twist of the Stormfields",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=16648,mapID=2405,rewardXP=11765,questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=253093,text="Stellar Vortex entered"},{orderIndex=1,type=0,amount=10,objectID=253154,text="Anomalous Residue collected"}},worldTaskTitle="The Twist of the Stormfields",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[92821] = {id=92821,name="Ignite the Skies: Silvermoon",level=0,requiredLevel=0,faction="both",expansion=11,zoneID=15969,mapID=2393,description="The season of Midsummer is celebrated by many cultures across Azeroth. Even now, bonfires across the land are ignited in honor of the spirits of fire. To share our customs with all who dwell under the sun's warmth, I've had crates of sun blossoms brought to Silvermoon. Take to the skies and ignite the blossoms above, !",rewardGold=322100,rewardItems={23247},starts={{npcID=266846}},ends={{npcID=266846}},coords={x=0.484,y=0.8,source="quest_giver",zoneID=15969},questType="standard"},
[92826] = {id=92826,name="Lorewalking: The Loa of Kings",level=10,requiredLevel=10,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Where to begin? There's so much to say! There's a great story from the Zandalari about the connection between troll and loa. Let's start there!",rewardGold=1024800,rewardXP=2125,rewardItems={242386},starts={{npcID=253727}},ends={{npcID=253727}},questType="standard"},
[92829] = {id=92829,name="Lorewalking: Death of the Drakkari Loa",level=10,requiredLevel=10,faction="both",expansion=11,zoneID=15969,mapID=2393,description="The Drakkari of Zul'Drak are well known for massacring their loa. The prophets of the Drakkari loa decided to take the full power of the loa by force. The loa were blind-sided by this betrayal. They never dreamed rituals existed that could permanently kill them and steal their essence.",rewardGold=1024800,rewardXP=2125,rewardItems={242386},starts={{npcID=253727}},ends={{npcID=253727}},coords={x=0.642,y=0.162,source="quest_giver",zoneID=1519},questType="standard"},
[92831] = {id=92831,name="Lorewalking: The Blood Loa",level=10,requiredLevel=10,faction="both",expansion=11,zoneID=13309,mapID=1565,description="Not every loa is a protector and companion to trolls. There are loa that eat their followers, like the blood loa, Hakkar. In trade for sacrifices, Hakkar grants dark blood powers to his followers. But he always takes more than he gives. Hakkar the Soulflayer has absorbed so much blood from his cultists that he's become almost a perpetual threat to the world.",rewardGold=1024800,rewardXP=2125,starts={{npcID=253727}},ends={{npcID=253727}},coords={x=0.642,y=0.162,source="quest_giver",zoneID=1519},questType="standard"},
[92832] = {id=92832,name="Lorewalking: The Hash'ey",level=10,requiredLevel=10,faction="both",expansion=11,zoneID=15969,mapID=2393,description="The last story I want to share is about the Darkspear trolls... and Mueh'zala. Mueh'zala is a mighty Loa of Death. Highly manipulative, he puts his plans into motion by using others as his pawns. He's used a hash'ey in the past. A hash'ey is a troll imbued with the full power of the loa.",rewardGold=1024800,rewardXP=2125,rewardItems={275346},starts={{npcID=253727}},ends={{npcID=253727}},questType="standard"},
[92836] = {id=92836,name="Reignite the Skies: Stormwind",level=0,requiredLevel=0,faction="alliance",expansion=11,zoneID=1519,mapID=84,description="Welcome to the Midsummer Festival of Fire, friend! Have you come to toss a few torches? Or maybe dance around the maypole? Ah, you must be here to ignite the blossom lights over the skies of Stormwind, aren't you? It is an old tradition, long forgotten but newly rekindled! Well, come on then, take to the skies and fly!",rewardGold=309800,rewardItems={23247},starts={{npcID=252528}},ends={{npcID=252528}},coords={x=0.48,y=0.718,source="quest_giver",zoneID=1519},questType="standard"},
[92839] = {id=92839,name="Reignite the Skies: Orgrimmar",level=0,requiredLevel=0,faction="horde",expansion=11,zoneID=440,mapID=71,description="Midsummer is a time to reflect on the past and future. As old traditions fade, new traditions are born. One old tradition, practiced long ago, involved the offering of sun blossoms to An'she. As summer winds took them upwards, the blossoms would burn bright blue and orange. But faded traditions need not remain lost. Will you take to the skies to ignite the sun blossoms and help rekindle this old tradition?",rewardGold=341600,rewardItems={23247},starts={{npcID=250811},{npcID=251986}},ends={{npcID=250811}},coords={x=0.478,y=0.374,source="quest_giver",zoneID=1637},questType="standard"},
[92848] = {id=92848,name="Special Assignment: The Grand Magister's Drink",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=15968,mapID=2395,questType="standard"},
[92864] = {id=92864,name="Drift Them Away",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="With the hydras hunted out of the area, the drifter population in the cascades to the west is on the rise. Egg sacks are making the water murky and undrinkable, and the drifters are becoming very territorial. We must ensure that the reintroduction of the hydras will succeed. We need to cull the number of drifters and clear some of their egg sacks. You look like someone capable of doing this task. Will you help me?",objectivesText="Slay 8 Cascade Drifters and remove 5 Drifter Egg Sacks from the cascades at Nordrassil Roots.",rewardGold=341600,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=253312}},ends={{npcID=253312}},coords={x=0.696,y=0.506,source="quest_giver",zoneID=15355},questType="standard"},
[92865] = {id=92865,name="Feeding the Buds",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="The orchid hydra's favorite food is the violet chloroceros--especially the buds on the bull's back. With the hydras gone for so long, the violet chloroceros grazed too much of the fauna. Soon, there will only be mud in that once lush and beautiful part of Harandar . I want to introduce my hydras to their primary source of food, and I would appreciate it if you could bring me four of those buds.",objectivesText="Collect 4 Chloroceros Buds from the Violet Chloroceros, then feed them to the Hydra Budlings in Har'athir. Progress: The precious budlings will be very happy with their first taste of the chloroceros buds .",rewardGold=341600,rewardXP=12170,rewardItems={255577},rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=253312}},ends={{npcID=253312}},coords={x=0.696,y=0.506,source="quest_giver",zoneID=15355},questType="standard"},
[92866] = {id=92866,name="Re-Hydra-ted",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="With the previous tasks done, it is time to reintroduce the budlings to the wilds. I have marked suitable locations to place the budlings. The little hydras will be an easy pick, so expect predators to attack you. I am sad to see them go. However, I know it is for the ecosystem's and their own good.",objectivesText="Place the budlings in the marked areas. Progress: How are my budlings doing? Precious babies that they are.",rewardGold=341600,rewardXP=12170,rewardItems={260705},rewardCurrencies={{id=3316,amount=25},{id=3370,amount=250}},starts={{npcID=253312}},ends={{npcID=253312}},coords={x=0.696,y=0.506,source="quest_giver",zoneID=15355},questType="standard"},
[92868] = {id=92868,name="He Went Thataway",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="You've been invaluable, . As for that little menace, after he was done wreaking havoc here, I didn't really pay attention to where he went next. I'm sure you'll find him eventually. Let's hope you do before he wrecks half the city, hmm?",objectivesText="Speak to Drathen in the Bazaar.",rewardGold=34100,rewardXP=1470,rewardCurrencies={{id=3316,amount=5},{id=3365,amount=10}},starts={{npcID=253015}},ends={{npcID=253468}},coords={x=0.354,y=0.578,source="quest_giver",zoneID=15969},questType="standard"},
[92869] = {id=92869,name="Fishy Dis-pondencies",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="That dog tore right through the pond and sent half the sunwhiskers flying right out of the water! Quickly, get them back in the pond before they perish!",objectivesText="Return 8 Coy Sunwhisker to the pond in the Bazaar. Progress: Hurry! They're terribly delicate creatures!",rewardGold=156400,rewardXP=5885,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=253468}},ends={{npcID=253468}},coords={x=0.448,y=0.604,source="quest_giver",zoneID=15969},questType="standard"},
[92870] = {id=92870,name="Scoot Along Now",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="That dog! The last I saw he was tearing through the pond. I didn't see where he went, but he has to be nearby! His barks... they haunt me...",objectivesText="Catch Lil' Scoots and return him to Ranger Telenus .",rewardGold=341600,rewardXP=11765,rewardItems={267456},rewardCurrencies={{id=3316,amount=25},{id=3365,amount=250}},starts={{npcID=253468}},ends={{npcID=252500}},coords={x=0.448,y=0.604,source="quest_giver",zoneID=15969},questType="standard"},
[92882] = {id=92882,name="A Hunter's Plight",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="I am desperate enough to ask an outsider for help. To join the Ka'dani, the elite hunters of Har'athir, you must complete a ritual under the guidance of an experienced Ka'dani. However, there are none left to guide me, so I cannot take the trial. But I have heard words of your actions. Maybe Akazi , the Ka'dani Elder, would let you stand as my guide. You may not know the ritual, but you know the hunt. Please, let us speak to Elder Akazi . We must try.",objectivesText="Ketan wants you to talk to Elder Akazi about the Ka'dani trials. Progress: Ketan tells me that you wish to mentor him. Is this true?",rewardGold=34100,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3370,amount=10}},starts={{npcID=253390}},ends={{npcID=253392}},coords={x=0.694,y=0.528,source="quest_giver",zoneID=15355},questType="standard"},
[92883] = {id=92883,name="A Hunter's Duty",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="At the start of the trial, the mentor and trainee gather materials to forge a hunting weapon. The weapon is more than an extension of the Ka'dani-- it's part of their being. There is no other weapon like it, as each is unique. You will help Ketan hunt and gather the materials and decorations, as well as a gift for the weaponsmith.",objectivesText="Hunt down beasts around Har'athir and collect materials to forge a Ka'dani weapon. Progress: Were you able to get everything? I know some of the required materials can be hard to gather.",rewardGold=341600,rewardXP=12170,rewardItems={255258,255259,255260,255261},rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=253392}},ends={{npcID=253433}},coords={x=0.704,y=0.506,source="quest_giver",zoneID=15355},questType="standard"},
[92884] = {id=92884,name="A Hunter's Weapon",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Forging the Ka'dani weapon is a crucial moment in the trial. We will have to follow Al'yaat's instructions. Once Al'yaat forges the weapon, you will bring it to Elder Akazi . There will be a short ceremony where he will hand me the weapon. The ceremony concludes with the elder announcing our final task. I shouldn't let the excitement take the better of me, but one thing at a time. We must be patient and calculated as if we were on a hunt.",objectivesText="Help Al'yaat forge the Ka'dani weapon, then deliver it to Elder Akazi . Progress: Forging a Ka'dani weapon is not an easy feat. A master craftsman must use the very best materials brought by the mentor and trainee.",rewardGold=341600,rewardXP=12170,rewardItems={257717},rewardCurrencies={{id=3316,amount=10},{id=3370,amount=50}},starts={{npcID=253433}},ends={{npcID=253392}},coords={x=0.7,y=0.528,source="quest_giver",zoneID=15355},questType="standard"},
[92885] = {id=92885,name="A Hunter's Prey",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2413,description="The last trial stands before you. Together, you have forged a weapon that will fell any beast, but the weapon is nothing without the hunter. Since you are not a Ka'dani, I present you with a difficult hunt. Ketan and you will hunt down and slay a prey known to all Har'athir hunters: the great Radooni . The beast ventured too close to Har'athir and should be a suitable hunt. Return to me once your hunt is complete and Radooni 's sap is on the spear.",objectivesText="Hunt down the great Radooni , then return to Elder Akazi .",rewardGold=683200,rewardXP=15215,rewardItems={260472,260473,260474,260476,260477,260478,260479,260481,260482,260483},rewardChoices={260472,260473,260474,260476,260477,260478,260479,260481,260482,260483},rewardCurrencies={{id=3316,amount=25},{id=3370,amount=250}},starts={{npcID=253392}},ends={{npcID=253392}},coords={x=0.704,y=0.506,source="quest_giver",zoneID=15355},questType="standard"},
[92890] = {id=92890,name="A Handful of Voidlight Marl",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15355,mapID=2413,rewardCurrencies={{id=3316,amount=500}},starts={{npcID=240407}},ends={{npcID=240407}},coords={x=0.51,y=0.508,source="quest_giver",mapID=2413},questType="standard"},
[92891] = {id=92891,name="A Cluster of Voidlight Marl",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15355,mapID=2413,rewardCurrencies={{id=3316,amount=1000}},starts={{npcID=240407}},ends={{npcID=240407}},coords={x=0.51,y=0.508,source="quest_giver",mapID=2413},questType="standard"},
[92892] = {id=92892,name="A Trove of Voidlight Marl",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15355,mapID=2413,rewardCurrencies={{id=3316,amount=2000}},starts={{npcID=240407}},ends={{npcID=240407}},coords={x=0.51,y=0.508,source="quest_giver",mapID=2413},questType="standard"},
[92895] = {id=92895,name="Hagar's Invitation",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15921,mapID=2413,description="Hagar has a message she believes the elves and trolls of Azeroth must all hear. She has sent a call to leaders from the elven and troll tribes to come to Harandar. I have come here to ask the blood elves to join us, but you should be there as well. You have been with us through so much of this. The Rootways from Silvermoon would be the fastest way.",rewardGold=34100,rewardXP=1370,starts={{npcID=253640}},ends={{npcID=253654}},coords={x=0.454,y=0.7,source="quest_giver",zoneID=15969},questType="standard"},
[92897] = {id=92897,name="The Preparations Are Complete",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description=", I bear an important message from Hagar. You are invited to a special meeting in Harandar. Please meet me in Silvermoon to discuss it. Orweyna",rewardGold=34100,rewardXP=1370,ends={{npcID=253640}},questType="standard"},
[92899] = {id=92899,name="History Lesson",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15921,mapID=2413,description="Hagar requested that we invite to this meeting all of the troll and elven leaders we know. It was not easy to convince them to come. There are some... past grievances between these groups. Hagar hopes to overcome these divisions. As we wait for the others to arrive, feel free to speak to the other delegates. The wait is making them restless, so try not to inflame tensions.",rewardGold=170800,rewardXP=6850,rewardItems={246731},starts={{npcID=253654}},ends={{npcID=253651}},coords={x=0.442,y=0.532,source="quest_giver",zoneID=15921},questType="standard"},
[92900] = {id=92900,name="A Favor for Kinduru",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Zul'jarra could not leave Zul'Aman as the Amani still recover. She sent Zul'jan in her stead. She hoped showing trust and giving him dis responsibility would bring him out of her shadow. Make use of his talents. But dis news... I am an old troll. I have a hard time reining Zul'jan in, but he may listen to you. Would you join us? Zul'jarra and I would be grateful if Zul'jan stayed out of trouble.",rewardGold=34100,rewardXP=1370,starts={{npcID=253651}},ends={{npcID=253673}},coords={x=0.438,y=0.512,source="quest_giver",zoneID=15921},questType="standard"},
[92901] = {id=92901,name="Revisionist History",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Not all of the visions in this place were clear to us. Some of them were... strange. One in particular seemed to revolve around an unfamiliar people: a people that we learned are the Amani trolls. The magic used to create the painting, to pull the memories from the past, are tied to the haranir and those close to us. If there was no connection, the Zur'ashar--who create the paintings--could not have recalled troll history. I can show you and Zul'jan, and you can judge for yourselves.",rewardGold=341600,rewardXP=13690,starts={{npcID=253675}},ends={{npcID=255659}},coords={x=0.386,y=0.468,source="quest_giver",zoneID=15355},questType="standard"},
[92904] = {id=92904,name="Return to Zul'Aman",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16194,mapID=2536,description="I have heard de story since I was a child! De Amani were outnumbered and still dey fought on! Dey claimed victory through sheer will! Orweyna says de visions cannot lie. Uncle thinks details of de battle could have been lost. Dey would question everything it means to be Amani. Zul'jan scowls.> I must find de truth of dis. Uncle says if anyone would know, it would be de loa. De loa have said nothing of dis before, but we must start somewhere. It's time to go home.",rewardGold=34100,rewardXP=1370,starts={{npcID=255660}},ends={{npcID=253788}},coords={x=0.348,y=0.44,source="quest_giver",zoneID=15355},questType="standard"},
[92907] = {id=92907,name="Amani Answers",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16194,mapID=2536,description="My uncle has already started communin' with de loa to find information on dis Ula'tek. Meanwhile, we gonna dig through his boxes to see what we can find. Zul'jan points to all the boxes scattered around the terrace.> My uncle has de biggest collection of histories among de Amani. I used to read through dem when I was a boy. Look for anything about Ula'tek, snakes, or early Amani history. I'll take these, you search de others.",rewardGold=170800,rewardXP=6850,starts={{npcID=253788}},ends={{npcID=256363}},coords={x=0.164,y=0.206,source="quest_giver",zoneID=16194},questType="standard"},
[92916] = {id=92916,name="A Call for Aid",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15947,mapID=2437,description=", I call upon you to aid the Amani again as a fellow hash'ura. Another dire threat is upon them. Malacrass has returned. Witherbark Bluffs is under attack by a monstrous enemy the likes of which I have never seen. And with our brush against the Twilight's Blade, the timing could not be worse. Zul'jan deserted us and... we believe he may be at least partially at fault. We will deal with both of them in time. For now, help us before we are overrun.",rewardGold=34100,rewardXP=1370,starts={{npcID=263331}},ends={{npcID=253476}},coords={x=0.436,y=0.682,source="quest_giver",zoneID=15947},questType="standard"},
[92917] = {id=92917,name="Saving Those Bound",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15947,mapID=2437,description="We fell back from the town gates. There were so many wounded and poisoned. Orweyna, Tak'lejo, and I best serve the Amani here. But you should be out there helping Zul'jarra . Malacrass's serpents are capturing Witherbark, coiling around them, and filling them with poison. Free them--and make sure to find Dak'zor . He was on the front line and first to fall.",rewardGold=341600,rewardXP=13690,starts={{npcID=253476}},ends={{npcID=255269}},coords={x=0.37,y=0.232,source="quest_giver",zoneID=15947},questType="standard"},
[92919] = {id=92919,name="All Bark, All Bite",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15947,mapID=2437,description="The wounds I have seen... the ferocity. Not only do these serpents slither on the ground and coil around our warriors' bodies, but they cut deep with their poisoned blades and target them with their talons as they dive from the skies. Zul'jarra and her forces cannot win this on their own, but my hands are needed here. Help Zul'jarra by taking them down.",rewardGold=341600,rewardXP=13690,starts={{npcID=253493}},ends={{npcID=255269}},coords={x=0.37,y=0.232,source="quest_giver",zoneID=15947},questType="standard"},
[92920] = {id=92920,name="Down With the Skies",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15947,mapID=2437,description="I will need some time to call upon Akil'zon and open de way. Dat's where you come in. Protect me, my hash'ura. I entrust you with my life. We've taken great leaps before, eh?",rewardGold=683200,rewardXP=17110,rewardItems={278893,278894,278895,278896},rewardCurrencies={{id=3316,amount=20},{id=3504,amount=100}},starts={{npcID=258992}},ends={{npcID=255327}},coords={x=0.5,y=0.544,source="quest_giver",zoneID=15947},questType="standard"},
[92921] = {id=92921,name="To the Skybridge",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Zul'jarra 's face is dark with rage as she looks off toward the Skybridge.> Zul'jan... you let dat snake Malacrass taint your mind and heart. For what? Power? De lightwood was one thing. But dis? I don't know what Malacrass has planned for de captives, but we have to take de fight to him and away from our people. Follow de monsters' path back to de Skybridge. I will consult de loa and meet you there. With their help, we will stop this.",rewardGold=34100,rewardXP=1370,starts={{npcID=255282}},ends={{npcID=257078}},coords={x=0.374,y=0.238,source="quest_giver",zoneID=15947},questType="standard"},
[92924] = {id=92924,name="What Lies Beyond the Fog",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="With de loa, we are powerful. Without de loa, we are still the Amani. We will get our kin back. Liadrin will join us soon with reinforcements, and my warriors are eager to take vengeance. There can be no delay. For my people's sake and for Zul'jan's.",rewardGold=34100,rewardXP=1370,rewardCurrencies={{id=3316,amount=5},{id=3504,amount=10}},starts={{npcID=255327}},ends={{npcID=253528}},coords={x=0.51,y=0.544,source="quest_giver",zoneID=15947},questType="standard"},
[92925] = {id=92925,name="The Glint of History",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="The ruins across this island are ancient, built by the Amani long ago. If we discover how they came to be here, we may learn the truth of Ula'tek. Then we can show Zul'jan what he is really chasing. I have an idea of where to look for that crypt. Let us go together, .",rewardGold=170800,rewardXP=6850,rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=253514}},ends={{npcID=253514}},coords={x=0.574,y=0.49,source="quest_giver",zoneID=16365},questType="standard"},
[92926] = {id=92926,name="Prey: Astalor's Initiative",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2393,description="Ah, . I am glad to see you here in our city, even if the times are trying. We are once again beset on all sides by uncertain friends and dangerous foes, but I am not unprepared. I have a... guest, housed nearby. They may hold the key to our city's survival. Meet me near the harbor if you have the strength to do what must be done.",objectivesText="Meet Astalor Bloodsworn near the harbor in Silvermoon.",rewardGold=85400,rewardXP=2940,starts={{npcID=246231}},ends={{npcID=253513}},coords={x=0.566,y=0.654,source="quest_giver",zoneID=15969},questType="standard"},
[92927] = {id=92927,name="Echoed Steps",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="Sometimes the goddess' visions are not easy to understand at first, but in time she reveals her intentions. I will keep the Children of Ula'tek out of your path as you follow her memories. Trust that she will reveal what we need to learn. Meet me up ahead once you have witnessed her memories of the Amani.",rewardGold=341600,rewardXP=13690,rewardItems={278905,278906,278907,278908},rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=253514}},ends={{npcID=253514}},coords={x=0.574,y=0.49,source="quest_giver",zoneID=16365},questType="standard"},
[92928] = {id=92928,name="What Was Buried",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="The visions of Nek'zali led us here. That we found where she took her last breath is no coincidence. There must be something within this crypt that the goddess wishes for us to see. Zul'jarra bid us to find the truth of Ula'tek. Perhaps here we will find the answers we seek. Let us see where the story we were told in the Den of Echoes ends, and where the truth begins.",rewardGold=341600,rewardXP=13690,rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=253514}},ends={{npcID=255270}},coords={x=0.574,y=0.49,source="quest_giver",zoneID=16365},questType="standard"},
[92929] = {id=92929,name="Lurking in the Dark",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="Those who built this crypt would not have sealed it without good reason. A great evil from the past must dwell here. We should put to rest any spirits and undead we find. They cannot keep us from the answers we seek.",rewardGold=341600,rewardXP=13690,rewardItems={278877,278878,278879,278880},rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=253514}},ends={{npcID=255270}},coords={x=0.574,y=0.49,source="quest_giver",zoneID=16365},questType="standard"},
[92930] = {id=92930,name="Written by the Victors",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="A version of this history is written into the Den of Echoes. The same events, only recorded by Amani hands instead of haranir ones. But something is missing: Nek'zali. How is she part of the story of Ula'tek? And we do not know how Ula'tek came to this world. We must go deeper into the crypt and witness the truth written on its walls.",rewardXP=17110,rewardItems={279452},rewardCurrencies={{id=3316,amount=100},{id=3504,amount=1500}},starts={{npcID=255270}},ends={{npcID=253514}},coords={x=0.446,y=0.767,source="quest_giver",zoneID=16365},questType="standard"},
[92931] = {id=92931,name="Delay the Venom",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="The wound from Zul'jan's blade. It won't heal. Zul'jan must have poisoned her. She's weakening, and I have not been successful in curing her with Light. Blast it! Whatever you found in that crypt can wait. The Amani are trying to find a cure. Ask Raz'taka if he's made any progress. If you need anything else, talk to Tak'lejo. Zul'jarra needs to focus on recovering.",rewardGold=256200,rewardXP=10270,rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=253827}},ends={{npcID=253514}},coords={x=0.574,y=0.49,source="quest_giver",zoneID=16365},questType="standard"},
[92932] = {id=92932,name="Clear the Swamp",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="Look in the distance. Restless, evil energy fills the sky. That structure ahead must have the answers we seek. The creatures that stand in our way must be culled. We cannot risk being overcome on such a vital mission.",rewardGold=341600,rewardXP=13690,rewardItems={278901,278902,278903,278904},rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=253514}},ends={{npcID=253514}},coords={x=0.574,y=0.49,source="quest_giver",zoneID=16365},questType="standard"},
[92933] = {id=92933,name="Haunted Shore",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="With Zul'jarra down, de Amani are losin' heart with each passin' moment. We gotta do somethin' to show dem that dis isn't over. Those tortollans have been helpin' where they can. Let's repay de favor and help out de captain. Seein' a bunch of their lost crew return to town oughta give dem some hope in dis cursed land.",rewardGold=341600,rewardXP=13690,rewardItems={279285},rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=253829}},ends={{npcID=253829}},coords={x=0.674,y=0.622,source="quest_giver",zoneID=16365},questType="standard"},
[92934] = {id=92934,name="Fuel the Calling",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="As you foretold, red rain falls from de sky. De heavens align. A great beast rouses at de door beneath de world. At last, a weapon for de Amani--one greater than any Zandalari loa. We just need de fuel to summon it. Most of de warband is injured and isolated. Fallen soldiers will welcome de sight of you, expecting you to heal dem. Take your dagger and do what must be done. Only you can save us, Nek'zali.",rewardGold=341600,rewardXP=13690,rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=254020}},ends={{npcID=254020}},coords={x=0.692,y=0.64,source="quest_giver",zoneID=16365},questType="standard"},
[92935] = {id=92935,name="Pushed to the Brink",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="De ocean at our back slithers with tentacles and eyes, but we are safer there than on dis land. We were fools to think we could claim it from Kith'ix. I have stood by your new obsession with rituals and superstitions, Nek'zali. Now, I need you to be de healer you once were. Help my soldiers fight off de aqir. Buy us the time we need for de transport boats to arrive.",rewardGold=341600,rewardXP=13690,rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=253557}},ends={{npcID=253557}},coords={x=0.692,y=0.642,source="quest_giver",zoneID=16365},questType="standard"},
[92936] = {id=92936,name="The Summoning of Ula'tek",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="Where is de rest of our warband?! De lines are breaking! My soldiers will hold dem off as long as dey can. De weak should run. But you and I... if we die, let it be together with weapons in hand, sister.",rewardGold=256200,rewardXP=10270,rewardItems={278885,278886,278887,278888},rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=253557}},ends={{npcID=253829}},coords={x=0.692,y=0.642,source="quest_giver",zoneID=16365},questType="standard"},
[92937] = {id=92937,name="Awakened Evil",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="Nek'zali, dat priestess... We should bring word of what we've seen back to de hash'ey. Orweyna . Ay! Wait--what's wrong with her?",rewardGold=683200,rewardXP=17110,rewardItems={279243,279244,279245,279280,279281,279282,279283},rewardChoices={279243,279244,279245,279280,279281,279282,279283},rewardCurrencies={{id=3316,amount=100},{id=3504,amount=1500}},starts={{npcID=253829}},ends={{npcID=253827}},coords={x=0.674,y=0.622,source="quest_giver",zoneID=16365},questType="standard"},
[92938] = {id=92938,name="Site of Terror",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="The air is thick with restless spirits. But there's more--it is the goddess. Where her voice was once quiet, I can feel it is now raised in anguish. Like a scream of terror. I fear for what we may find ahead. I will follow her voice. Come. Together, we uncover her memories of this place.",rewardGold=341600,rewardXP=13690,rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=253514}},ends={{npcID=253514}},coords={x=0.574,y=0.49,source="quest_giver",zoneID=16365},questType="standard"},
[92939] = {id=92939,name="It's Not Just a Rock!",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15958,mapID=2405,description="$p, I have something strange, here. While scouting in the Storm Fields, I found this rock a beast was chewing. Look at it! Could these be runes? Writing? But so ancient? Here? What could it mean? Strangely, I think I've been hearing a voice in my head since I found this thing... We must investigate further. Maybe we can find more of this rubble in the bellies of those beasts?",objectivesText="Collect 6 Ancient Rubble from monsters in the Storm Fields. Progress: Why are these beasts even eating these rocks?",rewardGold=341600,rewardXP=12845,rewardItems={260363},rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=253038}},ends={{npcID=253038}},coords={x=0.37,y=0.588,source="quest_giver",zoneID=15458},questType="standard"},
[92944] = {id=92944,name="Sifting Through Void",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="There's no rubble on the surface. The beasts are burrowing, so they must be finding it in a cavern underground. I've been thinking of how to get there. You've noticed the vortexes that dot the Storm Fields? They twist space, moving things from place to place. Step through one and I can reveal the anomalous residue that surrounds them. Collect the residue and I can make a spell to redirect the portal to where the source of the rubble is!",objectivesText="Jump in the Stellar Vortexes in the Storm Fields and collect 10 Anomalous Residue. Progress: I had some suspicion about these runes not being domanaar or ethereal. The specter all but confirms my thoughts. This could be something different. Maybe even a civilization!",rewardGold=341600,rewardXP=6425,rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=253038}},ends={{npcID=253038}},coords={x=0.37,y=0.588,source="quest_giver",zoneID=15458},questType="standard"},
[92945] = {id=92945,name="The Power of Anguish",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="These threats we chase are intelligent. Determined. Deadly. Their ingenuity will seek to confound you. Their strength will seek to destroy you. It is from their very will to live--to predate--that we will extract the essence required to fuel the magical defenses of our city. I have had my assistants lay out our friend's toys. You'd do best to familiarize yourself with them.",rewardGold=85400,rewardXP=2940,starts={{npcID=253513,x=0.428,y=0.104,zoneID=15968}},ends={{npcID=253513,x=0.428,y=0.104,zoneID=15968}},coords={x=0.428,y=0.104,source="quest_giver",zoneID=15968},questType="world",worldTaskTitle="The Power of Anguish"},
[92946] = {id=92946,name="Buried in the Dark",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="We're at the brink of a monumental discovery! Hurry, there's no time to even call for backup. We must find this strange spirit! With this residue, I can make a spell to adjust the vortex. It'll lead us to the source of this engraved rubble. Based on the specter's guidance, I believe we'll find an entire cave. Be ready, $p.",objectivesText="Jump into the northernmost Stellar Vortex in the Storm Fields and investigate the cave beyond. Progress: What more could we learn?",rewardGold=341600,rewardXP=12845,rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=253038}},ends={{npcID=253038}},coords={x=0.37,y=0.588,source="quest_giver",zoneID=15458},questType="standard"},
[92948] = {id=92948,name="In Over My Head",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="Akintunde created a weapon to end all intelligent life on this world, eons and eons ago? I hardly believe it. But truth or lie, we can't leave this spirit be. He's clearly dangerous. If he truly knows how to create such a weapon, we can't let him contact anyone from Azeroth. We both know a few warmongers who would do anything for that kind of power... I think I can realign the vortex again to take us directly to Akintunde. Ready yourself for a fight, $p.",objectivesText="Step into the Northernmost Stellar Vortex in the Stormfields to confront Akitunde the Unstoppable. Progress: I sensed no remorse at all from him. How could that be?",rewardGold=683200,rewardXP=16055,rewardItems={264403,264404,264405,264406},rewardCurrencies={{id=3316,amount=25},{id=3389,amount=250}},starts={{npcID=253038}},ends={{npcID=253038}},coords={x=0.37,y=0.588,source="quest_giver",zoneID=15458},questType="standard"},
[92951] = {id=92951,name="Digging Deeper",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15947,mapID=2437,description="De mask says we are lookin' for de scrolls of Malacrass. While we are in Maisara, try to find any scrolls de Vilebranch have left around. Maisara is a dangerous place, so don't bother sortin' through dem--just grab 'em and we can check later. Even if dey don't mention Ula'tek, we might find information about their plans or intentions against de Amani.",rewardGold=683200,rewardXP=17110,rewardItems={262752},starts={{npcID=253806}},ends={{npcID=253804}},coords={x=0.444,y=0.366,source="quest_giver",zoneID=15947},questType="standard"},
[92952] = {id=92952,name="Mission to Maisara",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15947,mapID=2437,description="De magic helped, but... not enough. I still don't remember my name or past life. Dat knowledge may be lost forever... I do remember more about Ula'tek--or rather, where we might find more information! I was forced into dis form by de Vilebranch trolls. Dey kept dark knowledge secret from de other tribes, includin' knowledge of Ula'tek. If we are to know more, we must go to de Maisara Deeps.",rewardGold=34100,rewardXP=1370,starts={{npcID=253833}},ends={{npcID=253805}},coords={x=0.39,y=0.388,source="quest_giver",zoneID=15947},questType="standard"},
[92953] = {id=92953,name="Memories of Malacrass",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15947,mapID=2437,description="While I was a servant of de Vilebranch, I remember discussions about Malacrass's research into Ula'tek. Malacrass recorded his knowledge in scrolls that he kept with him. Now that he's dead, we need to find out what happened to dem. De Vilebranch hex masters won't talk willingly... but if you slay dem, I can use their own necromantic magic against dem to compel dem to speak.",rewardGold=683200,rewardXP=17110,starts={{npcID=253805}},ends={{npcID=253804}},coords={x=0.444,y=0.366,source="quest_giver",zoneID=15947},questType="standard"},
[92954] = {id=92954,name="Maisara Caverns: Master of Souls",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16395,mapID=2437,description="Malacrass's notes are with Vordaza, and she's using them to further her necromantic experiments. I need you to go into de Maisara Caverns to recover them. It will be dangerous, and you will need to gather allies before venturing in. I will stay here and protect my uncle. We need to sort through all de scrolls we gathered and see what else we can find out.",rewardGold=1366400,rewardXP=23530,rewardItems={262791},starts={{npcID=253806,x=0.444,y=0.366,zoneID=15947}},ends={{npcID=253806,x=0.444,y=0.366,zoneID=15947}},coords={x=0.444,y=0.366,source="quest_giver",zoneID=15947},questType="world",worldTaskTitle="Maisara Caverns: Master of Souls",db2QuestInfoID=81,db2QuestInfoName="Dungeon"},
[92955] = {id=92955,name="The Tablets of Numazon",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15947,mapID=2437,description="De ancestors did not bow to a loa--dey claimed a weapon! A weapon dat led to our victory. I must know more. You said de tablets at Numazon are de oldest in Zul'Aman. We can continue de search there. Perhaps de ancient Amani left behind clues for us. Uncle says we should bring de mask. A stray memory might be de key to unlocking dis mystery.",rewardGold=34100,rewardXP=1370,starts={{npcID=256363}},ends={{npcID=253834}},coords={x=0.17,y=0.206,source="quest_giver",zoneID=16194},questType="standard"},
[92957] = {id=92957,name="There's the Rub",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15947,mapID=2437,description="If de tablets were made when de Amani first arrived in Zul'Aman, den there must be some clue about Ula'tek here. De tablets are too heavy to carry, so Uncle suggested dat we take rubbings of de inscriptions. I scouted ahead and gathered a few, but I ran into de Vilebranch. I came back here to make sure Uncle was safe. Enter Numazon and collect more of de rubbings while I watch over Uncle. Watch out for de Vilebranch.",rewardGold=341600,rewardXP=13690,rewardItems={262654},starts={{npcID=253834}},ends={{npcID=253832}},coords={x=0.39,y=0.388,source="quest_giver",zoneID=15947},questType="standard"},
[92958] = {id=92958,name="Brain Drain",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15947,mapID=2437,description="I wish I could be more help but... de gaps in my memory. Due to de damage de mask has sustained, dat magic has leaked out for who knows how long. You repaired de physical parts of de mask, but de magic within is still weak. Zul'jan says Vilebranch trolls occupy this crypt. De magic dat binds me together is like de magic they use. You might be able to help. Retrieve their hex fetishes--I should be able to drain the magic from them.",rewardGold=341600,rewardXP=13690,rewardItems={262659},starts={{npcID=253833}},ends={{npcID=253833}},coords={x=0.39,y=0.388,source="quest_giver",zoneID=15947},questType="standard"},
[93010] = {id=93010,name="The Serpent Shrine",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16194,mapID=2536,description="Here! De note says Ula'tek was sealed away by de Amani. To break de seal, one needs a \"key.\" Zul'jan flips through the notes.> De key was hidden within a shrine and protected with ancient magic. But which shrine... Zul'jan looks up.> Didn't de tablets at Numazon mention a shrine bein' \"dedicated to de serpent's victory?\" We know from de visions in Harandar dat Ula'tek was a serpent. Dat must be it! De key is hidden at de serpent shrine in Atal'Aman!",rewardGold=34100,rewardXP=1370,starts={{npcID=253806}},ends={{npcID=253840}},coords={x=0.444,y=0.366,source="quest_giver",zoneID=15947},questType="standard"},
[93011] = {id=93011,name="Legacy of the Amani",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15947,mapID=2437,description="If Malacrass was right, de key to Ula'tek should be right here. Zul'jan 's heavy hammer thumps onto the shrine for emphasis.> It may take me some time to break through de stone to find it. I don't know what kind of protection de ancestors have in place, but you will have to deal with dem while I work. I admit, I did not believe de visions in Harandar. I don't fully trust Malacrass's notes either. But if de key is here, dat would be undeniable proof dat what we are chasing is real.",rewardGold=683200,rewardXP=17110,starts={{npcID=253840}},ends={{npcID=259778}},coords={x=0.676,y=0.472,source="quest_giver",zoneID=16194},questType="standard"},
[93012] = {id=93012,name="Dead End",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15947,mapID=2437,description="After the meeting in Harandar, I came here to speak with Zul'jarra about the vision you witnessed. Zul'jan had seemed upset when you left and it was not my intent to make him so. But all of that can wait. Now that you're awake, you should go speak to Zul'jarra . She wants to know what happened at Atal'Aman.",rewardGold=683200,rewardXP=17110,rewardItems={268557},starts={{npcID=259778}},ends={{npcID=253848}},coords={x=0.444,y=0.666,source="quest_giver",zoneID=15947},questType="standard"},
[93013] = {id=93013,name="Special Assignment: Push Back the Light",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=15355,mapID=2413,rewardXP=13690,questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=241799,text="Ride the Haranir Petalwing"},{orderIndex=1,type=15,amount=1,objectID=0,text="Lightbloom rutaani defeated"}},worldTaskTitle="Special Assignment: Push Back the Light",db2QuestInfoID=286,db2QuestInfoName="Capstone World Quest"},
[93018] = {id=93018,name="Them That Were Lost",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="My brother is here. And so are de captives. Dey are bein' held in de small shrines ahead. For what, I don't know. But somehow my brother is involved. Gettin' my people free of dis place is of de highest priority. Do whatever is necessary to free dem. Zul'jan can wait until de prisoners are safe.",rewardGold=341600,rewardXP=13690,rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=253528}},ends={{npcID=253528}},coords={x=0.448,y=0.278,source="quest_giver",zoneID=16365},questType="standard"},
[93019] = {id=93019,name="Situation Normal, All Snaked Up",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="Zul'jarra 's hand tightens on her axe.> We knew de island was cursed, but is dis de curse? Or has what Zul'jan and Malacrass done brought dem here? De answer doesn't matter. We must find and save de ones dey kidnapped--and find my brother. Zul'jarra surveys the island stretching out around her. Her eyes narrow.> I see somethin' ahead. A structure. I'm gonna see if my people are there. You protect de people here. Crush de serpents. Grind dem into de ground. Meet me when you are done.",rewardGold=341600,rewardXP=13690,rewardItems={267376,268113,278897,278898,278899,278900},rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=253528}},ends={{npcID=253528}},coords={x=0.448,y=0.278,source="quest_giver",zoneID=16365},questType="standard"},
[93022] = {id=93022,name="Fire, the Only Way to Be Sure",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="De prisoners need to be rescued, yes, but dis place is an abomination. We must cleanse it with de spirit-born fire of Jan'alai. Take dis totem. It will allow you to wield de breath of our loa. Purge their nests. And kill de spiteful broodsisters that laid dem!",rewardGold=341600,rewardXP=13690,rewardItems={280377},rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=259218}},ends={{npcID=259218}},coords={x=0.578,y=0.472,source="quest_giver",zoneID=16365},questType="standard"},
[93023] = {id=93023,name="Death of Furies",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="Now only these creatures block our way to... Zul'jarra growls softly.> ...to Zul'jan. Dey are protectin' him like he's one of dem. One of their army. Whether he is or not, we gotta take dem down if we're gonna find out.",rewardGold=683200,rewardXP=17110,rewardItems={279194,279195,279196},rewardChoices={279194,279195,279196},rewardCurrencies={{id=3316,amount=20},{id=3504,amount=100}},starts={{npcID=253528}},ends={{npcID=253528}},coords={x=0.448,y=0.278,source="quest_giver",zoneID=16365},questType="standard"},
[93024] = {id=93024,name="Come With Me",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="Stay here, hash'ura. I'm goin' in to talk to him. Maybe I can talk him into leavin' on his own--and tellin' us what Malacrass has planned. I hope to de loa that he will come to his senses.",rewardGold=170800,rewardXP=6850,rewardCurrencies={{id=3316,amount=100},{id=3504,amount=1500}},starts={{npcID=253528}},ends={{npcID=258860}},coords={x=0.448,y=0.278,source="quest_giver",zoneID=16365},questType="standard"},
[93043] = {id=93043,name="When Predator Becomes Prey",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,description="Such a strong will to survive, even when trapped in a cage. Do not underestimate your prey, $p. They can strike at any time. Our friend here will be more than willing to demonstrate, I am sure...",objectivesText="Survive an ambush by your prey. Progress: Speak with Astalor Bloodsworn to continue.",rewardGold=85400,rewardXP=2940,starts={{npcID=253513}},ends={{npcID=253513}},coords={x=0.428,y=0.104,source="quest_giver",zoneID=15968},questType="standard"},
[93046] = {id=93046,name="Nestled Belongings",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=15355,mapID=2413,rewardXP=13690,rewardItems={256138,256143,256144,256145},questType="world",db2Objectives={{orderIndex=0,type=0,amount=4,objectID=253808,text="Orweyna's Belongings found"}},worldTaskTitle="Nestled Belongings",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[93047] = {id=93047,name="Butchery Basics",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="We can't keep up with how much these soldiers eat. Lend us just a bit of your time to feed dis army, hm? We need boar. Not just a steak or two, we need de entire boar. Nothin' goes to waste, yah?",rewardGold=341600,rewardXP=12170,rewardItems={258890},rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=241072,x=0.454,y=0.694,zoneID=15947}},ends={{npcID=241072,x=0.454,y=0.694,zoneID=15947}},coords={x=0.454,y=0.694,source="quest_giver",zoneID=15947},questType="world",worldTaskTitle="Butchery Basics"},
[93048] = {id=93048,name="Got No Rhythm",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Dat boy Kovu stormed out of here without even tryin' a single step. He thinks he's got two left feet, but he isn't even willin' to try. You look like an impressive fighter. He'll respect you for dat. Maybe he just needs de right dance partner to show him de steps. Help him out, hm?",rewardGold=170800,rewardXP=6085,rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=254142,x=0.468,y=0.662,zoneID=15947}},ends={{npcID=254142,x=0.468,y=0.662,zoneID=15947}},coords={x=0.468,y=0.662,source="quest_giver",zoneID=15947},questType="world",worldTaskTitle="Got No Rhythm"},
[93049] = {id=93049,name="Homework Support",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="My friends are goin' out to play down where de shade lilies grow, but I'm supposed to do a buncha borin' apothecary stuff. Papa wants me to collect some plants to make salves and balms we use for healin'. I asked if it could wait and he said no. What if... you helped me out? Just dis once, pleeease?",rewardGold=341600,rewardXP=12170,rewardItems={258891,258892},rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=254144,x=0.466,y=0.68,zoneID=15947}},ends={{npcID=254144,x=0.466,y=0.68,zoneID=15947}},coords={x=0.466,y=0.68,source="quest_giver",zoneID=15947},questType="world",worldTaskTitle="Homework Support"},
[93050] = {id=93050,name="Altar History",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="De altars need to be infused with de power of de loas every so often. I'm not as spry as I used to be and de altars are all spread out. Help an old shaman out, eh? I'll give you my totem to channel de loas' power into de altars. And maybe you can learn a thing or two from de other acolytes and myself in de process.",rewardGold=170800,rewardXP=6085,rewardItems={267005},rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=254146,x=0.434,y=0.688,zoneID=15947}},ends={{npcID=257797,x=0.434,y=0.688,zoneID=15947}},coords={x=0.434,y=0.688,source="quest_giver",zoneID=15947},questType="world",worldTaskTitle="Altar History"},
[93051] = {id=93051,name="The Final Exam",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="My trainin' is almost complete! My commander says I need to prove myself against a strong fighter before she can recommend me for combat. But I've been strugglin' to find someone willin' to spar with me after... uh, after what happened de last time... You look capable. And intimidatin'. Mind helpin' me out here? And no goin' easy on me, yes? I can take it.",rewardGold=683200,rewardXP=15215,rewardCurrencies={{id=3316,amount=20},{id=3354,amount=100}},starts={{npcID=255406,x=0.432,y=0.67,zoneID=15947}},ends={{npcID=255907,x=0.438,y=0.646,zoneID=15947}},coords={x=0.432,y=0.67,source="quest_giver",zoneID=15947},questType="world",worldTaskTitle="The Final Exam"},
[93053] = {id=93053,name="Cleaning the Den",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=15355,mapID=2413,rewardXP=13690,questType="world",db2Objectives={{orderIndex=0,type=3,amount=8,objectID=253825,text="Dried Acorn removed"}},worldTaskTitle="Cleaning the Den",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[93063] = {id=93063,name="Broken Spears",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="De spirits, their weapons--I recognize dem! Dey are Amani: heroes and warriors from our murals and stories! Dis was de site of a great battle--one dat earned us de right to call dis land Zul'Aman. We should bring evidence of our history back to the others watchin' Zul'jarra, to remind 'em we got our ancestors watchin' over us. Takin' de raised spirits' weapons may \"raise some spirits\" back at camp, no?",rewardGold=341600,rewardXP=13690,rewardItems={279231,279232,279233,279234,279235,279236,279237,279238},rewardChoices={279231,279232,279233,279234,279235,279236,279237,279238},rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=253829}},ends={{npcID=253829}},coords={x=0.674,y=0.622,source="quest_giver",zoneID=16365},questType="standard"},
[93064] = {id=93064,name="Awe of She",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="It's the priestess again--the one whose remains we found in the crypt. These memories--no. Not memories. They are like nightmares. Something horrible befell the goddess. We must see it directly. Hear her song through all the noise. I fear this vision will be too much for me alone. Join me, both of you, and let us witness the goddess' past terror.",rewardGold=85400,rewardXP=3420,rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=253514}},ends={{npcID=253557}},coords={x=0.574,y=0.49,source="quest_giver",zoneID=16365},questType="standard"},
[93071] = {id=93071,name="Rotten to the Core",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=15355,mapID=2413,rewardXP=13690,questType="world",db2Objectives={{orderIndex=0,type=0,amount=15,objectID=246780,text="Decanimated fungarians slain"}},worldTaskTitle="Rotten to the Core",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[93086] = {id=93086,name="To the Sanctum!",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2395,description="You have done well here, $p. Meet me at my sanctum and we can begin in earnest.",objectivesText="Return to Astalor's Sanctum.",rewardGold=85400,rewardXP=2940,rewardCurrencies={{id=3316,amount=16},{id=3387,amount=4000}},starts={{npcID=253513}},ends={{npcID=246231}},coords={x=0.428,y=0.104,source="quest_giver",zoneID=15968},questType="standard"},
[93093] = {id=93093,name="Gnarldin Trophies",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="I was sent here to prove dat I am ready to be an Amani warrior. All dat want de honor must prove demselves. I chose de gnarldin since dey are close now, and I heard Zul'jarra softened dem up a little. Looks like I wasn't de only one who thought dat and was wrong. But I still need to collect as many trophies from de gnarldin as possible. If I have de bigshot hash'ura helpin' me, there's no way I can lose, no? You get de trophies. I will stay behind to watch our backs.",objectivesText="Recover 35 trophies from gnarldin and their allies. Progress: Did you get de trophies? De gnarldin have plenty of dem from all their fightin'.",rewardGold=341600,rewardXP=12170,rewardItems={256672,257080,257081,257082,257084,257086,257087,257088,257090},rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=253997}},ends={{npcID=253997}},coords={x=0.288,y=0.334,source="quest_giver",zoneID=15947},questType="standard"},
[93094] = {id=93094,name="Scavenged Victory",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Many warriors have chosen to face de gnarldin since dey came to Zul'Aman , but many have failed. Dey thought now dat de gnarldin are in our territory and weakened, dey would be easier... De gnarldin hunters have collected tablets from de Amani hunters dat fell here. But with you at my side, we can get \"vengeance\" for those dat lost their lives here--no killin' or life riskin' required. We don't have to kill de gnarldin. We just have to get close enough to gather de tablets. What do you say?",objectivesText="Recover 6 Hunter's Tablets from fallen Amani. Progress: With those tablets, no one can question our strength!",rewardGold=341600,rewardXP=12170,rewardItems={256685},rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=253997}},ends={{npcID=253997}},coords={x=0.288,y=0.334,source="quest_giver",zoneID=15947},questType="standard"},
[93095] = {id=93095,name="Bitter Fury",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="De leader of de gnarldin here is known as Tusk Taker . Take a wild guess why she's named dat. There is a trophy dis one has in a cave. Take it, and she will run out rarin' for a fight. Defeat her for me, and no one can challenge my right to be an Amani warrior.",objectivesText="Steal Tusk Taker's Taken Tusk Trophy to lure her out, then defeat her. Progress: Did you kill Tusk Taker yet?",rewardGold=683200,rewardXP=15215,rewardCurrencies={{id=3316,amount=20},{id=3354,amount=100}},starts={{npcID=253997}},ends={{npcID=253997}},coords={x=0.288,y=0.334,source="quest_giver",zoneID=15947},questType="standard"},
[93096] = {id=93096,name="Amani Honor",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Dat is all de trophies we need. I'll take dem to de meetin' point nearby. All we gotta do is wait there for Huntmaster Jinki to show up. Come!",objectivesText="Meet Kel'vujo at the meeting point to receive your reward from Huntmaster Jinki .",rewardGold=683200,rewardXP=15215,rewardItems={264460,264461,264462,264463,264464,264465,264466,264467,269980},rewardChoices={264460,264461,264462,264463,264464,264465,264466,264467,269980},rewardCurrencies={{id=3316,amount=25},{id=3354,amount=250}},starts={{npcID=253997}},ends={{npcID=253998}},coords={x=0.288,y=0.334,source="quest_giver",zoneID=15947},questType="standard"},
[93112] = {id=93112,name="Infinite Research: Special Assignment, Fel Skies",level=10,requiredLevel=10,faction="both",expansion=11,mapID=619,description="$p, you have grown significantly stronger. It is time to test your mettle. I have a special assignment for you to carry out. See it done and I shall reward you with immense power.",objectivesText="Defeat 50 airborne Lost Legion demons. Progress: With great power comes, in this timeline, even more power.",starts={{npcID=241748}},ends={{npcID=241748}},questType="standard"},
[93113] = {id=93113,name="Infinite Research: Special Assignment, Rare Dare",level=10,requiredLevel=10,faction="both",expansion=11,mapID=619,description="$p, you have grown significantly stronger. It is time to test your mettle. I have a special assignment for you to carry out. See it done and I shall reward you with immense power.",objectivesText="Defeat 15 rare enemies. Progress: With great power comes, in this timeline, even more power.",starts={{npcID=241748}},ends={{npcID=241748}},questType="standard"},
[93114] = {id=93114,name="Infinite Research: Special Assignment, Sampling the World",level=10,requiredLevel=10,faction="both",expansion=11,mapID=619,description="$p, you have grown significantly stronger. It is time to test your mettle. I have a special assignment for you to carry out. See it done and I shall reward you with immense power.",objectivesText="Complete Eternus 's various requests. Progress: With great power comes, in this timeline, even more power.",starts={{npcID=241748}},ends={{npcID=241748}},questType="standard"},
[93116] = {id=93116,name="Infinite Research: Special Assignment, Here to Slay",level=10,requiredLevel=10,faction="both",expansion=11,mapID=619,description="$p, you have grown significantly stronger. It is time to test your mettle. I have a special assignment for you to carry out. See it done and I shall reward you with immense power.",objectivesText="Slay enemies across the Broken Isles.",starts={{npcID=241748}},ends={{npcID=241748}},questType="standard"},
[93117] = {id=93117,name="Infinite Research: Special Assignment, Boss Rush",level=10,requiredLevel=10,faction="both",expansion=11,mapID=619,description="$p, you have grown significantly stronger. It is time to test your mettle. I have a special assignment for you to carry out. See it done and I shall reward you with immense power.",objectivesText="Defeat 10 dungeon, raid, or world bosses.",starts={{npcID=241748}},ends={{npcID=241748}},questType="standard"},
[93118] = {id=93118,name="Infinite Research: Special Assignment, Power Overwhelming",level=10,requiredLevel=10,faction="both",expansion=11,mapID=619,description="$p, you have grown significantly stronger. It is time to test your mettle. I have a special assignment for you to carry out. See it done and I shall reward you with immense power.",objectivesText="Collect Epoch Mementos.",starts={{npcID=241748}},ends={{npcID=241748}},questType="standard"},
[93120] = {id=93120,name="Infinite Research: Special Assignment, A World to Explore",level=10,requiredLevel=10,faction="both",expansion=11,mapID=619,description="This is my final special assignment for you, $p. There is an entire world--an entire timeline--left for you to explore. Our work carries on. We must leave no corner of the world unexamined.",objectivesText="Complete 10 World Quests. Progress: With great power comes, in this timeline, even more power.",starts={{npcID=241748}},ends={{npcID=241748}},questType="standard"},
[93171] = {id=93171,name="Calling All Combatants!",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Run, don't walk! The Artisan's Consortium has teamed up with local Silvermoon artisans in Falconwing Square to offer a new selection of heraldries and crafted equipment. These are certified for use in arenas and battlegrounds, guaranteed! Head on down and look for Mirvedon to receive your free sample today. Act now while supplies last! Terms and conditions apply. -Aisha",objectivesText="Follow up on the advertisement with Mirvedon at Falconwing Square in Silvermoon City .",rewardGold=34100,rewardXP=1370,rewardItems={256608},ends={{npcID=243225}},coords={mapID=2393,source="quest_giver",x=0.34,y=0.812},questType="standard"},
[93178] = {id=93178,name="A Quiet Walk Interrupted",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="It is de hash'ura! De favored of our wily loa! Maybe you can help... My father, Oban, is ill and I have been givin' him all my attention. When I turned my back an hour ago, my daughter, Kanza, had run off! I searched de village, but I can't go further and leave my father behind. Please, find where she went? She can be on her own, but she's a sensitive girl, and I don't want her goin' far. Dat fool boy Haz'kel wouldn't come down, but he may have seen her leave. Ask him first.",objectivesText="Help Nerunda find Kanza's whereabouts in Zul'Aman . Progress: I'm so worried about Kanza! She shouldn't be on her own.",rewardGold=170800,rewardXP=6085,rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=254716}},ends={{npcID=254716}},coords={x=0.366,y=0.25,source="quest_giver",zoneID=15947},questType="standard"},
[93179] = {id=93179,name="Childlike Devotion",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="She's goin' to Filo's shrine. She's too old for dat. She's almost thirteen--an adult. Filo is de Loa of Childhood and protects children. Parents pray to Filo for healthy children. It is even said if a child dies, Filo waits with a child in de afterlife until their parents claim dem. Dat is superstition, but dat's why she's goin'. We lost her twin, Janaka. She must think she's with Filo. The way to Filo's shrine is dangerous, and dat loa won't speak to her. Do what you can to bring her home!",objectivesText="Find Kanza at the Shrine of Filo. Progress: < Kanza eyes you uncertainly.>",rewardGold=170800,rewardXP=6085,rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=254716}},ends={{npcID=254719}},coords={x=0.366,y=0.25,source="quest_giver",zoneID=15947},questType="standard"},
[93180] = {id=93180,name="Shrine Preparations",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Kanza makes no sound but briefly meets your gaze. She points off toward the hot spring pools. Maybe she wants you to do something there?>",objectivesText="Follow Kanza and help her by killing 4 Stinger Matriarchs , 6 Stinger Hatchlings , and by collecting 20 Thorncaps . Progress: < Kanza shifts her weight from foot to foot, swaying impatiently.>",rewardGold=341600,rewardXP=12170,rewardItems={265341},rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=254719}},ends={{npcID=258014}},coords={x=0.522,y=0.322,source="quest_giver",zoneID=15947},questType="standard"},
[93181] = {id=93181,name="Temple and a Teapot",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Kanza is dancing with excitement. She holds her small hand with one finger up. One last thing to do. You must almost be ready for the ritual to summon Filo--if that is indeed what she is asking for your help to do. She fishes in her tunic for something and presents an object to you: the broken handle of a teapot, presumably from the one she dropped on the way here. Perhaps she needs a substitute?>",objectivesText="Buy a teapot from a vendor in nearby Camp Stonewash and help Kanza start the ritual. Progress: < Kanza looks nervous and expectant.>",rewardGold=341600,rewardXP=12170,rewardItems={265401},rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=258014}},ends={{npcID=258363}},coords={x=0.514,y=0.306,source="quest_giver",zoneID=15947},questType="standard"},
[93182] = {id=93182,name="Healing Homeward",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="I will go home.",objectivesText="Return to Nerunda in Witherbark Bluffs and check if Kanza returned home.",rewardGold=335000,rewardXP=12170,rewardCurrencies={{id=3316,amount=25},{id=3354,amount=250}},starts={{npcID=258363}},ends={{npcID=258569}},coords={x=0.522,y=0.32,source="quest_giver",zoneID=15947},questType="standard"},
[93199] = {id=93199,name="Slithering in the Mire",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="De Children of Ula'tek overwhelmed de swamp and its inhabitants. Dey kill anything in their path, just to increase their numbers and expand their holdings. Do what you can to reduce their numbers. Keep dem distracted and occupied. I'll sneak ahead and look for Wa'kani and de other scouts.",rewardGold=341600,rewardXP=13690,rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=254372}},ends={{npcID=254376}},coords={x=0.63,y=0.444,source="quest_giver",zoneID=16365},questType="standard"},
[93200] = {id=93200,name="A Handful of Voidlight Marl",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,rewardCurrencies={{id=3316,amount=500}},starts={{npcID=240838}},ends={{npcID=240838}},coords={x=0.434,y=0.474,source="quest_giver",mapID=2395},questType="standard"},
[93229] = {id=93229,name="Fried Eggs",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="De snakes are focused on two things: killin' and reproducin'. Dey took over dis part of de swamp, leaving nothing livin' in their path and layin' eggs all over de place! Burn any of de eggs you come across. Careful, though. You get too close, dey can burst open, and you don't wanna be anywhere near dem when dat happens.",rewardGold=341600,rewardXP=13690,rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=254372}},ends={{npcID=254376}},coords={x=0.63,y=0.444,source="quest_giver",zoneID=16365},questType="standard"},
[93233] = {id=93233,name="Savagery Among the Ruins",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="De murlocs entrenched demselves in these old ruins. Dey are usually a tough, but cowardly sort. Dis batch is different. Probably gone mad--don't know why, don't care. Clear de ruins while you search. Don't slay their young, though. Dey don't seem to be affected by whatever got de others.",rewardGold=341600,rewardXP=13690,rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=254376}},ends={{npcID=254431}},coords={x=0.66,y=0.39,source="quest_giver",zoneID=16365},questType="standard"},
[93239] = {id=93239,name="Scouts in the Swamp",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="I looked around some more while you were rescuin' Wa'kani. I think de other scouts were taken by de murlocs. We'll have to search further into de ruins. I'll circle 'round and see if I can find anything. You're better than me in a fight, so you can search where I can't. Locate de scouts and meet me near de docks.",rewardGold=341600,rewardXP=13690,rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=254376}},ends={{npcID=254431}},coords={x=0.66,y=0.39,source="quest_giver",zoneID=16365},questType="standard"},
[93244] = {id=93244,name="Special Assignment: Agents of the Shield",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=15458,mapID=2405,description="WQ",rewardXP=11765,rewardItems={263510},questType="world",db2Objectives={{orderIndex=1,type=0,amount=1,objectID=256951,text="Amalgam's power rerouted"},{orderIndex=2,type=0,amount=1,objectID=256950,text="Unbound's power rerouted"},{orderIndex=3,type=0,amount=1,objectID=256949,text="Dweller's power rerouted"},{orderIndex=4,type=0,amount=1,objectID=256945,text="Surge's power rerouted"},{orderIndex=0,type=1,amount=1,objectID=263510,text="Slay ethereals for an Overflow Diverter"}},worldTaskTitle="Special Assignment: Agents of the Shield",db2QuestInfoID=286,db2QuestInfoName="Capstone World Quest"},
[93257] = {id=93257,name="Revantusk at Risk",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Fishers of de forest tribes constantly talk to each other about our hauls, and none are more legendary than de river-walking Revantusk and their crabs! But... I've heard they've fallen on hard times. First, de Twilight's Blade ransacked their city. Now, their cages aren't bringing in enough meat for de refugees. De Revantusk have a new head river-walker, Kahanea , who could use an extra set of hands in taking care of dis crab problem. You up to de task, outsider?",objectivesText="Find Kahanea in Nalorakk's Prowl.",rewardGold=34100,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3354,amount=10}},starts={{npcID=254488}},ends={{npcID=254491}},coords={x=0.458,y=0.706,source="quest_giver",zoneID=15947},questType="standard"},
[93258] = {id=93258,name="Crab Clues",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="De rumors are true. No matter what we try, we aren't netting as many crabs as before. And de ones we do catch taste wrong, even making some of my people sick! I succeeded my mother's position as head river-walker after losing her to de Twilight's Blade. Dealing with dis famine, my new duties, and my grief... It's so much for me to bear. Dis is de area where we first noticed an issue with our crabs. Can you investigate for me while I make more traps?",objectivesText="Investigate the lakeshore for causes of the food shortage. Progress: I must make dis right--for my people. For my mother. I wish she could give us guidance.",rewardGold=341600,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=254491}},ends={{npcID=254491}},coords={x=0.322,y=0.838,source="quest_giver",zoneID=15947},questType="standard"},
[93259] = {id=93259,name="Clobbering Crawlers",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="While I continue to scout de area for causes of dis famine, please harvest crab meat for our refugees. Their hunger only gets worse as our investigation goes on. Since de traps aren't working, you have to hunt those crabs yourself and get food straight from de source! Make sure you're getting healthy meat, though. I'm worried about some of those crabs being infected with de Void.",objectivesText="Harvest 10 pieces of Mouthwatering Crab Meat from the crabs upriver. Progress: My people have been through so much. Everyone deserves a warm home to return to, and a hearty meal to restore their strength and spirit.",rewardGold=335000,rewardXP=12170,rewardItems={259471},rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=254491}},ends={{npcID=254491}},coords={x=0.322,y=0.838,source="quest_giver",zoneID=15947},questType="standard"},
[93260] = {id=93260,name="Caging Crawlers",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Our traps being mucked up with de Void would explain why we've been catching fewer crabs! And why some of de crabs have made our people sick. Please clean our traps upriver! Based on Nak'tek's report, de infected crabs sound dangerous... so be careful approaching those traps. You can find de baskets nestled among de sticks or by bases of waterfalls--dey provide a natural disguise! Crabs are easily tricked dat way.",objectivesText="Clean 6 Crab Traps upriver. Progress: Were you able to clean any of de traps? Or find a source of de filth gumming them up?",rewardGold=335000,rewardXP=12170,rewardItems={264166},rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=254491}},ends={{npcID=254491}},coords={x=0.322,y=0.838,source="quest_giver",zoneID=15947},questType="standard"},
[93261] = {id=93261,name="A Crab of Unusual Size",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="I followed de Void pollution trail upriver and spotted a beast before it ran off to its cave: an enormous, void-addled crab. It was shedding those shards dat were polluting de river! As long as dis beast lives, it'll keep spreading pollution and infecting crabs with de Void. It must be stopped! I'd stay and fight, but I must warn everyone at de Overlook. Please, . Slay dat crab and remove de source of its corruption before it can hurt more of my people!",objectivesText="Defeat the Mania-Crab and remove the source of its corruption. Progress: I don't know if de Twilight's Blade created dat beast or not, but it needs to GO!",rewardGold=322100,rewardXP=12170,rewardItems={260410,263278,263279,263280,263281},rewardCurrencies={{id=3316,amount=25},{id=3354,amount=250}},starts={{npcID=254491}},ends={{npcID=254491}},coords={x=0.322,y=0.838,source="quest_giver",zoneID=15947},questType="standard"},
[93263] = {id=93263,name="It Just Had to Be...",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Malacrass called these creatures the Children of Ula'tek. Then it is so. My vision led Zul'jan to Ula'tek and from Ula'tek to Malacrass. Together, they must seek her. I will do whatever is in my power to help, and make this right for Zul'jarra and her people. Let us kill as many of these monsters as we can. We will fight side by side and uproot this shared foe.",rewardGold=341600,rewardXP=13690,rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=255758}},ends={{npcID=258992}},coords={x=0.44,y=0.544,source="quest_giver",zoneID=15947},questType="standard"},
[93265] = {id=93265,name="Severing the Serpent's Head",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Zul'jarra is covered in sweat, blood, and venom. Her face is grim in a way you haven't seen before.> I need your help. I ordered soldiers to move to a hut in de north as a lookout and to protect some Witherbark civilians trapped there. But one of de monster brutes caught their scent. Kill it and rescue de civilians before dey end up like Dak'zor! I will stay here and make sure none of these snakes get into de lodge.",rewardGold=683200,rewardXP=17110,rewardItems={278881,278882,278883,278884},starts={{npcID=255269}},ends={{npcID=255282}},coords={x=0.374,y=0.238,source="quest_giver",zoneID=15947},questType="standard"},
[93266] = {id=93266,name="Drumming Up the Troops",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15947,mapID=2437,description="De loa have blessed our battle! Nalorakk and Halazzi are rippin' at their flanks. Akil'zon and Jan'alai are knockin' dem from de skies. We will stay to de ground and push through de center--all of us--and rid Zul'Aman of these pests. Sound de drums again, hash'ura. Call our warriors to de battle in Atal'Aman. Now we are united and dey will heed us!",rewardGold=341600,rewardXP=13690,rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=257078}},ends={{npcID=258992}},coords={x=0.44,y=0.544,source="quest_giver",zoneID=15947},questType="standard"},
