[93339] = {id=93339,name="Trinket Trading",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="I've never seen murlocs dis vicious. A few of dem are holdin' something feathered dat glints green. Dat might be de source of de darkness I sense. When you're out among de ruins, keep your eyes open for these objects. I think de murlocs unearthed somethin' dat's got them going mad.",rewardGold=341600,rewardXP=13690,rewardItems={257977,271176},rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=255226}},ends={{npcID=255553}},coords={x=0.66,y=0.39,source="quest_giver",zoneID=16365},questType="standard"},
[93340] = {id=93340,name="The Shadow Shard",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="I thought de murlocs were driven into their frenzy by de trinkets, but they're just baubles made by de snakes. Once we drew closer to dat lighthouse, I began to suspect dey were not de cause. I can feel it from here. A pulsing darkness. Ancient. If you go up there, you may find de true source of de murlocs' madness.",rewardGold=683200,rewardXP=17110,rewardItems={280376},rewardCurrencies={{id=3316,amount=25},{id=3504,amount=250}},starts={{npcID=255553}},ends={{npcID=255553}},coords={x=0.688,y=0.372,source="quest_giver",zoneID=16365},questType="standard"},
[93365] = {id=93365,name="Midnight (81-89) E",level=81,requiredLevel=81,faction="none",expansion=11,rewardXP=17850,rewardItems={135539},questType="standard"},
