[93372] = {id=93372,name="Delver's Call: Shadow Enclave",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="The perfidious cultists of the Twilight's Blade have infiltrated Eversong and set up their horrid operations in a nearby cavern. Clear them out before they spread any further!",objectivesText="Complete the Shadow Enclave delve on any difficulty. Progress: Yes, <name>?",rewardGold=4099200,rewardXP=23530,starts={{npcID=611933}},ends={{npcID=242398}},coords={x=0.508,y=0.4,source="quest_giver",zoneID=15968},questType="standard"},
