[93384] = {id=93384,name="Delver's Call: Collegiate Calamity",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="The arcane tome, clearly agitated by something, bears the mark of Silvermoon's Thalassian University. It could be worth investigating.",objectivesText="Complete the Collegiate Calamity delve on any difficulty. Progress: Is something amiss at the university?",rewardGold=4099200,rewardXP=23530,starts={{npcID=612038}},ends={{npcID=242398}},coords={x=0.417,y=0.615,source="quest_giver",zoneID=15969},questType="standard"},
[93385] = {id=93385,name="Delver's Call: The Darkway",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16642,mapID=2393,description="Remnants of the Twilight's Blade scurry like rats through the Arcway tunnels beneath Suramar. Exterminate the vermin before they spread.",objectivesText="Complete The Darkway delve on any difficulty.",rewardGold=4099200,rewardXP=23530,starts={{npcID=612039}},ends={{npcID=242399}},coords={x=0.522,y=0.78,source="quest_giver",zoneID=15969},questType="standard"},
[93386] = {id=93386,name="Delver's Call: Parhelion Plaza",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16542,mapID=2393,description="Adventurers! Quel'Danas is once more under attack by the Void, and any who are able to provide assistance should head to the battlements of Parhelion Plaza to help stem the tide.",objectivesText="Complete the Parhelion Plaza delve on any difficulty. Progress: The Void is relentless. Be cautious.",rewardGold=4099200,rewardXP=23530,starts={{npcID=612894}},ends={{npcID=242398}},coords={x=0.523,y=0.776,source="quest_giver",zoneID=15969},questType="standard"},
[93387] = {id=93387,name="Dealing with Pests",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="Every time I leave my hut, I return to a mess and soggy little murloc footprints. I am plannin' a different approach to deal with those pestersome amphibian encroachers, but I need to sort out some ingredients. While I work out my list for those pests--there is a ghost named Jelvik dat keeps after me for somethin'. Tell him to move along.",rewardGold=170800,rewardXP=6850,rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=263327}},ends={{npcID=263327}},coords={x=0.61,y=0.326,source="quest_giver",zoneID=16365},questType="standard"},
[93388] = {id=93388,name="Unusual Alchemy",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="My list is ready. I need you to gather de ingredients to keep dem murlocs away for good. First, talk to Maka de Trawler. He and de kelpweaver from Torga's Beak like to catch fish in de inlet. Bring me some fish guts--disgustin' and perfect. Next, head out to Mlurkkr Mire. I need dat dirty ol' pearl dey think is so special. While you're in de Mire, relieve some of dem irritatin' serpent folk of some scales. Mind you, I only want de good ones.",rewardGold=341600,rewardXP=13690,rewardItems={258044,258168},rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=263327}},ends={{npcID=260226}},coords={x=0.61,y=0.326,source="quest_giver",zoneID=16365},questType="standard"},
[93389] = {id=93389,name="Rocksblood",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="I've been here so long dat pieces of my memory are lost to time. I feel an emptiness for something I loved. There will be no rest for me until I know who or what it was. I can only remember one word... Rocksblood. I don't know who or what dat is. Check de murloc ruins to de south. There's someone who can point you in de right direction. Since Ofi is bein' stubborn, I need you to help me remember.",rewardGold=341600,rewardXP=13690,rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=260710}},ends={{npcID=254605}},coords={x=0.61,y=0.328,source="quest_giver",zoneID=16365},questType="standard"},
[93390] = {id=93390,name="Acceptable Apprentice",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="Dis part is gonna be fun. I got de mixture started. It is already unpleasant, but now we will make it really vile. When you feel mentally prepared to be a useful one again, let me know.",rewardGold=170800,rewardXP=6850,rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=260226}},ends={{npcID=260226}},coords={x=0.604,y=0.33,source="quest_giver",zoneID=16365},questType="standard"},
[93391] = {id=93391,name="Make it Stinky",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="Best you move our little deterrents out to de strip of land between my home and de maniacs' mire. They may try to stop you, but hold fast. If it works, dey will be running with their tails between their legs. Do murlocs even have tails?",rewardGold=341600,rewardXP=13690,rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=260226}},ends={{npcID=260226}},coords={x=0.604,y=0.33,source="quest_giver",zoneID=16365},questType="standard"},
[93392] = {id=93392,name="Recovering Memories",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="To de northeast, there's a small island. I remember long ago a great roarin' and howlin' dat echoed across de waters. I could hear de anger, but there was also pain. I could not venture to dat place. What if I became lost, my own feelings swallowed by de bigger ones? One day, it became quiet again, but now I feel dis is de final key to de lock on my soul. Go there. Find de last piece.",rewardGold=683200,rewardXP=17110,rewardCurrencies={{id=3316,amount=20},{id=3504,amount=100}},starts={{npcID=254605}},ends={{npcID=254605}},coords={x=0.61,y=0.326,source="quest_giver",zoneID=16365},questType="standard"},
[93393] = {id=93393,name="A Little Kindness",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="You know, my friend, as happy as I am... I keep thinkin' how sad we made dat beast. I do not wish dat feelin' on another livin' soul. He took care of dear Sava for all de years she was lost. Could you help us with one last request? If you could bring him a friend of his own, it will repay our debt. Then we can move on once and for all--me and Sava will be free.",rewardXP=13690,rewardItems={268644,268961},rewardCurrencies={{id=3316,amount=25},{id=3504,amount=250}},starts={{npcID=254605}},ends={{npcID=263327}},coords={x=0.61,y=0.326,source="quest_giver",zoneID=16365},questType="standard"},
[93396] = {id=93396,name="Bursting at the Seams",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15458,mapID=2405,description="Veraan... alive... Kifaan shakes his head in disbelief.> I've spent countless hours running this moment through my head, but now that it's here, I find myself grasping for words... The Shadowguard attempted to raise Dimensius to power... they've sworn fealty to Xal'atath as she wages war on worlds. Am I supposed to just... pretend none of that happened? Is THAT what my oaths to family require? And what of Veraan? Does she regret her involvement? I should check on her.",objectivesText="Help Kifaan check on his sister's well-being.",rewardGold=170800,rewardXP=6425,rewardCurrencies={{id=3316,amount=10},{id=3389,amount=50}},starts={{npcID=244516}},ends={{npcID=244516}},coords={x=0.376,y=0.484,source="quest_giver",zoneID=15458},questType="standard"},
[93397] = {id=93397,name="Gnawing Hunger",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=15458,mapID=2405,rewardXP=11765,rewardItems={258146},questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=254754,text="Gather carrion to weaken Slavering Ultradons"}},worldTaskTitle="Gnawing Hunger",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[93409] = {id=93409,name="Delver's Call: Atal'Aman",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16556,mapID=2437,description="<The fallen scout's body bears terrible wounds, but still clutches tightly to a report detailing an immanent Vilebranch attack on Atal'Aman.>",objectivesText="Complete the Atal'Aman delve on any difficulty.",rewardGold=4099200,rewardXP=23530,starts={{npcID=254726}},ends={{npcID=240274}},coords={x=0.398,y=0.384,source="quest_giver",zoneID=15947},questType="standard"},
[93410] = {id=93410,name="Delver's Call: Twilight Crypts",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16557,mapID=2437,description="The ancient Amani crypts near the Broken Throne have been overrun. Clear them of interlopers before the dead within can be defiled further.",objectivesText="Complete the Twilight Crypts delve on any difficulty.",rewardGold=4099200,rewardXP=23530,starts={{npcID=612242}},ends={{npcID=240274}},coords={x=0.437,y=0.673,source="quest_giver",zoneID=15947},questType="standard"},
[93416] = {id=93416,name="Delver's Call: The Gulf of Memory",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16595,mapID=2413,description="Rumors of disturbances in the Gulf of Memory have begun to spread. Deal with the issue before it can take root.",objectivesText="Complete the Gulf of Memory delve on any difficulty. Progress: What did you find?",rewardGold=4099200,rewardXP=23530,starts={{npcID=612259}},ends={{npcID=238170}},coords={x=0.528,y=0.517,source="quest_giver",zoneID=15355},questType="standard"},
[93417] = {id=93417,name="The Vaults of Atal'Utek: Altar of Fangs",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16915,mapID=2512,description="Orweyna told us what she saw... Damn it, Zul'jan ! Does he truly not understand what he's done? Despite what we have accomplished, he sees the bonds Zul'jarra forged with the both of us as weakness and chases this idea of a \"supreme Amani Empire\" still. And in the process, he has gravely wounded his sister. But maybe Zul'jarra is right--maybe he doesn't know. We have to get that dagger. By making him see sense, or by force.",rewardGold=1366400,rewardXP=27380,rewardItems={273781,273785,273787,273789,273791},rewardChoices={273781,273785,273787,273789,273791},rewardCurrencies={{id=3316,amount=25},{id=3504,amount=250}},starts={{npcID=253827}},ends={{npcID=259226}},coords={x=0.574,y=0.49,source="quest_giver",zoneID=16365},questType="dungeon"},
[93418] = {id=93418,name="The Venomous Abyss",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="I saw things in de venom haze. Heard Zul'jan screamin', felt what's eatin' away at him. Heard Malacrass whisperin' in his ear. Ula'tek has haunted de Amani from de beginning. De lengths we went to for power and empire, and de blood it cost... Dat wasn't greatness. Deep down, Zul'jan knows it too. Malacrass stole my grandfather from me. I won't let him take Zul'jan too.",rewardGold=20496000,rewardXP=27380,rewardItems={279009,279010,279508},rewardChoices={279009,279010},rewardCurrencies={{id=3439,amount=10},{id=3504,amount=1500}},starts={{npcID=259319}},ends={{npcID=259417}},coords={x=0.572,y=0.486,source="quest_giver",zoneID=16365},questType="raid"},
[93419] = {id=93419,name="Nature of Her Wounds",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="The Fang is cursed from the summoning of Ula'tek. We can use it to cure Zul'jarra . I just-- We have to act fast. She's fading!",rewardGold=170800,rewardXP=6850,rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=259226}},ends={{npcID=259319}},coords={x=0.572,y=0.486,source="quest_giver",zoneID=16365},questType="standard"},
[93420] = {id=93420,name="Lor'themar's Judgement",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=15969,mapID=2393,description="We need to tell Lor'themar what happened here. Meet me in Silvermoon. As for Zul'jarra... she needs time. She needs her people, and her people need her. She will survive this. I am sure of it. She must!",rewardGold=85400,rewardXP=3420,rewardItems={279292},starts={{npcID=259417}},ends={{npcID=259417}},questType="standard"},
[93421] = {id=93421,name="Delver's Call: The Grudge Pit",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16548,mapID=2413,description="See big fight. Best fight! Grudge Pit. Be there!",objectivesText="Complete The Grudge Pit delve on any difficulty. Progress: How fighting?",rewardGold=4099200,rewardXP=23530,starts={{npcID=612264}},ends={{npcID=243226}},coords={x=0.711,y=0.521,source="quest_giver",zoneID=15355},questType="standard"},
[93423] = {id=93423,name="Sparks of War: Eversong Woods",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Mysterious creatures are out in the wild across the Eversong Woods . Go and see what you can find out about them.",rewardItems={219934},rewardCurrencies={{id=2123,amount=1000},{id=1792,amount=500},{id=1602,amount=50},{id=3316,amount=50}},starts={{npcID=254971,x=0.362,y=0.81,zoneID=15969}},ends={{npcID=254971,x=0.362,y=0.81,zoneID=15969}},coords={x=0.362,y=0.81,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Sparks of War: Eversong Woods"},
[93424] = {id=93424,name="Sparks of War: Zul'Aman",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="There's unknown danger out in Zul'Aman . Get out there and clear things up!",rewardItems={219934},rewardCurrencies={{id=2123,amount=1000},{id=1792,amount=500},{id=1602,amount=50},{id=3316,amount=50}},starts={{npcID=254971,x=0.362,y=0.81,zoneID=15969}},ends={{npcID=254971,x=0.362,y=0.81,zoneID=15969}},coords={x=0.362,y=0.81,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Sparks of War: Zul'Aman"},
[93425] = {id=93425,name="Sparks of War: Harandar",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Powerful creatures have grown through the lands across Harandar . Go look into it.",rewardItems={219934},rewardCurrencies={{id=2123,amount=1000},{id=1792,amount=500},{id=1602,amount=50},{id=3316,amount=50}},starts={{npcID=254971,x=0.362,y=0.81,zoneID=15969}},ends={{npcID=254971,x=0.362,y=0.81,zoneID=15969}},coords={x=0.362,y=0.81,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Sparks of War: Harandar"},
[93426] = {id=93426,name="Sparks of War: Voidstorm",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Chaotic forces are being disruptive in the Voidstorm . Go investigate and clear things up!",rewardItems={219934},rewardCurrencies={{id=2123,amount=1000},{id=1792,amount=500},{id=1602,amount=50},{id=3316,amount=50}},starts={{npcID=254971,x=0.362,y=0.81,zoneID=15969}},ends={{npcID=254971,x=0.362,y=0.81,zoneID=15969}},coords={x=0.362,y=0.81,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Sparks of War: Voidstorm"},
[93427] = {id=93427,name="Delver's Call: Sunkiller Sanctum",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16592,mapID=2405,description="Sunkiller Sanctum is a den of Xal'atath's most pathetic sycophants. I encourage any mercenaries, adventurers, or general do-gooders who happen upon this bounty to pay it a visit and dispense the justice you are all so happy to talk on and on about. - Perodius",objectivesText="Complete the Sunkiller Sanctum delve on any difficulty. Progress: Ah, a <race>. How delightful.",rewardGold=4099200,rewardXP=23530,starts={{npcID=612354}},ends={{npcID=254765}},coords={x=0.427,y=0.707,source="quest_giver",zoneID=15458},questType="standard"},
[93428] = {id=93428,name="Delver's Call: Shadowguard Point",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16549,mapID=2405,description="Witness the fates of those who bend their neck to Xal'atath. I issue a challenge to any creature of Void or flesh. Pursue the nearby ethereals and dispatch anyone who serves the so-called Harbinger. - Perodius",objectivesText="Complete the Shadowguard Point delve on any difficulty. Progress: Have you come to me for a reason, <class>?",rewardGold=4099200,rewardXP=23530,starts={{npcID=612364}},ends={{npcID=254765}},coords={x=0.376,y=0.519,source="quest_giver",zoneID=15458},questType="standard"},
[93432] = {id=93432,name="Swords to Plowshares",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=16194,mapID=2536,description="First Mor'duun and the Blade ambush Atal'Aman. Now it's overrun by these \"echoes...\" At least, that's what Doru calls them: echoes. All I see are ghosts of a bloodier time. And like those days, no matter how many we cut through, they never stop swarming in. Get out there and see for yourself. Bring de echoes' remains as well. Doru wants to study what dey are and how dey work.",rewardGold=341600,rewardXP=12170,rewardItems={259204},rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=254783,x=0.454,y=0.45,zoneID=16194}},ends={{npcID=254783,x=0.454,y=0.45,zoneID=16194}},coords={x=0.454,y=0.45,source="quest_giver",zoneID=16194},questType="world",worldTaskTitle="Swords to Plowshares"},
[93433] = {id=93433,name="Shrine, Sealed, Delivered",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=16194,mapID=2536,description="Curse de echoes. Curse Zul'jin, and Mor'duun, and dat snake Malacrass too. They only cause more mess for de livin' to clean up. Listen, hash'ura. I need you to deliver supplies to each of de shrines in de city. We've packaged food, water, bandages, and reagents to keep their barriers at full strength. Ask about their status as well. Though safe, they all likely feel boxed in.",rewardGold=341600,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=254827,x=0.452,y=0.45,zoneID=16194}},ends={{npcID=254827,x=0.452,y=0.45,zoneID=16194}},coords={x=0.452,y=0.45,source="quest_giver",zoneID=16194},questType="world",worldTaskTitle="Shrine, Sealed, Delivered"},
[93435] = {id=93435,name="Four Instigators",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=16194,mapID=2536,description="De scouts report seein' a few unique faces among de echoes. I felt old angers rising when I heard de names. Dey were not honorable fighters for us to challenge ourselves against, such as yourself. They were vermin--greedy opportunists that drove legions of connivin' adventurers to rob us of our possessions, our treasures, and... our tusks. Slayin' de echoes of these key figures should reduce de number of echoes appearin'. And it will make me grin to know they've fallen.",rewardGold=341600,rewardXP=12170,rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=254783,x=0.454,y=0.45,zoneID=16194}},ends={{npcID=254783,x=0.454,y=0.45,zoneID=16194}},coords={x=0.454,y=0.45,source="quest_giver",zoneID=16194},questType="world",worldTaskTitle="Four Instigators"},
[93436] = {id=93436,name="Hex the Innocent, Disrupt the Guilty",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=16194,mapID=2536,description="I will study de ashes you acquired, but we can get dis situation under control by means other than de axe. You must disrupt de battlefield, hash'ura. De echoes believe dey're in de midst of a decades-old battle, so we must target de support dey relied on back then. Poison de feasts dey find respite at, hex their disrespectful civilian allies, and sabotage dat chest they seem so keen on lootin'!",rewardGold=341600,rewardXP=12170,rewardItems={259967},rewardCurrencies={{id=3316,amount=10},{id=3354,amount=50}},starts={{npcID=254827,x=0.452,y=0.45,zoneID=16194}},ends={{npcID=254827,x=0.452,y=0.45,zoneID=16194}},coords={x=0.452,y=0.45,source="quest_giver",zoneID=16194},questType="world",worldTaskTitle="Hex the Innocent, Disrupt the Guilty"},
[93437] = {id=93437,name="In Their Own Blood",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2536,description="After studying de ashes, Doru believes we can only fight with de past using weapons of de past. I cannot ask this of any Amani. Or Witherbark, Revantusk, or Shadowpine. Ya presence with us in these times must be fate... because we could only make this request to an outsider. Ya must inhabit a soul of de profane ones: those that accepted Malacrass's vile bargain and consumed loa power during de era of Zul'jin. Return to de shrine of de profane one ya wish to merge with. Ancestors forgive us...",rewardGold=683200,rewardXP=15215,rewardItems={264184},rewardCurrencies={{id=3316,amount=25},{id=3354,amount=250}},starts={{npcID=254783,x=0.454,y=0.45,zoneID=16194}},ends={{npcID=254783,x=0.454,y=0.45,zoneID=16194}},coords={x=0.454,y=0.45,source="quest_giver",zoneID=16194},questType="world",worldTaskTitle="In Their Own Blood"},
[93438] = {id=93438,name="Special Assignment: Precision Excision",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=16648,mapID=2405,rewardXP=11765,questType="world",db2Objectives={{orderIndex=2,type=0,amount=99,objectID=255730,text="Forces slain in lower courtyard HIDDEN"},{orderIndex=4,type=0,amount=99,objectID=255740,text="Forces slain in upper courtyard HIDDEN"},{orderIndex=5,type=0,amount=5,objectID=255735,text="High value targets eliminated"},{orderIndex=7,type=0,amount=99,objectID=255788,text="Forces slain in Stormarion Watch HIDDEN"},{orderIndex=8,type=0,amount=5,objectID=255793,text="Stormarion Supplies destroyed"},{orderIndex=0,type=0,amount=1,objectID=255628,text="Ride the War-Wyrm"},{orderIndex=1,type=0,amount=10,objectID=255730,text="Forces slain in lower courtyard"},{orderIndex=3,type=0,amount=10,objectID=255740,text="Forces slain in upper courtyard"},{orderIndex=6,type=0,amount=7,objectID=255788,text="Forces slain in Stormarion Watch"}},worldTaskTitle="Special Assignment: Precision Excision",db2QuestInfoID=286,db2QuestInfoName="Capstone World Quest"},
[93440] = {id=93440,name="Personal History",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=16194,mapID=2536,description="With Mor'duun slain and de Twilight's Blade defeated, my people want to return to Atal'Aman. It should be a moment of great celebration but... somethin' unexpected is barrin' our way. Seek out Torundo and Elder Doru. Dey are supportin' de resettlement. They'll know how best to use your talents. Prepare yourself, hash'ura, and do not hesitate to defend Atal'Aman no matter who you meet there.",rewardGold=30900,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3354,amount=10}},starts={{npcID=249653,x=0.456,y=0.654,zoneID=15947}},ends={{npcID=254783,x=0.454,y=0.45,zoneID=16194}},coords={x=0.456,y=0.654,source="quest_giver",zoneID=15947},questType="world",worldTaskTitle="Personal History"},
[93449] = {id=93449,name="Trouble in the Swamp",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="A group of my people went over to Mlurkkr Mire and have not returned. Dey were looking into an incursion of de Children of Ula'tek in de region. There are also troubling reports of de local murlocs actin' more violent than usual, and de priest Wa'kani said she detected a strong dark energy she wanted to check out. Their leader, Zawadi , was due to report back an hour ago. Will you go find dem and lend aid if needed?",rewardGold=34100,rewardXP=1370,rewardCurrencies={{id=3316,amount=5},{id=3504,amount=10}},starts={{npcID=257091}},ends={{npcID=254372}},coords={x=0.574,y=0.474,source="quest_giver",zoneID=16365},questType="standard"},
[93453] = {id=93453,name="A Grave Concern",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Dearly Departed, Having just tasted the bitter sting of mortality, there seems no better time to discuss with you the oft ignored subject of death and memorialization. Of what you leave behind in a real, physical sense. Leave discussion of love and other such frivolities to the philosophers and dandies. I speak of cold, hard stone and the deeds carved upon it. Find me in Silvermoon.",objectivesText="Meet with Nelthius Shadestone in Silvermoon. Progress: Have you made your selection?",rewardGold=34100,rewardXP=1470,starts={{npcID=254616}},ends={{npcID=254616}},coords={x=0.526,y=0.776,source="quest_giver",zoneID=15969},questType="standard"},
[93454] = {id=93454,name="Words to Hear",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="Malacrass helped my grandfather lead de Amani to ruin. Now he's gonna do de same to my brother. If we could just separate de two of them... But Jan won't listen. He thinks Ula'tek is a weapon dat will bring de return of de Amani Empire. After de vision he saw--and who knows what else Malacrass told him--I can't convince him otherwise. De hash'ey requires counsel, my hash'ura. Gather de others and join me.",rewardGold=170800,rewardXP=6850,rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=258859}},ends={{npcID=253514}},coords={x=0.584,y=0.454,source="quest_giver",zoneID=16365},questType="standard"},
[93495] = {id=93495,name="A Soaring Journey Through Time",level=0,requiredLevel=0,faction="both",expansion=11,zoneID=13862,mapID=2112,description="The sands of time flow back and forth like ocean waves. Journey once more through the timeways, to the time of Dragon Aspects and Primal Incarnates. Bring me tales of victory in an era of great adventure and danger.",rewardGold=1353200,rewardItems={232877},starts={{npcID=255019}},ends={{npcID=255019}},questType="standard"},
[93497] = {id=93497,name="A Soaring Path Through Time",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="It was a time of forging new alliances and enemies. Reminisce with me about the great Dragon Aspects and their return to glory. Venture back in time to the Dragon Isles and return with what knowledge you can.",rewardItems={250116,274714},starts={{npcID=256212}},ends={{npcID=256212}},coords={x=0.488,y=0.646,source="quest_giver",zoneID=15969},questType="standard"},
[93499] = {id=93499,name="Enshrouded in Arenas",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="An important test to being a strong warrior is coordinating with others in combat. Find fellow combatants to join you in battle in the arena.",objectivesText="Obtain Honor in Rated Arenas while in a Party.",rewardCurrencies={{id=1792,amount=500},{id=1602,amount=175}},starts={{npcID=254971}},ends={{npcID=254971}},coords={x=0.362,y=0.81,source="quest_giver",zoneID=15969},questType="pvp"},
[93501] = {id=93501,name="The Season Starts: Midnight",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Things have started to get interesting, . I'm hearing of all sorts of treasures popping up in delves. I'm compiling my notes in this book, and our illustrious hosts have even broken out some of their own artifacts to trade for what we uncover. Why don't you take a look before we head out. Better prepared than dead.",rewardGold=34100,rewardXP=1370,rewardCurrencies={{id=3310,amount=25},{id=3310,amount=37}},starts={{npcID=242381,x=0.524,y=0.78,zoneID=15969}},ends={{npcID=242381,x=0.524,y=0.78,zoneID=15969}},coords={x=0.524,y=0.78,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="The Season Starts: Midnight"},
[93502] = {id=93502,name="Enshrouded Solo",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Independence is key to excel in battle. Display your solo capabilities in then come back to me.",objectivesText="Complete 12 rounds of Solo Shuffle.",rewardCurrencies={{id=1792,amount=500},{id=1602,amount=175}},starts={{npcID=254971}},ends={{npcID=254971}},coords={x=0.362,y=0.81,source="quest_giver",zoneID=15969},questType="pvp"},
[93503] = {id=93503,name="Enshrouded in Teamwork",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="The ability to work with a group to take objectives is key in training. Practice this on the battlefield.",objectivesText="Obtain Honor in Rated Battleground Blitz or in Rated Battlegrounds.",rewardCurrencies={{id=1792,amount=750},{id=1602,amount=175}},starts={{npcID=254971}},ends={{npcID=254971}},coords={x=0.362,y=0.81,source="quest_giver",zoneID=15969},questType="pvp"},
[93504] = {id=93504,name="Enshrouded in Skirmishes",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Practice makers perfect. A great place to practice is with others like yourself looking to practice. Set off and find others like yourself to practice small-scale skirmishes, then return to me.",objectivesText="Obtain Honor from Arena Skirmishes.",rewardCurrencies={{id=1792,amount=350},{id=1602,amount=125}},starts={{npcID=254971}},ends={{npcID=254971}},coords={x=0.362,y=0.81,source="quest_giver",zoneID=15969},questType="pvp"},
[93505] = {id=93505,name="Enshrouded in War",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Large conflicts get you to take a look at the larger picture. Give it a try then come back to me.",objectivesText="Obtain Honor in Epic Battlegrounds.",rewardCurrencies={{id=1792,amount=500},{id=1602,amount=175}},starts={{npcID=254971}},ends={{npcID=254971}},coords={x=0.362,y=0.81,source="quest_giver",zoneID=15969},questType="pvp"},
[93506] = {id=93506,name="Enshrouded in Battle",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="You can learn a lot on the battlefield on your own. Go ahead and see what you observe.",objectivesText="Obtain Honor in Random Battlegrounds. Progress: There's still more to explore.",rewardChoices={3354,3365},rewardCurrencies={{id=1792,amount=500},{id=1602,amount=175}},starts={{npcID=254971}},ends={{npcID=254971}},coords={x=0.362,y=0.81,source="quest_giver",zoneID=15969},questType="pvp"},
[93507] = {id=93507,name="Disrupting the Void",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=15458,mapID=2405,rewardXP=13690,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Shadowguard operation disrupted"},{orderIndex=4,type=2,amount=13,objectID=543716,text="Obtuse Joint 0.9"},{orderIndex=5,type=2,amount=13,objectID=543427,text="Obtuse Joint 1.1"},{orderIndex=6,type=2,amount=13,objectID=548730,text="Straight 0.6"}},worldTaskTitle="Disrupting the Void",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[93511] = {id=93511,name="A Missing Member",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="He took him! Finley...big...purple...man!",rewardGold=34100,rewardXP=1370,rewardCurrencies={{id=3310,amount=25},{id=3310,amount=37}},starts={{npcID=255103,x=0.524,y=0.782,zoneID=15969}},ends={{npcID=242381,x=0.524,y=0.78,zoneID=15969}},coords={x=0.524,y=0.782,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="A Missing Member"},
