[93519] = {id=93519,name="Midnight Delves!",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Things are starting to get interesting in Delves. Come see me in Silvermoon.",objectivesText="Visit Valeera in Silvermoon.",rewardGold=34100,rewardXP=1370,rewardCurrencies={{id=3310,amount=25}},ends={{npcID=242381}},coords={mapID=2393,source="quest_giver",x=0.525,y=0.781},questType="standard"},
