[93525] = {id=93525,name="Nulling Nullaeus",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="That thing looked tough, and it took Reno out as an afterthought. We'll want the best gear we can get before trying to take it down. Thankfully, I have some leads on bountiful delves we can start with.",rewardGold=4099200,rewardXP=27380,rewardItems={264413},rewardCurrencies={{id=3310,amount=25},{id=3310,amount=37}},starts={{npcID=242381,x=0.524,y=0.78,zoneID=15969}},ends={{npcID=242381,x=0.524,y=0.78,zoneID=15969}},coords={x=0.524,y=0.78,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Nulling Nullaeus"},
