[93566] = {id=93566,name="Renowned with the Amani Tribe",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15947,mapID=2437,description="You continue to prove yourself to de Amani and de other forest tribes alike. Speak to me when next you are in Amani'Zar. Zul'jarra asked me to put a few items aside as our way of sayin' thanks.",objectivesText="Speak with Magovu in Amani'Zar Village.",rewardItems={251970},starts={{npcID=240279}},ends={{npcID=240279}},questType="standard"},
[93569] = {id=93569,name="Exaliburn",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=15458,mapID=2405,questType="standard",worldTaskTitle="Exaliburn",db2QuestInfoID=265,db2QuestInfoName="Hidden Quest"},
