[93575] = {id=93575,name="Maisara Caverns: Maisara Hungers",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=16395,mapID=2437,description="I will not leave my people to die to de Vilebranch's dark rituals. We must go after dem. The heart of Maisara Caverns is where de Vilebranch keep their secrets. I expect dis to be a bloody trip. We will have to face de ugliness of the Vilebranch greed, and what it is costin' all of us. We must discover what purpose they have for my stolen kin. If any still be alive. I will be dere to aid you... but bring a fierce party of warriors. We will need it.",rewardGold=1366400,rewardXP=24340,rewardChoices={251161,251164,251166,251167,251169,251170,251172,251176,251177},rewardCurrencies={{id=3316,amount=25},{id=3354,amount=250}},starts={{npcID=244521,x=0.44,y=0.344,zoneID=15947}},ends={{npcID=244521,x=0.44,y=0.344,zoneID=15947}},coords={x=0.44,y=0.344,source="quest_giver",zoneID=15947},questType="world",worldTaskTitle="Maisara Caverns: Maisara Hungers",db2QuestInfoID=81,db2QuestInfoName="Dungeon"},
[93576] = {id=93576,name="The Search for Wa'kani",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="While you were keepin' de snakes busy, I was lookin' for Wa'kani and de other scouts. De scouts are still missin', but Wa'kani is in dat temple over there. I tried gettin' closer, but it's too heavily guarded. You should have no problem, though. Please rescue my fool sista before de snakes do something foul to her.",rewardGold=341600,rewardXP=13690,rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=254376}},ends={{npcID=255978}},coords={x=0.66,y=0.39,source="quest_giver",zoneID=16365},questType="standard"},
[93577] = {id=93577,name="Captured Instinct",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=16648,mapID=2405,rewardXP=11765,questType="world",db2Objectives={{orderIndex=0,type=3,amount=1,objectID=255543,text="Ride the Cataloger's Disc"},{orderIndex=1,type=15,amount=1,objectID=0,text="Take Pictures of Wildlife"},{orderIndex=2,type=0,amount=34,objectID=255539,text="Common"},{orderIndex=3,type=0,amount=20,objectID=255540,text="Rare"},{orderIndex=4,type=0,amount=13,objectID=255541,text="Epic"},{orderIndex=5,type=0,amount=9,objectID=255542,text="Legendary"}},worldTaskTitle="Captured Instinct",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
