[93651] = {id=93651,name="The Blinding Vale: Lightbloom Roots",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15355,mapID=2393,description="We have traced Ruia's flight through the Rootways. As we suspected, he has sought refuge deep within The Blinding Vale, where the Lightbloom first took root within Harandar. With Alndust empowering our command of life, we are able to keep the Lightbloom from spreading uncontrolled. But we will run out of Alndust long before Ruia runs out of patience. Ruia is wise and powerful. But his actions in Eversong prove that his conviction has grown into an uncontrollable fanaticism. He must be stopped.",rewardGold=1366400,rewardXP=24340,rewardItems={251183,251190,251194,251197},rewardChoices={251183,251185,251190,251194,251197,251200},rewardCurrencies={{id=3316,amount=25},{id=3370,amount=250}},starts={{npcID=255822,x=0.366,y=0.686,zoneID=15969},{npcID=255828,x=0.508,y=0.53,zoneID=15355}},ends={{npcID=255828,x=0.508,y=0.53,zoneID=15355}},coords={x=0.366,y=0.686,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="The Blinding Vale: Lightbloom Roots",db2QuestInfoID=81,db2QuestInfoName="Dungeon"},
[93664] = {id=93664,name="Rotten Fish",expansion=11,mapID=2512,objectivesText="Level 90 Requirements: - Venom-Crazed Murkfen slain x 8",questType="world",db2Objectives={{orderIndex=0,type=0,amount=8,objectID=262752,text="Venom-Crazed Murkfen slain"}},worldTaskTitle="Rotten Fish",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
