[93667] = {id=93667,name="Camp Stonewash",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="You're not the first strange thing I've seen today. Scout Zel'kanra shakes her head.> Saw a big, shelled creature along the path to Jan'Alor. Amaxi took a bunch of scouts and went after it. They've been gone a while. Think you could check in on them?",objectivesText="Find Amaxi outside Camp Stonewash in Zul'Aman .",rewardGold=30900,rewardXP=1520,rewardCurrencies={{id=3316,amount=5},{id=3354,amount=10}},starts={{npcID=255852}},ends={{npcID=242388}},coords={x=0.442,y=0.336,source="quest_giver",zoneID=15947},questType="standard"},
[93668] = {id=93668,name="An Old Game for a New Age",level=0,requiredLevel=0,faction="none",expansion=11,objectivesText="Meet up with Aethas Sunreaver, Riftblade Maella, and Auric Sunchaser at the Decor Duel training area.",questType="standard"},
