[93690] = {id=93690,name="Alchemy Services Requested",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Welcome back, . If you're still interested in working with the Artisan's Consortium, we would value your aid. We need highly skilled artisans to craft supplies for the war effort. If your work meets Silvermoon's high standards of quality, please fill any public crafting orders you find on the board. You can also fill orders for yourself, your guildmates, or private patrons. Bring back proof of completed orders and I'll see that you're adequately compensated.",objectivesText="Fill Alchemy Crafting Orders for the Artisan's Consortium. Progress: Bring back proof of completed orders and I'll see that you're adequately compensated.",rewardXP=11765,rewardItems={263454},starts={{npcID=243283},{npcID=243357}},ends={{npcID=243283}},coords={x=0.45,y=0.55,source="quest_giver",zoneID=15969},questType="standard"},
[93691] = {id=93691,name="Blacksmithing Services Requested",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Welcome back, . If you're still interested in working with the Artisan's Consortium, we would value your aid. We need highly skilled artisans to craft supplies for the war effort. If your work meets Silvermoon's high standards of quality, please fill any public crafting orders you find on the board. You can also fill orders for yourself, your guildmates, or private patrons. Bring back proof of completed orders and I'll see that you're adequately compensated.",objectivesText="Fill Blacksmithing Crafting Orders for the Artisan's Consortium. Progress: Bring back proof of completed orders and I'll see that you're adequately compensate",rewardXP=11765,rewardItems={263455},starts={{npcID=241450},{npcID=243283}},ends={{npcID=243283}},coords={x=0.436,y=0.516,source="quest_giver",zoneID=15969},questType="standard"},
[93692] = {id=93692,name="Engineering Services Requested",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Welcome back, . If you're still interested in working with the Artisan's Consortium, we would value your aid. We need highly skilled artisans to craft supplies for the war effort. If your work meets Silvermoon's high standards of quality, please fill any public crafting orders you find on the board. You can also fill orders for yourself, your guildmates, or private patrons. Bring back proof of completed orders and I'll see that you're adequately compensated.",objectivesText="Fill Engineering Crafting Orders for the Artisan's Consortium. Progress: Bring back proof of completed orders and I'll see that you're adequately compensated.",rewardXP=11765,rewardItems={263456},starts={{npcID=241452},{npcID=243283}},ends={{npcID=243283}},coords={x=0.436,y=0.54,source="quest_giver",zoneID=15969},questType="standard"},
