[94457] = {id=94457,name="Midnight: Battlegrounds",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Battlegrounds stand as crucible where soldiers clash for honor, resources, and glory. Each victory hones your skill and strengthens your resolve. Go, test yourself against worthy foes and bring pride to your banner.",objectivesText="Complete any Battleground in Midnight.",rewardGold=683200,rewardXP=20540,rewardItems={254677,268490,279527,279575},ends={{npcID=256203}},coords={mapID=2393,source="quest_giver",x=0.49,y=0.645},questType="standard"},
[94464] = {id=94464,name="Heritage of the Haranir",level=50,requiredLevel=50,faction="both",expansion=11,zoneID=15355,mapID=2413,description="You have travelled far and learned much of Aln'hara's grace. It is time to return home and share the wisdom you have earned with your people.",objectivesText="Tell Orweyna of your travels at the Den in Harandar.",rewardItems={258812,258814,258815,258816,258817,258820,258821,258822,258824,258825,258826,258827,258828,258829,258830,258831,258832,258833},ends={{npcID=255828}},coords={mapID=2413,source="quest_giver",x=0.508,y=0.53},questType="standard"},
