[94474] = {id=94474,name="The Great Vault",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="In wake of recent events, the Vanguard of the Light has recovered and preserved relics of exceptional power and craftsmanship. To safeguard these treasures from prying eyes, the Magisters of Silvermoon have conjured a vault within Silvermoon's bank. Only the most proven of champions may earn the right to draw from its splendor. If the Light deems you worthy, you may be bestowed an artifact of great power.",objectivesText="Obtain a piece of loot from the Great Vault. Progress: The Light favors you, and so too does the vault. Look within.",rewardGold=341600,rewardXP=13690,rewardItems={265039},starts={{npcID=239670}},ends={{npcID=239670}},coords={x=0.504,y=0.65,source="quest_giver",zoneID=15969},questType="standard"},
[94475] = {id=94475,name="The Voidspire: Flicker in the Hollow",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16340,mapID=2405,description="There's little light in these lands. What remains is fractured, hidden, or fading. Fetch me Echoes of Radiance and I will grant you passage where no path should exist.",objectivesText="Collect 3 Echoes of Radiance within The Voidspire on Normal difficulty. Progress: Safe passage has its price.",rewardGold=683200,rewardXP=17110,rewardItems={265014},starts={{npcID=241076}},ends={{npcID=241076}},questType="raid"},
[94476] = {id=94476,name="The Voidspire: Flicker in the Hollow",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16340,mapID=2405,description="There's little light in these lands. What remains is fractured, hidden, or fading. Fetch me Echoes of Radiance and I will grant you passage where no path should exist.",objectivesText="Collect 3 Echoes of Radiance within The Voidspire on Heroic difficulty. Progress: Safe passage has its price.",rewardGold=683200,rewardXP=17110,rewardItems={265015},starts={{npcID=241076}},ends={{npcID=241076}},questType="raid"},
