[94622] = {id=94622,name="Work It",level=0,requiredLevel=0,faction="both",expansion=11,zoneID=15969,mapID=2393,description="The Trial of Style gives us the opportunity to look good, . The camera makes sure we keep looking good. So focus on me and my camera, follow my directions and I'll make sure you look fantastic!",rewardGold=34100,starts={{npcID=258379,x=0.512,y=0.764,zoneID=15969}},ends={{npcID=258379,x=0.512,y=0.764,zoneID=15969}},coords={x=0.512,y=0.764,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Work It"},
[94623] = {id=94623,name="Building the Voidforge",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,description="I have been considering how I may offer you greater strength, my friend. I've come up with something, but I need your help building a proper Voidforge. What? Oh, fear not, all my ulterior motives are still aligned with your cause. For now. To begin, I need one Elementary Voidcore. You will be able to find shards from the more powerful foes you habitually encounter. Inflict your usual violence, return the shards, and I can weave them back into a true Voidcore to serve as the forge's foundation.",rewardGold=1366400,rewardXP=27380,rewardItems={265695},starts={{npcID=235697,x=0.514,y=0.728,zoneID=15458},{npcID=243907,x=0.512,y=0.684,zoneID=15458}},ends={{npcID=243907,x=0.512,y=0.684,zoneID=15458}},coords={x=0.514,y=0.728,source="quest_giver",zoneID=15458},questType="world",worldTaskTitle="Building the Voidforge",db2QuestInfoID=282,db2QuestInfoName="Important Quest"},
[94625] = {id=94625,name="An Elementary Voidcore",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,description="The work continues. Find enough shards and we can fuse them back into an Elemental Voidcore. I have acquired sufficient reagents to transmute $30474w cores in total thus far. The nascent Voidforge will require $30506W before it is fully formed, and you have generously contributed $3409cur so far. Go out and indulge in a bit more violence, will you?",rewardGold=1366400,rewardXP=27380,rewardItems={265695},starts={{npcID=243907,x=0.512,y=0.684,zoneID=15458}},ends={{npcID=243907,x=0.512,y=0.684,zoneID=15458}},coords={x=0.512,y=0.684,source="quest_giver",zoneID=15458},questType="world",worldTaskTitle="An Elementary Voidcore",db2QuestInfoID=282,db2QuestInfoName="Important Quest"},
