[94790] = {id=94790,name="Research Console: Exploring the Void",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15458,mapID=2405,description="No rest for the researchers, as they say. As much as I would love to go traipsing around this blasted voidscape, I need to remain at this post. But you! You can be our eyes and ears in the abyss. Go and explore the Voidstorm , maybe we can find some additional samples to feed into the console.",rewardGold=341600,rewardXP=11765,rewardCurrencies={{currencyID=3400,quantity=1}},starts={{npcID=248328,x=0.526,y=0.728,zoneID=15458}},ends={{npcID=248328,x=0.526,y=0.728,zoneID=15458}},coords={x=0.526,y=0.728,source="quest_giver",zoneID=15458},questType="world",worldTaskTitle="Research Console: Exploring the Void"},
