[95245] = {id=95245,name="Midnight: World Tour",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="The immediate danger has passed, but there is still much to be done. Go out and work with our allies to secure what ground we have made against the darkness. Whether it is in Azeroth or beyond, there is still much to be done.",rewardGold=341600,rewardXP=11765,starts={{npcID=235787,x=0.454,y=0.704,zoneID=15969}},ends={{npcID=235787,x=0.454,y=0.704,zoneID=15969}},coords={x=0.454,y=0.704,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Midnight: World Tour",db2QuestInfoID=282,db2QuestInfoName="Important Quest"},
[95253] = {id=95253,name="Shocking Appetites",expansion=11,mapID=2512,objectivesText="Level 90 Requirements: - Deepwater Venom-Spewer fed to death x 3 - Serpent fed 01 x 4 - Serpent fed 02 x 4 - Serpent fed 03 x 4 - Zapgut Gland x 12",rewardItems={268628},questType="world",db2Objectives={{orderIndex=1,type=0,amount=3,objectID=260227,text="Deepwater Venom-Spewer fed to death"},{orderIndex=2,type=0,amount=4,objectID=260303,text="Serpent fed 01"},{orderIndex=0,type=14,amount=1,objectID=223651,text="Gather Zapgut Glands to feed to Venom-Spewers"},{orderIndex=3,type=0,amount=4,objectID=260301,text="Serpent fed 02"},{orderIndex=4,type=0,amount=4,objectID=260302,text="Serpent fed 03"}},worldTaskTitle="Shocking Appetites",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
