[95268] = {id=95268,name="New Tools, New Heights",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,description="There is another sort of Void power I know you will be interested in. An Ascendant Voidcore is difficult to come by, and even more difficult to work. With the Voidforge completed, I can now weave a magnificent Nilhammer capable of such things. Of course, I will need you to help with the materials. It will take time. Take this chunk of Hungering Oblivium . It can devour moments of extreme violence to be catalyzed to new heights of power, but I don't think you'll have any trouble managing that, will you?",rewardGold=1366400,rewardXP=27380,rewardItems={269668},starts={{npcID=243907,x=0.512,y=0.684,zoneID=15458}},ends={{npcID=243907,x=0.512,y=0.684,zoneID=15458}},coords={x=0.512,y=0.684,source="quest_giver",zoneID=15458},questType="world",worldTaskTitle="New Tools, New Heights",db2QuestInfoID=282,db2QuestInfoName="Important Quest"},
[95269] = {id=95269,name="Feeding the Nilhammer",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,description="Our nascent Nilhammer coalesces! But I will need to weave the Void energies from more Hungering Oblivium into it before it can fully take form. Luckily I have prepared another piece for you to catalyze. Extreme violence, remember?",rewardGold=1366400,rewardXP=27380,rewardItems={269668},starts={{npcID=243907,x=0.512,y=0.684,zoneID=15458}},ends={{npcID=243907,x=0.512,y=0.684,zoneID=15458}},coords={x=0.512,y=0.684,source="quest_giver",zoneID=15458},questType="world",worldTaskTitle="Feeding the Nilhammer",db2QuestInfoID=282,db2QuestInfoName="Important Quest"},
[95271] = {id=95271,name="The Ascendant Nilhammer",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,rewardGold=1366400,rewardXP=27380,rewardItems={268650},starts={{npcID=243907,x=0.512,y=0.684,mapID=2405}},ends={{npcID=243907,x=0.512,y=0.684,mapID=2405}},coords={x=0.512,y=0.684,source="quest_giver",mapID=2405},questType="world",worldTaskTitle="The Ascendant Nilhammer",db2QuestInfoID=282,db2QuestInfoName="Important Quest"},
[95276] = {id=95276,name="The Last Push",level=88,requiredLevel=88,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Our forces are starting to move out to take the fight to Xal'atath. I've received word there are many areas that you've visited that could still use some aid. We must focus our attention on the counter offensive. Can you help those that are in need?",objectivesText="Reach level 90. Quests in Silvermoon City , Eversong Woods, Zul'aman, Harandar, and Voidstorm will now scale to your level. World Quests are now unlocked. Progress: There's plenty out there that can be done.",rewardGold=85400,rewardXP=3210,starts={{npcID=235787}},ends={{npcID=235787}},coords={x=0.454,y=0.704,source="quest_giver",zoneID=15969},questType="standard"},
