[95324] = {id=95324,name="The War Beyond the Roots",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Your actions in Harandar caused quite an uproar. The elders are up in arms. The rootwardens are worried. It's really quite exhausting. But there is good news as well. Orweyna has heard rumblings from every corner of the roots. She tells me of haranir who wish to see the world as she does--who feel compelled to seek the goddess beyond the boughs of Harandar. I will handle things in Harandar. Go to your leaders. Tell them that the haranir are ready to join the fight.",rewardItems={246736},starts={{npcID=255819,x=0.366,y=0.686,zoneID=15969}},ends={{npcID=235787,x=0.454,y=0.704,zoneID=15969}},coords={x=0.366,y=0.686,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="The War Beyond the Roots",db2QuestInfoID=282,db2QuestInfoName="Important Quest"},
[95336] = {id=95336,name="Frenzied Fossicking",level=25,requiredLevel=25,faction="both",expansion=11,zoneID=16105,mapID=2352,description="Ya be down for helping me out with a little spot of bother? Shajanji be over in the mountains collecting some local rocks. If you could go help her out, I'd be mighty grateful ta ya. Just bring them back ta me. I be keeping them safe for her. I--She needs a lot of them. She be an avid collector.",rewardGold=341600,rewardXP=3440,rewardCurrencies={{id=3363,amount=1}},starts={{npcID=263442}},ends={{npcID=263442}},coords={x=0.542,y=0.566,source="quest_giver",zoneID=15524},questType="standard"},
[95355] = {id=95355,name="The Messenger",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Namaji in Amani'Zar Village. Perhaps these items should be returned to her.>",rewardGold=34100,rewardXP=1370,ends={{npcID=260721},{npcID=260904}},questType="standard"},
[95373] = {id=95373,name="A Nebulous Endeavour",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,description="I see you haven't come across a Nebulous Voidcore before. I can now weave them for you from the energies of the Catalyst as they accumulate, but you'll have to provide raw reagents. With the Voidcore in hand, you'll have to seek out powerful enemies in order to transmute it into useful equipment. Its capable of capturing part of their essence to become something more powerful that you can put to use in the battles ahead.",rewardGold=1366400,rewardXP=27380,starts={{npcID=243907,x=0.512,y=0.684,zoneID=15458}},ends={{npcID=243907,x=0.512,y=0.684,zoneID=15458}},coords={x=0.512,y=0.684,source="quest_giver",zoneID=15458},questType="world",worldTaskTitle="A Nebulous Endeavour",db2QuestInfoID=282,db2QuestInfoName="Important Quest"},
[95381] = {id=95381,name="Fire in the Sky",expansion=11,mapID=2512,objectivesText="Level 90 Requirements: - Ride the War Eagle - Bone Cages destroyed x 10 - Children of Ula'tek slain x 20 - Children of Ula'tel slain HIDDEN x 99 - Eggs burned x 30 - Serpents slain x 12 - Serpents slain HIDDEN x 99 - Stage 03 Begin Conversation",questType="world",db2Objectives={{orderIndex=1,type=0,amount=10,objectID=260832,text="Bone Cages destroyed"},{orderIndex=4,type=0,amount=30,objectID=260379,text="Eggs burned"},{orderIndex=2,type=0,amount=20,objectID=260869,text="Children of Ula'tek slain"},{orderIndex=5,type=0,amount=12,objectID=260870,text="Serpents slain"},{orderIndex=3,type=0,amount=99,objectID=260869,text="Children of Ula'tel slain HIDDEN"},{orderIndex=6,type=0,amount=99,objectID=260870,text="Serpents slain HIDDEN"},{orderIndex=7,type=0,amount=1,objectID=260927,text="Stage 03 Begin Conversation"},{orderIndex=0,type=0,amount=1,objectID=260380,text="Ride the War Eagle"}},worldTaskTitle="Fire in the Sky",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[95387] = {id=95387,name="One Neighbor's Junk is Another Troll's Treasure",level=25,requiredLevel=25,faction="both",expansion=11,zoneID=16105,mapID=2352,description="Ya be down for helping ol' Griftah out with a little spot of bother? Shajanji be over in the mountains collecting some local rocks. If you could go help her out, I'd be mighty greatful ta ya. Just bring them back ta Griftah . I be keeping them safe for her. I--She needs a lot of them. She be an avid collector.",rewardGold=34100,rewardXP=430,rewardCurrencies={{id=3363,amount=2}},starts={{npcID=260485}},ends={{npcID=260485}},questType="standard"},
[95391] = {id=95391,name="Ritual Site Renowned",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Adventurer you have shown a flair for dealing with these Ritual Sites. It is only appropriate that we should reward you for your continued assistance.",objectivesText="Speak with Lady Darkglen in Silvermoon City.",rewardItems={269234},ends={{npcID=257416}},coords={mapID=2393,source="quest_giver",x=0.478,y=0.496},questType="standard"},
