[95520] = {id=95520,name="Purging the Vaults",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2509,description="De fiends of dis temple would see us all dead. We are all dat stands between them and de mainland, you understand? We hold dem here. Not one scale, not one bony finger, none of them will leave dis temple while we breathe. Get out there and cut them down.",rewardGold=341600,rewardXP=13690,rewardItems={273000,279382},rewardCurrencies={{id=3310,amount=125},{id=3310,amount=187},{id=3316,amount=150},{id=3448,amount=1500}},starts={{npcID=262798,x=0.472,y=0.608,zoneID=16535},{npcID=267635,x=0.586,y=0.458,zoneID=16365}},ends={{npcID=262798,x=0.472,y=0.608,zoneID=16535}},coords={x=0.472,y=0.608,source="quest_giver",zoneID=16535},questType="world",worldTaskTitle="Purging the Vaults",db2QuestInfoID=284,db2QuestInfoName="Meta Quest"},
[95521] = {id=95521,name="The Med'jai Medallion",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16535,mapID=2509,description="Me'si , will know where this came from.>",rewardGold=85400,rewardXP=3420,rewardCurrencies={{id=3316,amount=10},{id=3448,amount=50},{id=3504,amount=50}},starts={{npcID=641565}},ends={{npcID=261659}},coords={x=0.48,y=0.519,source="quest_giver",zoneID=16535},questType="standard"},
[95522] = {id=95522,name="Guardians of Death, Guardians in Stone",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16535,mapID=2509,description="In de legends passed down, dey speak of a group of heroic guardians whose sacrifice protect us to dis day. These honored few, known as de Med'jai, adorned their belts with gems like these--de better to draw their enemies in and defeat dem. We were told dey went on a great expedition to fight de evil abroad, but it seems de greatest of de evils was within--below our feet. Please, , search for dis gem's true home. If our ancestor spirits watch over us, perhaps we will find their resting place.",rewardGold=170800,rewardXP=6850,rewardCurrencies={{id=3316,amount=10},{id=3448,amount=50},{id=3504,amount=50}},starts={{npcID=261659}},ends={{npcID=261659}},coords={x=0.488,y=0.64,source="quest_giver",zoneID=16535},questType="group"},
[95523] = {id=95523,name="Worthy of the Past",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16535,mapID=2509,description="De Soulcoilers must pay, . De Soulcoilers believed their actions saved de Amani. Instead, our people and our future was plundered. We did not realize until it was too late. End them. Shatter their very souls so that even de great Mueh'zala cannot put dem back together.",rewardGold=683200,rewardXP=17110,rewardCurrencies={{id=3316,amount=20},{id=3448,amount=100},{id=3504,amount=100}},starts={{npcID=261895}},ends={{npcID=262281}},questType="group"},
[95524] = {id=95524,name="The Unremembered",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16535,mapID=2509,description="I am not de only Med'jai tasked with keeping sentinel over de priests. There were three of us, entombed in stone that matched how we looked in life. I must know if dey are still there. Can you help me find them? My body is bound in dis stone, but my spirit is not. Bring my gem to those places, if you can find dem. If we cannot wake dem, we will at least honor dem.",rewardGold=341600,rewardXP=13690,rewardCurrencies={{id=3316,amount=10},{id=3448,amount=50},{id=3504,amount=50}},starts={{npcID=261895}},ends={{npcID=262281}},questType="group"},
[95525] = {id=95525,name="A Worthy Vigil",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16535,mapID=2509,description="De temple has changed since I began my watch, . When you first woke me, all I saw was corruption and impure spirits. De consequence of our weakness. Now, I see dat we have not failed. De battlefield has changed, as dey always do. Please take my gem and bring it back to de others like you. Perhaps my spirit can become a force for good on dis new battlefield, in a new way.",rewardGold=85400,rewardXP=3420,rewardItems={280277,280278},rewardChoices={280277,280278},rewardCurrencies={{id=3316,amount=25},{id=3448,amount=250},{id=3504,amount=250}},starts={{npcID=263557}},ends={{npcID=261659}},coords={x=0.392,y=0.482,source="quest_giver",zoneID=16535},questType="standard"},
[95529] = {id=95529,name="Spearin' Sky Snakes",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=16365,mapID=2512,rewardXP=13690,questType="world",worldTaskTitle="Spearin' Sky Snakes",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[95547] = {id=95547,name="Ritual Site Challenge Report: Tendrils",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Lady Darkglen needs to be told to better prepare for countering future Ritual Sites.>",objectivesText="Return your report to Lady Darkglen in Silvermoon City . Progress: What do you have there?",rewardGold=341600,ends={{npcID=257416}},coords={mapID=2393,source="quest_giver",x=0.478,y=0.496},questType="standard"},
[95548] = {id=95548,name="Tainted Sample",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Lady Darkglen would be interested in studying it further.>",objectivesText="Return the tainted sample to Lady Darkglen .",rewardGold=341600,ends={{npcID=257416}},coords={mapID=2393,source="quest_giver",x=0.478,y=0.496},questType="standard"},
[95549] = {id=95549,name="Raising Magical Alarms",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="I have a request. These Ritual Sites invoke some interesting magic. I would like you to obtain some sample readings. You don't need to concern yourself with the details. Just visit the area I will mark on your map and press the button. You may end up garnering some extra attention when you do so.",rewardGold=341600,rewardItems={271094},starts={{npcID=257416,x=0.478,y=0.496,zoneID=15969}},ends={{npcID=257416,x=0.478,y=0.496,zoneID=15969}},coords={x=0.478,y=0.496,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Raising Magical Alarms"},
[95550] = {id=95550,name="Thin Their Ranks",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="I don't like it. We have far too many scouts returning wounded from these so-called ritual sites. Thin out the ranks of these cultists.",rewardGold=341600,starts={{npcID=257411,x=0.48,y=0.496,zoneID=15969}},ends={{npcID=257411,x=0.48,y=0.496,zoneID=15969}},coords={x=0.48,y=0.496,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Thin Their Ranks"},
[95551] = {id=95551,name="Misappropriated Treasures",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Rae'ana .>",objectivesText="Return the stolen treasures to Rae'ana . Progress: Oh? What do you have there?",rewardGold=341600,ends={{npcID=255495}},coords={mapID=2393,source="quest_giver",x=0.478,y=0.505},questType="standard"},
[95552] = {id=95552,name="Dark Obelisk Investigation",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description=", we have reports that the leaders of the Ritual Sites are using dark obelisks to bolster their forces with malevolent boons. I need you to investigate the objects they are using to gain these boons.",rewardGold=341600,starts={{npcID=257416,x=0.478,y=0.496,zoneID=15969}},ends={{npcID=257416,x=0.478,y=0.496,zoneID=15969}},coords={x=0.478,y=0.496,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Dark Obelisk Investigation"},
[95553] = {id=95553,name="Manifested Density",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="I'm hearing strange murmurings from my scouts. Some are claiming that strange manifestations are appearing and cursing intruders. Could I ask you to investigate and see if there is any truth to these rumors?",rewardGold=341600,starts={{npcID=257411,x=0.48,y=0.496,zoneID=15969}},ends={{npcID=257411,x=0.48,y=0.496,zoneID=15969}},coords={x=0.48,y=0.496,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Manifested Density"},
[95554] = {id=95554,name="Questionable Power",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="<This creature was being enhanced by an unknown magic. Perhaps you should gather more of these fragments.>",objectivesText="Collect Fragments of Power. Progress: You have something for me?",rewardGold=341600,ends={{npcID=257416}},coords={mapID=2393,source="quest_giver",x=0.478,y=0.496},questType="standard"},
[95564] = {id=95564,name="The Serpent's Tail",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="De Shadowpine shamans are at our hash'ey's command. We speak de language of fire from de wing of Jan'alai, but we also need help. With de help of the other tribes, we have secured this camp. But we won't hold it for long without your help. I have a few things I would ask you to do, hash'ura, if you are willin'.",rewardGold=341600,rewardXP=13690,rewardItems={271851},rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=259218}},ends={{npcID=259218}},coords={x=0.578,y=0.472,source="quest_giver",zoneID=16365},questType="standard"},
