[95576] = {id=95576,name="Majestic Eagle Statue",level=25,requiredLevel=25,faction="both",expansion=11,zoneID=15524,mapID=2351,description="Ya be down for helping ol' Griftah out with a little spot of bother? Shajanji be over in the mountains collecting some local rocks. If you could go help her out, I'd be mighty greatful ta ya. Just bring them back ta Griftah. I be keeping them safe for her. I--She needs a lot of them. She be an avid collector.",rewardGold=34100,rewardXP=430,rewardItems={269937},starts={{npcID=255213}},ends={{npcID=255213},{npcID=255297}},questType="standard"},
