[95662] = {id=95662,name="A Suspicious Stew",expansion=11,mapID=2512,objectivesText="Level 90 Requirements: - Speak to Witherbark Cook - Prepare a \"Warrior's Meal\" - Recruitment Fliers",questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=208282,text="Speak to Witherbark Cook"},{orderIndex=1,type=0,amount=1,objectID=208283,text="Prepare a \"Warrior's Meal\""}},worldTaskTitle="A Suspicious Stew",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[95673] = {id=95673,name="Suspicious Scare-gull",level=25,requiredLevel=25,faction="both",expansion=11,zoneID=16105,mapID=2352,description="Hey there, could ya help a poor troll down on their luck? I'm looking for some feathers from ya neighborhood. If ya give the birds around here a good scare, they'll take off and drop some, just bring them back here.",rewardGold=341600,rewardXP=3440,rewardItems={270210},rewardCurrencies={{id=3363,amount=1}},starts={{npcID=262234}},ends={{npcID=262234}},coords={x=0.542,y=0.572,source="quest_giver",zoneID=15524},questType="standard"},
[95768] = {id=95768,name="My Stuff's Better Than Your Stuff",level=25,requiredLevel=25,faction="both",expansion=11,zoneID=16105,mapID=2352,description="Hey there, . I set up shop to trade some of our neighborhood goods with our new friends here, and I've been selling like hotcakes! I could use a break though, would you mind watching the shop for me? If any customers come by, just offer them what you think is best.",rewardGold=341600,rewardXP=3440,rewardCurrencies={{id=3363,amount=1}},starts={{npcID=262240},{npcID=262669}},ends={{npcID=262240},{npcID=262669}},coords={x=0.544,y=0.56,source="quest_giver",zoneID=15524},questType="standard"},
[95779] = {id=95779,name="Moments in a Mug",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=10473,mapID=2541,description="A man who knows his way around a drink deserves the finest brew. I have just the thing in mind for my friend, Flynn. The ingredients I need are within my family's brewery in the Valley of Four Winds. I would fetch them myself, but a brewmaster must also know when to sit, breathe, and appreciate what is within the mug. Would you go to Stormstout Brewery and bring those ingredients to me, friend?",rewardItems={275038,278694},starts={{npcID=259343}},ends={{npcID=259343}},coords={x=0.438,y=0.642,source="quest_giver",zoneID=10473},questType="standard"},
[95780] = {id=95780,name="Hope for the Orphans",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=3703,mapID=111,description="Garona and I both don't talk about our childhoods much. There's not a lot worth saying. The children in that orphanage in Shattrath--they're living what we lived. I'm not asking you to fix that. I'm asking you to show up and remind them the world holds something worth fighting for. For me, revenge was worth fighting for. But maybe they can have a brighter future. Go play games with them. Try to show them what a person worth looking up to actually is.",rewardItems={278038},starts={{npcID=259335}},ends={{npcID=259335}},coords={x=0.556,y=0.646,source="quest_giver",mapID=111},questType="standard"},
[95781] = {id=95781,name="No Wax Like Home",level=83,requiredLevel=83,faction="none",expansion=11,zoneID=10473,mapID=2541,questType="standard"},
[95794] = {id=95794,name="De-cryption Process",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=16365,mapID=2512,rewardXP=13690,questType="world",db2Objectives={{orderIndex=0,type=0,amount=6,objectID=262517,text="Spirits de-crypted"}},worldTaskTitle="De-cryption Process",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[95804] = {id=95804,name="The Children of Ula'tek",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="Are these tortollans lost? How long have dey been here? We have a settlement of dem near de Shrine of Filo, but dis is a place dey should not be. A day not long ago, I would have chased dem off. But we've been havin' good luck with outsiders. Zul'jarra 's face. It's the first you've seen since before Malacrass's return.> We should talk to dem. Maybe dey know how dis started.",rewardGold=85400,rewardXP=3420,rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=253528}},ends={{npcID=253528}},coords={x=0.448,y=0.278,source="quest_giver",zoneID=16365},questType="standard"},
[95807] = {id=95807,name="Over Easy",expansion=11,mapID=2512,objectivesText="Level 90 Requirements: - Egg of Ula'tek x 40 - Vilescar Brawler x 25 - Swarming Python x 100 - Dustscale Cobra x 25 - Preying Writhe x 25",questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Cull the Blistering Terrace"}},worldTaskTitle="Over Easy",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[95815] = {id=95815,name="Downhill Jam",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=16900,mapID=2599,rewardXP=8825,questType="world",db2Objectives={{orderIndex=1,type=0,amount=1,objectID=262745,text="Ice Block ridden to the goal"},{orderIndex=0,type=0,amount=1,objectID=262746,text="Ride the Ice Block"}},worldTaskTitle="Downhill Jam",db2QuestInfoID=283,db2QuestInfoName="Bonus Objective with Completion Toast"},
[95842] = {id=95842,name="Midnight: Void Assaults",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Both Void forces and old enemies press us in this turbulent time. We must stay vigilant and let no faction gain a foothold. You must put a stop to these Void assaults! Stay alert, our scouts report some factions may be using the smaller strikes to prepare for a major incursion. If so, I know you will help with the defense.",objectivesText="Complete Void Strikes and Void Incursions in Midnight.",rewardGold=683200,rewardXP=20540,rewardItems={254677,268490,279527,279575},ends={{npcID=256203}},coords={mapID=2393,x=0.49,y=0.646},questType="standard"},
[95843] = {id=95843,name="Midnight: Ritual Sites",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="There have been many enemies that seek to use dark rituals to send horrors our way. The rangers have always risen to challenge and dealt with them. With the pressure on our forces, I must ask you to take up this mission. There are dangerous Ritual Sites that must be disrupted. Our enemies will most likely try again, so you must be dogged and continue to thwart them each time they make the attempt.",objectivesText="Complete Ritual Sites in Midnight.",rewardGold=683200,rewardXP=20540,rewardItems={254677,268490,279527,279575},ends={{npcID=256203}},coords={mapID=2393,x=0.49,y=0.646},questType="standard"},
