[95933] = {id=95933,name="Traces in the Dark",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Champion, Riftblade Maella would like to speak with you again. The dark particles you have brought us, the information you've been gathering on our enemies and the countless victories you have bought for Quel'Thalas have not gone unnoticed. It seems Maella has a plan. Seek her out when you can.",rewardGold=341600,rewardXP=11765,starts={{npcID=263121,x=0.48,y=0.494,zoneID=15969}},ends={{npcID=255368,x=0.274,y=0.766,zoneID=15969},{npcID=263479,x=0.476,y=0.51,zoneID=15969}},coords={x=0.48,y=0.494,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Traces in the Dark"},
