[95954] = {id=95954,name="An Ancient Foe",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16535,mapID=2509,description="You have done well, , but a shadow remains cast over the temple, in the form of the High Priest Jin'tal. A particularly fervent and ambitious priest in life, I am unsurprised that he has survived into undeath. I sense that he practices his abhorrent faith in the nearby Mortuary. Please, . End him. I will help you if I can.",rewardGold=683200,rewardXP=17110,rewardCurrencies={{id=3316,amount=20},{id=3448,amount=100},{id=3504,amount=100}},starts={{npcID=262281}},ends={{npcID=263557}},coords={x=0.44,y=0.56,source="quest_giver",zoneID=16535},questType="group"},
