[96004] = {id=96004,name="Prey: A Slithering Threat",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15958,mapID=2393,description="Do you feel it, $p? We are being watched. I do not know by whom, or to what end, but it appears that our... efforts have drawn fresh attention. Go out and survey the field. Let us test the mettle of these newcomers.",rewardGold=341600,rewardXP=13690,rewardCurrencies={{id=3392,amount=250}},starts={{npcID=246231,x=0.566,y=0.654,zoneID=15969}},ends={{npcID=246231,x=0.566,y=0.654,zoneID=15969}},coords={x=0.566,y=0.654,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Prey: A Slithering Threat",db2QuestInfoID=282,db2QuestInfoName="Important Quest"},
[96017] = {id=96017,name="Temple Patrol: Dragged Below",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=16535,questType="standard",db2Objectives={{orderIndex=0,type=0,amount=5,objectID=263423,text="Desperate Warrior rescued"}},worldTaskTitle="Temple Patrol: Dragged Below",db2QuestInfoID=283,db2QuestInfoName="Bonus Objective with Completion Toast"},
[96029] = {id=96029,name="Special Assignment: Face the Swarm",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=16365,rewardXP=13690,coords={mapID=2512,x=0.712,y=0.154},questType="standard"},
[96048] = {id=96048,name="The Time to Strike",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description=", Your efforts against the recent void and ethereal incursions have paid off. It's time we take the fight to them. Meet me at the Ranger-Captain's strike station in Silvermoon. Do not delay. Riftblade Maella",rewardGold=34100,rewardXP=1470,starts={{npcID=263929,x=0.484,y=0.646,zoneID=15969}},ends={{npcID=263479,x=0.476,y=0.51,zoneID=15969}},coords={x=0.484,y=0.646,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="The Time to Strike"},
[96049] = {id=96049,name="Stalkers of the Stars",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="With the help of Belath Dawnblade and Decimus, we've learned our enemies orchestrate their attacks from former Legion worlds. I've requested the demon hunter's aid in navigating these worlds and fortifying our defenses. Seek them out and lend them any assistance they need. Inform Belath we mobilize soon.",rewardGold=341600,rewardXP=11765,rewardCurrencies={{id=3405,amount=10}},starts={{npcID=263479}},ends={{npcID=263479}},coords={x=0.476,y=0.51,source="quest_giver",zoneID=15969},questType="standard"},
[96051] = {id=96051,name="Through the Cold Rift",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16900,mapID=2599,description="The Legion keystone and the dark particles you found gave us a needle in the endless, vast haystack of the Twisting Nether. With the Cynosure of Twilight, the artifact used to open the way to the Voidstorm, we can thread this needle and open a rift to our enemy's doorstep. With the components in place, my riftwardens stand at the ready. Take up the Cynosure and point and be ready, .",rewardGold=256200,rewardXP=8825,rewardCurrencies={{id=3405,amount=10}},starts={{npcID=263480}},ends={{npcID=263482}},coords={x=0.516,y=0.71,source="quest_giver",zoneID=15458},questType="standard"},
[96052] = {id=96052,name="Through the Mana Rift",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16943,mapID=2600,description="The energy from the Hal'hadar battery core and dark particles allowed us to piece together a faint trail of nether energy. With the Cynosure of Twilight, we can illuminate and ignite this trail, taking us directly to our enemy's doorstep. The anchors are in place and my riftwalkers await your move. Take up the Cynosure and point. Let us see what awaits us on the other side.",rewardGold=322100,rewardXP=11765,starts={{npcID=263480}},ends={{npcID=264024}},coords={x=0.516,y=0.71,source="quest_giver",zoneID=15458},questType="standard"},
[96053] = {id=96053,name="Surveying the Frozen Wastes",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16900,mapID=2599,description="We still hold the element of surprise, which gives us a moment to fortify our position. While Y'mera opens a more stable travel network for the rest of our forces, our scouts have gone ahead to survey the terrain. Meet with them in the field and activate our surveillance beacons. I will remain here to cover the arrival of our reinforcements.",rewardGold=341600,rewardXP=11765,rewardCurrencies={{id=3405,amount=40}},starts={{npcID=263482}},ends={{npcID=263987}},coords={x=0.596,y=0.218,source="quest_giver",zoneID=16900},questType="standard"},
[96054] = {id=96054,name="Surveying the Mana-Bog",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16943,mapID=2600,description="Our sudden arrival allows us a brief moment to fortify our hold here. While Y'mera works on bringing the rest of our forces through a more stable network, our scouts have gone ahead to survey the terrain and the enemy. Meet with them in the field and activate our surveillance beacons. I will remain here with Y'mera and Decimus should any of those skiffs overhead decide to pay us a visit.",rewardGold=341600,rewardXP=11765,rewardCurrencies={{id=3405,amount=40}},starts={{npcID=264024}},ends={{npcID=264028}},coords={x=0.484,y=0.82,source="quest_giver",zoneID=16943},questType="standard"},
[96066] = {id=96066,name="Slithering Surveyor",expansion=11,mapID=2512,objectivesText="Level 90 Requirements: - Ride the Cataloger's Disc - Common x 100 - Rare x 25 - Epic x 12 - Legendary x 6",questType="world",db2Objectives={{orderIndex=0,type=3,amount=1,objectID=263538,text="Ride the Cataloger's Disc"},{orderIndex=1,type=15,amount=1,objectID=0,text="Take Pictures of Wildlife"},{orderIndex=2,type=0,amount=100,objectID=263511,text="Common"},{orderIndex=3,type=0,amount=25,objectID=263512,text="Rare"},{orderIndex=4,type=0,amount=12,objectID=263513,text="Epic"},{orderIndex=5,type=0,amount=6,objectID=263514,text="Legendary"}},worldTaskTitle="Slithering Surveyor",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[96080] = {id=96080,name="Void Strike",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="We have reports of new void strikes occurring around Eversong Forest and Zul'Aman. We need you to head out immediately to investigate one of these strikes. I will mark your map with the latest location from our scouts.",objectivesText="Investigate a Void Strike. Progress: What do you have to report?",rewardGold=341600,rewardXP=11765,rewardItems={264914,272125},starts={{npcID=257411}},ends={{npcID=257411}},coords={x=0.48,y=0.496,source="quest_giver",zoneID=15969},questType="standard"},
[96089] = {id=96089,name="Somethin's Not Right",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="Whatever's wrong with her, whatever those creatures did, I need her healed! Will you help?",rewardGold=170800,rewardXP=6850,rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=263618}},ends={{npcID=253837}},coords={x=0.57,y=0.48,source="quest_giver",zoneID=16365},questType="standard"},
[96090] = {id=96090,name="Venemetic",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="I have the other ingredients for the emetic here. The last ingredient I need is some venom to trigger a response. I overheard the trolls talk about a place just to the north called the Serpent's Tail. They say it's chock-full of venomous baddies, but we only need the poison from the Children of Ula'tek. They say there are even rivers full of the caustic stuff, but don't go swimming in them. They're too concentrated and will eat right through the collection bottle before you can scream, \"I'm melting!\"",rewardGold=341600,rewardXP=13690,rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=253837}},ends={{npcID=253837}},coords={x=0.572,y=0.484,source="quest_giver",zoneID=16365},questType="standard"},
[96091] = {id=96091,name="Get the Balance Right",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="I've set up three bottles with different ingredients. All you have to do is add just the right amount... just a dash of venom to each. Balance them out. You can use Ofi's cauldron right over there. I'm sure she won't mind. Whatever's in there has likely been bubbling since before she was born. No, I'm not going to do it for you. I've lived long enough to know not to touch that stuff! Once you have the results, give the emetic to your medic friend and we'll see what happens.",rewardGold=170800,rewardXP=6850,rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=253837}},ends={{npcID=253837}},coords={x=0.572,y=0.484,source="quest_giver",zoneID=16365},questType="standard"},
[96092] = {id=96092,name="That Fool, Ruma",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="Unfortunately, this has moved beyond my area of expertise. Fortunately, I know someone who can help. Probably. Unfortunately, he left for some \"great adventure\" on Gnarldor Isle to the south. More likely, he's on a great bender. Here, take this elixir and give it to our former ship's doctor, Ruma. I always like to keep one handy. It'll sober him right up. Then it's on you to convince him to devise a cure. Good luck!",rewardGold=170800,rewardXP=6850,rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=253837}},ends={{npcID=263663}},coords={x=0.572,y=0.484,source="quest_giver",zoneID=16365},questType="standard"},
[96093] = {id=96093,name="It's a Satchel, Not a Bag",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="Well, you see, I was on quite the adventure with my friend, Tormunda, and a few others. Seeing the world, sipping exotic drinks, rest and relaxation. But then, disaster struck our camp. Gnarldin! We were separated and I did what you're supposed to do when you're lost: stay where you are. So, I've been resting here. But I'm afraid in all the commotion, I left my satchel behind. It has all of my best things in it. So you see, if you want my help, you'll have to go and get it for me.",rewardGold=683200,rewardXP=17110,rewardItems={274486},rewardCurrencies={{id=3316,amount=20},{id=3504,amount=100}},starts={{npcID=263663}},ends={{npcID=263663}},coords={x=0.646,y=0.774,source="quest_giver",zoneID=16365},questType="standard"},
[96094] = {id=96094,name="To the Forum",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="If we're to help this La'una of yours, we need to go to the source. You said they were scouting the western ledge of the Fangs when all of this happened? Everyone knows you don't go there. We should NOT go out there. But, that is precisely where we must go because that's where we'll find the cure. Or, meet our demise. Whichever comes first.",rewardGold=34100,rewardXP=1370,rewardCurrencies={{id=3316,amount=5},{id=3504,amount=10}},starts={{npcID=263663}},ends={{npcID=263674}},coords={x=0.646,y=0.774,source="quest_giver",zoneID=16365},questType="standard"},
[96095] = {id=96095,name="Sampling the Local Wildlife",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="If I'm going to devise a cure, I need samples and plenty of them. Lucky for us we have the two things we need: You and all of the infected wildlife roaming throughout this place.",rewardGold=341600,rewardXP=13690,rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=263674}},ends={{npcID=263674}},coords={x=0.238,y=0.644,source="quest_giver",zoneID=16365},questType="standard"},
[96096] = {id=96096,name="Scout Team Seven",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="When we first came out here our leader, Dusk Prowler Hano'mon , took de team too far in. He always was a... not very well-liked. I was scoutin' de rear and by de time I came across La'una, she was already affected by whatever dis is. It's possible de rest of my scout team is still out there. If dey are, I need to know their fate, one way or de other. Their names are A'pone, Kamaina, Ko'ruku, Uha'ne, and Hano'mon.",rewardGold=341600,rewardXP=13690,rewardItems={281226},rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=263675}},ends={{npcID=263675}},coords={x=0.238,y=0.646,source="quest_giver",zoneID=16365},questType="standard"},
[96097] = {id=96097,name="What the Scouts Saw",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="If my guess is correct, I think I know what we're missing. Would you be so kind as to ask these scouts about what they've seen while they were out there? I suspect they already know what, or who, is behind all of this.",rewardGold=170800,rewardXP=6850,rewardItems={281244},rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=263674}},ends={{npcID=263675}},coords={x=0.238,y=0.644,source="quest_giver",zoneID=16365},questType="standard"},
[96098] = {id=96098,name="The Final Reagents",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="I saw de Children of Ula'tek as well, . Dey both are conjurin' in their separate towers out there. Now it's time to put an end to de threat. We can't have dem comin' out of de Vaults of Atal'Utek and spreadin' dis infection all over Zul'Aman... or farther. And don't forget about de reagents de doctor needs!",rewardGold=683200,rewardXP=17110,rewardCurrencies={{id=3316,amount=20},{id=3504,amount=100}},starts={{npcID=263675}},ends={{npcID=263674}},coords={x=0.238,y=0.646,source="quest_giver",zoneID=16365},questType="standard"},
[96099] = {id=96099,name="La'una's Fate",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="The prescription is ready. Now all we have to do, all YOU have to do, is give it to the patient. Don't worry, it'll work. I'm sure of it. Well, I'm mostly sure. Let's say, sixty-seven percent certain. Those are pretty good odds considering the alternative.",rewardGold=170800,rewardXP=6850,rewardItems={280218},rewardCurrencies={{id=3316,amount=25},{id=3504,amount=250}},starts={{npcID=263674}},ends={{npcID=263618}},coords={x=0.238,y=0.644,source="quest_giver",zoneID=16365},questType="standard"},
[96110] = {id=96110,name="Venom Fishing: Proof is in the Ooze",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="If ye mean to be part of my crew, ye best be ready to handle the venom curse. Know how to fish? Every creature with gills on this isle is ready to sink its teeth into you. Prove ye can fish up even the smallest of the venom-cursed fish and I'll show ye how to take on deadlier and nastier fishin'.",rewardGold=341600,rewardXP=13690,rewardCurrencies={{id=3316,amount=10},{id=3540,amount=100}},starts={{npcID=258755}},ends={{npcID=258755}},coords={x=0.572,y=0.486,source="quest_giver",zoneID=16365},questType="standard"},
[96111] = {id=96111,name="Venom Fishing: Shell of Yourself",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="You've learned some o' my secrets to fishin' in these cursed waters, but everything ye learn from here on serves a greater purpose than survival. Revenge. The Great White Serpent that sank my ship is still alive. If we intend to kill it, we need the power o' my crew, now lost to the venom-curse. Master Grenadier Birdie has one good shot: her first shot. Build yerself a decoy and you'll have a chance to kill her. Take her explosives. We'll need 'em to blow that snake to smithereens.",rewardGold=683200,rewardXP=17110,rewardItems={274033},rewardCurrencies={{id=3316,amount=10},{id=3540,amount=150}},starts={{npcID=258755}},ends={{npcID=258755}},coords={x=0.572,y=0.486,source="quest_giver",zoneID=16365},questType="standard"},
[96112] = {id=96112,name="Venom Fishing: Maddening Concoction",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="We need somethin' to protect that shell-less back o' yers when we face the Great White Serpent. Leathertongue made dishes that made us immune to nigh anything, this being on account o' them nearly killin' us every mealtime! His pots and pans could withstand any nightmare. We need that strength. The key to defeating the cook is to challenge his skill. Make a dish of the foulest ingredients and he'll be there to face ye.",rewardGold=683200,rewardXP=17110,rewardCurrencies={{id=3316,amount=10},{id=3540,amount=200}},starts={{npcID=258755}},ends={{npcID=258755}},coords={x=0.572,y=0.486,source="quest_giver",zoneID=16365},questType="standard"},
[96113] = {id=96113,name="Venom Fishing: Maximum Potency",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=16365,mapID=2512,description="We're almost ready to face the Great White Serpent. We only need one more thing. I want ye to take my quartermaster's boat. Inktail has plans on plans. Before the venom, she was cool and reserved even in the wildest storms. With the venom curse, she's become even more elusive. I've only seen her lose her deadly composure once. She has a mighty love of rare fish. It's a gamble, but go into the temple and find a fish overwhelmed with venom. It may be enough to draw her out of hidin'.",rewardGold=683200,rewardXP=17110,starts={{npcID=258755}},ends={{npcID=258755}},questType="standard"},
[96114] = {id=96114,name="A Small Pouch of Crystals",level=70,requiredLevel=70,faction="both",expansion=11,zoneID=15347,mapID=2346,rewardCurrencies={{id=2815,amount=250}},starts={{npcID=231409}},ends={{npcID=231409}},coords={x=0.436,y=0.508,source="quest_giver",mapID=2346},questType="standard"},
[96115] = {id=96115,name="A Small Pouch of Crystals",level=70,requiredLevel=70,faction="both",expansion=11,zoneID=15347,mapID=2346,rewardCurrencies={{id=2815,amount=250}},starts={{npcID=231409}},ends={{npcID=231409}},coords={x=0.436,y=0.508,source="quest_giver",mapID=2346},questType="standard"},
[96116] = {id=96116,name="A Cache of Crystals",level=70,requiredLevel=70,faction="both",expansion=11,zoneID=14752,mapID=2255,rewardCurrencies={{id=2815,amount=250}},starts={{npcID=223750}},ends={{npcID=220867},{npcID=223750}},coords={x=0.552,y=0.412,source="quest_giver",mapID=2255},questType="standard"},
