[96210] = {id=96210,name="Scrubbing Troubles",expansion=11,mapID=2600,objectivesText="Level 80 Requirements: - Infected Aberrations slain x 15",questType="world",db2Objectives={{orderIndex=0,type=0,amount=15,objectID=263968,text="Infected Aberrations slain"}},worldTaskTitle="Scrubbing Troubles",db2QuestInfoID=296,db2QuestInfoName="World Quest (Short Duration)"},
[96217] = {id=96217,name="Sporadic Power Drain",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=16943,mapID=2600,rewardXP=11765,rewardItems={272975},questType="world",db2Objectives={{orderIndex=0,type=14,amount=1,objectID=230010,text="Hal'hadar Keeper Keycodes acquired"},{orderIndex=1,type=0,amount=10,objectID=264061,text="Spore Motes freed"}},worldTaskTitle="Sporadic Power Drain",db2QuestInfoID=296,db2QuestInfoName="World Quest (Short Duration)"},
[96223] = {id=96223,name="The Magisters' Call",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="The Magisters request your presence at Thalassian University. Please proceed to the upper levels overlooking the harbor. This concerns a private matter of minor urgency.",rewardGold=34100,rewardXP=1370,starts={{npcID=265903,x=0.478,y=0.516,mapID=2393}},ends={{npcID=264063,x=0.388,y=0.486,mapID=2393},{npcID=264064,x=0.388,y=0.486,mapID=2393}},coords={x=0.478,y=0.516,source="quest_giver",mapID=2393},questType="world",worldTaskTitle="The Magisters' Call",db2QuestInfoID=282,db2QuestInfoName="Important Quest"},
[96224] = {id=96224,name="The Magisters' Conundrum",level=80,requiredLevel=80,faction="alliance",expansion=11,zoneID=17067,mapID=2649,description="Magisters' Terrace is home to many mysterious artifacts. Among them is a relic once central to our pursuit of magical knowledge. A few years ago, the relic fell into a state of dormancy. After the Dawnwell reignited, this artifact began to stir. Upon returning it to the Lycaneum for study, the relic unleashed chaos upon the library. I believe your unique expertise may be helpful in quelling this chaos.",rewardGold=34100,rewardXP=1470,starts={{npcID=264063}},ends={{npcID=264066}},coords={x=0.388,y=0.486,source="quest_giver",zoneID=15969},questType="standard"},
[96225] = {id=96225,name="The Magisters' Conundrum",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=17067,mapID=2649,description="For the last few decades, a dormant artifact laid beneath the halls of Magisters' Terrace. Once serving as a beacon of knowledge to the Magisters, the artifact abruptly fell silent some decades ago. After the Dawnwell's rebirth, the artifact reawakened. When we returned it to the Lycaneum for study, it unleashed chaos upon the library. Your assistance, and discretion, would be most appreciated.",rewardGold=34100,rewardXP=1470,starts={{npcID=264064}},ends={{npcID=264065}},coords={x=0.388,y=0.486,source="quest_giver",zoneID=15969},questType="standard"},
[96226] = {id=96226,name="Omnium Anomalies",level=80,requiredLevel=80,faction="alliance",expansion=11,zoneID=16215,mapID=2424,description="Shortly after the Omnium awoke, it began manifesting arcane anomalies around the Lycaneum. We believe these anomalies to be malfunctioning security protocols--the hostile projections they conjure can be quite lethal. If we do not dispatch them quickly, they will continue to manifest. As you deal with them, keep an eye out for anything peculiar that can help us understand the Omnium's current state.",rewardGold=341600,rewardXP=11765,rewardCurrencies={{id=3316,amount=150}},starts={{npcID=264065}},ends={{npcID=264065}},coords={x=0.624,y=0.154,source="quest_giver",mapID=2424},questType="standard"},
[96227] = {id=96227,name="Lycaneum Chaos",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=17067,mapID=2649,description="When the Omnium began to stir in its vault, we thought to move it here for observation. Evidently, this was a bad idea. The arcane magics seeping out are causing chaos. Folios casting all sorts of incomplete spells, arcane sparks running amok--even the candle flames have sprung to life! But we cannot simply destroy them, as the magics here are too volatile. I have procured a ward-lance from the arsenal of the spellbreakers. It will dispel the volatile magic. Here, take it. And do be careful.",rewardGold=341600,rewardXP=11765,rewardCurrencies={{id=3316,amount=150}},starts={{npcID=264066}},ends={{npcID=264066}},coords={x=0.636,y=0.166,source="quest_giver",zoneID=17067},questType="standard"},
[96228] = {id=96228,name="The Shadowed Spire",level=80,requiredLevel=80,faction="alliance",expansion=11,zoneID=15968,mapID=2395,description="Time and time again, Dar'Khan continues to haunt us in some form. To think the Omnium also fell prey to his madness... If he really severed the Void Magicule from the Omnium, then I have no doubt he would have hidden it well. I have a suspicion I know where to start looking. Meet me at Dawnstar Spire in Eversong Woods.",rewardGold=256200,rewardXP=8825,rewardCurrencies={{id=3316,amount=100}},starts={{npcID=264065}},ends={{npcID=264067}},coords={x=0.624,y=0.154,source="quest_giver",mapID=2395},questType="standard"},
[96229] = {id=96229,name="The Void Reveals",level=80,requiredLevel=80,faction="alliance",expansion=11,zoneID=15968,mapID=2395,description="After reclaiming Silvermoon, the Magisters torched Dar'Khan's personal study and dwellings within the city walls. I had thought I had found everything I needed the first time I searched this place, but now... It seems that Dar'Khan left some secrets. This portal will take us to them. I do not know what we will find on the other side. Be on your guard.",rewardGold=683200,rewardXP=14705,rewardItems={274036},rewardCurrencies={{id=3316,amount=400}},starts={{npcID=264067}},ends={{npcID=269814}},coords={x=0.626,y=0.63,source="quest_giver",mapID=2395},questType="standard"},
[96230] = {id=96230,name="Unraveling the Wards",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16215,mapID=2424,description="The Magicules, the orbs you see on the relic, were never meant to be severed from the Omnium. By tearing one out, Dar'Khan likely sent the artifact into a frenzied state before it shut down. Even if the Void Magicule is restored, the Omnium will need recalibrating. We will need Belo'vir's key-cipher, now my key-cipher, to do this. I will meet you at my study and we can recover it.",rewardGold=341600,rewardXP=11765,rewardCurrencies={{id=3316,amount=150}},starts={{npcID=264066}},ends={{npcID=264945}},coords={x=0.636,y=0.166,source="quest_giver",mapID=2424},questType="standard"},
[96231] = {id=96231,name="The Grand Magister's Key-Cipher",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16215,mapID=2424,description="After Belo'vir's death, I contemplated opening this vault. I talked myself out of it. A key for a shattered lock serves no purpose. And yet, even as Kael'thas tried to open it with his key, I couldn't help but wonder... It doesn't matter, . I am nearly done with the master ward on the upper floor. Meet me there. No doubt, Belo'vir took extra steps to safeguard his vault.",rewardGold=341600,rewardXP=11765,rewardItems={274261},starts={{npcID=264945}},ends={{npcID=264944}},coords={x=0.588,y=0.574,source="quest_giver",mapID=2424},questType="standard"},
[96232] = {id=96232,name="Return to the Omnium",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=17067,mapID=2424,description="Well, now that we've recovered the piece Dar'Khan stole, we are one step closer to restoring the Omnium. Hopefully your endeavor with Rommath was a little less troublesome? When you're ready, return to the Magisters' Terrace. I will clean up anything left behind here and join you shortly.",rewardGold=85400,rewardXP=2940,starts={{npcID=269814}},ends={{npcID=264066}},coords={x=0.624,y=0.626,source="quest_giver",zoneID=15968},questType="standard"},
[96233] = {id=96233,name="The Omnium Reawakens",level=80,requiredLevel=80,faction="alliance",expansion=11,zoneID=17067,mapID=2424,description="For years, as Silvermoon and its people changed, this relic sat in a vault beneath the Terrace, unresponsive and dormant. We may never truly understand why the relic fell silent when it did or why it refused the prince's call, but perhaps in time, we might. Let us hope the missing Magicule and the key-cipher will be enough to restore it. Are you ready, ?",rewardGold=309800,rewardXP=11765,rewardCurrencies={{id=3316,amount=250}},starts={{npcID=264066}},ends={{npcID=264069}},coords={x=0.636,y=0.166,source="quest_giver",zoneID=17067},questType="standard"},
[96238] = {id=96238,name="Return to the Omnium",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=17067,mapID=2424,description="With Belo'vir's key-cipher recovered and Umbric in possession of the Void Magicule, we should return to the Lycaneum. Hopefully we have all that we need to recalibrate the Sunstrider Omnium. I will meet you back in the Magisters' Terrace when I am done here.",rewardGold=85400,rewardXP=2940,starts={{npcID=264944}},ends={{npcID=264066}},coords={x=0.59,y=0.592,source="quest_giver",zoneID=16215},questType="standard"},
[96242] = {id=96242,name="An Easy Path to Trickery",level=0,requiredLevel=0,faction="both",expansion=11,zoneID=15969,mapID=2393,description="You can always speak to me to enter a game of Decor Duel, but did you know there's an easier way? If there's a group you want to find, we have \"magic\" to help!",objectivesText="Use Group Finder to get into a Decor Duel game. <Group Finder -> Player vs. Player -> Decor Duel> Progress: You're on the easy path to Trickery? Good luck! <use Group Finder to play a PvP Decor Duel match.> <If you abandon her quest, or complete it, you may re-enter Decor Duel through Amolene again>",starts={{npcID=257125}},ends={{npcID=257125}},coords={x=0.314,y=0.766,source="quest_giver",zoneID=15969},questType="standard"},
[96245] = {id=96245,name="You've Seen it All Before",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Soridormi to visit her at the Wayfarer's Rest in Silvermoon City .>",objectivesText="Visit Soridormi at the Wayfarer's Rest in Silvermoon City .",rewardGold=34100,ends={{npcID=259153}},coords={mapID=2393,source="quest_giver",x=0.556,y=0.698},questType="standard"},
[96267] = {id=96267,name="Ancestral Gems",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16535,mapID=2509,description="When de Children of Ula'tek seized dis temple, many of my ancestors died defendin' it. Sacred relics were seized by de snakes! Even now, dey twist those items into foul magic! Among these items were some gems of great power. Search de vaults, ritual chambers, and every deep corner of de temple and recover any gems you find.",rewardGold=341600,rewardXP=13690,rewardItems={273303},rewardCurrencies={{id=3448,amount=350}},starts={{npcID=264611,x=0.504,y=0.638,zoneID=16535}},ends={{npcID=264611,x=0.504,y=0.638,zoneID=16535}},coords={x=0.504,y=0.638,source="quest_giver",zoneID=16535},questType="world",worldTaskTitle="Ancestral Gems",db2QuestInfoID=1,db2QuestInfoName="Group"},
[96268] = {id=96268,name="Marsh Mana Spores",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=16943,mapID=2600,rewardXP=11765,rewardItems={276276},questType="world",db2Objectives={{orderIndex=1,type=1,amount=5,objectID=276276,text="Mana Spores gathered"},{orderIndex=0,type=0,amount=1,objectID=264323,text="Jump on a Bouncy Mushroom"}},worldTaskTitle="Marsh Mana Spores",db2QuestInfoID=296,db2QuestInfoName="World Quest (Short Duration)"},
[96271] = {id=96271,name="Cursed Existence",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=16535,mapID=2509,description="When de poison spread through dis temple, many of our ancestors fell trying to defend dis place. Now Nek'zali has ensnared their spirits to serve her in restoring Ula'tek. Put de cursed spirits to rest so dey may pass beyond dis place.",rewardGold=683200,rewardXP=17110,questType="world",worldTaskTitle="Cursed Existence",db2QuestInfoID=1,db2QuestInfoName="Group"},
[96272] = {id=96272,name="Mashing Mushroom Mana Machines",expansion=11,mapID=2600,objectivesText="Level 80 Requirements: - Harvesting Machines deactivated x 8",questType="world",db2Objectives={{orderIndex=0,type=2,amount=8,objectID=651860,text="Harvesting Machines deactivated"}},worldTaskTitle="Mashing Mushroom Mana Machines",db2QuestInfoID=296,db2QuestInfoName="World Quest (Short Duration)"},
[96273] = {id=96273,name="A Balance Paid in Blood",level=90,requiredLevel=90,faction="alliance",expansion=11,zoneID=16535,mapID=2509,description="De Children of Ula'tek have upset de balance of de spirit world. Many spirits are angry and demand justice before dey can move on. De snakes' blood will restore de balance! Slay de Children of Ula'tek and all dat aid dem here in de temple.",rewardGold=341600,rewardXP=13690,starts={{npcID=264611,x=0.504,y=0.638,zoneID=16535}},ends={{npcID=264611,x=0.504,y=0.638,zoneID=16535}},coords={x=0.504,y=0.638,source="quest_giver",zoneID=16535},questType="world",worldTaskTitle="A Balance Paid in Blood",db2QuestInfoID=1,db2QuestInfoName="Group"},
[96275] = {id=96275,name="Wading In",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16535,mapID=2509,description="Too many spirits here have succumbed to de dark charms of Nek'zali, but there's still hope to save others. Place spirit guardians throughout de lakes of venom so dey may offer sanctuary to spirits nearby. De venom lakes are deadly, so go prepared!",rewardGold=341600,rewardXP=13690,rewardItems={274422},rewardCurrencies={{id=3310,amount=100},{id=3310,amount=150},{id=3448,amount=250},{id=3448,amount=350}},starts={{npcID=264611,x=0.504,y=0.638,zoneID=16535}},ends={{npcID=264611,x=0.504,y=0.638,zoneID=16535}},coords={x=0.504,y=0.638,source="quest_giver",zoneID=16535},questType="world",worldTaskTitle="Wading In",db2QuestInfoID=1,db2QuestInfoName="Group"},
[96276] = {id=96276,name="Dark Charms",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16535,mapID=2509,description="De Children of Ula'tek play cruel games on de spirits here. Dey use dark charms to keep dem trapped and tormented. De charms are hidden throughout de temple. Find and burn them, so de spirits here can find peace.",rewardGold=341600,rewardXP=13690,rewardItems={274422},rewardCurrencies={{id=3310,amount=100},{id=3310,amount=150},{id=3316,amount=50},{id=3448,amount=200}},starts={{npcID=264611,x=0.504,y=0.638,zoneID=16535}},ends={{npcID=264611,x=0.504,y=0.638,zoneID=16535}},coords={x=0.504,y=0.638,source="quest_giver",zoneID=16535},questType="world",worldTaskTitle="Dark Charms",db2QuestInfoID=1,db2QuestInfoName="Group"},
[96293] = {id=96293,name="Mush-Vroom!",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=17103,mapID=2600,rewardXP=11765,questType="world",db2Objectives={{orderIndex=0,type=0,amount=6,objectID=264835,text="Batteries thrown at volatile mushrooms"}},worldTaskTitle="Mush-Vroom!",db2QuestInfoID=296,db2QuestInfoName="World Quest (Short Duration)"},
[96295] = {id=96295,name="A Pertinent Punishment",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=16900,mapID=2618,rewardXP=14705,questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=265527,text="Portal entered"}},worldTaskTitle="A Pertinent Punishment",db2QuestInfoID=289,db2QuestInfoName="World Boss"},
[96305] = {id=96305,name="The Innocent Essence",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=16535,mapID=2509,description="When de defenders fell, cursed to their fate, so too did de great eagle Tok'jara who flew with dem. Such innocence did not deserve dis curse. Even now, de spirit struggles to break free, forming a twisting geyser as it rises from the venomous pools. Help it be free, claim its essence from the poison, and end its suffering.",rewardGold=341600,rewardXP=13690,rewardItems={273838},questType="world",worldTaskTitle="The Innocent Essence",db2QuestInfoID=1,db2QuestInfoName="Group"},
[96307] = {id=96307,name="Special Assignment: Wraith Wrath",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=16365,rewardXP=13690,questType="standard"},
[96310] = {id=96310,name="Disrupting the Order",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16900,mapID=2599,description="Great work defeating their forces. Every step we take will keep Azeroth safe. But usurpers are still trying to seize control. Baraat has already spotted high ranking domanaar looking at the remaining resources. We need to defeat the Umbrawardens and any of their forces along the way.",rewardGold=341600,rewardXP=11765,rewardCurrencies={{id=3405,amount=25}},starts={{npcID=263482}},ends={{npcID=265166}},coords={x=0.596,y=0.218,source="quest_giver",zoneID=16900},questType="standard"},
[96329] = {id=96329,name="Hexes and Hoaxes",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=16365,mapID=2642,rewardXP=13690,questType="world",db2Objectives={{orderIndex=1,type=19,amount=0,objectID=42836,text="Crypt escaped"},{orderIndex=0,type=19,amount=0,objectID=44280,text="Stairs found"}},worldTaskTitle="Hexes and Hoaxes",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[96338] = {id=96338,name="Port of Entry",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16900,mapID=2619,description=", take a look at that platform above. What do you think they use that for? The void creatures steal wildlife from Azeroth and move them here to be broken, then added to their forces. That platform must be where creatures are first brought in. Let's force our way through any defenses up there and destroy that portal!",rewardGold=341600,rewardXP=11765,rewardCurrencies={{id=3405,amount=25}},starts={{npcID=265166}},ends={{npcID=265166}},coords={x=0.668,y=0.425,source="quest_giver",zoneID=16900},questType="standard"},
[96349] = {id=96349,name="Ancestral Gems",expansion=11,mapID=2509,objectivesText="Level 90 Recover 30 Ritual Gems from the deepest interiors of the Vaults of Atal'Utek. Requirements: - Ritual Gem x 30",questType="world",worldTaskTitle="Ancestral Gems",db2QuestInfoID=1,db2QuestInfoName="Group"},
[96352] = {id=96352,name="Dark Charms",expansion=11,mapID=2509,objectivesText="Level 90 Burn 20 Dark Charms found throughout the Vaults of Atal'Utek. Requirements: - Dark Charms destroyed x 20",questType="world",worldTaskTitle="Dark Charms",db2QuestInfoID=1,db2QuestInfoName="Group"},
[96354] = {id=96354,name="A Balance Paid in Blood",expansion=11,mapID=2509,objectivesText="Level 90 Slay enemies within the Vaults of Atal'Utek.",questType="world",worldTaskTitle="A Balance Paid in Blood",db2QuestInfoID=1,db2QuestInfoName="Group"},
[96360] = {id=96360,name="Wading In",expansion=11,mapID=2509,objectivesText="Level 90 Place 8 Spirit Guardians at locations in the venom. Requirements: - Spirit Guardians placed x 8 - Anti-venom shield used in Deadly Venom",questType="world",worldTaskTitle="Wading In",db2QuestInfoID=1,db2QuestInfoName="Group"},
[96361] = {id=96361,name="Cursed Existence",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=16535,mapID=2509,description="When de poison spread through dis temple, many of our ancestors fell trying to defend dis place. Now Nek'zali has ensnared their spirits to serve her in restoring Ula'tek. Put de cursed spirits to rest so dey may pass beyond dis place.",rewardGold=683200,rewardXP=17110,questType="world",worldTaskTitle="Cursed Existence",db2QuestInfoID=1,db2QuestInfoName="Group"},
[96382] = {id=96382,name="A New Approach",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16900,mapID=2618,description="For this threat, you'll need to think more like the domanaar. Luckily, I can do just that. What we need is a puppet. Someone we can give the reins who has no aspirations for your precious Azeroth. Those new domanaar you saw will need evaluation. Take this veil. You'll be able to blend in and observe them. I understand your urge to strike, but be patient. The time will come to eliminate all in your path, as your kind seems to enjoy. See if you can find a proper candidate.",rewardGold=341600,rewardXP=11765,rewardItems={275667},rewardCurrencies={{id=3405,amount=20}},starts={{npcID=264879}},ends={{npcID=264879}},coords={x=0.598,y=0.218,source="quest_giver",zoneID=16900},questType="standard"},
[96388] = {id=96388,name="Joining the Abyss Anglers",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Ya ever heard of de Abyss Anglers? Forest tribes have been hunting de land as well as de waters for generations. Don't be shy, hash'ura. Grab a suit and go for a dive!",rewardGold=341600,rewardXP=11765,rewardCurrencies={{id=3373,amount=100}},starts={{npcID=240195,x=0.682,y=0.202,zoneID=15947}},ends={{npcID=240195,x=0.682,y=0.202,zoneID=15947}},coords={x=0.682,y=0.202,source="quest_giver",zoneID=15947},questType="world",worldTaskTitle="Joining the Abyss Anglers"},
[96389] = {id=96389,name="A Place to Negotiate",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16900,mapID=2599,description="While you were attuning the gem to the Void, I managed to acquire one of Impotus's projection devices. We're going to use it to lure him to us, then prevent him from escaping with the gem. Not here, though. Let us find somewhere more discrete.",rewardGold=170800,rewardXP=5885,rewardCurrencies={{id=3405,amount=5}},starts={{npcID=265334}},ends={{npcID=267877}},questType="standard"},
[96400] = {id=96400,name="Lingering Corruption",expansion=11,mapID=2599,objectivesText="Level 80 Requirements: - Portal entered - Unstable Void Energy investigated - Fel Corrupted enemies smashed x 30",questType="world",db2Objectives={{orderIndex=1,type=0,amount=1,objectID=264975,text="Unstable Void Energy investigated"},{orderIndex=2,type=0,amount=30,objectID=264974,text="Fel Corrupted enemies smashed"},{orderIndex=0,type=0,amount=1,objectID=265503,text="Portal entered"}},worldTaskTitle="Lingering Corruption",db2QuestInfoID=296,db2QuestInfoName="World Quest (Short Duration)"},
[96410] = {id=96410,name="Seeking Knowledge Week 1 of 5: The Omnium Folio",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=17067,mapID=2649,description="Those who sought to learn from the Omnium had to contribute to it. While most Magisters studied within the Terrace, a select few were appointed as \"Seekers of Wisdom.\" Seekers would search for new and foreign magic to contribute to the Omnium's vast index for study. Given your... adventurous experience, I think you'd make an excellent seeker. If you're interested, the Grand Magister will explain more.",rewardGold=170800,rewardXP=6850,starts={{npcID=264069}},ends={{npcID=264070}},coords={x=0.604,y=0.112,source="quest_giver",zoneID=17067},questType="standard"},
[96432] = {id=96432,name="Power Overload",expansion=11,mapID=2600,objectivesText="Level 80 Requirements: - Fungal Processors overloaded x 12",rewardItems={274407},questType="world",db2Objectives={{orderIndex=0,type=0,amount=12,objectID=265079,text="Fungal Processors overloaded"}},worldTaskTitle="Power Overload",db2QuestInfoID=296,db2QuestInfoName="World Quest (Short Duration)"},
[96433] = {id=96433,name="Not the Mama",expansion=11,mapID=2599,objectivesText="Level 80 Requirements: - Assault defeated",questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=265072,text="Assault defeated"}},worldTaskTitle="Not the Mama",db2QuestInfoID=283,db2QuestInfoName="Bonus Objective with Completion Toast"},
[96439] = {id=96439,name="Gone Dark",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="These infernal nests are where de Children of Ula'tek spawn from. We must work to clear dem out if we are to have any hope of stemming de endless tide of snakes. I have been sending groups of my most fearless scouts to gather information on dem. All have returned... except for one. Go, track down Ulantu and Naj'kula in de Blistering Terrace. Find out why dey gone dark.",rewardGold=34100,rewardXP=1370,starts={{npcID=265173}},ends={{npcID=265173}},coords={x=0.578,y=0.466,source="quest_giver",zoneID=16365},questType="standard"},
[96440] = {id=96440,name="Victory Within Hindsight",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16900,mapID=2599,description="Great work, ! I can already picture the walls of the Acropolis crumbling. In fact, why don't we head there now and press our advantage? The Light can shine through the tiniest of cracks. I'll scout ahead and meet you on the way there.",rewardGold=341600,rewardXP=11765,rewardCurrencies={{id=3405,amount=25}},starts={{npcID=265166}},ends={{npcID=263482}},coords={x=0.668,y=0.425,source="quest_giver",zoneID=16900},questType="standard"},
[96441] = {id=96441,name="Seeking Knowledge Week 2 of 5: Ritualized Arcana",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=17067,mapID=2649,description="The nature of the Dawnwell has sparked a question among the minds of Magisters' Terrace: If magic can corrupt and suffuse other magics, how will the Dawnwell affect the ley lines branching out from it? With inquiry, comes experiment. The Ritual Sites in Quel'Thalas use the ley lines to fuel their magic. Disrupt these sites and retrieve samples of the arcana you find.",rewardGold=683200,rewardXP=17110,rewardCurrencies={{id=3316,amount=300}},starts={{npcID=264069}},ends={{npcID=264070}},coords={x=0.604,y=0.112,source="quest_giver",zoneID=17067},questType="standard"},
[96442] = {id=96442,name="Seeking Knowledge Week 3 of 5: Ley Line Assaults",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=17067,mapID=2424,description="Unfortunately, most of the measurable samples were expunged by the Ritual Site's excessive energy. If we are to accurately measure the various magics seeping into the ley lines, we'll need samples from a broader, less concentrated source. I am told the Farstriders continue to route the void strikes across Quel'Thalas. Bring me coalesced ley energy from any of the assaulting forces.",rewardGold=683200,rewardXP=17110,rewardCurrencies={{id=3316,amount=300}},starts={{npcID=264070}},ends={{npcID=264069}},coords={x=0.602,y=0.116,source="quest_giver",zoneID=17067},questType="standard"},
[96443] = {id=96443,name="Seeking Knowledge Week 4 of 5: Magical Primessence",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=17067,mapID=2424,description="Thanks to your efforts, we've isolated the effects of trace amounts of foreign magic coalescing with the ley lines. Our next phase is to compare these results against a pure sample of magic coalescing with the same energy. Your task is to track down a primessence of magic--be it arcane, Void, Light, or other--and acquire it from its deadly source. Good luck, .",rewardGold=683200,rewardXP=17110,rewardCurrencies={{id=3316,amount=300}},starts={{npcID=264070}},ends={{npcID=264069}},coords={x=0.602,y=0.116,source="quest_giver",zoneID=17067},questType="standard"},
[96444] = {id=96444,name="Seeking Knowledge Week 5 of 5: Off-World Magic",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=17067,mapID=2424,description="Although it made an excellent catalyst, the primessence you retrieved revealed a factor we did not account for. The alien nature of the Void and ethereal magic used in their assaults proved incompatible with the experiment. We need a sample of their magic if we are to make any progress--not from the assaults here in Quel'Thalas, but from the source of their attacks. I am told these enemies strike from off-world staging grounds. Good luck, .",rewardGold=1366400,rewardXP=17110,rewardCurrencies={{id=3316,amount=500}},starts={{npcID=264069}},ends={{npcID=264070}},coords={x=0.604,y=0.112,source="quest_giver",zoneID=17067},questType="standard"},
[96446] = {id=96446,name="Spark of Tides",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="A vision of tides permeates your mind. Eldara Dawnrunner might have more information regarding these Sparks of Tides.",rewardGold=30900,ends={{npcID=243229}},coords={mapID=2393,x=0.402,y=0.648},questType="standard"},
[96450] = {id=96450,name="Sideways",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2640,description="Naj'kula and I were here to observe how the Children of Ula'tek reproduce. We discovered dis lich, Lokago. Malacrass had him experimentin' on kidnapped Amani. I stole his records to try and figure out why, but de lich discovered us. I was injured. I dropped everythin'. Naj'kula was right behind me... We gotta recover de notes--and find Naj'kula!",rewardGold=341600,rewardXP=13690,rewardItems={276910,276911,276913},rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=265194}},ends={{npcID=265194}},questType="standard"},
[96451] = {id=96451,name="A Child of Ula'tek",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2640,description="I don't like dis. We should have found her by now. Ulantu 's face is sweaty and pale. She rubs her wound absentmindedly.> De lich must have dragged her back to where he was doin' his experiments. And if his notes are to be believed... We need to find Naj'kula quickly--or she may not be who she was.",rewardGold=683200,rewardXP=17110,rewardCurrencies={{id=3316,amount=20},{id=3504,amount=100}},starts={{npcID=265229}},ends={{npcID=265229}},questType="standard"},
[96457] = {id=96457,name="Nothing Must Remain",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2640,description="You saw what he did to Naj'kula. And who knows how many others. Ulantu is sweating and pale, gripping her stomach.> Too many lives were sacrificed in de name of these awful... whatever Kuku became. If only we could have killed de damned lich! But we can destroy his lab.",rewardGold=341600,rewardXP=13690,rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=265278}},ends={{npcID=265278}},questType="standard"},
[96458] = {id=96458,name="Last Promise",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="Lokago cut me with de same venom that twisted Naj'kula. I feel it burnin' me just the same. I intend to die an Amani. But my work is unfinished. Please get these notes to Kul'amara. Tell her she can find me at Naj'kula's side.",rewardGold=85400,rewardXP=3420,rewardItems={271609},rewardCurrencies={{id=3316,amount=25},{id=3504,amount=250}},starts={{npcID=265278}},ends={{npcID=265173}},questType="standard"},
[96466] = {id=96466,name="Prey: Anguish Island",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="Something is driving these creatures into our realm. I have sent one of my most capable servants to this \"Isle of Fangs\". Go and see what you can make of this den of snakes. In any other endeavor I would accompany you, of course--but I shall remain here. This island sounds like a most dreadful place. Do have fun, though.",rewardGold=85400,rewardXP=3420,starts={{npcID=246231}},ends={{npcID=265267}},coords={x=0.566,y=0.654,source="quest_giver",zoneID=15969},questType="standard"},
[96467] = {id=96467,name="Thirst for Knowledge",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="Two brothers came with us to dis cursed place... Zei'ka and Jun'ka. Zei'ka , he got de fire in him. Soon as we landed, he ran off, chasing whispers like dey were calling his name. But, Jun'ka, he ain't a fool. He went after his brother, tryin' to keep him from getting himself killed. I don't like dis. Dis island, it'll swallow us whole if we ain't careful. Go check on dem, eh?",rewardGold=34100,rewardXP=1370,starts={{npcID=265173}},ends={{npcID=265329}},coords={x=0.578,y=0.466,source="quest_giver",zoneID=16365},questType="standard"},
[96469] = {id=96469,name="The Crypt of the Disgraced",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="Jun'ka's my brother, but he frets too much to let me chase after my life's dream. Ever since I was a child, I wanted to learn more of our history. While much of it is told by de talespinners back home, they always skipped one thing: Atal'Utek. De more I dug, de more mysterious it became, and de more I became engrossed. Now, de scouts tell me that this crypt is filled with tablets inside. Tablets that could have de history of our people. I need to see those tablets, even if it kills me. You in?",rewardGold=341600,rewardXP=13690,rewardCurrencies={{id=3316,amount=10},{id=3504,amount=50}},starts={{npcID=265329}},ends={{npcID=265329}},coords={x=0.75,y=0.626,source="quest_giver",zoneID=16365},questType="standard"},
[96471] = {id=96471,name="Crumble and Tumble",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="Blast it all! I dragged y'all into dis muck just 'cause my brother's worried about my hide! You're gettin' outta here quick! I lead, you follow, and don't lag behind, or you're squashed!",rewardGold=170800,rewardXP=6850,rewardItems={280105},rewardCurrencies={{id=3316,amount=25},{id=3504,amount=250}},starts={{npcID=265330}},ends={{npcID=267032}},questType="standard"},
[96472] = {id=96472,name="The Nexus-Captain",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16943,mapID=2600,description="The Hal'hadar may not know we are here yet, but they still hold the advantage. Nexus-Captain Leth'ir and his associate, Mertei, are just over this ridge and surrounded by a small army. If you can rally enough allies and catch their leaders off guard, we will deal a devastating blow before they know what hit them. Proceed with caution, , and make sure you are not alone.",rewardGold=2732800,rewardXP=23530,rewardCurrencies={{id=3405,amount=75}},starts={{npcID=264028,x=0.708,y=0.622,zoneID=16943}},ends={{npcID=264024,x=0.484,y=0.82,zoneID=16943}},coords={x=0.708,y=0.622,source="quest_giver",zoneID=16943},questType="world",worldTaskTitle="The Nexus-Captain",db2QuestInfoID=1,db2QuestInfoName="Group"},
[96473] = {id=96473,name="Imperator Pertinax",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16900,description="Like all domanaar, Imperator Pertinax sees himself only as a predator and never the prey. Unfortunately, our prey is well-guarded in his Void Acropolis. If you manage to gather enough allies and catch the imperator off guard, we'll deal a crushing blow to our enemies. Move swiftly and cautiously, , and ensure you have backup before engaging Pertinax.",rewardGold=2732800,rewardXP=23530,rewardCurrencies={{id=3405,amount=75}},starts={{npcID=263987}},ends={{npcID=264879}},coords={x=0.416,y=0.846,source="quest_giver",zoneID=16900},questType="group"},
[96474] = {id=96474,name="Prey: Something for Astalor",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="$p! Ah, we haven't met. Not formally. I've overheard some of your discussions with Magister Astalor while I was, er, scrubbing the floors. You seem like quite the competent operator! That makes two of us. Usually. I'm a bit... preoccupied at the moment, what with the local wildlife and all. Maybe you can poke around for us?",rewardGold=341600,rewardXP=13690,starts={{npcID=265267,x=0.582,y=0.486,zoneID=16365}},ends={{npcID=265267,x=0.582,y=0.486,zoneID=16365}},coords={x=0.582,y=0.486,source="quest_giver",zoneID=16365},questType="world",worldTaskTitle="Prey: Something for Astalor"},
[96492] = {id=96492,name="Special Assignment: Demand and Supply",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=16365,rewardXP=13690,coords={mapID=2512,x=0.579,y=0.49},questType="standard"},
[96496] = {id=96496,name="The Road Not Taken Twice",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16900,mapID=2599,description="During our surveys of this iced desert, our scouts identified two areas worth keeping an eye on, but with a major problem: they're only accessible through single points of entry. Before I'm comfortable sending out more forces, we need to secure their exits. We've been working on teleportation crystals for faster local travel that leverage the domanaar's existing portal network, and we're close to a solution. You just need to field test them. Set up these prototype rift slippers and report back.",rewardGold=341600,rewardXP=11765,starts={{npcID=263482,x=0.596,y=0.218,zoneID=16900}},ends={{npcID=263482,x=0.596,y=0.218,zoneID=16900}},coords={x=0.596,y=0.218,source="quest_giver",zoneID=16900},questType="world",worldTaskTitle="The Road Not Taken Twice"},
[96497] = {id=96497,name="Spatial Reasoning",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16900,mapID=2599,description="The domanaar are more entrenched here than we thought and these storms refuse to relent even for a moment. We've finally figured out how to hijack their portal network for short range traversal thanks to your efforts setting up the rift slippers. Now we just need help setting up our portal bridges . Here are four strategic locations, including this outpost, for you to set up the portal bridges . Once active, you'll be able to more swiftly respond to threats as they arise. Time to get to work.",rewardGold=341600,rewardXP=11765,starts={{npcID=263482,x=0.596,y=0.218,zoneID=16900}},ends={{npcID=263482,x=0.596,y=0.218,zoneID=16900}},coords={x=0.596,y=0.218,source="quest_giver",zoneID=16900},questType="world",worldTaskTitle="Spatial Reasoning"},
[96498] = {id=96498,name="Grovewarden's Kris",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15355,mapID=2413,rewardItems={257155},starts={{npcID=251259}},ends={{npcID=251259}},coords={x=0.492,y=0.544,source="quest_giver",mapID=2413},questType="standard"},
