[96502] = {id=96502,name="Vivid Chloroceros",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15355,mapID=2413,rewardItems={263580},starts={{npcID=251259}},ends={{npcID=251259}},coords={x=0.492,y=0.544,source="quest_giver",mapID=2413},questType="standard"},
[96503] = {id=96503,name="Prey: A Ghostly Nightmare",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2393,description="It appears your scouting has born fruit. This power could prove a useful boon indeed. Return to Atal'Utek and siphon its magic for our glorious purpose.",rewardGold=341600,rewardXP=13690,starts={{npcID=246231}},ends={{npcID=246231}},coords={x=0.566,y=0.654,source="quest_giver",zoneID=15969},questType="standard"},
[96504] = {id=96504,name="Warm Haranir Blanket",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15355,mapID=2413,rewardItems={264245},starts={{npcID=251259}},ends={{npcID=251259}},coords={x=0.492,y=0.544,source="quest_giver",mapID=2413},questType="standard"},
[96505] = {id=96505,name="Grovewarden's Buckler",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15355,mapID=2413,rewardItems={257159},starts={{npcID=251259}},ends={{npcID=251259}},coords={x=0.492,y=0.544,source="quest_giver",mapID=2413},questType="standard"},
