[96703] = {id=96703,name="Veterans of the Great Dark",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="When the Hal'hadar attacked, we quickly learned about their history with the Army of the Light. Commander Tala'saan has been providing us information on these ethereals. His soldiers stand ready to join our cause. I've requested their expertise in establishing a forward camp for our mission. Aid them in their preparations and inform the commander we mobilize soon.",rewardGold=341600,rewardXP=11765,rewardCurrencies={{id=3405,amount=10}},starts={{npcID=263479}},ends={{npcID=263479}},coords={x=0.476,y=0.51,source="quest_giver",mapID=2393},questType="standard"},
[96708] = {id=96708,name="To the Voidstorm and Beyond!",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15458,mapID=2405,description="It may not seem like many, but the allies we've secured will have to be enough. It's time we move out. Our forces are gathering at the Howling Ridge. The energies of the Voidstorm will allow us to open the way to these worlds. I will meet you there. There is something here I still require for our mission.",rewardGold=34100,rewardXP=1470,starts={{npcID=263479}},ends={{npcID=263480}},coords={x=0.476,y=0.51,source="quest_giver",mapID=2405},questType="standard"},
[96709] = {id=96709,name="The Nexus-Captain (Heroic)",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=16943,questType="group"},
[96711] = {id=96711,name="Imperator Pertinax (Heroic)",level=90,requiredLevel=90,faction="none",expansion=11,questType="group"},
[96713] = {id=96713,name="Showdown on Val",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16900,description="Our enemy's hold on Val may be strong, but it is not unbreakable. For every monstrosity we cut down, we deny them another soldier to use against our world. Venture out into the frozen landscape and lay waste to their strongholds. Show them no mercy, .",rewardXP=17110,rewardItems={275690},starts={{npcID=263479},{npcID=263482}},ends={{npcID=263482}},coords={x=0.476,y=0.51,source="quest_giver",zoneID=15969},questType="standard"},
[96714] = {id=96714,name="Showdown on Val (Heroic)",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16900,description="Our enemy's hold on Val may be strong, but it is not unbreakable. For every monstrosity we cut down, we deny them another soldier to use against our world. Venture out into the frozen landscape and lay waste to their strongholds. Show them no mercy, .",rewardItems={275691},starts={{npcID=263479},{npcID=263482}},ends={{npcID=263482}},coords={x=0.476,y=0.51,source="quest_giver",zoneID=15969},questType="standard"},
[96716] = {id=96716,name="Showdown on Val",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16900,description="Our enemy's hold on Val may be strong, but it is not unbreakable. For every monstrosity we cut down, we deny them another soldier to use against our world. Venture out into the frozen landscape and lay waste to their strongholds. Show them no mercy, .",rewardXP=14705,rewardItems={272125},starts={{npcID=263479},{npcID=263482}},ends={{npcID=263482}},coords={x=0.476,y=0.51,source="quest_giver",zoneID=15969},questType="standard"},
[96717] = {id=96717,name="Showdown on Naigtal",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16943,description="Now this is quite a strange world, isn't it? The Hal'hadar must have found something of note. The stench of forges indicates they are plundering the riches and resources this remote rock has to offer. If you can disrupt the operations here, you can buy your precious world a moment of respite. Do what you do best, my little monster.",rewardXP=17110,rewardItems={275690},starts={{npcID=263531},{npcID=265303}},ends={{npcID=265303}},coords={x=0.476,y=0.51,source="quest_giver",zoneID=15969},questType="standard"},
[96718] = {id=96718,name="Showdown on Naigtal (Heroic)",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16943,description="Now this is quite a strange world, isn't it? The Hal'hadar must have found something of note. The stench of forges indicates they are plundering the riches and resources this remote rock has to offer. If you can disrupt the operations here, you can buy your precious world a moment of respite. Do what you do best, my little monster.",rewardItems={275691},starts={{npcID=263531},{npcID=265303}},ends={{npcID=265303}},coords={x=0.476,y=0.51,source="quest_giver",zoneID=15969},questType="standard"},
[96720] = {id=96720,name="Showdown on Naigtal",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16943,description="Now this is quite a strange world, isn't it? The Hal'hadar must have found something of note. The stench of forges indicates they are plundering the riches and resources this remote rock has to offer. If you can disrupt the operations here, you can buy your precious world a moment of respite. Do what you do best, my little monster.",rewardXP=14705,rewardItems={272125},starts={{npcID=263531},{npcID=265303}},ends={{npcID=265303}},coords={x=0.476,y=0.51,source="quest_giver",zoneID=15969},questType="standard"},
[96725] = {id=96725,name="Sparks of War: Val",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="The mysterious world of Val has been made accessible to us with a host of new creatures present. Go and see what you can find out about them.",rewardItems={275134},rewardCurrencies={{id=1792,amount=500},{id=1602,amount=50},{id=2123,amount=1000},{id=3316,amount=50}},starts={{npcID=254971,x=0.362,y=0.81,mapID=2393}},ends={{npcID=254971,x=0.362,y=0.81,mapID=2393}},coords={x=0.362,y=0.81,source="quest_giver",mapID=2393},questType="world",worldTaskTitle="Sparks of War: Val"},
[96726] = {id=96726,name="Sparks of War: Naigtal",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="The mysterious world of Naigtal has been made accessible to us with a host of new creatures present. Go and see what you can find out about this world and what the ethereals are up to.",rewardItems={275134},rewardCurrencies={{id=2123,amount=1000},{id=1792,amount=500},{id=1602,amount=50},{id=3316,amount=50}},starts={{npcID=254971,x=0.362,y=0.81,mapID=2393}},ends={{npcID=254971,x=0.362,y=0.81,mapID=2393}},coords={x=0.362,y=0.81,source="quest_giver",mapID=2393},questType="world",worldTaskTitle="Sparks of War: Naigtal"},
[96727] = {id=96727,name="Midnight: Offworld Showdowns",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=17103,description="Our effort to thwart the Void Assaults in Eversong and Zul'Aman have seen much success, but if we do not find a way to stop our aggressors from coming to our lands, they will bleed us until we can no longer stand. Riftblade Maella has recently discovered the location of two of our enemies' bases. She seeks to take the fight to them. Will you aid her strike team? Your efforts will not go unnoticed in these dark times!",rewardGold=683200,rewardXP=20540,rewardItems={254677,268490,279527,279575},ends={{npcID=256203}},coords={mapID=2393,x=0.49,y=0.646},questType="standard"},
[96728] = {id=96728,name="Ritual Site Studies: Week 1 of 3",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15968,mapID=2395,description="After you reported thinning out their ranks I got to thinking. What do they use to recruit members? Are they just as fanatical as their leaders? I wonder if we can break their will to fight by destroying a greater number of their ranks. I fear it will take more than one example to know for sure.",rewardGold=683200,rewardCurrencies={{id=3316,amount=300}},starts={{npcID=257416},{npcID=267813}},ends={{npcID=257416}},coords={x=0.478,y=0.496,source="quest_giver",mapID=2395},questType="standard"},
[96729] = {id=96729,name="Ritual Site Studies: Week 2 of 3",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="I have your next assignment, . I need you to study the resilience of these malevolent boons and their dark obelisks. They focus magic so well and the variety of boons is interesting. I need more data though. When you disrupt the next ritual site I need you to do so with these malevolent boons present.",rewardGold=683200,rewardCurrencies={{id=3316,amount=300}},starts={{npcID=257416}},ends={{npcID=257416}},coords={x=0.478,y=0.496,source="quest_giver",mapID=2393},questType="standard"},
[96730] = {id=96730,name="Ritual Site Studies: Week 3 of 3",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15968,mapID=2395,description="I think I am on the brink of a big discovery. These latest rituals involve a magic I had not previously heard of in the form of powerful embers that use the energy of their own forces to bolster their leader. If you disrupt these rituals and report your findings to me, I might be able to put this magic to use for us. Do not look at me that way. On my own demon minions of course. Did you think I meant troops like you? We are much too early for trials like that. Report back with your findings!",rewardGold=683200,rewardCurrencies={{id=3316,amount=300},{id=3513,amount=1}},starts={{npcID=257416},{npcID=267813}},ends={{npcID=257416}},coords={x=0.478,y=0.496,source="quest_giver",mapID=2395},questType="standard"},
[96731] = {id=96731,name="Advanced Ritual Site Studies: Week 4 of 6",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="I had an idea right after you left. We have thinned out their ranks, we have also seen that they can summon additional reinforcements. I want to test the limits of their reserves. If you take on this set of challenges, I promise you another key for the vault.",rewardGold=683200,rewardCurrencies={{id=3316,amount=300}},starts={{npcID=257416}},ends={{npcID=257416}},coords={x=0.478,y=0.496,source="quest_giver",mapID=2393},questType="standard"},
[96732] = {id=96732,name="Advanced Ritual Site Studies: Week 5 of 6",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Now that we have tested their troop reserves, our focus will be the dark obelisks and these boons they give. This requires close scrutiny and will surely entail you facing increased patrols while you explore the site. Not too difficult for someone like yourself. Just avoid them... or deal with them if you must.",rewardGold=683200,rewardCurrencies={{id=3316,amount=300}},starts={{npcID=257416}},ends={{npcID=257416}},coords={x=0.478,y=0.496,source="quest_giver",mapID=2393},questType="standard"},
[96733] = {id=96733,name="Advanced Ritual Site Studies: Week 6 of 6",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Welcome back my star pupil. I have one last assignment for you and this one will be a challenge. These embers that they use in these rituals. I have not had any success in replicating them or finding a way to counter them. I have one last idea I want you to try. You reported seeing magical manifestations of caster spirits. I have a theory that with these two challenges present there might be a way for them to cancel each other out.",rewardGold=683200,rewardCurrencies={{id=3316,amount=300},{id=3513,amount=1}},starts={{npcID=257416}},ends={{npcID=257416}},coords={x=0.478,y=0.496,source="quest_giver",mapID=2393},questType="standard"},
[96744] = {id=96744,name="Bouncy Mushrooms",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16943,description="Hello! Here's a trick to help you bounce on the purple mushrooms around here. You'll need it, because... I want some canopy specimens from the sporerays above us. Bounce up there, get some specimens, then come back down and I'll teach you how to ALWAYS bounce on those mushrooms.",rewardGold=341600,rewardXP=11765,rewardItems={275256},starts={{npcID=265559}},ends={{npcID=265559}},coords={x=0.478,y=0.812,source="quest_giver",zoneID=16943},questType="standard"},
[96745] = {id=96745,name="Aerospores",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16943,description="Now, practice using aerospores . They're up there too if you know where to look. Use them to shoot through the air! You'll need to bounce on mushrooms to get up to the spores and see them. Once you're up there, pass through some aerospores and find out what they do!",rewardGold=256200,rewardXP=8825,starts={{npcID=265559}},ends={{npcID=265559}},coords={x=0.478,y=0.812,source="quest_giver",zoneID=16943},questType="standard"},
[96746] = {id=96746,name="Sporefall: Rotmire",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Need help! End of Harandar! End of world! Spore Storm making something new for Grudge Pit, but too much. Too much! Can't control. Will break free! Destroy pit. Destroy us all! Must go to Sporefall, destroy Rotmire before they lose control! For Harandar! For Azeroth! For Grudge Pit!",rewardGold=20496000,rewardXP=27380,rewardItems={269258},starts={{npcID=266165,x=0.366,y=0.688,mapID=2393}},ends={{npcID=266165,x=0.366,y=0.688,mapID=2393}},coords={x=0.366,y=0.688,source="quest_giver",mapID=2393},questType="world",worldTaskTitle="Sporefall: Rotmire",db2QuestInfoID=62,db2QuestInfoName="Raid"},
[96780] = {id=96780,name="Local Kafa Shop",level=0,requiredLevel=0,faction="both",expansion=11,zoneID=16105,mapID=2352,starts={{npcID=263258}},ends={{npcID=263258}},coords={x=0.552,y=0.618,source="quest_giver",mapID=2352},questType="standard"},
[96794] = {id=96794,name="Fury of the Dead",level=90,requiredLevel=90,faction="none",expansion=11,questType="standard"},
[96801] = {id=96801,name="Calling All Combatants!",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Run, don't walk! The Artisan's Consortium has teamed up with local Silvermoon artisans in Falconwing Square to offer a new selection of heraldries and crafted equipment. These are certified for use in arenas and battlegrounds, guaranteed! Head on down and look for Mirvedon to receive your free sample today. Act now while supplies last! Terms and conditions apply. -Aisha",rewardGold=34100,rewardXP=1370,rewardItems={275385},ends={{npcID=243225}},questType="standard"},
[96808] = {id=96808,name="Sparks of War: The Coiled Isle",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="There's unknown danger out in the Coiled Isle . Get out there and clear things up!",rewardItems={219934},rewardCurrencies={{id=2123,amount=1000},{id=1792,amount=500},{id=1602,amount=50}},starts={{npcID=254971,x=0.362,y=0.81,mapID=2393}},ends={{npcID=254971,x=0.362,y=0.81,mapID=2393}},coords={x=0.362,y=0.81,source="quest_giver",mapID=2393},questType="world",worldTaskTitle="Sparks of War: The Coiled Isle"},
[96809] = {id=96809,name="Exterior Manaforge Translocator",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16943,mapID=2600,description="Maneuvering through this spore-infested rock is quickly becoming a chore, I'm sure you would agree. Thankfully, I've figured out a way to make use of the existing Manaforge Translocator network that was so thoughtfully built prior to our arrival. I can show you how to \"activate\" them for our use. You can start with the one we... translocated to camp.",rewardGold=341600,rewardXP=11765,starts={{npcID=265559,x=0.478,y=0.812,zoneID=16943}},ends={{npcID=265559,x=0.478,y=0.812,zoneID=16943}},coords={x=0.478,y=0.812,source="quest_giver",zoneID=16943},questType="world",worldTaskTitle="Exterior Manaforge Translocator"},
[96831] = {id=96831,name="Magister's Summons",level=90,requiredLevel=90,faction="alliance",expansion=11,zoneID=17067,description="Magister Umbric sends word that he and Rommath have a lead to further your empowerment of the Omnium Folio.",starts={{npcID=265903}},ends={{npcID=264069}},coords={x=0.478,y=0.516,source="quest_giver",zoneID=15969},questType="standard"},
[96845] = {id=96845,name="The Grappler",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16943,description="You have to try this Lightforge Hookshot ! Here, take this loaner one. To learn the ropes, use it on some mushrooms and aerospores around here. Come back and I'll give you a Hookshot for keeps.",rewardGold=341600,rewardXP=11765,starts={{npcID=265581}},ends={{npcID=265581}},coords={x=0.634,y=0.21,source="quest_giver",zoneID=16900},questType="standard"},
