[96935] = {id=96935,name="Curse Surge",level=90,requiredLevel=90,faction="none",expansion=11,questType="standard"},
[96936] = {id=96936,name="Accolades for the Umbral Contender",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2112,description=", you continue to impress me with your martial prowess! You've done such an incredible job defeating the forces of evil. I've got something from my coffers that I'd love to give you.",objectivesText="Speak with Lindormi regarding your deeds in Mythic Keystone dungeons.",rewardItems={275436},ends={{npcID=197711}},coords={mapID=2112,source="quest_giver",x=0.531,y=0.565},questType="standard"},
[96941] = {id=96941,name="A Pertinent Punishment",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=16900,mapID=2618,rewardXP=13690,questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=265527,text="Portal entered"}},worldTaskTitle="A Pertinent Punishment",db2QuestInfoID=289,db2QuestInfoName="World Boss"},
[96942] = {id=96942,name="Oh Captain, Die Captain!",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=16943,mapID=2600,rewardXP=13690,questType="world",worldTaskTitle="Oh Captain, Die Captain!",db2QuestInfoID=289,db2QuestInfoName="World Boss"},
