[96995] = {id=96995,name="Turn Back the Surge",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="De temple can no longer contain Ula'tek's wrath. De boldest of her brood are spilling out all over de isle! They'll destroy us all if we don't stem de tide of venom. Fight dem wherever dey dare to show their ugly heads. Do not let dem get a foothold.",rewardGold=341600,rewardXP=13690,rewardItems={273000,275911},rewardCurrencies={{id=3316,amount=100},{id=3504,amount=1000}},starts={{npcID=267635,x=0.586,y=0.458,zoneID=16365}},ends={{npcID=267635,x=0.586,y=0.458,zoneID=16365}},coords={x=0.586,y=0.458,source="quest_giver",zoneID=16365},questType="world",worldTaskTitle="Turn Back the Surge",db2QuestInfoID=284,db2QuestInfoName="Meta Quest"},
[97016] = {id=97016,name="Mixing Mysteries",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,description="You think you've got some potent ingredients for my stew, eh? We'll see what de spirits think. Show me what you've brought and I'll throw it in de cauldron. De spirits will eat their fill, and if dey like it, you might get a reward. Or a punishment, if dey hate it. So choose wisely!",rewardGold=341600,rewardXP=13690,rewardItems={248962,276117,276124,276126,277937,277938,277939,277940,277941,277942,277943,277944,277945,277946,277985,280189},starts={{npcID=254599},{npcID=263327}},ends={{npcID=267451}},coords={x=0.574,y=0.486,source="quest_giver",zoneID=16365},questType="standard"},
[97026] = {id=97026,name="Esoteric Ingredients",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,rewardGold=170800,rewardXP=6850,rewardItems={278084},rewardChoices={278084},ends={{npcID=254599}},questType="standard"},
[97031] = {id=97031,name="Vilaldoun Valediction",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16943,mapID=2646,rewardGold=312800,rewardXP=11765,starts={{npcID=658789,x=0.541,y=0.263,zoneID=17103}},ends={{npcID=266034,x=0.478,y=0.82,zoneID=16943}},coords={x=0.541,y=0.263,source="quest_giver",zoneID=17103},questType="world",worldTaskTitle="Vilaldoun Valediction"},
[97034] = {id=97034,name="Vanquish the Warmonger",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16900,mapID=2599,description="Poor Impotus doesn't seem to believe we can seize control from his nefarious kin. He's tragically unimaginative. We'll just need to show him an example of our combined strength. Slay that brute of a newcomer, Ignedus. I think his armor would look nice on our new savior. Ignedus seems to be quite careful in showing his face, but clearly quick to anger. Get in there and make some noise, as you're so comfortable doing. I expect him to respond in kind.",rewardGold=341600,rewardXP=11765,rewardItems={277116},rewardCurrencies={{id=3405,amount=30}},starts={{npcID=264879}},ends={{npcID=264941}},coords={x=0.598,y=0.218,source="quest_giver",zoneID=16900},questType="standard"},
[97035] = {id=97035,name="Depose the Deranged",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16900,mapID=2599,description="Defeating Ignedus is impressive, I suppose, but it does not mean you're any closer to taking Val. Periculus won't let you meddle with his playthings. He is an... eccentric one, to say the least, and dreadfully fascinated by you flesh-beings. You'll likely find him in the darkest hole this world has to offer, carving open the livestock that Pertinax gathered. He likes to toy with his prey, so I would advise caution.",rewardGold=341600,rewardXP=11765,rewardCurrencies={{id=3405,amount=30}},starts={{npcID=264941},{npcID=267578}},ends={{npcID=267578}},coords={x=0.62,y=0.216,source="quest_giver",zoneID=16900},questType="standard"},
[97036] = {id=97036,name="Umbral Title Bout",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16900,mapID=2599,description="Well then, it seems our goals are more aligned than before. You've impressed me. With Ignedus and Periculus dealt with, all that remains is my former associate. You will find Gladius Reginax atop that high platform, observing her quarry. She already knows you're coming, so don't aim to surprise her. There's only one way up there for you anyway: through that portal in the Glacial Reservoir. I will play my part and join you. A symbol of our... collaboration.",rewardGold=683200,rewardXP=14705,rewardCurrencies={{id=3405,amount=75}},starts={{npcID=267578}},ends={{npcID=264879}},coords={x=0.62,y=0.216,source="quest_giver",zoneID=16900},questType="standard"},
[97037] = {id=97037,name="Stargrim Revelations",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15458,mapID=2405,description="We have a problem, . The hologem you found revealed much about our people's time on this world and who the vigilants were in life. Who they were is not the problem, but rather the possessions they carried within their chassis. Possessions now in the hands of the Soul Architect who, as far as my scouts can tell, has left Naigtal. Archmage Y'mera will explain in greater detail.",rewardGold=256200,rewardXP=8825,starts={{npcID=265950}},ends={{npcID=245240}},coords={x=0.476,y=0.82,source="quest_giver",mapID=2405},questType="standard"},
[97071] = {id=97071,name="A Frigid Welcome to Val",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16900,mapID=2599,description="Even with the element of surprise, we are at a disadvantage without allies. Storming Pertinax's stronghold alone would be a death sentence. Take this beacon Tala'saan gave us and return to our entry point. I will meet you there and deliver my report to Maella. Let us hope we have some sort of shelter awaiting us.",rewardGold=256200,rewardXP=8825,rewardItems={276373},rewardCurrencies={{id=3405,amount=5}},starts={{npcID=263987}},ends={{npcID=263482}},coords={x=0.416,y=0.846,source="quest_giver",zoneID=16900},questType="standard"},
[97072] = {id=97072,name="A Swampy Welcome to Naigtal",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16943,mapID=2600,description="The Nexus-Captain is just over that hill, unaware of our arrival. Attacking now would catch his army off guard... and likely result in our demise. No matter what, we will need allies if we are to succeed. Use this beacon to return to our invasion point. By now, Y'mera has likely brought in the rest of our forces to support us. Speak with Maella when you arrive.",rewardGold=256200,rewardXP=8825,rewardItems={276371,276372},rewardCurrencies={{id=3405,amount=5}},starts={{npcID=264028}},ends={{npcID=264024}},coords={x=0.708,y=0.622,source="quest_giver",zoneID=16943},questType="standard"},
[97073] = {id=97073,name="Rustbolt Retailer",level=0,requiredLevel=0,faction="both",expansion=11,zoneID=16105,mapID=2352,starts={{npcID=267856}},ends={{npcID=267856}},coords={x=0.53,y=0.544,source="quest_giver",mapID=2352},questType="standard"},
[97075] = {id=97075,name="Quality Goods",level=0,requiredLevel=0,faction="both",expansion=11,zoneID=16105,mapID=2352,starts={{npcID=267870}},ends={{npcID=267870}},coords={x=0.402,y=0.73,source="quest_giver",mapID=2352},questType="standard"},
[97077] = {id=97077,name="A Shot at the Dark",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16900,mapID=2599,description="Now that our trap is attuned, we just need to lure our prey out into the open. I have strategically... dismantled... certain parts of the projection device I obtained. Impotus should have difficulty seeing and hearing you clearly. Claim to be one of his allies and demand a meeting at once. We will hope his curiosity gets the better of him. And then...",rewardGold=683200,rewardXP=14705,rewardCurrencies={{id=3405,amount=35}},starts={{npcID=267877}},ends={{npcID=264879}},coords={x=0.589,y=0.695,source="quest_giver",zoneID=16900},questType="standard"},
[97080] = {id=97080,name="More Disruptions: Val",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16900,description="We must not let up the pressure. Even now they are rebuilding from our attacks. Venture out again and show them no mercy!",rewardXP=14705,rewardItems={276387},starts={{npcID=263482}},ends={{npcID=263482}},questType="standard"},
[97081] = {id=97081,name="More Disruptions: Val (Heroic)",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16900,description="We must not let up the pressure. Even now they are rebuilding from our attacks. Venture out again and again show them no mercy!",rewardXP=17110,rewardItems={276388},starts={{npcID=263482}},ends={{npcID=263482}},questType="standard"},
[97082] = {id=97082,name="Dangerous Enemies: Val",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16900,description="Our scouts have reported seeing dangerous elite creatures that are hampering our efforts. I need you to dispatch them so we can continue our primary objective.",rewardXP=14705,rewardItems={276389},starts={{npcID=263482}},ends={{npcID=263482}},questType="standard"},
[97083] = {id=97083,name="Dangerous Enemies: Val (Heroic)",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16900,description="Our scouts have reported seeing dangerous elite creatures that are hampering our efforts. I need you to dispatch them so we can continue our primary objective.",rewardXP=17110,rewardItems={276390},starts={{npcID=263482}},ends={{npcID=263482}},questType="standard"},
[97084] = {id=97084,name="More Disruption: Naigtal",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16943,description="The stench of their forges still lingers. This means they are rebuilding. You must keep at it if you hope to disrupt their operations enough to end their threat. Now you can go. Wreak havoc.",rewardXP=14705,rewardItems={276387},starts={{npcID=265303}},ends={{npcID=264024}},questType="standard"},
[97085] = {id=97085,name="Dangerous Enemies: Naigtal",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16943,description="I hear your scouts talk of dangerous creatures and foes they have faced. It makes me wonder if you could defeat them? Why don't you go and try? It will certainly help your efforts here. I hope to see you return mostly intact.",rewardXP=14705,rewardItems={276389},starts={{npcID=265303}},ends={{npcID=264024}},questType="standard"},
[97086] = {id=97086,name="Dangerous Enemies: Naigtal (Heroic)",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16943,description="I hear your scouts talk of dangerous creatures and foes they have faced. It makes me wonder if you could defeat them? Why don't you go and try? It will certainly help your efforts here. I hope to see you return mostly intact.",rewardXP=17110,rewardItems={276390},starts={{npcID=265303}},ends={{npcID=264024}},questType="standard"},
[97087] = {id=97087,name="More Disruption: Naigtal (Heroic)",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16943,description="The stench of their forges still lingers. This means they are rebuilding. You must keep at it if you hope to disrupt their operations enough to end their threat. Now you can go. Wreak havoc.",rewardXP=17110,rewardItems={276388},starts={{npcID=265303}},ends={{npcID=264024}},questType="standard"},
[97088] = {id=97088,name="So Much More To Do",expansion=11,mapID=2393,objectivesText="Level 80",questType="world",worldTaskTitle="So Much More To Do",db2QuestInfoID=284,db2QuestInfoName="Meta Quest"},
[97089] = {id=97089,name="So Much More To Do",expansion=11,mapID=2393,objectivesText="Level 90",questType="world",worldTaskTitle="So Much More To Do",db2QuestInfoID=284,db2QuestInfoName="Meta Quest"},
[97128] = {id=97128,name="Lair: Nymrissa Wavecaller",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=16365,mapID=2512,rewardXP=13690,questType="world",worldTaskTitle="Lair: Nymrissa Wavecaller",db2QuestInfoID=289,db2QuestInfoName="World Boss"},
[97141] = {id=97141,name="Spoils of the Vaults",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,description="It takes de whole of our strength to keep de forces of Ula'tek from overwhelming de isle. Dat battle is waged inside the Vault of Ula'tek, against the endless tide of her children. Kill one, and two more will slither out of de venom. Venture in, , and lend your power to our weary fighters. Who knows? You may even find something valuable in dat ancient, cursed place.",rewardGold=341600,rewardXP=13690,rewardItems={276531,276532,276533,276534},starts={{npcID=268228}},ends={{npcID=268228}},coords={x=0.588,y=0.46,source="quest_giver",zoneID=16365},questType="standard"},
[97215] = {id=97215,name="A Secondary Strike",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15458,mapID=2393,description="We have struck a major blow against our enemies. Still, they continue their assaults. Decimus and my riftwardens have targeted another world from which they launch these attacks. The bulk of our forces have temporarily withdrawn to the Voidstorm so that we may begin our assault on this second world. Our strike team awaits us at the Howling Ridge.",rewardGold=34100,rewardXP=1470,starts={{npcID=263479,x=0.476,y=0.51,mapID=2393}},ends={{npcID=263480,x=0.516,y=0.71,mapID=2405}},coords={x=0.476,y=0.51,source="quest_giver",mapID=2405},questType="world",worldTaskTitle="A Secondary Strike"},
[97256] = {id=97256,name="Knocking Off the Top (Heroic)",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16943,mapID=2599,description="Even the most ruthless of creatures falter when they see their greatest champions crumble to ash. Remind our enemies here just how quickly their leaders fall! Let them know just how unrelenting and vicious you monsters of Azeroth really are! Bring me the Void Commander's Emblems and I will reward you accordingly.",rewardGold=1024800,rewardItems={276787,276788,276789,276790,276791,276792,276793,276794,276799,277554},rewardChoices={276787,276788,276789,276790,276791,276792,276793,276794,276799},starts={{npcID=264879,x=0.598,y=0.218,zoneID=16900},{npcID=265303,x=0.484,y=0.82,zoneID=16943}},ends={{npcID=264879,x=0.598,y=0.218,zoneID=16900},{npcID=265303,x=0.484,y=0.82,zoneID=16943}},coords={x=0.598,y=0.218,source="quest_giver",zoneID=16900},questType="world",worldTaskTitle="Knocking Off the Top (Heroic)"},
[97321] = {id=97321,name="Slithering Spoils",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="I've got good news and bad news. Bad is that all those curios we dug up together? Melted. Good news? I've found some very interesting new poisons to work with. But let me explain what happened...",rewardGold=34100,rewardXP=1370,rewardItems={277934,277949},rewardCurrencies={{id=3310,amount=25}},starts={{npcID=242381,x=0.524,y=0.78,mapID=2393}},ends={{npcID=242381,x=0.524,y=0.78,mapID=2393}},coords={x=0.524,y=0.78,source="quest_giver",mapID=2393},questType="world",worldTaskTitle="Slithering Spoils"},
[97382] = {id=97382,name="Counter-Curse Bounty",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,description="Every part of dis isle is cursed, . When de curse of Ula'tek coalesces into a fight, dat is when it is most important to strike back. We need all de help we can get keeping it at bay. You look strong... but you'll need better equipment if you want to stay alive. Defeat the leader of one of dese surges, and then we can discuss a reward.",rewardGold=341600,rewardXP=13690,rewardItems={276641,276642,276643,276644},starts={{npcID=268228}},ends={{npcID=268228}},coords={x=0.588,y=0.46,source="quest_giver",zoneID=16365},questType="standard"},
[97383] = {id=97383,name="Spirit Corrosion",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16535,description="Our scouts found dis relic in one of da crypts. Maybe Er'inye knows what to do with it?",rewardItems={278048},starts={{npcID=268228}},ends={{npcID=262880}},coords={x=0.588,y=0.46,source="quest_giver",zoneID=16365},questType="standard"},
[97454] = {id=97454,name="Seasonal Refresher: Midnight",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Since the opening of the Coiling Isles, things have started to get interesting again in delves. See if our dear hosts have anything they can spare for those of us actually risking our necks and check the Delver's Guide for any updates. A quick refresher never hurt anyone.",rewardGold=34100,rewardXP=1370,rewardCurrencies={{id=3310,amount=25},{id=3310,amount=37}},starts={{npcID=242381,x=0.524,y=0.78,zoneID=15969}},ends={{npcID=242381,x=0.524,y=0.78,zoneID=15969}},coords={x=0.524,y=0.78,source="quest_giver",zoneID=15969},questType="world",worldTaskTitle="Seasonal Refresher: Midnight",db2QuestInfoID=282,db2QuestInfoName="Important Quest"},
