[97461] = {id=97461,name="Cursed Fishing 101",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=16365,rewardGold=34100,rewardXP=1370,questType="standard"},
[97462] = {id=97462,name="Rocky Shores",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=16365,rewardGold=34100,rewardXP=1370,questType="standard"},
