[97464] = {id=97464,name="A Dash of Poison",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,rewardGold=34100,rewardXP=1370,rewardCurrencies={{id=3540,amount=150}},ends={{npcID=257598}},questType="standard"},
[97465] = {id=97465,name="The Intended Way to Fish",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,rewardGold=34100,rewardXP=1370,rewardCurrencies={{id=3540,amount=150}},ends={{npcID=257598}},questType="standard"},
[97482] = {id=97482,name="Fangs for the Memories",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2634,description="That snake monstrosity was vicious, with venom potent enough to burn through stone. We'll want to make sure we get our hands on the best gear we can before we think about taking it on. I've got some ideas about turning that venom to our own ends, though, so we can hit the ground running.",rewardGold=4099200,rewardXP=27380,rewardItems={275988},rewardCurrencies={{id=3310,amount=25}},starts={{npcID=242381,x=0.524,y=0.78,mapID=2393}},ends={{npcID=242381,x=0.524,y=0.78,mapID=2393}},coords={x=0.524,y=0.78,source="quest_giver",mapID=2393},questType="world",worldTaskTitle="Fangs for the Memories"},
[97557] = {id=97557,name="Tailing the Tlhapi",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,description="Toxic Tlhapi . Nasty little fish. Everything's wrong about them, from their big, buggy eyes to their sweet, succulent meat... Not to mention the toxicity. The seas would be much better without them fouling things up.",rewardGold=341600,rewardXP=13690,rewardCurrencies={{id=3316,amount=10},{id=3540,amount=150}},starts={{npcID=268394}},ends={{npcID=268394}},coords={x=0.516,y=0.502,source="quest_giver",zoneID=16365},questType="standard"},
[97562] = {id=97562,name="Culling the Killifish",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,description="Spotted Killifish . Grotesque little creatures. The little demons swarm like insects, washing up on shores in such horrific numbers that it would take several meals to devour them all. You can do your part by collecting some for me, ridding the waters of their foul presence.",rewardGold=341600,rewardXP=13690,rewardCurrencies={{id=3316,amount=10},{id=3540,amount=150}},starts={{npcID=268394}},ends={{npcID=268394}},coords={x=0.516,y=0.502,source="quest_giver",zoneID=16365},questType="standard"},
[97571] = {id=97571,name="Dogging the Darters",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,description="Dirty Darters . Ghoulish little buggers. The way they flit about the water is so unnerving, so disquieting, one can't help but imagine them darting right down one's gullet... You can do your part by collecting some for me, ridding the waters of their foul presence.",rewardGold=341600,rewardXP=13690,rewardCurrencies={{id=3316,amount=10},{id=3540,amount=150}},starts={{npcID=268394}},ends={{npcID=268394}},coords={x=0.516,y=0.502,source="quest_giver",zoneID=16365},questType="standard"},
[97616] = {id=97616,name="Corrosive Gifts: Corrosive Power",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16535,rewardXP=11765,rewardItems={273000},ends={{npcID=262880}},questType="standard"},
[97621] = {id=97621,name="The Singularity Anchor",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,description="Our sojourn to this world has brought the ren'dorei an even deeper understanding of the Void than before. The domanaar with whom we share a common enemy are almost strangely generous with their knowledge. I believe they want us to become as fearsome as they are. There is a Singularity Anchor in Stormarion Citadel. I have learned how to draw upon some of its power to craft you a powerful item. But first, we must ensure it does not fall into the hands of our enemies.",rewardGold=341600,rewardXP=13690,rewardItems={264507},starts={{npcID=248328}},ends={{npcID=248328}},coords={x=0.526,y=0.728,source="quest_giver",mapID=2405},questType="standard"},
[97622] = {id=97622,name="A Soiree to Remember",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15968,mapID=2395,description="You seek an audience with Saltheril? And you're wearing... that? Excuse me for a moment while I laugh into my handkerchief. Now, let me be professional. You are cordially invited to attend Saltheril's soiree. Don't embarrass yourself, . The best of Silvermoon are watching.",rewardGold=341600,rewardXP=13690,rewardItems={266429,266430,266431,266432},starts={{npcID=240838}},ends={{npcID=240838}},coords={x=0.434,y=0.474,source="quest_giver",mapID=2395},questType="standard"},
[97624] = {id=97624,name="Seeking Legends",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Harandar hides wisdom in every annal of its history, . You would do well to seek out its legends for yourself. I suspect you may learn something of this world and our places in it.",rewardGold=341600,rewardXP=13690,rewardItems={263265,263267,263268,263269},starts={{npcID=240407}},ends={{npcID=240407}},coords={x=0.51,y=0.508,source="quest_giver",mapID=2413},questType="standard"},
[97625] = {id=97625,name="Glorious Abundance",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15947,mapID=2437,description="De Loa of Abundance may not be one of de four great ones, but his worshippers are certainly de most devout. Seek him out yaself. You can find him in northern Zul'Aman near Halazzi's Temple, but I also hear he's established harvest sites in Eversong Woods, Harandar, and even de land of Void through de gargantuan skymouth. If nothing else, de rewards he grants are glorious--to de worthy, at least.",rewardGold=341600,rewardXP=13690,rewardItems={265739,265740},rewardChoices={265739,265740},starts={{npcID=240279}},ends={{npcID=240279}},coords={x=0.458,y=0.658,source="quest_giver",mapID=2437},questType="standard"},
[97640] = {id=97640,name="Vaults of Atal'Utek: One Coin Too Many",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16535,mapID=2509,description="You don't look so good, . You found something out dere, huh? De vaults are full of treasure, most of it cursed. I don't trust her, but dat spirit-witch you saw knows all de secrets of dis horrid place. If anyone can help, it's her.",rewardGold=170800,rewardXP=6850,rewardCurrencies={{id=3448,amount=1000}},starts={{npcID=262798}},ends={{npcID=262880}},coords={x=0.472,y=0.608,source="quest_giver",zoneID=16535},questType="standard"},
[97661] = {id=97661,name="The Protection of the Med'jai",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16535,description="Er'inye would likely be interested in studying it.>",rewardGold=170800,rewardXP=6850,ends={{npcID=262880}},coords={mapID=2638,x=0.3626,y=0.237},questType="standard"},
[97662] = {id=97662,name="The Winds of Tok'jara",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16535,description="Er'inye might be interested in studying it.>",rewardGold=170800,rewardXP=6850,ends={{npcID=262880}},coords={mapID=2509,x=0.485,y=0.2576},questType="standard"},
[97668] = {id=97668,name="The Watchful Gaze of Szarith",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16535,description="Er'inye would be interested in studying it.>",rewardGold=170800,rewardXP=6850,ends={{npcID=262880}},coords={mapID=2613,x=0.686,y=0.1566},questType="standard"},
[97669] = {id=97669,name="The Luck of the Bound Spirit",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16535,description="Er'inye would likely be interested in studying it.>",rewardGold=170800,rewardXP=6850,ends={{npcID=262880}},coords={mapID=2509,x=0.417,y=0.536},questType="standard"},
[97670] = {id=97670,name="A Handful of Voidlight Marl",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,rewardCurrencies={{id=3316,amount=500}},starts={{npcID=268228}},ends={{npcID=268228}},coords={x=0.588,y=0.46,source="quest_giver",zoneID=16365},questType="standard"},
[97910] = {id=97910,name="Cracked Keystone",level=80,requiredLevel=80,faction="none",expansion=11,description="Fragmentary images of heroic deeds flash through your mind as you touch the stone, but they fade as fast as they arrive. Perhaps performing a suitably impressive task will stabilize the stone's magic once more?",rewardGold=1366400,rewardXP=23530,rewardCurrencies={{id=3440,amount=20},{id=3441,amount=20}},questType="standard"},
[97945] = {id=97945,name="In the Catalyst's Shadow",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2405,description="Ah, ! Good. Now that you've helped me amass such a wealth of resources, it's time for me to pursue other... interests. What? You expected a more dramatic betrayal? Never! Don't worry, $p, while I may be occupied elsewhere, I'll never tire of watching your adventures. Adventures still bolstered by my gifts, of course. Many have shown interest, but I've only found one void elf... amusingly strange enough to mentor. Orin Straylight is the name. You'll find him by the Catalyst in Silvermoon.",rewardGold=1366400,rewardXP=27380,starts={{npcID=243907,x=0.512,y=0.684,mapID=2405}},ends={{npcID=269987,x=0.4,y=0.646,mapID=2393}},coords={x=0.512,y=0.684,source="quest_giver",mapID=2393},questType="world",worldTaskTitle="In the Catalyst's Shadow",db2QuestInfoID=282,db2QuestInfoName="Important Quest"},
[97978] = {id=97978,name="Prismatic Potential",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Greetings, . Our mutual friend explained everything to us. Don't worry, my shade and I took to Decimus' voidweaving like fish to water. We had an idea. The Catalyst's transformative energies are immense and span the breadth of known elemental forces. If I can learn to isolate the void from that spectrum of power, I could use it to weave Nebulous Voidcores just as Decimus did with the Voidforge. We are no domanaar, though. We need practice.",rewardGold=1366400,rewardXP=27380,rewardItems={265695},starts={{npcID=269987}},ends={{npcID=269987}},coords={x=0.4,y=0.646,source="quest_giver",mapID=2393},questType="standard",worldTaskTitle="Prismatic Potential",db2QuestInfoID=282,db2QuestInfoName="Important Quest"},
[97981] = {id=97981,name="Umbral Blessings of the Catalyst",expansion=11,mapID=2405,objectivesText="Level 90 With this research complete, I can begin weaving Nebulous Voidcores out of the Catalyst's energy. I'll need raw materials to do so, and I may not be as efficient as Decimus was with the Voidforge.",questType="world",worldTaskTitle="Umbral Blessings of the Catalyst",db2QuestInfoID=282,db2QuestInfoName="Important Quest"},
[98012] = {id=98012,name="Nebulous Voidcores: Veteran Mistcrest",expansion=11,mapID=2393,questType="world",worldTaskTitle="Nebulous Voidcores: Veteran Mistcrest"},
[98015] = {id=98015,name="Nebulous Voidcores: Voidlight Marl",expansion=11,mapID=2393,questType="world",worldTaskTitle="Nebulous Voidcores: Voidlight Marl"},
[98016] = {id=98016,name="Nebulous Voidcores: Gold",expansion=11,mapID=2393,questType="world",worldTaskTitle="Nebulous Voidcores: Gold"},
[98172] = {id=98172,name="Trailing Xal'atath",level=90,requiredLevel=90,faction="alliance",expansion=11,zoneID=15969,mapID=2393,description="We must not lose sight of our true goal here in Silvermoon, : to bring Xal'atath to justice. We all saw her void armies at the Sunwell. They were rushing downward, INTO the well, a thousand a minute. And now: silence. Listen for their whispers, . With any luck, we'll pick up on their trail again, and then we'll find Xal'atath... and perhaps even those that pursued her.",rewardGold=683200,rewardXP=20540,rewardItems={279573,279576},starts={{npcID=270645}},ends={{npcID=270645}},coords={x=0.49,y=0.646,source="quest_giver",mapID=2393},questType="standard"},
[98204] = {id=98204,name="Cursed Keepsake",level=0,requiredLevel=0,faction="both",expansion=11,rewardGold=341600,rewardItems={244347,245991,245993,252042,253396,253703,255652,255712,256361,256684,258540,263876,267205,267355,267435,268943,272129,272142,278696,278701},starts={{npcID=262726}},ends={{npcID=262726}},questType="standard"},
[98218] = {id=98218,name="Return to Amani'Zar",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15947,mapID=2437,description=", Your aid is requested in Amani'Zar Village. Please meet me there. --Liadrin",rewardGold=34100,rewardXP=1370,ends={{npcID=263331}},questType="standard"},
[98220] = {id=98220,name="Altar of Fangs",expansion=11,mapID=2393,questType="world",worldTaskTitle="Altar of Fangs",db2QuestInfoID=81,db2QuestInfoName="Dungeon"},
[98232] = {id=98232,name="Midnight: Vaults of Atal'Utek",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Zul'jarra's forces stand watch at the gates of the Vaults of Atal'Utek, holding the line against those wicked serpents. The fate of the entire Eastern Kingdoms rests on their blades. We would do well to provide them with reinforcements. The Children of Ula'tek are fierce, but they are no match for a seasoned like you. Traverse the temple and thin their ranks, however you can.",rewardGold=683200,rewardXP=13690,rewardItems={254677,268490,279527,279575},ends={{npcID=256203}},coords={mapID=2393,x=0.49,y=0.646},questType="standard"},
[98234] = {id=98234,name="Week 1 of 3: Gladiator's Distinction",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Interested in training against some of our fighters? Step into the ring and show us your mettle. Make sure you equip these medallions, and defeat at least two teams of enemies.",rewardItems={280097,280118},starts={{npcID=256212}},ends={{npcID=256212}},coords={x=0.488,y=0.646,source="quest_giver",mapID=2393},questType="pvp"},
[98343] = {id=98343,name="Venom Fishing: My Second-Best",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,mapID=2512,description="Before I send ye out hunting, ye should acquaint yerself with what remains of my crew. Most perished in the wreck, of course. Others fell into the swamp. Some traitorous gits... well, we'll get to them in a moment, won't we? But me loyal second mate is holding down the fort, just down river of me Landing. She'll set you up right.",rewardGold=341600,rewardXP=13690,starts={{npcID=258755}},ends={{npcID=257598}},coords={x=0.572,y=0.486,source="quest_giver",zoneID=16365},questType="standard"},
[98379] = {id=98379,name="Ancient Depths, Ancient Venom",expansion=11,mapID=2393,objectivesText="Level 90 Collect 3 Primordial Venom Motes from Ancient Foes in the Vaults of Atal'Utek or bosses within the Venomous Abyss raid on Raid Finder or higher difficulty to help Orin with his Catalyst research. The Catalyst will grant access to Ascendant Venomstones used to upgrade Midnight Season 2 weapons, trinkets, and necklaces. Requirements: - Primordial Venom Mote x 3",questType="world",worldTaskTitle="Ancient Depths, Ancient Venom",db2QuestInfoID=282,db2QuestInfoName="Important Quest"},
[98388] = {id=98388,name="Into the Vaults of Atal'Utek",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16535,mapID=2509,description="Past dis bulwark, there's nothin but snakes, spirits, and venomous death. I've lost three lieutenants dis week. Strong ones. Brave ones. Maybe stronger and braver than you. Warleader Abdumati looks you over with a weary eye.> If you want to fling yaself into de abyss, be my guest. Bring back my scouts, if you can find dem amongst de bones. But watch your step. Dat venom will swallow you whole.",rewardGold=341600,rewardXP=13690,rewardItems={278472},starts={{npcID=262798},{npcID=271885}},ends={{npcID=262798}},coords={x=0.472,y=0.608,source="quest_giver",zoneID=16535},questType="standard"},
[98390] = {id=98390,name="Ascending with Venomstones",expansion=11,mapID=2405,questType="world",worldTaskTitle="Ascending with Venomstones",db2QuestInfoID=282,db2QuestInfoName="Important Quest"},
[98406] = {id=98406,name="A Curated Gift",level=0,requiredLevel=0,faction="both",expansion=11,zoneID=15524,mapID=2351,description="I have watched the effort and care you take with the other mortals of your neighborhood, here in Razorwind Shores. This ceaseless labor on their behalf is the sort of behavior that I encourage. There's no profit to be had for you, but that isn't a driving concern for the best of your kind. In recognition of your efforts and status, I offer you a gift. This small device contains a piece of decor for you to place in your home. I will have another for you next week.",rewardItems={245539,246958,249923,253397,253481,254561,277975},starts={{npcID=248854}},ends={{npcID=248854},{npcID=253596}},questType="standard"},
[98414] = {id=98414,name="A Request from the Captain",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,description="Oh, uh. The Captain has requested you join him at Tokka's Landing as soon as you can. Second Mate Sluggs quivers in her shell.> He had a mean look about him. Tread lightly.",rewardGold=34100,rewardXP=1370,starts={{npcID=257598}},ends={{npcID=258755}},coords={x=0.516,y=0.498,source="quest_giver",zoneID=16365},questType="standard"},
[98415] = {id=98415,name="A Favor to the Captain",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,description="Oh! While you were out fishing, Captain Tokka asked to see you again. I think he's beginning to trust you. Second Mate Sluggs grimaces.> The Captain's trust d-does tend to come with caveats.",rewardGold=34100,rewardXP=1370,starts={{npcID=257598}},ends={{npcID=258755}},coords={x=0.516,y=0.498,source="quest_giver",zoneID=16365},questType="standard"},
[98416] = {id=98416,name="A Plea from the Captain",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=16365,description="Ohh, the Captain's really in a foul mood this time. I think you'd better go see what he wants. You're the only one who can soothe his storms, these days.",rewardGold=34100,rewardXP=1370,questType="standard"},
[98419] = {id=98419,name="Shoulder to Shoulder",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16535,mapID=2509,description="De Vaults are a dangerous place. Lotta brave, headstrong fighters think dey can face de Children of Ula'tek alone. If dey're lucky, we manage to recover de bodies before dey get eaten. I like you, $p. It'd be a shame to see a serpent feed you to its young. So be smart. Find people to watch your back, then carve your way through de temple together.",rewardGold=341600,rewardXP=13690,rewardCurrencies={{id=3316,amount=50},{id=3448,amount=200},{id=3448,amount=250},{id=3448,amount=350}},starts={{npcID=262798,x=0.472,y=0.608,zoneID=16535}},ends={{npcID=262798,x=0.472,y=0.608,zoneID=16535}},coords={x=0.472,y=0.608,source="quest_giver",zoneID=16535},questType="world",worldTaskTitle="Shoulder to Shoulder",db2QuestInfoID=1,db2QuestInfoName="Group"},
[98420] = {id=98420,name="What's Out There?",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16535,mapID=2509,description="Knowledge is de most important weapon in war. These Vaults are ancient and vast--our scouts cannot see everything. What lurks in de depths of these corrupted halls? Dat's precisely what I need to know. Get out there and tell me what you see, but it's dangerous to go alone. You best bring some comrades if you want to make it back.",rewardGold=341600,rewardXP=13690,rewardCurrencies={{id=3316,amount=50},{id=3448,amount=200},{id=3448,amount=250},{id=3448,amount=350}},starts={{npcID=262798,x=0.472,y=0.608,zoneID=16535}},ends={{npcID=262798,x=0.472,y=0.608,zoneID=16535}},coords={x=0.472,y=0.608,source="quest_giver",zoneID=16535},questType="world",worldTaskTitle="What's Out There?",db2QuestInfoID=1,db2QuestInfoName="Group"},
[98428] = {id=98428,name="Vaults of Atal'Utek: The Altar of Corrosion",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16535,mapID=2509,description="De Altar of Corrosion . Who can say when dis accursed piece of stone rose out of de venom? I have studied it for lifetimes and have only just tasted its power. Er'inye licks her spectral lips.> Say de word, and I will convert de corrosion you carry to something more useful. Den, you may commune with de Altar and accept its many gifts.",rewardGold=170800,rewardXP=6850,starts={{npcID=262880}},ends={{npcID=262880}},coords={x=0.51,y=0.626,source="quest_giver",zoneID=16535},questType="standard"},
[98515] = {id=98515,name="Vaults of Atal'Utek: A Toxic Tour",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16535,mapID=2509,description="Dis temple is where all de Children of Ula'tek first crawl out of de ooze. Dis is where we hold de line. De threat comes in waves. Sometimes short strikes. Sometimes an incursion dat overwhelms de whole temple. Sometimes a huge monstrosity rising out of de venom. Whatever dey send, send it back cryin' to its big evil mama! And in de meantime, do what you can to keep our patrols safe.",rewardGold=341600,rewardXP=13690,rewardItems={273000,279382},rewardCurrencies={{id=3448,amount=1500},{id=3448,amount=1875},{id=3504,amount=500}},starts={{npcID=262798}},ends={{npcID=262798}},coords={x=0.472,y=0.608,source="quest_giver",zoneID=16535},questType="standard"},
}
end)
